import React, { Component } from "react";
import classNames from "classnames/bind";
import "views/common/plugins/feedback/style.css";
import OverAllRating from "./components/feedbackrequest/OverAllRatingInput";
import TextInput from "./components/feedbackrequest/TextInput";
import DecisionOptionSelectInput from "./components/feedbackrequest/DecisionOptionSelectInput";
import MultiOptionDropDownSingleSelectInput from "./components/feedbackrequest/MultiOptionDropDownSingleSelectInput";
import MultiOptionMultiSelectInput from "./components/feedbackrequest/MultiOptionMultiSelectInput";
import MultiOptionSingleSelectInput from "./components/feedbackrequest/MultiOptionSingleSelectInput";
import LongTextInput from "./components/feedbackrequest/LongTextInput";
import ReactionInput from "./components/feedbackrequest/ReactionInput";
import MultiStarsSelectInput from "./components/feedbackrequest/MultiStarsSelectInput";
import SingleDecisionOptionSingleSelectInput from "./components/feedbackrequest/SingleDecisionOptionSingleSelectInput";
import { store } from "_helpers";
import { feedbackRequestActions } from "_actions";
import { feedbackTemplateActions } from "_actions";
import { connect } from "react-redux";
import SingleStartsSelectInput from "./components/feedbackrequest/SingleStarsSelectInput";
import {
  partitionFeedbackQuestions,
  countAnsweredQuestions,
  validateFeedbackAnswers,
} from "./feedbackForm.utils";
import {
  C5I_BRAND_NAME,
  C5I_FEEDBACK_LOGO,
  C5I_FEEDBACK_MARK,
} from "./feedbackForm.constants";
import LuxFeedbackRichAside from "./components/feedbackrequest/LuxFeedbackRichAside";

class FeedbackRequestPage extends Component {
  constructor() {
    super();
    this.state = {
      feedbackRequestAnswers: null,
      feedbackData: null,
      hasError: false,
      formError: false,
      isSubmitFailed: false,
      requestSubmited: false,
    };
  }

  componentDidMount() {
    document.title = `${C5I_BRAND_NAME} — Client Feedback`;
    document.body.classList.add("lux-fb-body");
    const { templateId, feedbackRequestId, feedbackId } = this.props.match.params;
    this.setState({
      feedbackTemplateId: templateId,
      feedbackRequestId,
      feedbackId,
      feedbackData: null,
    });
    if (templateId) {
      this.getFeedbackDataFromTemplateRequest(templateId);
    }
    if (feedbackRequestId) {
      this.getFeedbackDataFromFeedbackRequest(feedbackRequestId);
    }
    if (feedbackId) {
      this.getFeedbackDataFromFeedback(feedbackId);
    }
  }

  componentWillUnmount() {
    document.body.classList.remove("lux-fb-body");
  }

  getFeedbackDataFromTemplateRequest = (feedbackTemplateId) => {
    store.dispatch(
      this.props.getFeedbackTemplate(feedbackTemplateId, this.mapFeedbackDataFromTemplate)
    );
  };

  getFeedbackDataFromFeedback = (feedbackId) => {
    store.dispatch(this.props.getFeedback(feedbackId, this.mapFeedbackDataFromFeedback));
  };

  getFeedbackDataFromFeedbackRequest = (feedbackRequestId) => {
    store.dispatch(
      this.props.getFeedbackRequest(feedbackRequestId, this.mapFeedbackDataFromFeedbackRequest)
    );
  };

  mapFeedbackDataFromTemplate = (templateResponse) => {
    this.setState({
      feedbackData: templateResponse,
      itemId: "000001",
      itemName: "Sample Project Name",
      viewMode: "TEMPLATE",
    });
  };

  mapFeedbackDataFromFeedback = (feedbackResponse) => {
    this.setState({
      feedbackData: {
        ...feedbackResponse.feedbackTemplateInfo,
        itemId: feedbackResponse.itemId,
        itemName: feedbackResponse.itemName,
      },
      viewMode: "TEMPLATE",
    });
  };

  mapFeedbackRequestAndTemplateQuestionDataList = (feedbackDataList, questionDataList) => {
    return questionDataList.map((item) => {
      const matchedItem = feedbackDataList.find((obj) => obj.id === item.id);
      if (matchedItem) {
        return { ...item, answer: matchedItem.answer };
      }
      return item;
    });
  };

  mapFeedbackDataFromFeedbackRequest = (feedbackRequestResponse) => {
    if (
      feedbackRequestResponse.hasOwnProperty("error") ||
      !feedbackRequestResponse.feedbackInfo
    ) {
      this.setState({ hasError: true });
    } else {
      const questionDataList = feedbackRequestResponse.feedbackDataList
        ? this.mapFeedbackRequestAndTemplateQuestionDataList(
            feedbackRequestResponse.feedbackDataList,
            feedbackRequestResponse.feedbackTemplateInfo.questionDataList
          )
        : feedbackRequestResponse.feedbackTemplateInfo.questionDataList;
      this.setState({
        feedbackData: {
          ...feedbackRequestResponse,
          itemId: feedbackRequestResponse.feedbackInfo.itemId,
          itemName: feedbackRequestResponse.feedbackInfo.itemName,
          questionDataList,
        },
        viewMode: "REQUESTED",
      });
    }
  };

  isReadOnlyMode = () => {
    return (
      this.state.feedbackData &&
      this.state.viewMode === "REQUESTED" &&
      this.state.feedbackData.status !== "REQUESTED"
    );
  };

  isTemplateMode = () => this.state.viewMode === "TEMPLATE";

  onChange = (feedbackAnswer) => {
    const newFeedbackQuestionItems = [...this.state.feedbackData.questionDataList];
    const idx =
      feedbackAnswer.index != null
        ? feedbackAnswer.index
        : newFeedbackQuestionItems.findIndex((q) => q.id === feedbackAnswer.id);
    if (idx < 0) return;
    newFeedbackQuestionItems[idx] = {
      ...newFeedbackQuestionItems[idx],
      ...feedbackAnswer,
    };
    this.setState({
      feedbackData: {
        ...this.state.feedbackData,
        questionDataList: newFeedbackQuestionItems,
      },
    });
  };

  submitCallBack = (feedbackRequestResponse) => {
    if (feedbackRequestResponse.hasOwnProperty("error")) {
      this.setState({ isSubmitFailed: true });
    } else {
      this.setState({
        requestSubmited: true,
        feedbackData: {
          ...this.state.feedbackData,
          status: "RECEIVED",
        },
      });
    }
  };

  resetPage = () => {
    const questionDataList = this.state.feedbackData.feedbackTemplateInfo
      ? this.state.feedbackData.feedbackTemplateInfo.questionDataList
      : this.state.feedbackData.questionDataList;
    this.setState({
      formError: false,
      isSubmitFailed: false,
      feedbackData: {
        ...this.state.feedbackData,
        questionDataList,
      },
    });
  };

  submitFeedbackRequestAnswers = () => {
    const isValidForm = validateFeedbackAnswers(this.state.feedbackData.questionDataList);
    if (isValidForm) {
      const feedbackRequestRequest = {
        id: this.state.feedbackData.id,
        feedbackDataList: this.state.feedbackData.questionDataList.map((questionConfig) => ({
          id: questionConfig.id,
          question: questionConfig.question,
          answer: questionConfig.answer,
        })),
      };
      store.dispatch(
        this.props.updateFeedbackRequest(feedbackRequestRequest, this.submitCallBack)
      );
    }
    this.setState({ formError: !isValidForm });
  };

  isFeedbackSubmited = () => {
    return (
      this.state.feedbackData &&
      this.state.feedbackData.status &&
      (this.state.feedbackData.status === "RECEIVED" ||
        this.state.feedbackData.status === "REVIEW" ||
        this.state.feedbackData.status === "CLOSED")
    );
  };

  renderQuestion = (questionConfig) => {
    const readonly = this.isReadOnlyMode();
    const common = { key: questionConfig.id, questionConfig, onChange: this.onChange, readonly };
    switch (questionConfig.type) {
      case "boolean":
        return <DecisionOptionSelectInput {...common} />;
      case "string":
        return <TextInput {...common} />;
      case "number":
        return <TextInput {...common} type="number" />;
      case "longstring":
        return <LongTextInput {...common} />;
      case "multiopitonrating":
        return <MultiStarsSelectInput {...common} />;
      case "dropdown":
        return <MultiOptionDropDownSingleSelectInput {...common} />;
      case "starrating":
        return <SingleStartsSelectInput {...common} />;
      case "multiselect":
        return <MultiOptionMultiSelectInput {...common} />;
      case "singleselectoption":
        return <SingleDecisionOptionSingleSelectInput {...common} />;
      case "singleselectmultioptions":
        return <MultiOptionSingleSelectInput {...common} />;
      case "overallstarrating":
        return <OverAllRating {...common} />;
      case "reaction":
        return <ReactionInput {...common} />;
      default:
        return null;
    }
  };

  renderHeroIntro = () => {
    const isTemplate = this.isTemplateMode();
    const data = this.state.feedbackData;
    const templateName =
      (data.feedbackTemplateInfo && data.feedbackTemplateInfo.name) || data.name || null;

    if (isTemplate) {
      return {
        eyebrow: "Template preview",
        title: templateName || "Feedback template",
        lead:
          "Internal preview of the C5i client form. Responses are not saved — validate questions, rating scales, and tone before sending invitations.",
      };
    }

    return {
      eyebrow: `${C5I_BRAND_NAME} client feedback`,
      title: "Please rate your experience working with C5i",
      lead:
        "Your perspective on delivery quality, communication, and collaboration helps us strengthen every engagement. Time permitting, we invite you to share thoughtful ratings and comments below.",
    };
  };

  render() {
    const { feedbackData, hasError, formError, isSubmitFailed, requestSubmited } = this.state;
    const isTemplate = this.isTemplateMode();
    const readonly = this.isReadOnlyMode();
    const showForm = feedbackData && !hasError;
    const partitions = showForm
      ? partitionFeedbackQuestions(feedbackData.questionDataList)
      : { hero: [], body: [], footer: [] };
    const progress = showForm ? countAnsweredQuestions(feedbackData.questionDataList) : null;
    const progressPct =
      progress && progress.total > 0
        ? Math.round((progress.answered / progress.total) * 100)
        : 0;
    const intro = showForm ? this.renderHeroIntro() : null;
    const hasHeroRating = partitions.hero.length > 0;

    return (
      <main className="lux-fb-page feedback-public-page">
        <div className="lux-fb-page__inner">
          <header className="lux-fb-page__header">
            <img src={C5I_FEEDBACK_LOGO} className="lux-fb-page__logo" alt={C5I_BRAND_NAME} />
            <img src={C5I_FEEDBACK_MARK} className="lux-fb-page__logo-mark" alt="" aria-hidden="true" />
          </header>

          {!feedbackData && hasError === false && (
            <div className="lux-fb-page__shell">
              <div className="lux-fb-loading">Preparing your feedback form…</div>
            </div>
          )}

          {hasError === true && (
            <div className="lux-fb-page__shell">
              <div className="lux-fb-alert lux-fb-alert--error" style={{ margin: "1.75rem" }}>
                The feedback link you followed is incorrect or has expired. Please check the URL or
                contact your project team for a new invitation.
              </div>
            </div>
          )}

          {showForm && (
            <div
              className={classNames("lux-fb-page__shell", {
                "is-template-preview": isTemplate,
              })}
            >
              {isTemplate && (
                <div className="lux-fb-page__ribbon" aria-hidden="true">
                  <i className="fe fe-layers" />
                  Template preview
                </div>
              )}

              <div className="lux-fb-shell-layout">
                <div className="lux-fb-shell-main">
                  <section className="lux-fb-hero">
                    <p className="lux-fb-hero__eyebrow">
                      <i className="fe fe-message-square" aria-hidden="true" />
                      {intro.eyebrow}
                    </p>
                    <h1 className="lux-fb-hero__title">{intro.title}</h1>
                    <p className="lux-fb-hero__lead">{intro.lead}</p>
                    <div className="lux-fb-hero__meta">
                      {feedbackData.itemName && (
                        <span className="lux-fb-hero__chip">
                          <i className="fe fe-briefcase" aria-hidden="true" />
                          Project · <strong>{feedbackData.itemName}</strong>
                        </span>
                      )}
                      {feedbackData.personName && !isTemplate && (
                        <span className="lux-fb-hero__chip">
                          <i className="fe fe-user" aria-hidden="true" />
                          For <strong>{feedbackData.personName}</strong>
                        </span>
                      )}
                      {feedbackData.emailSubject && !isTemplate && (
                        <span className="lux-fb-hero__chip">
                          <i className="fe fe-mail" aria-hidden="true" />
                          Re <strong>{feedbackData.emailSubject}</strong>
                        </span>
                      )}
                      {isTemplate && (
                        <span className="lux-fb-hero__chip">
                          <i className="fe fe-eye" aria-hidden="true" />
                          Sample data only
                        </span>
                      )}
                    </div>
                    {!readonly && !isTemplate && progress && progress.total > 0 && (
                      <div className="lux-fb-progress" aria-label="Form progress">
                        <div className="lux-fb-progress__bar">
                          <div
                            className="lux-fb-progress__fill"
                            style={{ width: `${progressPct}%` }}
                          />
                        </div>
                        <span className="lux-fb-progress__text">
                          {progress.answered} of {progress.total} answered
                        </span>
                      </div>
                    )}
                  </section>

                  {this.isFeedbackSubmited() && !requestSubmited && (
                    <div className="lux-fb-alert lux-fb-alert--info">
                      Feedback was already submitted by{" "}
                      <strong>
                        {feedbackData.personName} ({feedbackData.personEmail})
                      </strong>
                      . You can review answers below.
                    </div>
                  )}

                  {requestSubmited && (
                    <div className="lux-fb-alert lux-fb-alert--success">
                      Thank you — your feedback was submitted successfully. You may close this page.
                    </div>
                  )}

                  <form
                className="lux-fb-form"
                onSubmit={(e) => {
                  e.preventDefault();
                  if (!readonly && !isTemplate) {
                    this.submitFeedbackRequestAnswers();
                  }
                }}
              >
                {partitions.hero.length > 0 && (
                  <section className="lux-fb-section lux-fb-section--hero" aria-label="Overall rating">
                    <div className="lux-fb-section__head lux-fb-section__head--center">
                      <h2 className="lux-fb-section__title">Overall experience</h2>
                      <p className="lux-fb-section__hint">
                        Based on the following aspects of your engagement with {C5I_BRAND_NAME},
                        how would you rate your overall experience?
                      </p>
                    </div>
                    <div className="lux-fb-grid lux-fb-grid--hero">
                      {partitions.hero.map((q) => (
                        <React.Fragment key={q.id}>{this.renderQuestion(q)}</React.Fragment>
                      ))}
                    </div>
                    <p className="lux-fb-thanks-line">
                      Thank you for sharing your feedback — it genuinely helps our team improve.
                    </p>
                  </section>
                )}

                {partitions.body.length > 0 && (
                  <section className="lux-fb-section" aria-label="Detailed feedback">
                    <div className="lux-fb-section__head">
                      <h2 className="lux-fb-section__title">Detailed dimensions</h2>
                      <p className="lux-fb-section__hint">
                        Time permitting, please share your experience on the parameters below.
                        Required items are marked with an asterisk.
                      </p>
                    </div>
                    <div className="lux-fb-grid">
                      {partitions.body.map((q) => (
                        <React.Fragment key={q.id}>{this.renderQuestion(q)}</React.Fragment>
                      ))}
                    </div>
                  </section>
                )}

                {partitions.footer.length > 0 && (
                  <section className="lux-fb-section" aria-label="Overall mood">
                    <div className="lux-fb-section__head">
                      <h2 className="lux-fb-section__title">Overall mood</h2>
                      <p className="lux-fb-section__hint">
                        How would you describe the tone of this engagement?
                      </p>
                    </div>
                    <div className="lux-fb-grid">
                      {partitions.footer.map((q) => (
                        <React.Fragment key={q.id}>{this.renderQuestion(q)}</React.Fragment>
                      ))}
                    </div>
                  </section>
                )}

                {!readonly && !isTemplate && (
                  <footer className="lux-fb-foot">
                    <p className="lux-fb-foot__note">
                      Required fields are marked with <span className="lux-fb-q__required">*</span>.
                      Your responses are confidential and used to improve our service.
                    </p>
                    <div className="lux-fb-foot__actions">
                      <button type="button" className="lux-fb-btn" onClick={() => this.resetPage()}>
                        Reset
                      </button>
                      <button type="submit" className="lux-fb-btn lux-fb-btn--primary" id="submit">
                        Submit feedback
                        <img src="/assets/images/custom/emoji/thumb.gif" alt="" aria-hidden="true" />
                      </button>
                    </div>
                  </footer>
                )}

                {isTemplate && (
                  <footer className="lux-fb-foot">
                    <p className="lux-fb-foot__note">
                      This is a preview for internal testing. Clients will not see the template
                      badge or sample project label.
                    </p>
                    <div className="lux-fb-foot__actions">
                      <span className="lux-fb-btn lux-fb-btn--primary" style={{ opacity: 0.55, cursor: "default" }}>
                        Submit feedback
                      </span>
                    </div>
                  </footer>
                )}

                {formError && (
                  <div className="lux-fb-alert lux-fb-alert--error" role="alert">
                    Please complete all required fields before submitting.
                  </div>
                )}
                {isSubmitFailed && (
                  <div className="lux-fb-alert lux-fb-alert--error" role="alert">
                    Submission failed. Please try again in a moment.
                  </div>
                )}
                  </form>
                </div>

                <LuxFeedbackRichAside
                  isTemplate={isTemplate}
                  showRatingLegend={hasHeroRating}
                />
              </div>
            </div>
          )}

          <p className="lux-fb-page__legal">
            © {new Date().getFullYear()} {C5I_BRAND_NAME}. Confidential client feedback — used to
            improve project delivery and partnership quality.
          </p>
        </div>
      </main>
    );
  }
}

const mapStateToProps = () => ({
  isLoading: true,
});

const mapDispatchToProps = () => ({
  getFeedbackRequest: feedbackRequestActions.getFeedbackRequest,
  getFeedback: feedbackRequestActions.getFeedback,
  getFeedbackTemplate: feedbackTemplateActions.getFeedbackTemplate,
  updateFeedbackRequest: feedbackRequestActions.updateFeedbackRequest,
});

export default connect(mapStateToProps, mapDispatchToProps)(FeedbackRequestPage);
