import {
  RETENTION_DOMAINS,
  RETENTION_STATUSES,
  normalizeRetentionPolicy,
} from "config/data-retention.config";

export function formatRetentionPeriod(days) {
  if (days == null || days <= 0) {
    return "Indefinite";
  }
  if (days >= 365) {
    const years = Math.round((days / 365) * 10) / 10;
    return years === 1 ? "1 year" : `${years} years`;
  }
  return `${days} days`;
}

export function buildRetentionPolicyMetrics(policies) {
  const rows = (policies || []).map(normalizeRetentionPolicy).filter(Boolean);
  const legalHold = rows.filter((row) => row.legalHold || row.status === RETENTION_STATUSES.LEGAL_HOLD);
  const autoPurge = rows.filter((row) => row.autoPurge && !row.legalHold);
  const recordsHeld = rows.reduce((sum, row) => sum + (row.recordsHeld || 0), 0);
  const expiringSoon = rows.filter((row) => {
    if (!row.nextPurgeAt || row.legalHold) {
      return false;
    }
    const purgeDate = new Date(row.nextPurgeAt);
    if (Number.isNaN(purgeDate.getTime())) {
      return false;
    }
    const daysUntil = (purgeDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24);
    return daysUntil >= 0 && daysUntil <= 90;
  });

  return {
    totalPolicies: rows.length,
    legalHoldCount: legalHold.length,
    autoPurgeCount: autoPurge.length,
    recordsHeld,
    expiringSoon: expiringSoon.length,
    archivedCount: rows.filter((row) => row.status === RETENTION_STATUSES.ARCHIVED).length,
  };
}

export function buildRetentionPolicyInsights(policies) {
  const rows = (policies || []).map(normalizeRetentionPolicy).filter(Boolean);
  const insights = [];

  const holds = rows.filter((row) => row.legalHold);
  if (holds.length > 0) {
    insights.push({
      id: "legal-hold",
      tone: "rose",
      icon: "fe fe-alert-octagon",
      title: `${holds.length} policy(ies) on legal hold`,
      copy: "Purge jobs are suspended until holds are released.",
    });
  }

  const expiring = rows.filter((row) => {
    if (!row.nextPurgeAt || row.legalHold) return false;
    const purgeDate = new Date(row.nextPurgeAt);
    if (Number.isNaN(purgeDate.getTime())) return false;
    const daysUntil = (purgeDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24);
    return daysUntil >= 0 && daysUntil <= 30;
  });
  if (expiring.length > 0) {
    insights.push({
      id: "purge-soon",
      tone: "amber",
      icon: "fe fe-clock",
      title: `${expiring.length} purge window(s) within 30 days`,
      copy: "Review records before auto-purge executes.",
    });
  }

  const noPurge = rows.filter((row) => !row.autoPurge && !row.legalHold);
  if (noPurge.length > 0) {
    insights.push({
      id: "manual",
      tone: "blue",
      icon: "fe fe-archive",
      title: `${noPurge.length} manual retention policy(ies)`,
      copy: "Archival requires explicit compliance approval.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${rows.length} policies aligned`,
      copy: "Retention windows match Tracopus governance defaults.",
    });
  }

  return insights.slice(0, 3);
}

export function filterRetentionPolicies(policies, filters = {}) {
  const { status = "ALL", domain = "ALL", query = "" } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (policies || [])
    .map(normalizeRetentionPolicy)
    .filter(Boolean)
    .filter((row) => {
      if (status === "LEGAL_HOLD" && !row.legalHold) {
        return false;
      }
      if (status === "ACTIVE" && (row.legalHold || row.status !== RETENTION_STATUSES.ACTIVE)) {
        return false;
      }
      if (status === "ARCHIVED" && row.status !== RETENTION_STATUSES.ARCHIVED) {
        return false;
      }
      if (domain !== "ALL" && row.domain !== domain) {
        return false;
      }
      if (!normalizedQuery) {
        return true;
      }
      const haystack = [row.name, row.entityType, row.domain, row.description, row.owner]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(normalizedQuery);
    });
}

export function getRetentionDomainMeta(domainKey) {
  return RETENTION_DOMAINS[domainKey] || { label: domainKey, icon: "fe fe-circle", tone: "slate" };
}

export function applyRetentionDaysUpdate(policy, retentionDays) {
  const base = normalizeRetentionPolicy(policy);
  return {
    ...base,
    retentionDays,
    updatedAt: new Date().toISOString().slice(0, 10),
  };
}

export function applyLegalHoldUpdate(policy, legalHold) {
  const base = normalizeRetentionPolicy(policy);
  return {
    ...base,
    legalHold,
    status: legalHold ? RETENTION_STATUSES.LEGAL_HOLD : RETENTION_STATUSES.ACTIVE,
    autoPurge: legalHold ? false : base.autoPurge,
    updatedAt: new Date().toISOString().slice(0, 10),
  };
}

export function applyAutoPurgeUpdate(policy, autoPurge) {
  const base = normalizeRetentionPolicy(policy);
  if (base.legalHold) {
    return base;
  }
  return {
    ...base,
    autoPurge,
    updatedAt: new Date().toISOString().slice(0, 10),
  };
}

export function buildRetentionDomainSeries(policies) {
  const rows = (policies || []).map(normalizeRetentionPolicy).filter(Boolean);
  const totals = {};
  rows.forEach((row) => {
    totals[row.domain] = (totals[row.domain] || 0) + (row.recordsHeld || 0);
  });
  return Object.keys(RETENTION_DOMAINS)
    .filter((key) => totals[key] > 0)
    .map((key) => ({
      id: key,
      label: RETENTION_DOMAINS[key].label,
      value: totals[key],
      tone: RETENTION_DOMAINS[key].tone,
    }));
}

export function buildRetentionStatusSeries(policies) {
  const rows = (policies || []).map(normalizeRetentionPolicy).filter(Boolean);
  const active = rows.filter((row) => !row.legalHold && row.status === RETENTION_STATUSES.ACTIVE).length;
  const hold = rows.filter((row) => row.legalHold).length;
  const archived = rows.filter((row) => row.status === RETENTION_STATUSES.ARCHIVED).length;
  return [
    { id: "active", label: "Active", value: active, tone: "green" },
    { id: "hold", label: "Legal hold", value: hold, tone: "rose" },
    { id: "archived", label: "Archived", value: archived, tone: "slate" },
  ].filter((row) => row.value > 0);
}
