import { apiErrorResult } from "config/mock-fallback.utils";

/** Famstack often returns HTTP 200 with ServiceResponse.error — treat as failure. */
function extractServiceError(response) {
  if (!response || typeof response !== "object" || !response.error) {
    return null;
  }
  const first = Array.isArray(response.error) ? response.error[0] : response.error;
  if (!first) {
    return null;
  }
  if (typeof first === "string") {
    return first;
  }
  return first.message || first.code || "Request failed";
}

function assertServiceSuccess(response, fallbackMessage) {
  if (!response || response.source === "api-error") {
    throw new Error(fallbackMessage || "Unable to complete integration request.");
  }
  if (typeof response === "string") {
    throw new Error(response || fallbackMessage || "Request failed");
  }
  const serviceError = extractServiceError(response);
  if (serviceError) {
    const error = new Error(serviceError);
    error.response = { data: response, status: 200 };
    throw error;
  }
  return response;
}

