async function updateIntegrationCredentials(legacyKey, credentials) {
  if (!shouldUseIntegrationCenterApi()) {
    throw new Error("Integration Center API is not enabled.");
  }
  const response = await axiosUtils.put(
    `${urlConfig.INTEGRATION_CENTER_API_PATH}/connections/${legacyKey}/credentials?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    credentials || {}
  );
  assertServiceSuccess(response, "Unable to persist integration credentials.");
  return { payload: (response && response.payload) || response, source: "api" };
}

