import React, { Component } from "react";
import { connect } from "react-redux";
import { employeeActions } from "_actions";
import { store } from "_helpers";
import ProjectEstimateAddLineModal from "../modal/ProjectEstimateAddLineModal";
import {
    getMonthRangeOptions,
    getEstimateTotal,
    getTeamGrandTotal,
    getMonthSubtotal,
    countTeamLines,
    countTeamMonths,
    formatEstimateName,
    formatHoursLabel,
    getSharePct,
} from "./projectEstimate.utils";

class ProjectEstimateTeam extends Component {
    constructor() {
        super();
        this.state = {
            teamProjectEstimate: null,
            showAddLineModal: false,
        };
    }

    componentDidMount() {
        this.setState({ teamProjectEstimate: this.props.teamProjectEstimate });
    }

    componentDidUpdate(prevProps) {
        if (prevProps.teamProjectEstimate !== this.props.teamProjectEstimate) {
            this.setState({ teamProjectEstimate: this.props.teamProjectEstimate });
        }
    }

    getMonthOptions = () =>
        getMonthRangeOptions(
            this.props.projectInfo.estStartTime,
            this.props.projectInfo.estCompletionTime
        );

    onAddMonthlyEstimate = (month, estimateType, estimateName, estimateHours) => {
        this.setState(
            (prevState) => {
                const updated = {
                    ...prevState.teamProjectEstimate,
                    estimates: {
                        ...(prevState.teamProjectEstimate.estimates || {}),
                        [month]: {
                            ...((prevState.teamProjectEstimate.estimates &&
                                prevState.teamProjectEstimate.estimates[month]) ||
                                {}),
                            [estimateType]: {
                                ...((prevState.teamProjectEstimate.estimates &&
                                    prevState.teamProjectEstimate.estimates[month] &&
                                    prevState.teamProjectEstimate.estimates[month][
                                        estimateType
                                    ]) ||
                                    {}),
                                [estimateName]: estimateHours,
                            },
                        },
                    },
                    estimateTypes: [
                        ...new Set([
                            ...(prevState.teamProjectEstimate.estimateTypes || []),
                            estimateType,
                        ]),
                    ],
                };
                return { teamProjectEstimate: updated };
            },
            () => {
                this.props.onAddTeamEstimate(
                    this.props.teamId,
                    this.state.teamProjectEstimate
                );
            }
        );
    };

    removeMonthFromEstimate = (monthToBeDeleted) => {
        const teamProjectEstimateNew = { ...this.state.teamProjectEstimate };
        delete teamProjectEstimateNew.estimates[monthToBeDeleted];
        this.setState({ teamProjectEstimate: teamProjectEstimateNew }, () => {
            this.props.onAddTeamEstimate(
                this.props.teamId,
                this.state.teamProjectEstimate
            );
        });
    };

    renderHourFacts = (hours) => {
        const { projectItem } = this.props;
        return (
            <div className="lux-estimate-facts">
                <div className="lux-estimate-fact is-primary">
                    <span>Base</span>
                    <strong>
                        {formatHoursLabel(hours && hours.estimate)}
                    </strong>
                </div>
                {projectItem.automationEnabled && (
                    <div className="lux-estimate-fact is-muted">
                        <span>With tool</span>
                        <strong>
                            {formatHoursLabel(hours && hours.estimateAutomation)}
                        </strong>
                    </div>
                )}
                {projectItem.revisedEstEnabled && (
                    <div className="lux-estimate-fact is-accent">
                        <span>Revised</span>
                        <strong>
                            {formatHoursLabel(hours && hours.estimateRevised)}
                        </strong>
                    </div>
                )}
            </div>
        );
    };

    render() {
        const team = this.props.teamProjectEstimate || this.state.teamProjectEstimate;
        if (!team) return null;

        const monthOptions = this.getMonthOptions();
        const estimateTypes = team.estimateTypes || [];
        const { editable, projectItem, projectGrandTotal } = this.props;
        const months = countTeamMonths(team);
        const lines = countTeamLines(team);
        const teamTotal = getTeamGrandTotal(team, "estimate", monthOptions);
        const projectShare = projectGrandTotal
            ? getSharePct(teamTotal, projectGrandTotal)
            : null;
        const hasAnyMonth =
            team.estimates &&
            monthOptions.some(({ value }) => team.estimates[value]);

        return (
            <article className="lux-estimate-team-card">
                <header className="lux-estimate-team-card__head">
                    <span className="lux-estimate-team-card__icon" aria-hidden="true">
                        <i className="fe fe-users" />
                    </span>
                    <div className="lux-estimate-team-card__copy">
                        <h3 className="lux-estimate-team-card__name">
                            {team.teamName || "Unnamed team"}
                        </h3>
                        <span className="lux-estimate-team-card__types">
                            {months} month{months === 1 ? "" : "s"}
                            {" · "}
                            {lines} resource line{lines === 1 ? "" : "s"}
                            {estimateTypes.length > 0
                                ? ` · ${estimateTypes.join(" · ")}`
                                : " · No types yet"}
                        </span>
                    </div>
                    <div className="lux-estimate-team-card__head-stat">
                        <span>Team total</span>
                        <strong>{formatHoursLabel(teamTotal)}</strong>
                        {projectShare != null && (
                            <em>{projectShare}% of project</em>
                        )}
                    </div>
                    {editable && (
                        <button
                            type="button"
                            className="lux-estimate-team-card__remove"
                            onClick={() =>
                                this.props.removeTeamFromEstimate(this.props.teamId)
                            }
                            title="Remove team"
                            aria-label="Remove team"
                        >
                            <i className="fe fe-trash-2" />
                        </button>
                    )}
                </header>

                {!hasAnyMonth && (
                    <div className="lux-estimate-team-card__empty">
                        <i className="fe fe-calendar" aria-hidden="true" />
                        <p>No monthly lines yet for this team.</p>
                        {editable && (
                            <span>Use Add estimate line to begin.</span>
                        )}
                    </div>
                )}

                {team.estimates &&
                    monthOptions.map(({ value: monthYear }) => {
                        if (!team.estimates[monthYear]) return null;
                        const monthTotal = getMonthSubtotal(
                            team,
                            monthYear,
                            "estimate"
                        );
                        const monthShare = getSharePct(monthTotal, teamTotal);
                        return (
                            <div key={monthYear} className="lux-estimate-month-block">
                                <div className="lux-estimate-month-block__head">
                                    <div className="lux-estimate-month-block__title">
                                        <i className="fe fe-calendar" aria-hidden="true" />
                                        <strong>{monthYear}</strong>
                                    </div>
                                    <div className="lux-estimate-month-block__meta">
                                        <span className="lux-estimate-month-block__subtotal">
                                            {formatHoursLabel(monthTotal)}
                                        </span>
                                        <em>{monthShare}% of team</em>
                                    </div>
                                    {editable && (
                                        <button
                                            type="button"
                                            className="lux-estimate-month-block__remove"
                                            onClick={() =>
                                                this.removeMonthFromEstimate(monthYear)
                                            }
                                            title="Remove month"
                                            aria-label={`Remove ${monthYear}`}
                                        >
                                            <i className="fe fe-x" />
                                        </button>
                                    )}
                                </div>

                                {estimateTypes.map((estimateType) => {
                                    const typeData =
                                        team.estimates[monthYear][estimateType];
                                    if (!typeData) return null;
                                    const typeMonthTotal = Object.values(typeData).reduce(
                                        (sum, hours) =>
                                            sum + parseFloat((hours && hours.estimate) || 0),
                                        0
                                    );
                                    return (
                                        <div
                                            key={`${monthYear}-${estimateType}`}
                                            className="lux-estimate-type-block"
                                        >
                                            <div className="lux-estimate-type-block__bar">
                                                <span className="lux-estimate-type-block__label">
                                                    {estimateType}
                                                </span>
                                                <span className="lux-estimate-type-block__total">
                                                    {formatHoursLabel(typeMonthTotal)}
                                                </span>
                                            </div>
                                            <ul className="lux-estimate-lines">
                                                {Object.keys(typeData).map((estimateName) => (
                                                    <li
                                                        key={estimateName}
                                                        className="lux-estimate-lines__item"
                                                    >
                                                        <div className="lux-estimate-lines__name">
                                                            <i
                                                                className="fe fe-layers"
                                                                aria-hidden="true"
                                                            />
                                                            <span title={estimateName}>
                                                                {formatEstimateName(estimateName)}
                                                            </span>
                                                        </div>
                                                        {this.renderHourFacts(
                                                            typeData[estimateName]
                                                        )}
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    );
                                })}
                            </div>
                        );
                    })}

                {estimateTypes.length > 0 && (
                    <div className="lux-estimate-team-card__totals">
                        <span className="lux-estimate-team-card__totals-label">
                            By type (all months)
                        </span>
                        <div className="lux-estimate-team-card__totals-vals">
                            {estimateTypes.map((estimateType) => (
                                <span
                                    key={estimateType}
                                    className="lux-estimate-team-card__total-chip"
                                >
                                    <em>{estimateType}</em>
                                    <strong>
                                        {formatHoursLabel(
                                            getEstimateTotal(
                                                team,
                                                estimateType,
                                                "estimate",
                                                monthOptions
                                            )
                                        )}
                                    </strong>
                                </span>
                            ))}
                        </div>
                    </div>
                )}

                {editable && (
                    <>
                        <button
                            type="button"
                            className="lux-estimate-add-line-btn"
                            onClick={() => {
                                if (!this.props.employeeAppConfig) {
                                    store.dispatch(
                                        employeeActions.getModuleConfig(this.props.teamId)
                                    );
                                }
                                this.setState({ showAddLineModal: true });
                            }}
                        >
                            <i className="fe fe-plus" /> Add estimate line
                        </button>
                        <ProjectEstimateAddLineModal
                            show={this.state.showAddLineModal}
                            teamId={this.props.teamId}
                            teamName={team.teamName}
                            projectInfo={this.props.projectInfo}
                            projectItem={projectItem}
                            userTeams={this.props.userTeams}
                            onClose={() => this.setState({ showAddLineModal: false })}
                            onAdd={this.onAddMonthlyEstimate}
                        />
                    </>
                )}
            </article>
        );
    }
}

const mapStateToProps = (state) => ({
    employeeAppConfig: state.employees.createConfig,
});

export default connect(mapStateToProps)(ProjectEstimateTeam);
