import React, { useMemo, useState } from "react";
import classNames from "classnames/bind";
import {
  buildDependencyValidationReport,
  computeCriticalPathAnalysis,
  validateDependencyLink,
  validateDependencySchedule,
} from "config/project-governance.utils";

export default function DependencyValidationPanel({
  milestones,
  dependencies,
  projectFilter,
  canEdit,
  onCreateDependency,
  createError,
  creating,
}) {
  const [predecessorId, setPredecessorId] = useState("");
  const [successorId, setSuccessorId] = useState("");
  const [lagDays, setLagDays] = useState(0);
  const [localError, setLocalError] = useState(null);

  const scopedMilestones = useMemo(() => {
    if (!projectFilter || projectFilter === "ALL") {
      return milestones;
    }
    return milestones.filter((row) => row.projectId === projectFilter);
  }, [milestones, projectFilter]);

  const scopedDependencies = useMemo(() => {
    const milestoneIds = new Set(scopedMilestones.map((row) => row.id));
    return dependencies.filter(
      (dep) => milestoneIds.has(dep.predecessorId) && milestoneIds.has(dep.successorId)
    );
  }, [dependencies, scopedMilestones]);

  const validationIssues = useMemo(
    () =>
      buildDependencyValidationReport(milestones, dependencies, {
        projectId: projectFilter,
      }),
    [milestones, dependencies, projectFilter]
  );

  const analysis = useMemo(
    () =>
      computeCriticalPathAnalysis(milestones, dependencies, {
        projectId: projectFilter,
      }),
    [milestones, dependencies, projectFilter]
  );

  const draftLink = useMemo(() => {
    const predecessor = scopedMilestones.find((row) => row.id === predecessorId);
    const successor = scopedMilestones.find((row) => row.id === successorId);
    return {
      projectId: predecessor && predecessor.projectId,
      predecessorId,
      predecessorName: predecessor && predecessor.name,
      successorId,
      successorName: successor && successor.name,
      type: "FINISH_TO_START",
      lagDays: Number(lagDays) || 0,
    };
  }, [scopedMilestones, predecessorId, successorId, lagDays]);

  const draftValidation = useMemo(() => {
    if (!predecessorId || !successorId) {
      return null;
    }
    const structural = validateDependencyLink(scopedDependencies, draftLink);
    if (!structural.valid) {
      return structural;
    }
    return validateDependencySchedule(scopedMilestones, draftLink);
  }, [scopedDependencies, scopedMilestones, draftLink, predecessorId, successorId]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLocalError(null);
    if (!canEdit || !onCreateDependency) {
      return;
    }
    if (!draftValidation || !draftValidation.valid) {
      setLocalError((draftValidation && draftValidation.reason) || "Choose valid predecessor and successor milestones.");
      return;
    }
    try {
      await onCreateDependency(draftLink);
      setPredecessorId("");
      setSuccessorId("");
      setLagDays(0);
      setLocalError(null);
    } catch (err) {
      setLocalError(err && err.message ? err.message : "Unable to create dependency.");
    }
  };

  const displayError = localError || createError;

  return (
    <div className="lux-gov-deps-panel">
      <div className="lux-gov-deps-panel__summary">
        <div>
          <p className="lux-gov-deps-panel__eyebrow">Critical path</p>
          <strong>{analysis.criticalMilestoneIds.length}</strong>
          <span>milestones · {analysis.criticalDependencyIds.length} links</span>
        </div>
        <div>
          <p className="lux-gov-deps-panel__eyebrow">Schedule duration</p>
          <strong>{analysis.hasCycle ? "—" : `${analysis.projectDurationDays}d`}</strong>
          <span>longest dependency chain</span>
        </div>
        <div>
          <p className="lux-gov-deps-panel__eyebrow">Validation</p>
          <strong className={validationIssues.length ? "is-warn" : "is-ok"}>
            {validationIssues.length ? validationIssues.length : "Clear"}
          </strong>
          <span>{validationIssues.length ? "issues to review" : "all checks passed"}</span>
        </div>
      </div>

      {validationIssues.length ? (
        <ul className="lux-gov-deps-panel__issues">
          {validationIssues.map((issue) => (
            <li key={issue.id} className={classNames("lux-gov-deps-panel__issue", `is-${issue.severity}`)}>
              <strong>{issue.title}</strong>
              <span>{issue.copy}</span>
            </li>
          ))}
        </ul>
      ) : null}

      {canEdit ? (
        <form className="lux-gov-deps-panel__form" onSubmit={handleSubmit}>
          <p className="lux-gov-deps-panel__form-title">Link milestones</p>
          <div className="lux-gov-deps-panel__fields">
            <label>
              Predecessor
              <select value={predecessorId} onChange={(e) => setPredecessorId(e.target.value)}>
                <option value="">Select milestone</option>
                {scopedMilestones.map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.name}
                  </option>
                ))}
              </select>
            </label>
            <label>
              Successor
              <select value={successorId} onChange={(e) => setSuccessorId(e.target.value)}>
                <option value="">Select milestone</option>
                {scopedMilestones.map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.name}
                  </option>
                ))}
              </select>
            </label>
            <label>
              Lag (days)
              <input
                type="number"
                min="0"
                value={lagDays}
                onChange={(e) => setLagDays(e.target.value)}
              />
            </label>
            <button type="submit" className="lux-gov-deps-panel__submit" disabled={creating}>
              {creating ? "Linking…" : "Add dependency"}
            </button>
          </div>
          {draftValidation && predecessorId && successorId ? (
            <p
              className={classNames("lux-gov-deps-panel__hint", {
                "is-error": !draftValidation.valid,
                "is-ok": draftValidation.valid,
              })}
            >
              {draftValidation.valid
                ? "Finish-to-start link passes structural and schedule checks."
                : draftValidation.reason}
            </p>
          ) : null}
          {displayError ? <p className="lux-gov-deps-panel__hint is-error">{displayError}</p> : null}
        </form>
      ) : null}
    </div>
  );
}
