import React, { useMemo } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import DashboardApexChart from "../dashboard/DashboardApexChart";
import TimesheetLuxuryDialog from "./TimesheetLuxuryDialog";
import { DAILY_TARGET_MINS } from "./timesheetBoard.utils";
import {
  buildEntryDetailModel,
  buildEntryRowHoursChart,
  resolveTaskFromRequest,
} from "./timesheetDetail.utils";

function TimesheetEntryDetailModal({ show, payload, timeSheetRequest, weekDates, onClose }) {
  const model = useMemo(() => {
    if (!show || !payload || !timeSheetRequest) return null;

    const resolved = resolveTaskFromRequest(
      timeSheetRequest,
      payload.timesheetType,
      payload.taskGroupId,
      payload.taskIndex
    );

    if (!resolved) return null;

    return buildEntryDetailModel({
      timesheetType: payload.timesheetType,
      taskGroupId: payload.taskGroupId,
      timeEntryTaskSection: resolved.section,
      timeSheetTaskItem: resolved.task,
      weekDates,
    });
  }, [show, payload, timeSheetRequest, weekDates]);

  const chart = useMemo(() => (model ? buildEntryRowHoursChart(model.dayRows) : null), [model]);

  const weekPulse = useMemo(() => {
    if (!model) return null;
    const workdayCount = Math.max(
      (model.dayRows || []).filter((row) => {
        const short = String(row.dayShort || "").toLowerCase();
        return short !== "sat" && short !== "sun";
      }).length,
      1
    );
    const targetMins = DAILY_TARGET_MINS * workdayCount;
    const rawPct = targetMins > 0 ? Math.round((model.rowTotalMins / targetMins) * 100) : 0;
    const pct = Math.min(100, rawPct);
    const remainingMins = Math.max(0, targetMins - model.rowTotalMins);
    const overMins = Math.max(0, model.rowTotalMins - targetMins);
    const tone =
      model.rowTotalMins <= 0 ? "slate" : overMins > 0 ? "rose" : remainingMins <= 0 ? "green" : "sky";
    const statusLabel =
      model.rowTotalMins <= 0
        ? "Not started"
        : overMins > 0
          ? `${(overMins / 60).toFixed(overMins % 60 ? 1 : 0)}h over`
          : remainingMins <= 0
            ? "On target"
            : `${(remainingMins / 60).toFixed(remainingMins % 60 ? 1 : 0)}h left`;
    const hint =
      tone === "green"
        ? "This line is on pace for the week target."
        : tone === "rose"
          ? "Logged above the week target — review if overtime was intended."
          : tone === "sky"
            ? "Keep logging on open workdays to close the week gap."
            : "No hours on this line yet for the selected week.";
    return {
      targetMins,
      targetHours: (targetMins / 60).toFixed(0),
      pct,
      rawPct,
      remainingLabel: statusLabel,
      workdayCount,
      activeDays: model.activeDays || 0,
      tone,
      hint,
    };
  }, [model]);

  if (!model) {
    return (
      <TimesheetLuxuryDialog
        show={show}
        onClose={onClose}
        ariaLabel="Time entry details"
        kicker="Time entry"
        title="Entry not found"
        subtitle="This row may have been removed."
        panelClassName="lux-ts-detail__panel--entry-line"
      >
        <p className="lux-ts-detail__empty">Unable to load entry details.</p>
      </TimesheetLuxuryDialog>
    );
  }

  const maxDayMins = Math.max(
    DAILY_TARGET_MINS,
    ...(model.dayRows || []).map((row) => row.mins || 0),
    1
  );

  return (
    <TimesheetLuxuryDialog
      show={show}
      onClose={onClose}
      wide
      ariaLabel="Time entry details"
      kicker="Time entry line"
      kickerIcon="fe-clock"
      title={model.title}
      subtitle={model.subtitle}
      metaChips={model.metaChips}
      badge={model.badge}
      panelClassName="lux-ts-detail__panel--entry-line"
      footer={
        <div className="lux-ts-entry-line__foot">
          <span>
            <i className="fe fe-info" aria-hidden="true" />
            Tip: click a day column on the board to review every entry for that date.
          </span>
          <button type="button" className="lux-ts-entry-line__done" onClick={onClose}>
            Done
          </button>
        </div>
      }
    >
      <div className="lux-ts-entry-line">
        {weekPulse ? (
          <div
            className={classNames("lux-ts-progress", `is-${weekPulse.tone}`)}
            aria-label="Week progress"
            style={{ "--ts-progress": `${weekPulse.pct}%` }}
          >
            <span className="lux-ts-progress__accent" aria-hidden="true" />
            <div className="lux-ts-progress__ring" aria-hidden="true">
              <strong>
                <CountUp end={weekPulse.pct} duration={0.7} preserveValue />
                <small>%</small>
              </strong>
            </div>
            <div className="lux-ts-progress__body">
              <div className="lux-ts-progress__top">
                <span className="lux-ts-progress__icon" aria-hidden="true">
                  <i className="fe fe-activity" />
                </span>
                <div className="lux-ts-progress__titles">
                  <em>Week progress</em>
                  <strong>
                    {model.rowTotalDisplay}
                    <span> of {weekPulse.targetHours}h target</span>
                  </strong>
                </div>
                <span className={classNames("lux-ts-progress__pill", `is-${weekPulse.tone}`)}>
                  {weekPulse.remainingLabel}
                </span>
              </div>
              <p className="lux-ts-progress__hint">{weekPulse.hint}</p>
              <div className="lux-ts-progress__meta">
                <span>
                  <b>{weekPulse.activeDays}</b> active days
                </span>
                <span>
                  <b>{weekPulse.workdayCount}</b> workdays
                </span>
                <span>
                  <b>{weekPulse.rawPct}%</b> of target
                </span>
              </div>
              <div className="lux-ts-progress__track" aria-hidden="true">
                <i style={{ width: `${Math.max(weekPulse.pct, model.rowTotalMins ? 6 : 0)}%` }} />
                <em title="Week target" />
              </div>
            </div>
          </div>
        ) : null}

        <div className="lux-ts-entry-line__kpis" aria-label="Entry metrics">
          <article className="lux-ts-entry-line__kpi is-primary">
            <span className="lux-ts-entry-line__kpi-icon" aria-hidden="true">
              <i className="fe fe-clock" />
            </span>
            <div>
              <em>Week total</em>
              <strong>{model.rowTotalDisplay}</strong>
              <span>Logged on this line</span>
            </div>
          </article>
          <article className="lux-ts-entry-line__kpi is-green">
            <span className="lux-ts-entry-line__kpi-icon" aria-hidden="true">
              <i className="fe fe-calendar" />
            </span>
            <div>
              <em>Active days</em>
              <strong>
                <CountUp end={model.activeDays || 0} duration={0.6} preserveValue />
              </strong>
              <span>Days with hours</span>
            </div>
          </article>
          <article className="lux-ts-entry-line__kpi is-sky">
            <span className="lux-ts-entry-line__kpi-icon" aria-hidden="true">
              <i className="fe fe-trending-up" />
            </span>
            <div>
              <em>Avg / active day</em>
              <strong>{model.avgPerActiveDay}</strong>
              <span>Pace on logged days</span>
            </div>
          </article>
          <article className="lux-ts-entry-line__kpi is-amber">
            <span className="lux-ts-entry-line__kpi-icon" aria-hidden="true">
              <i className="fe fe-message-square" />
            </span>
            <div>
              <em>Days with notes</em>
              <strong>
                <CountUp end={model.daysWithComments || 0} duration={0.6} preserveValue />
              </strong>
              <span>Comments captured</span>
            </div>
          </article>
        </div>

        <div className="lux-ts-entry-line__split">
          <section className="lux-ts-entry-line__card">
            <header className="lux-ts-entry-line__card-head">
              <div>
                <h4>Hours this week</h4>
                <p>Daily breakdown for this row · 8h reference</p>
              </div>
            </header>
            {chart ? (
              <DashboardApexChart type="bar" series={chart.series} options={chart.options} height={220} />
            ) : (
              <p className="lux-ts-detail__empty">No hours chart for this line yet.</p>
            )}
          </section>

          <section className="lux-ts-entry-line__card">
            <header className="lux-ts-entry-line__card-head">
              <div>
                <h4>Day-by-day</h4>
                <p>Status, hours, and notes — denser days glow brighter</p>
              </div>
            </header>
            <ul className="lux-ts-entry-line__days" aria-label="Day by day hours">
              {model.dayRows.map((row) => {
                const barPct = Math.min(100, Math.round(((row.mins || 0) / maxDayMins) * 100));
                return (
                  <li
                    key={row.dateString}
                    className={classNames("lux-ts-entry-line__day", {
                      "has-hours": row.mins > 0,
                      "has-notes": row.hasDetails,
                      "is-empty": row.mins <= 0,
                    })}
                  >
                    <div className="lux-ts-entry-line__day-top">
                      <div className="lux-ts-entry-line__day-when">
                        <strong>{row.dayLabel}</strong>
                        <span
                          className={classNames(
                            "lux-ts-detail__status-pill",
                            `is-${row.statusMeta.tone}`
                          )}
                        >
                          <i className={`fe ${row.statusMeta.icon}`} aria-hidden="true" />
                          {row.statusMeta.label}
                        </span>
                      </div>
                      <strong className="lux-ts-entry-line__day-hours">{row.hoursDisplay}</strong>
                    </div>
                    <div className="lux-ts-entry-line__day-bar" aria-hidden="true">
                      <i style={{ width: `${row.mins > 0 ? Math.max(barPct, 6) : 0}%` }} />
                    </div>
                    {(row.comments || row.skill || row.quantity) && (
                      <div className="lux-ts-entry-line__day-meta">
                        {row.comments && (
                          <p>
                            <i className="fe fe-message-square" aria-hidden="true" />
                            {row.comments}
                          </p>
                        )}
                        {(row.skill || row.quantity) && (
                          <p className="lux-ts-entry-line__day-attrs">
                            {row.skill && <span>Skill · {row.skill}</span>}
                            {row.quantity && <span>Qty · {row.quantity}</span>}
                          </p>
                        )}
                      </div>
                    )}
                  </li>
                );
              })}
            </ul>
          </section>
        </div>
      </div>
    </TimesheetLuxuryDialog>
  );
}

export default TimesheetEntryDetailModal;
