import React, { Component } from "react";
import classNames from "classnames/bind";
import { REVENUE_RECOGNITION_POLICIES_META } from "config/finance-intelligence-nav.config";
import { revenueRecognitionService } from "_services/revenueRecognition.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceField,
  FinanceFormGrid,
  FinanceInsightPanel,
  FinanceLuxPanel,
  FinanceQuickNav,
  FinanceRegisterPrimary,
  FinanceRegisterWrap,
  FinanceRevRecSectionTabs,
  FinanceStatusBadge,
  FinanceToolbar,
  REV_REC_QUICK_LINKS,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

const POLICY_TYPES = [
  { value: "TIME_BASED", label: "Time based" },
  { value: "MILESTONE", label: "Milestone" },
  { value: "PERCENT_COMPLETE", label: "Percent complete" },
  { value: "MANUAL_ADJUSTMENT", label: "Manual adjustment" },
];

class RevenueRecognitionPoliciesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    rows: [],
    query: "",
    typeFilter: "ALL",
    createForm: {
      name: "",
      policyType: "TIME_BASED",
      periodCount: "3",
      milestoneCount: "2",
      percentComplete: "100",
      allowManualAdjustment: false,
      currency: "USD",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Rev-rec policies");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await revenueRecognitionService.listPolicies();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load policies"),
      });
    }
  };

  handleFormChange = (patch) => {
    this.setState({ createForm: { ...this.state.createForm, ...patch } });
  };

  handleCreate = async (event) => {
    event.preventDefault();
    const { createForm } = this.state;
    if (!createForm.name || !createForm.policyType) {
      return;
    }
    this.setState({ saving: true });
    const result = await revenueRecognitionService.createPolicy({
      name: createForm.name,
      policyType: createForm.policyType,
      periodCount: createForm.periodCount ? Number(createForm.periodCount) : null,
      milestoneCount: createForm.milestoneCount ? Number(createForm.milestoneCount) : null,
      percentComplete: createForm.percentComplete ? Number(createForm.percentComplete) : null,
      allowManualAdjustment: !!createForm.allowManualAdjustment,
      currency: createForm.currency || "USD",
    });
    this.setState({ saving: false });
    if (result.source === "api" && result.payload) {
      this.setState({
        createForm: {
          name: "",
          policyType: "TIME_BASED",
          periodCount: "3",
          milestoneCount: "2",
          percentComplete: "100",
          allowManualAdjustment: false,
          currency: "USD",
        },
      });
      this.loadData();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  getFiltered = () => {
    const { rows, query, typeFilter } = this.state;
    const q = (query || "").trim().toLowerCase();
    return rows.filter((row) => {
      if (typeFilter !== "ALL" && String(row.policyType || "").toUpperCase() !== typeFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [row.name, row.policyRef, row.policyType, row.currency]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, saving, rows, createForm, query, typeFilter } = this.state;
    const filtered = this.getFiltered();
    const activeCount = rows.filter((r) => r.active !== false).length;
    const kpiCards = [
      {
        id: "policies",
        label: "Policies",
        value: rows.length,
        hint: "Recognition methods",
        tone: "violet",
        icon: "fe fe-sliders",
      },
      {
        id: "active",
        label: "Active",
        value: activeCount,
        hint: "Available for schedules",
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "types",
        label: "Types",
        value: new Set(rows.map((r) => r.policyType).filter(Boolean)).size,
        hint: "Distinct methods",
        tone: "indigo",
        icon: "fe fe-layers",
      },
      {
        id: "manual",
        label: "Manual adj.",
        value: rows.filter((r) => r.allowManualAdjustment).length,
        hint: "Allow adjustments",
        tone: "amber",
        icon: "fe fe-edit-2",
      },
    ];

    return (
      <FinanceLuxPage
        testId="rev-rec-policies-page"
        pageMeta={REVENUE_RECOGNITION_POLICIES_META}
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        demoLabel={null}
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><FinanceActionButton
              to="/finance/revenue-recognition/schedules"
              icon="fe fe-calendar"
              variant="primary"
            >
              Generate schedule
            </FinanceActionButton>
          </>}
      >
        <FinanceRevRecSectionTabs active="/finance/revenue-recognition/policies" />
        <FinanceQuickNav
          links={REV_REC_QUICK_LINKS}
          eyebrow="Recognition workflow"
          title="Policies drive schedule generation"
        />
        <FinanceInsightPanel
          insights={[
            {
              id: "time",
              tone: "indigo",
              icon: "fe fe-clock",
              title: "Time-based",
              copy: "Split total amount evenly across periodCount months.",
            },
            {
              id: "milestone",
              tone: "green",
              icon: "fe fe-flag",
              title: "Milestone",
              copy: "Recognize when linked deliverable milestones complete.",
            },
            {
              id: "next",
              tone: "violet",
              icon: "fe fe-arrow-right",
              title: "Next: schedules",
              copy: "After creating a policy, generate a schedule with Project / PO links.",
              path: "/finance/revenue-recognition/schedules",
            },
          ]}
        />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load policies."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <FinanceLuxPanel
          title="Create policy"
          meta="Recognition method used by schedule generation"
          icon="fe fe-plus"
          accent="violet"
        >
          <form className="lux-finance-form" onSubmit={this.handleCreate}>
            <FinanceFormGrid columns={4}>
              <FinanceField label="Name" hint="Visible on schedules">
                <input
                  className="form-control"
                  value={createForm.name}
                  onChange={(e) => this.handleFormChange({ name: e.target.value })}
                  required
                  placeholder="e.g. Linear 3-month"
                  data-testid="rrp-name"
                />
              </FinanceField>
              <FinanceField label="Type">
                <select
                  className="form-control"
                  value={createForm.policyType}
                  onChange={(e) => this.handleFormChange({ policyType: e.target.value })}
                  data-testid="rrp-type"
                >
                  {POLICY_TYPES.map((t) => (
                    <option key={t.value} value={t.value}>
                      {t.label}
                    </option>
                  ))}
                </select>
              </FinanceField>
              <FinanceField label="Periods">
                <input
                  className="form-control"
                  value={createForm.periodCount}
                  onChange={(e) => this.handleFormChange({ periodCount: e.target.value })}
                />
              </FinanceField>
              <FinanceField label="Currency">
                <input
                  className="form-control"
                  value={createForm.currency}
                  onChange={(e) => this.handleFormChange({ currency: e.target.value })}
                />
              </FinanceField>
              <FinanceField label="Manual adjustment">
                <label className="lux-finance-check">
                  <input
                    type="checkbox"
                    checked={!!createForm.allowManualAdjustment}
                    onChange={(e) => this.handleFormChange({ allowManualAdjustment: e.target.checked })}
                  />
                  <span>Allow manual adjustments</span>
                </label>
              </FinanceField>
            </FinanceFormGrid>
            <div className="lux-finance-form__actions">
              <FinanceActionButton type="submit" icon="fe fe-check" variant="primary" disabled={saving || !createForm.name}>
                {saving ? "Saving…" : "Create policy"}
              </FinanceActionButton>
            </div>
          </form>
        </FinanceLuxPanel>

        <FinanceLuxPanel
          title="Policy register"
          meta={`${filtered.length} of ${rows.length} polic${rows.length === 1 ? "y" : "ies"}`}
          icon="fe fe-list"
          accent="indigo"
        >
          <FinanceToolbar
            query={query}
            onQueryChange={(value) => this.setState({ query: value })}
            placeholder="Search name, type, ref…"
            countLabel={
              <>
                <strong>{filtered.length}</strong> shown
              </>
            }
          >
            <div className="lux-hrms-dash__filter-group">
              {["ALL", ...POLICY_TYPES.map((t) => t.value)].map((value) => (
                <button
                  key={value}
                  type="button"
                  className={classNames("lux-hrms-dash__filter-chip", {
                    "is-active": typeFilter === value,
                  })}
                  onClick={() => this.setState({ typeFilter: value })}
                >
                  {value === "ALL" ? "All types" : value.replace(/_/g, " ").toLowerCase()}
                </button>
              ))}
            </div>
          </FinanceToolbar>

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading policies"
              description="Fetching recognition policy catalog."
            />
          ) : filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title={rows.length === 0 ? "No policies yet" : "No matching policies"}
              description={
                rows.length === 0
                  ? `Create a policy for team ${commonUtils.getCurrentUserTeamId()} to begin scheduling.`
                  : "Try a different search or type filter."
              }
              showCreate={false}
            />
          ) : (
            <FinanceRegisterWrap>
              <table className="lux-finance-register" data-testid="rev-rec-policies-table">
                <thead>
                  <tr>
                    <th>Policy</th>
                    <th>Type</th>
                    <th>Manual</th>
                    <th>Status</th>
                    <th>Ref</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((row) => (
                    <tr key={row.policyRef || row.id}>
                      <td>
                        <FinanceRegisterPrimary
                          title={row.name}
                          meta={row.currency || "USD"}
                          icon="fe fe-sliders"
                          tone="violet"
                        />
                      </td>
                      <td>
                        <span className="lux-finance-chip">{row.policyType || "—"}</span>
                      </td>
                      <td>
                        <FinanceStatusBadge
                          status={row.allowManualAdjustment ? "Y" : "N"}
                          label={row.allowManualAdjustment ? "Allowed" : "Off"}
                        />
                      </td>
                      <td>
                        <FinanceStatusBadge
                          status={row.active !== false}
                          label={row.active === false ? "Inactive" : "Active"}
                        />
                      </td>
                      <td>
                        <code className="lux-finance-code">{row.policyRef || row.id || "—"}</code>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </FinanceRegisterWrap>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default RevenueRecognitionPoliciesPage;
