/**
 * EMP360-004 — Performance tab is customer-visible only when org capability + live API are on.
 * Hides UI_ONLY / "coming next" placeholders from navigation.
 */
export function isEmployee360PerformanceTabLive() {
  return shouldUsePerformanceManagement() === true && shouldUsePerformanceManagementApi() === true;
}

/**
 * EMP360-005 — Finance tab is customer-visible only when org capability + live API are on.
 */
export function isEmployee360FinanceTabLive() {
  return shouldUseEmployeeFinance() === true && shouldUseEmployeeFinanceApi() === true;
}

export function isEmployee360EnvEnabled() {
  return envconfig.EMPLOYEE_360_ENABLED === true;
}

export function isEmployee360Enabled() {
  return shouldUseEmployee360();
}

export function isEmployee360RouteEnabled(menuAccessControl) {
  if (!menuAccessControl || !menuAccessControl.peopleModules) {
    return false;
  }
  return menuAccessControl.peopleModules.employee360Enabled === true;
}
