import { dashboardActions } from "_actions";
import { userUtils } from "_helpers";
import { accessUtils } from "_helpers";
import { store } from "_helpers";
import React, { Component } from "react";
import DeviceRegistrationSection from "./components/fragments/DeviceRegistrationSection";
import ScheduleListSection from "./components/fragments/ScheduleListSection";
import ServiceHealthSection from "./components/fragments/ServiceHealthSection";
import SettingsPageNav from "./components/settings/SettingsPageNav";
import {
  CompanySettingsSection,
  LocalizationSettingsSection,
  NotificationSettingsSection,
} from "./components/settings/SettingsLuxSections";
import {
  buildHeaderHealthPulse,
  resolveSettingsTabFromSearch,
} from "./components/settings/settingsTab.utils";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import HowToUseLink from "views/common/fragments/HowToUseLink";
import {
  PageDataSourceReporter,
  PageHealthPulseReporter,
} from "views/common/PageChromeContext";

const HEALTH_POLL_MS = 60000;

const TAB_META = {
  mobile: { label: "Mobile app", desc: "Pair devices for secure mobile access" },
  schedulers: { label: "Schedulers", desc: "Manage background cron jobs" },
  health: { label: "Service health", desc: "Monitor platform and integrations" },
  company: { label: "Company", desc: "Organization profile and contacts" },
  localization: { label: "Localization", desc: "Regional formats and currency" },
  notifications: { label: "Notifications", desc: "Alert channels and event preferences" },
};

class ProfileSettingsPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getProfileSettingsControl(),
      activeTab: null,
      serviceHealth: null,
      healthLoading: false,
      removingHealthId: null,
    };
    this._mounted = false;
    this._healthPollTimer = null;
  }

  isDeviceRegistrationEnabled = () => {
    const user = userUtils.getCurrentUser();
    return user && user.deviceAppEnabled === true;
  };

  getAvailableTabs = () => {
    const { permission, serviceHealth, healthLoading } = this.state;
    const tabs = [];
    const pulse = !healthLoading && serviceHealth ? buildHeaderHealthPulse(serviceHealth) : null;

    if (permission.deviceRegistrationEnabled === true && this.isDeviceRegistrationEnabled()) {
      tabs.push({ id: "mobile", label: "Mobile app", icon: "fe fe-smartphone" });
    }
    if (permission.schedulerViewEnabled === true) {
      tabs.push({ id: "schedulers", label: "Schedulers", icon: "fe fe-clock" });
    }
    if (permission.serviceHealthEnabled === true) {
      tabs.push({
        id: "health",
        label: "Service health",
        icon: "fe fe-activity",
        badge: pulse && pulse.downCount > 0 ? String(pulse.downCount) : undefined,
      });
    }
    if (permission.companySettingsEnabled === true) {
      tabs.push({ id: "company", label: "Company", icon: "fe fe-briefcase" });
    }
    if (permission.localizationSettingsEnabled === true) {
      tabs.push({ id: "localization", label: "Localization", icon: "fe fe-globe" });
    }
    if (permission.notificationSettingsEnabled === true) {
      tabs.push({ id: "notifications", label: "Notifications", icon: "fe fe-bell" });
    }

    return tabs;
  };

  resolveTabFromLocation = (tabs) => {
    const search = (this.props.location && this.props.location.search) || "";
    return resolveSettingsTabFromSearch(search, tabs);
  };

  loadServiceHealth = () => {
    if (this.state.permission.serviceHealthEnabled !== true) {
      return;
    }
    store.dispatch(
      dashboardActions.getServiceHealth((serviceHealth) => {
        if (!this._mounted) {
          return;
        }
        this.setState({
          serviceHealth: serviceHealth || {},
          healthLoading: false,
        });
      })
    );
  };

  componentDidMount() {
    this._mounted = true;
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    const tabs = this.getAvailableTabs();
    const nextState = {
      activeTab: tabs.length > 0 ? this.resolveTabFromLocation(tabs) : null,
    };
    if (this.state.permission.serviceHealthEnabled === true) {
      nextState.healthLoading = true;
      this.setState(nextState);
      this.loadServiceHealth();
      this._healthPollTimer = window.setInterval(this.loadServiceHealth, HEALTH_POLL_MS);
      return;
    }
    this.setState(nextState);
  }

  handleRemoveServer = (health) => {
    const id = health && health.id;
    if (id == null || this.state.removingHealthId != null) {
      return;
    }
    this.setState({ removingHealthId: id });
    store.dispatch(
      dashboardActions.removeServiceHealth(id, (ok) => {
        if (!this._mounted) {
          return;
        }
        this.setState({ removingHealthId: null });
        if (!ok) {
          return;
        }
        this.setState((prev) => {
          const current = prev.serviceHealth || {};
          return {
            serviceHealth: {
              ...current,
              healthStatusResponses: (current.healthStatusResponses || []).filter(
                (row) => Number(row.id) !== Number(id)
              ),
            },
          };
        });
        this.loadServiceHealth();
      })
    );
  };

  componentDidUpdate(prevProps) {
    const prevSearch = prevProps.location && prevProps.location.search;
    const nextSearch = this.props.location && this.props.location.search;
    if (prevSearch === nextSearch) {
      return;
    }
    const tabs = this.getAvailableTabs();
    const nextTab = this.resolveTabFromLocation(tabs);
    if (nextTab && nextTab !== this.state.activeTab) {
      this.setState({ activeTab: nextTab });
    }
  }

  componentWillUnmount() {
    this._mounted = false;
    if (this._healthPollTimer) {
      window.clearInterval(this._healthPollTimer);
      this._healthPollTimer = null;
    }
  }

  handleTabChange = (tabId) => {
    this.setState({ activeTab: tabId });
    const { history, location } = this.props;
    if (!history || !location || !tabId) {
      return;
    }
    const params = new URLSearchParams(location.search || "");
    if (params.get("tab") === tabId) {
      return;
    }
    params.set("tab", tabId);
    history.replace({ pathname: location.pathname, search: `?${params.toString()}` });
  };

  renderActiveSection = () => {
    const { activeTab, permission, serviceHealth, healthLoading, removingHealthId } = this.state;

    if (activeTab === "mobile" && permission.deviceRegistrationEnabled) {
      return <DeviceRegistrationSection />;
    }
    if (activeTab === "schedulers" && permission.schedulerViewEnabled) {
      return <ScheduleListSection />;
    }
    if (activeTab === "health" && permission.serviceHealthEnabled) {
      return (
        <ServiceHealthSection
          serviceHealth={serviceHealth}
          loading={healthLoading}
          removingHealthId={removingHealthId}
          onRemoveServer={this.handleRemoveServer}
        />
      );
    }
    if (activeTab === "company" && permission.companySettingsEnabled) {
      return <CompanySettingsSection />;
    }
    if (activeTab === "localization" && permission.localizationSettingsEnabled) {
      return <LocalizationSettingsSection />;
    }
    if (activeTab === "notifications" && permission.notificationSettingsEnabled) {
      return <NotificationSettingsSection />;
    }
    return null;
  };

  render() {
    const tabs = this.getAvailableTabs();
    const activeMeta = TAB_META[this.state.activeTab];
    const { serviceHealth, healthLoading, permission } = this.state;
    const healthPulse =
      permission.serviceHealthEnabled && !healthLoading && serviceHealth
        ? buildHeaderHealthPulse(serviceHealth)
        : null;

    return (
      <div className="lux-hrms-settings lux-bid-requests">
        <PageDataSourceReporter dataSource="api" />
        {healthPulse ? <PageHealthPulseReporter pulse={healthPulse} /> : null}
        <section className="lux-hrms-settings__hero" aria-label="Settings overview">
          <div className="lux-hrms-settings__hero-top" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '1rem' }}>
            <div>
              <LuxSummaryEyebrow variant="settings" className="lux-hrms-settings__eyebrow">
                Administration
              </LuxSummaryEyebrow>
              <h2 className="lux-hrms-settings__title">Workspace settings</h2>
              <p className="lux-hrms-settings__subtitle">
                Manage mobile registration, schedulers, service health, and organization preferences.
              </p>
            </div>
            <HowToUseLink href="/documentation/hrms/settings.html" testId="settings-howto-link" />
          </div>
          <div className="lux-hrms-settings__stats">
            <span>
              <strong>{tabs.length}</strong> sections available
            </span>
            {activeMeta && (
              <>
                <span className="lux-hrms-settings__dot">·</span>
                <span>
                  Viewing <strong>{activeMeta.label}</strong> — {activeMeta.desc}
                </span>
              </>
            )}
          </div>
        </section>

        <SettingsPageNav tabs={tabs} activeTab={this.state.activeTab} onChange={this.handleTabChange} />

        <div className="lux-hrms-settings__content">{this.renderActiveSection()}</div>
      </div>
    );
  }
}

export default ProfileSettingsPage;
