import React from "react";
import classNames from "classnames/bind";
import {
  formatDisplayValue,
  formatProfileDate,
} from "./profilePage.utils";
import ProfileSection from "./ProfileSection";

function ProfileField({ label, value, icon, fullWidth }) {
  const display = value || "—";
  return (
    <div className={classNames("profile-field", { "profile-field--full": fullWidth })}>
      <span className="profile-field__label">{label}</span>
      <span className="profile-field__value">
        {icon && <i className={`${icon} profile-field__icon`} aria-hidden="true" />}
        {display}
      </span>
    </div>
  );
}

function ProfileChipList({ items }) {
  if (!items || !items.length) {
    return <p className="profile-section__empty">No items recorded</p>;
  }
  return (
    <div className="profile-chip-list">
      {items.map((item) => (
        <span key={item} className="profile-chip">
          {item}
        </span>
      ))}
    </div>
  );
}

function ProfilePersonalView({ employee }) {
  if (!employee) return null;

  const domains = formatDisplayValue(employee.domains);
  const certifications = formatDisplayValue(employee.certifications);

  const loginFlags = [
    {
      label: "App login",
      enabled: employee.appLoginDisabled === false || employee.appLoginDisabled === "false",
      icon: "fe fe-smartphone",
    },
    {
      label: "Device login",
      enabled: employee.deviceAppEnabled === true || employee.deviceAppEnabled === "true",
      icon: "fe fe-tablet",
    },
    {
      label: "Leave sync",
      enabled: employee.extLeaveSyncEnabled === true || employee.extLeaveSyncEnabled === "true",
      icon: "fe fe-refresh-cw",
    },
  ];

  return (
    <div className="profile-personal lux-settings-tab__stack">
      <ProfileSection
        title="Contact"
        subtitle="Reach this employee — designation and role are shown in the summary above"
        icon="fe fe-mail"
      >
        <div className="profile-field-grid profile-field-grid--3">
          <ProfileField label="Email" value={employee.email} icon="fe fe-mail" />
          <ProfileField label="Mobile" value={employee.mobileNumber} icon="fe fe-phone" />
          <ProfileField label="Location" value={formatDisplayValue(employee.location)} icon="fe fe-map-pin" />
          <ProfileField label="Gender" value={formatDisplayValue(employee.gender)} />
          <ProfileField label="Date of birth" value={formatProfileDate(employee.dateOfBirth)} icon="fe fe-gift" />
          <ProfileField label="Qualification" value={formatDisplayValue(employee.qualification)} />
        </div>
      </ProfileSection>

      <ProfileSection
        title="Employment & reporting"
        subtitle="Official role, hierarchy, and level — teams in the sidebar; dates in the summary above"
        icon="fe fe-briefcase"
      >
        <div className="profile-field-grid profile-field-grid--3">
          <ProfileField label="Employee type" value={formatDisplayValue(employee.empType)} />
          <ProfileField label="Date of joining" value={formatProfileDate(employee.dateOfJoin)} icon="fe fe-calendar" />
          <ProfileField
            label="Exit date"
            value={employee.exitDate ? formatProfileDate(employee.exitDate) : "—"}
          />
          <ProfileField
            label="Reporting manager"
            value={(employee.managerDetails && employee.managerDetails.name) || "—"}
          />
          <ProfileField
            label="User role"
            value={(employee.userAccessDetails && employee.userAccessDetails.name) || "—"}
            icon="fe fe-shield"
          />
          <ProfileField
            label="Department lead"
            value={(employee.departmentLeadDetails && employee.departmentLeadDetails.name) || "—"}
          />
          <ProfileField
            label="LOB head"
            value={(employee.lobHeadDetails && employee.lobHeadDetails.name) || "—"}
          />
          <ProfileField label="Band" value={formatDisplayValue(employee.band)} />
          <ProfileField label="Grade" value={formatDisplayValue(employee.grade)} />
        </div>
      </ProfileSection>

      <ProfileSection
        title="Practice & delivery"
        subtitle="Client and organizational placement — service lines are in the sidebar"
        icon="fe fe-layers"
      >
        <div className="profile-field-grid profile-field-grid--2">
          <ProfileField label="Primary practice" value={formatDisplayValue(employee.department)} fullWidth />
          <ProfileField label="Secondary practice" value={formatDisplayValue(employee.subDepartment)} fullWidth />
          <ProfileField label="Division" value={formatDisplayValue(employee.division)} />
          <ProfileField label="Service category" value={formatDisplayValue(employee.serviceCategory)} />
          <ProfileField label="Primary client" value={formatDisplayValue(employee.primaryClient)} fullWidth />
        </div>
      </ProfileSection>

      <ProfileSection
        title="Credentials"
        subtitle="Domains and certifications — skills are in the summary above"
        icon="fe fe-award"
      >
        <div className="profile-subblock">
          <span className="profile-subblock__label">Domains</span>
          <ProfileChipList items={domains ? domains.split(", ") : []} />
        </div>
        <div className="profile-subblock">
          <span className="profile-subblock__label">Certifications</span>
          <ProfileChipList items={certifications ? certifications.split(", ") : []} />
        </div>
      </ProfileSection>

      <ProfileSection
        title="Platform access"
        subtitle="System login and integration flags — summary shows active count only"
        icon="fe fe-key"
      >
        <ul className="profile-flag-list">
          {loginFlags.map((flag) => (
            <li
              key={flag.label}
              className={classNames("profile-flag", { "is-on": flag.enabled, "is-off": !flag.enabled })}
            >
              <i className={flag.icon} aria-hidden="true" />
              <span>{flag.label}</span>
              <strong>{flag.enabled ? "Enabled" : "Disabled"}</strong>
            </li>
          ))}
        </ul>
      </ProfileSection>
    </div>
  );
}

export default ProfilePersonalView;
