import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

export default function OffboardingAssetBlockersPanel({ blockers }) {
  if (!blockers || blockers.length === 0) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        icon="fe fe-check-circle"
        title="No offboarding blockers"
        description="All assigned assets are cleared or returned for departing employees."
      />
    );
  }

  return (
    <div className="lux-asset-blockers">
      <p className="lux-asset-blockers__intro">
        These assigned assets must be returned before offboarding settlement can complete. Linked to{" "}
        <Link to="/people/offboarding">offboarding cases</Link>.
      </p>
      <div className="lux-doc-register-wrap">
        <table className="lux-doc-register">
          <thead>
            <tr>
              <th>Asset</th>
              <th>Assignee</th>
              <th>Tag</th>
              <th>Status</th>
              <th>Blocker</th>
            </tr>
          </thead>
          <tbody>
            {blockers.map((row) => (
              <tr key={row.id}>
                <td><strong>{row.name}</strong></td>
                <td>{row.assigneeName || "—"}</td>
                <td>{row.tag || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", {
                    "is-warning": row.status === "Assigned" || row.status === "In repair",
                  })}
                  >
                    {row.status}
                  </span>
                </td>
                <td>
                  {row.offboardingBlocker ? (
                    <span className="lux-asset-blockers__flag">Must return</span>
                  ) : (
                    "—"
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
