import { employeeActions } from "_actions";
import workItemUtils from "_helpers/workitem.utils";
import { workItemConstants } from "_constants";
import { workItemService } from "_services/workitem.service";
import { getApiErrorMessage } from "_helpers/apiError.utils";
import {
  refreshTimesheetAuditPanels,
  resolveTimesheetAuditRefreshTargets,
} from "_helpers/timesheetAudit.utils";
let leaveSynInProgress = false

class TimesheetPage extends Component {
 
  constructor() {
    super();
    this.timesheetLoadSeq = 0;
    this.deadlinePreviewSeq = 0;
    this.lastAppliedApprovalReviewSearch = null;
    this.state = {
      addEntryOpen: false,
      addEntrySession: 0,
      permission: accessUtils.getTimeSheetAccessControl(),
      selectedDate: dateUtils.getCurrentTime(),
      applicableDates: [],
      //selectedEmployeeIds: [commonUtils.getCurrentUserId()],
      selectedEmployee: commonUtils.getCurrentUser(),
      syncLeavesInProgress : false,
      submitInProgress: false,
      timesheetGovernance: null,
      deadlinePreview: null,
      discardInProgress: false,
      discardConfirm: null,
      pendingWeeks: [],
      pendingLoading: false,
      approvalActionInProgress: false,
      conflictCounts: {},
      conflictModal: {
        show: false,
        week: null,
        conflicts: [],
        loading: false,
      },
      defaulters: [],
      defaultersLoading: false,
      lockInProgress: false,
      unlockInProgress: false,
      reopenInProgress: false,
      actingDelegations: [],
      intelligenceEnabled: isTimesheetIntelligenceEnabled(),
      activeView: "board",
      intelligence: null,
      billability: null,
      recommendation: null,
      intelligenceLoading: false,
      agentActionLog: [],
      approvalReviewContext: null,
      auditRefreshKey: 0,
    }
  }

  bumpTimesheetAuditRefresh = (stateOverride) => {
    const source = stateOverride || this.state;
    refreshTimesheetAuditPanels(resolveTimesheetAuditRefreshTargets(source));
    this.setState((prev) => ({ auditRefreshKey: prev.auditRefreshKey + 1 }));
  };
  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name)
    this.handleTimesheetApprovalConfigChanged = () => {
      this.refreshTimesheetPermission();
    };
    this.handleApprovalDelegationConfigChanged = () => {
      this.refreshTimesheetPermission(() => {
        this.loadActingDelegations();
      });
    };
    window.addEventListener(
      TIMESHEET_APPROVAL_CONFIG_CHANGED,
      this.handleTimesheetApprovalConfigChanged
    );
    window.addEventListener(
      APPROVAL_DELEGATION_CONFIG_CHANGED,
      this.handleApprovalDelegationConfigChanged
    );
    Promise.all([loadTimesheetApprovalConfig(), loadApprovalDelegationConfig()]).then(() => {
      this.refreshTimesheetPermission(() => {
        this.loadActingDelegations().then(() => {
          this.loadPendingApprovals();
          this.loadDefaulters();
        });
      });
    });
    this.handleDateChange(dateUtils.getCurrentTime())
    if (this.state.permission.switchEmployeesEnabled === true) {
      this.loadEmployeeList(commonUtils.getUserTeams(this.props.userTeams))
    }
    this.applyApprovalReviewFromLocation();
  }

  componentDidUpdate(prevProps) {
    const prevSearch = prevProps.location && prevProps.location.search;
    const nextSearch = this.props.location && this.props.location.search;
    const employeesLoaded =
      (!prevProps.employees || !prevProps.employees.length) &&
      this.props.employees &&
      this.props.employees.length;
    if (prevSearch !== nextSearch || employeesLoaded) {
      this.applyApprovalReviewFromLocation();
    }
  }

  applyApprovalReviewFromLocation = () => {
    const search = this.props.location && this.props.location.search;
    if (!search || !search.includes("approvalReview=1")) {
      return;
    }
    if (this.lastAppliedApprovalReviewSearch === search) {
      return;
    }

    let reviewContext = parseTimesheetApprovalReviewSearch(search);
    if (!reviewContext || reviewContext.employeeId == null || !reviewContext.weekStartDate) {
      return;
    }

    const pendingWeek = (this.state.pendingWeeks || []).find((week) => {
      if (String(week.employeeId) !== String(reviewContext.employeeId)) {
        return false;
      }
      if (
        reviewContext.submissionId != null &&
        week.submissionId != null &&
        String(week.submissionId) === String(reviewContext.submissionId)
      ) {
        return true;
      }
      if (reviewContext.weekId != null && String(week.id) === String(reviewContext.weekId)) {
        return true;
      }
      return false;
    });
    if (pendingWeek) {
      reviewContext = buildApprovalReviewContext(pendingWeek);
    }

    const employees = this.props.employees || [];
    const employee =
      employees.find((item) => String(item.id) === String(reviewContext.employeeId)) ||
      {
        id: reviewContext.employeeId,
        name:
          (pendingWeek && pendingWeek.employeeName) ||
          reviewContext.employeeName ||
          `Employee #${reviewContext.employeeId}`,
      };

    const weekStart = dateUtils.convertDateToMoment(reviewContext.weekStartDate);
    if (!weekStart || !weekStart.isValid()) {
      return;
    }

    this.lastAppliedApprovalReviewSearch = search;
    this.setState({ selectedEmployee: employee, approvalReviewContext: reviewContext }, () => {
      this.handleDateChange(weekStart, employee, { preserveApprovalReview: true });
    });
  };

  componentWillUnmount() {
    if (this.handleTimesheetApprovalConfigChanged) {
      window.removeEventListener(
        TIMESHEET_APPROVAL_CONFIG_CHANGED,
        this.handleTimesheetApprovalConfigChanged
      );
    }
    if (this.handleApprovalDelegationConfigChanged) {
      window.removeEventListener(
        APPROVAL_DELEGATION_CONFIG_CHANGED,
        this.handleApprovalDelegationConfigChanged
      );
    }
  }

  loadIntelligenceContext = (options = {}) => {
    if (!this.state.intelligenceEnabled) {
      return Promise.resolve(null);
    }

    const userTeamIds = this.resolveTimesheetUserTeamIds();
    const userTeamId = userTeamIds && userTeamIds.length ? userTeamIds[0] : null;
    const weekStartDate = this.getSelectedWeekStartParam();
    const context = {
      timeSheetRequest: this.state.timeSheetRequest,
      applicableDates: this.state.applicableDates,
      employees: this.props.employees,
      defaulters: this.state.defaulters,
      pendingWeeks: this.state.pendingWeeks,
      conflictCounts: this.state.conflictCounts,
      userTeamId,
      weekStartDate,
    };

    // Avoid UI flicker: only show the loading skeleton when we have nothing to display,
    // or when the caller explicitly requests it (week / employee change).
    const showLoading =
      options.forceLoading === true || !this.state.recommendation;
    if (options.forceLoading === true) {
      // Week/employee changed — drop stale suggestion so we don't flash prior week's AI.
      this.setState({
        intelligenceLoading: true,
        recommendation: null,
        intelligence: null,
        billability: null,
      });
    } else if (showLoading) {
      this.setState({ intelligenceLoading: true });
    }

    const requestSeq = (this._intelligenceRequestSeq = (this._intelligenceRequestSeq || 0) + 1);

    return timesheetIntelligenceService
      .getIntelligenceBundle(context)
      .then(({ intelligence, billability, recommendation }) => {
        if (requestSeq !== this._intelligenceRequestSeq) {
          return null;
        }
        const failed = intelligence && intelligence.source === "api-error";
        const billabilityFailed = billability && billability.source === "api-error";
        const recommendationFailed = recommendation && recommendation.source === "api-error";
        this.setState({
          intelligence: failed ? null : intelligence,
          billability: failed || billabilityFailed ? null : billability,
          recommendation: failed || recommendationFailed ? null : recommendation,
          intelligenceLoading: false,
        });
        return failed ? null : intelligence;
      })
      .catch(() => {
        if (requestSeq !== this._intelligenceRequestSeq) {
          return null;
        }
        this.setState({ intelligenceLoading: false });
        return null;
      });
  };

  handleViewChange = (viewId) => {
    this.setState({ activeView: viewId });
  };

  handleAgentDraftAction = (action, recommendation) => {
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    const context = {
      timeSheetRequest: this.state.timeSheetRequest,
      userTeamId: userTeamIds && userTeamIds.length ? userTeamIds[0] : null,
      weekStartDate: this.getSelectedWeekStartParam(),
    };

    Promise.resolve(applyAgentDraftAction(recommendation, action, context)).then((entry) => {
      if (!entry) return;

      const nextRecommendation = recommendation
        ? {
            ...recommendation,
            decision: entry.action,
            decisionAt: entry.at,
            decisionMessage: entry.message,
            draftOnly: false,
          }
        : null;

      this.setState((prev) => ({
        recommendation: nextRecommendation,
        agentActionLog: [entry, ...(prev.agentActionLog || [])].slice(0, 5),
      }));

      if (entry.action === "accept") {
        store.dispatch(
          notificationActions.success(
            entry.nextStep ||
              "Recommendation accepted for this session — timesheet hours and status are unchanged."
          )
        );
        if (
          recommendation &&
          ["backfill_days", "reduce_leakage", "monitor"].includes(recommendation.primaryAction)
        ) {
          this.setState({ activeView: "board" });
        }
      } else if (entry.action === "reject") {
        store.dispatch(notificationActions.warning("Recommendation dismissed for this week."));
      } else if (entry.action === "defer") {
        store.dispatch(notificationActions.info("Recommendation deferred — you can revisit it later."));
      }
    });
  };

  refreshTimesheetPermission = (callback) => {
    this.setState({ permission: accessUtils.getTimeSheetAccessControl() }, () => {
      if (callback) callback();
    });
  }

  loadActingDelegations = () => {
    if (!shouldUseApprovalDelegation()) {
      this.setState({ actingDelegations: [] });
      return Promise.resolve([]);
    }
    const delegateId = commonUtils.getCurrentUserId();
    if (!delegateId) {
      this.setState({ actingDelegations: [] });
      return Promise.resolve([]);
    }
    return approvalDelegationService
      .listActing(delegateId)
      .then((response) => {
        const actingDelegations = (response && response.payload) || [];
        this.setState({ actingDelegations });
        return actingDelegations;
      })
      .catch(() => {
        this.setState({ actingDelegations: [] });
        return [];
      });
  };

  loadPendingApprovals = () => {
    const permission = this.state.permission || accessUtils.getTimeSheetAccessControl();
    if (!isTimesheetApprovalActor(permission, this.state.actingDelegations)) {
      this.setState({ pendingWeeks: [], conflictCounts: {} });
      return Promise.resolve([]);
    }

    const managerId = commonUtils.getCurrentUserId();
    // Prefer all manager teams (same as /approvals inbox) so selected-team
    // filter cannot hide pending submissions from other teams.
    const userTeamIds = this.resolvePendingApprovalUserTeamIds();
    if (!userTeamIds.length) {
      this.setState({ pendingWeeks: [], conflictCounts: {}, pendingLoading: false });
      store.dispatch(
        notificationActions.warning(
          "Select a team (or ensure your default team is set) to load pending timesheet approvals."
        )
      );
      return Promise.resolve([]);
    }

    this.setState({ pendingLoading: true });
    return store
      .dispatch(timesheetApprovalActions.loadPendingApprovals(userTeamIds, managerId))
      .then((weeks) => {
        const pendingWeeks = weeks || [];
        this.setState({ pendingWeeks, pendingLoading: false }, () => {
          this.refreshConflictCounts(pendingWeeks);
          if (this.state.intelligenceEnabled) {
            this.loadIntelligenceContext();
          }
          if (
            this.props.location &&
            this.props.location.search &&
            this.props.location.search.includes("approvalReview=1")
          ) {
            this.lastAppliedApprovalReviewSearch = null;
            this.applyApprovalReviewFromLocation();
          }
        });
        return pendingWeeks;
      })
      .catch((error) => {
        this.setState({ pendingLoading: false });
        const message =
          (error && error.message) || "Unable to load pending timesheet approvals.";
        store.dispatch(notificationActions.error(message));
        return [];
      });
  };

  refreshConflictCounts = (weeks) => {
    const pendingWeeks = weeks || this.state.pendingWeeks || [];
    if (!pendingWeeks.length) {
      this.setState({ conflictCounts: {} });
      return Promise.resolve({});
    }

    const toIsoDate = (value) => {
      if (!value) return null;
      if (typeof value === "string") {
        return value.length >= 10 ? value.slice(0, 10) : value;
      }
      try {
        return new Date(value).toISOString().slice(0, 10);
      } catch (e) {
        return null;
      }
    };

    return Promise.all(
      pendingWeeks.map((week) =>
        timesheetApprovalService
          .listConflicts(week.id)
          .then((response) => {
            const conflicts = (response && response.payload) || [];
            let count = conflicts.length;
            if (week.submissionId && Array.isArray(week.activityDates) && week.activityDates.length) {
              const dateSet = new Set(
                week.activityDates.map((d) => toIsoDate(d)).filter(Boolean)
              );
              count = conflicts.filter((conflict) => {
                const conflictDate = toIsoDate(conflict.activityDate);
                return conflictDate && dateSet.has(conflictDate);
              }).length;
            }
            const key = pendingTimesheetConflictKey(week);
            return { key, count };
          })
          .catch(() => ({
            key: pendingTimesheetConflictKey(week),
            count: 0,
          }))
      )
    ).then((results) => {
      const conflictCounts = results.reduce((acc, item) => {
        if (item.key) {
          acc[item.key] = item.count;
        }
        return acc;
      }, {});
      this.setState({ conflictCounts });
      return conflictCounts;
    });
  };

  openConflictModal = (week) => {
    if (!week || !week.id) return;
    this.setState({
      conflictModal: {
        show: true,
        week,
        conflicts: [],
        loading: true,
      },
    });
    this.refreshConflictModal(week);
  };

  closeConflictModal = () => {
    this.setState({
      conflictModal: {
        show: false,
        week: null,
        conflicts: [],
        loading: false,
      },
    });
  };

  refreshConflictModal = (week) => {
    const targetWeek = week || (this.state.conflictModal && this.state.conflictModal.week);
    if (!targetWeek || !targetWeek.id) return Promise.resolve([]);

    return store
      .dispatch(timesheetApprovalActions.loadConflicts(targetWeek.id))
      .then((conflicts) => {
        let list = conflicts || [];
        const toIsoDate = (value) => {
          if (!value) return null;
          if (typeof value === "string") {
            return value.length >= 10 ? value.slice(0, 10) : value;
          }
          try {
            return new Date(value).toISOString().slice(0, 10);
          } catch (e) {
            return null;
          }
        };
        if (
          targetWeek.submissionId &&
          Array.isArray(targetWeek.activityDates) &&
          targetWeek.activityDates.length
        ) {
          const dateSet = new Set(
            targetWeek.activityDates.map((d) => toIsoDate(d)).filter(Boolean)
          );
          list = list.filter((conflict) => {
            const conflictDate = toIsoDate(conflict.activityDate);
            return conflictDate && dateSet.has(conflictDate);
          });
        }
        const conflictKey = pendingTimesheetConflictKey(targetWeek);
        this.setState((prevState) => ({
          conflictModal: {
            ...prevState.conflictModal,
            week: targetWeek,
            conflicts: list,
            loading: false,
          },
          conflictCounts: {
            ...prevState.conflictCounts,
            ...(conflictKey ? { [conflictKey]: list.length } : {}),
          },
        }));
        return list;
      })
      .catch(() => {
        this.setState((prevState) => ({
          conflictModal: {
            ...prevState.conflictModal,
            loading: false,
          },
        }));
        return [];
      });
  };

  handleResolveConflict = (conflictId, payload) =>
    store.dispatch(timesheetApprovalActions.resolveConflict(conflictId, payload));

  handleApproveTimesheetWeek = (week, approvalComment) => {
    if (!week || !week.id) return;
    const conflictKey = pendingTimesheetConflictKey(week);
    const conflictCount = conflictKey ? this.state.conflictCounts[conflictKey] : 0;
    if (conflictCount > 0) {
      store.dispatch(
        notificationActions.warning("Resolve open conflicts before approving this timesheet.")
      );
      this.openConflictModal(week);
      return;
    }

    const approverId = commonUtils.getCurrentUserId();
    this.setState({ approvalActionInProgress: true });
    store
      .dispatch(timesheetApprovalActions.approveWeek(week, approverId, approvalComment))
      .then(() => {
        this.clearApprovalReviewContextForWeek(week);
        this.loadPendingApprovals();
        this.bumpTimesheetAuditRefresh();
        if (
          this.state.selectedEmployee &&
          String(this.state.selectedEmployee.id) === String(week.employeeId)
        ) {
          this.handleDateChange(this.state.selectedDate);
        }
      })
      .finally(() => {
        this.setState({ approvalActionInProgress: false });
      });
  };

  handleRejectTimesheetWeek = (week, rejectionComment) => {
    if (!week || !week.id) return;
    const approverId = commonUtils.getCurrentUserId();
    this.setState({ approvalActionInProgress: true });
    store
      .dispatch(timesheetApprovalActions.rejectWeek(week, approverId, rejectionComment))
      .then(() => {
        this.clearApprovalReviewContextForWeek(week);
        this.loadPendingApprovals();
        this.bumpTimesheetAuditRefresh();
        if (
          this.state.selectedEmployee &&
          String(this.state.selectedEmployee.id) === String(week.employeeId)
        ) {
          this.handleDateChange(this.state.selectedDate);
        }
      })
      .finally(() => {
        this.setState({ approvalActionInProgress: false });
      });
  };

  getSelectedWeekStartParam = () => {
    const weekStart = this.state.selectedDate
      ? this.state.selectedDate.clone().startOf("isoWeek")
      : dateUtils.getCurrentTime().clone().startOf("isoWeek");
    return weekStart.format(dateUtils.SERVER_DATE_FORMAT);
  };

  loadDefaulters = () => {
    const permission = this.state.permission || accessUtils.getTimeSheetAccessControl();
    if (!isManagerTimesheetApprover(permission)) {
      this.setState({ defaulters: [] });
      return Promise.resolve([]);
    }

    // Scope to the team picker (same as board / employee list). Pending inbox
    // still uses resolvePendingApprovalUserTeamIds() for all manager teams.
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    const weekStartDate = this.getSelectedWeekStartParam();

    this.setState({ defaultersLoading: true });
    return store
      .dispatch(timesheetApprovalActions.loadDefaulters(userTeamIds, weekStartDate))
      .then((rows) => {
        this.setState({ defaulters: rows || [], defaultersLoading: false }, () => {
          if (this.state.intelligenceEnabled) {
            this.loadIntelligenceContext();
          }
        });
        return rows;
      })
      .catch(() => {
        this.setState({ defaultersLoading: false });
        return [];
      });
  };

  handleUnlockCurrentWeek = () => {
    const { timeSheetRequest, selectedDate } = this.state;
    if (!timeSheetRequest || !timeSheetRequest.weekId) {
      return;
    }
    const actorId = commonUtils.getCurrentUserId();
    this.setState({ unlockInProgress: true });
    store
      .dispatch(
        timesheetApprovalActions.unlockWeeks({
          actorId,
          weekIds: [timeSheetRequest.weekId],
        })
      )
      .then(() => {
        this.handleDateChange(selectedDate);
        this.loadDefaulters();
      })
      .finally(() => {
        this.setState({ unlockInProgress: false });
      });
  };

  handleReopenCurrentWeek = (submissionId, reopenReason) => {
    const { timeSheetRequest, selectedDate } = this.state;
    if (!timeSheetRequest || !timeSheetRequest.weekId) {
      return;
    }
    const actorId = commonUtils.getCurrentUserId();
    this.setState({ reopenInProgress: true });
    store
      .dispatch(
        timesheetApprovalActions.reopenWeek(
          timeSheetRequest.weekId,
          actorId,
          submissionId,
          reopenReason
        )
      )
      .then(() => {
        this.handleDateChange(selectedDate);
        this.loadDefaulters();
        this.bumpTimesheetAuditRefresh();
      })
      .finally(() => {
        this.setState({ reopenInProgress: false });
      });
  };

  handleLockPayrollWeek = () => {
    const actorId = commonUtils.getCurrentUserId();
    // Match Compliance defaulters scope — selected team only, not all manager teams.
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    const weekStartDate = this.getSelectedWeekStartParam();

    this.setState({ lockInProgress: true });
    store
      .dispatch(
        timesheetApprovalActions.lockWeeks({
          actorId,
          userTeamIds,
          weekStartDate,
          payrollProcessed: true,
        })
      )
      .then(() => {
        this.handleDateChange(this.state.selectedDate);
        this.loadPendingApprovals();
        this.loadDefaulters();
      })
      .finally(() => {
        this.setState({ lockInProgress: false });
      });
  };

  handleViewPendingWeek = (week) => {
    if (!week) return;
    const employees = this.props.employees || [];
    const employee =
      employees.find((item) => String(item.id) === String(week.employeeId)) ||
      (week.employeeId
        ? { id: week.employeeId, name: week.employeeName || `Employee #${week.employeeId}` }
        : null);
    if (!employee) return;

    const weekStart = week.weekStartDate
      ? dateUtils.convertDateToMoment(week.weekStartDate)
      : this.state.selectedDate;
    const approvalReviewContext = buildApprovalReviewContext(week);

    this.setState({ selectedEmployee: employee, approvalReviewContext }, () => {
      this.handleDateChange(
        weekStart && weekStart.isValid() ? weekStart : this.state.selectedDate,
        employee,
        { preserveApprovalReview: true }
      );
    });
  };

  handleDismissApprovalReview = () => {
    this.setState({ approvalReviewContext: null });
  };

  clearApprovalReviewContextForWeek = (week) => {
    const context = this.state.approvalReviewContext;
    if (!context || !week || week.id == null) {
      return;
    }
    if (String(context.weekId) !== String(week.id)) {
      return;
    }
    if (
      context.submissionId != null &&
      week.submissionId != null &&
      String(context.submissionId) !== String(week.submissionId)
    ) {
      return;
    }
    this.setState({ approvalReviewContext: null });
  };

  resolveApprovalReviewContextForNavigation = (date, employee, options = {}) => {
    const context = this.state.approvalReviewContext;
    if (!context || options.preserveApprovalReview) {
      return context;
    }
    if (!employee || employee.id == null) {
      return null;
    }
    const weekStart = date.clone().startOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT);
    const sameEmployee = String(employee.id) === String(context.employeeId);
    const sameWeek =
      !context.weekStartDate || toIsoDate(context.weekStartDate) === toIsoDate(weekStart);
    return sameEmployee && sameWeek ? context : null;
  };

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({ type: workItemConstants.INITIALIZE_TIME_SHEET_USER_TEAMS, userTeams });
    this.setState({ timesheetGovernance: null, deadlinePreview: null }, () => {
      this.loadEmployeeList(userTeams);
      this.loadPendingApprovals();
      this.loadDefaulters();
      this.loadDeadlinePreview();
    });
  }

  loadEmployeeList = (userTeams) => {
    const selected = commonUtils.getSelectedUserTeamIds(userTeams);
    const userTeamIds = commonUtils.resolveUserTeamIds(
      selected.length ? selected : null
    );
    if (!userTeamIds.length) {
      return;
    }
    store.dispatch(this.props.getTeamsEmployees(userTeamIds));
  }

  syncLeavesHandler = () => {
    if (leaveSynInProgress === true) {
      return;
    }
    leaveSynInProgress = true;
    if (this.state.selectedEmployee && this.state.selectedEmployee.extLeaveSyncEnabled === true && this.state.selectedEmployee.empCode) {
      const startDate = this.state.selectedDate.clone().startOf('isoWeek').format(dateUtils.SERVER_DATE_FORMAT);
      const endDate = this.state.selectedDate.clone().endOf('isoWeek').format(dateUtils.SERVER_DATE_FORMAT);
      this.setState({
        syncLeavesInProgress: true
      })
      store.dispatch(this.props.syncEmployeeLeaves(this.state.selectedEmployee, startDate, endDate, (employeeLeavesSyncResponse) => {
        leaveSynInProgress = false;
        this.setState({
          syncLeavesInProgress: false
        })
       
        if (employeeLeavesSyncResponse && employeeLeavesSyncResponse.payload && employeeLeavesSyncResponse.payload.length > 0) {
          this.handleDateChange(this.state.selectedDate);
        }
      }))
    } 
  }

  resolveSelectedEmployee = (selectedEmployees) => {
    const picked = commonUtils.getSelectedEmployee(selectedEmployees);
    if (!picked || !picked.id) {
      return null;
    }
    const fromTeamList =
      this.props.employees &&
      this.props.employees.find(
        (employee) => String(employee.id) === String(picked.id)
      );
    return fromTeamList ? { ...fromTeamList } : { ...picked };
  };

  handleEmployeesSelection = (selectedEmployees) => {
    const selectedEmployee = this.resolveSelectedEmployee(selectedEmployees);
    if (!selectedEmployee) {
      return;
    }
    const approvalReviewContext = this.resolveApprovalReviewContextForNavigation(
      this.state.selectedDate,
      selectedEmployee
    );
    this.setState({ selectedEmployee, approvalReviewContext }, () => {
      this.handleDateChange(this.state.selectedDate, selectedEmployee, {
        preserveApprovalReview: !!approvalReviewContext,
      });
    });
  };

  updateTimeSheetRequest = (timeSheetRequest, options = {}) => {
    // Do not refresh AI suggestions on every cell/hour edit — that flashes the
    // recommendation panel. Soft-refresh only when a full week payload is loaded.
    this.setState({ timeSheetRequest }, () => {
      if (options.refreshIntelligence && this.state.intelligenceEnabled) {
        this.loadIntelligenceContext();
      }
    });
  }

  resetTimeSheet = () => {
    this.handleDateChange(this.state.selectedDate);
  }

  /**
   * Discard / reset action dock:
   * - unsaved local edits → reload from server
   * - pending week → withdraw submission back to editable draft (hours kept)
   * - saved draft/ready → clear all hours and save
   */
  closeDiscardConfirm = () => {
    this.setState({ discardConfirm: null });
  };

  handleDiscardTimesheet = ({ hasUnsavedChanges, weekPending } = {}) => {
    const { timeSheetRequest } = this.state;
    if (hasUnsavedChanges) {
      this.resetTimeSheet();
      return;
    }
    if (weekPending) {
      if (!timeSheetRequest || !timeSheetRequest.weekId) {
        store.dispatch(notificationActions.warning("No pending timesheet to withdraw."));
        return;
      }
      this.setState({ discardConfirm: { type: "withdraw" } });
      return;
    }
    this.setState({ discardConfirm: { type: "clear" } });
  };

  confirmDiscardTimesheet = () => {
    const { discardConfirm, timeSheetRequest, selectedDate } = this.state;
    const confirmType = discardConfirm && discardConfirm.type;

    if (confirmType === "withdraw") {
      this.setState({ discardConfirm: null });
      if (!timeSheetRequest || !timeSheetRequest.weekId) {
        store.dispatch(notificationActions.warning("No pending timesheet to withdraw."));
        return;
      }
      const actorId = commonUtils.getCurrentUserId();
      this.setState({ discardInProgress: true });
      timesheetApprovalService
        .withdrawWeek(timeSheetRequest.weekId, actorId)
        .then(() => {
          store.dispatch(notificationActions.success("Timesheet withdrawn — you can edit and resubmit."));
          this.handleDateChange(selectedDate);
          this.loadPendingApprovals();
          this.bumpTimesheetAuditRefresh();
        })
        .catch((error) => {
          const message =
            (error && error.message) || error || "Unable to withdraw timesheet.";
          store.dispatch(notificationActions.error(message));
        })
        .finally(() => {
          this.setState({ discardInProgress: false });
        });
      return;
    }

    if (confirmType === "clear") {
      if (!hasClearableDraftTimesheetHours(timeSheetRequest)) {
        this.setState({ discardConfirm: null });
        store.dispatch(
          notificationActions.warning(
            "No draft hours to clear. Approved and pending-approval days stay locked."
          )
        );
        return;
      }
      const cleared = buildClearDraftTimesheetPayload(timeSheetRequest);
      this.setState({ discardInProgress: true });
      this.persistClearDraftTimesheet(cleared)
        .then(() => {
          store.dispatch(notificationActions.success("Draft timesheet hours cleared."));
          this.setState({ discardConfirm: null });
          this.handleDateChange(selectedDate);
        })
        .catch((error) => {
          store.dispatch(
            notificationActions.error(getApiErrorMessage(error, "Unable to clear timesheet hours."))
          );
        })
        .finally(() => {
          this.setState({ discardInProgress: false });
        });
    }
  };

  persistClearDraftTimesheet = (clearedPayload) => {
    const date = this.state.selectedDate;
    const startDate = date.clone().startOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = date.clone().endOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT);
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    const currentEmployeeId = commonUtils.getCurrentUserId();
    if (!userTeamIds.length) {
      return Promise.reject(
        new Error("Cannot save timesheet: no team is selected. Set your default team and try again.")
      );
    }
    if (!this.state.selectedEmployee || !this.state.selectedEmployee.id) {
      return Promise.reject(new Error("Select an employee before saving the timesheet."));
    }
    return workItemService
      .addTimesheetData({
        startDate,
        endDate,
        employeeIds: [this.state.selectedEmployee.id],
        currentEmployeeId,
        userTeamIds,
        payload: clearedPayload,
      })
      .then((response) => {
        const payload = response && response.payload;
        if (payload) {
          this.updateTimeSheetRequest(payload);
        }
        return payload;
      });
  };

  handleSubmitTimesheet = (timeSheetOverride, activityDates, lateReasonPayload) => {
    const { selectedDate, permission } = this.state;
    const timeSheetRequest = timeSheetOverride || this.state.timeSheetRequest;
    if (!isTimesheetApprovalWorkflowActive(timeSheetRequest, permission)) {
      store.dispatch(
        notificationActions.warning(
          "Timesheet approval is disabled for this team. Save timesheet directly — submit is not required."
        )
      );
      return;
    }
    if (!timeSheetRequest || !timeSheetRequest.weekId) {
      store.dispatch(
        notificationActions.warning("Save your draft before submitting for approval.")
      );
      return;
    }
    const actorId = commonUtils.getCurrentUserId();
    const submitFn = isResubmitAction(timeSheetRequest)
      ? timesheetApprovalService.resubmitWeek
      : timesheetApprovalService.submitWeek;
    const dates =
      activityDates && activityDates.length
        ? activityDates
        : undefined;

    this.setState({ submitInProgress: true });
    submitFn(timeSheetRequest.weekId, actorId, dates, lateReasonPayload)
      .then((response) => {
        const payload = response && response.payload ? response.payload : response;
        const warnings = formatTimesheetGovernanceWarnings(
          payload && payload.governance
        );
        this.setState({ timesheetGovernance: payload && payload.governance });
        store.dispatch(
          notificationActions.success(
            warnings.length
              ? `Timesheet submitted for approval. ${warnings[0]}`
              : "Timesheet submitted for approval."
          )
        );
        this.handleDateChange(selectedDate);
        this.loadPendingApprovals();
        this.bumpTimesheetAuditRefresh();
      })
      .catch((error) => {
        const message =
          (error && error.message) || error || "Unable to submit timesheet.";
        store.dispatch(notificationActions.error(message));
      })
      .finally(() => {
        this.setState({ submitInProgress: false });
      });
  };

  resolveTimesheetUserTeamIds = () => {
    const selected = commonUtils.getSelectedUserTeamIds(
      commonUtils.getUserTeams(this.props.userTeams)
    );
    return commonUtils.resolveUserTeamIds(selected.length ? selected : null);
  };

  /**
   * Manager pending inbox: always use all of the manager's teams so the panel
   * matches /workspace/approvals live aggregation (selected filter is for timesheet edit only).
   */
  resolvePendingApprovalUserTeamIds = () => {
    const all = commonUtils.getCurrentUserTeamIds();
    if (all && all.length) {
      return all;
    }
    const current = commonUtils.getCurrentUserTeamId();
    return current != null ? [current] : [];
  };
  handleUpdateTimeSheet = (submitCallBackFunction, payloadOverride) => {
    let currentEmployeeId = commonUtils.getCurrentUserId();
    let date = this.state.selectedDate;
    const timeSheetRequest =
      payloadOverride != null ? payloadOverride : this.state.timeSheetRequest;
    const startDate = date.clone().startOf('isoWeek').format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = date.clone().endOf('isoWeek').format(dateUtils.SERVER_DATE_FORMAT);
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    if (!userTeamIds.length) {
      store.dispatch(
        notificationActions.error(
          "Cannot save timesheet: no team is selected. Set your default team and try again."
        )
      );
      return;
    }
    if (!this.state.selectedEmployee || !this.state.selectedEmployee.id) {
      store.dispatch(notificationActions.error("Select an employee before saving the timesheet."));
      return;
    }
    // Wait for save to complete so weekId is present before enabling Submit.
    store.dispatch(
      this.props.addTimesheetData(
        startDate,
        endDate,
        [this.state.selectedEmployee.id],
        currentEmployeeId,
        userTeamIds,
        timeSheetRequest,
        (payload) => {
          this.updateTimeSheetRequest(payload);
          if (payload && payload.weekId) {
            this.bumpTimesheetAuditRefresh({
              ...this.state,
              timeSheetRequest: payload,
            });
          }
          if (typeof submitCallBackFunction === "function") {
            submitCallBackFunction(payload);
          }
          if (
            payload &&
            !payload.weekId &&
            isTimesheetApprovalWorkflowActive(payload, this.state.permission)
          ) {
            store.dispatch(
              notificationActions.warning(
                "Draft saved, but approval staging did not return a week id. Confirm timesheet approval is enabled for this team in Application Config."
              )
            );
          }
        }
      )
    );
  }

  handleDateChange = (date, employeeOverride, options = {}) => {
    const employee = employeeOverride || this.state.selectedEmployee;
    if (!employee || !employee.id) {
      return;
    }

    const startDate = date.clone().startOf("isoWeek");
    const endDate = date.clone().endOf("isoWeek");
    const loadSeq = ++this.timesheetLoadSeq;
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    const approvalReviewContext = this.resolveApprovalReviewContextForNavigation(
      date,
      employee,
      options
    );

    store.dispatch(
      this.props.loadTimeSheetData(
        startDate.format(dateUtils.SERVER_DATE_FORMAT),
        endDate.format(dateUtils.SERVER_DATE_FORMAT),
        [employee.id],
        userTeamIds,
        (timesheetResponse) => {
          if (loadSeq !== this.timesheetLoadSeq) {
            return;
          }
          this.updateTimeSheetRequest(timesheetResponse, { refreshIntelligence: true });
        }
      )
    );

    this.setState({
      selectedDate: date,
      timeSheetRequest: null,
      timesheetGovernance: null,
      deadlinePreview: null,
      approvalReviewContext,
      applicableDates: {
        currentWeekDates: dateUtils
          .getCurrentWeekDateArray(date)
          .map((dateObject) => dateObject.value),
        workItemMinDates: workItemUtils.getWorkItemCreateStartMinDate(
          startDate,
          this.state.permission
        ),
        workItemMaxDates: workItemUtils.getWorkItemCreateEndMaxDate(
          endDate,
          this.state.permission
        ),
      },
    }, () => {
      this.loadDefaulters();
      this.loadDeadlinePreview();
      if (this.state.intelligenceEnabled) {
        this.loadIntelligenceContext({ forceLoading: true });
      }
    });
  };

  loadDeadlinePreview = () => {
    const date = this.state.selectedDate;
    if (!date || !date.clone) {
      return;
    }
    const weekStart = date.clone().startOf("isoWeek").format(dateUtils.DATE_PICKER_FORMAT);
    const weekEnd = date.clone().endOf("isoWeek").format(dateUtils.DATE_PICKER_FORMAT);
    const loadSeq = ++this.deadlinePreviewSeq;
    this.setState({ deadlinePreview: null });
    workTimeGovernanceService
      .getDeadlinePreview({ weekStart, weekEnd })
      .then((result) => {
        if (loadSeq !== this.deadlinePreviewSeq) {
          return;
        }
        this.setState({ deadlinePreview: result && result.payload ? result.payload : null });
      })
      .catch(() => {
        if (loadSeq !== this.deadlinePreviewSeq) {
          return;
        }
        this.setState({ deadlinePreview: null });
      });
  };

  resolveTimesheetGovernance = () => {
    return mergeTimesheetDeadlinePreview(
      this.state.timesheetGovernance,
      this.state.deadlinePreview
    );
  };


  goToNext = () => {
    this.handleDateChange(dateUtils.addXDays(this.state.selectedDate, 7))
  };

  goToBack = () => {
    this.handleDateChange(dateUtils.substractXDays(this.state.selectedDate, 7))
  };

  goToCurrent = () => {
    this.handleDateChange(dateUtils.getCurrentTime())
  };

  cancelShowSelectionWindow = () => {
    this.setState({ addEntryOpen: false });
  };

  createItemClickHandler = () => {
    if (this.state.addEntryOpen) {
      return;
    }
    if (!canAddTimesheetEntry(this.state.timeSheetRequest, this.state.permission)) {
      return;
    }
    this.setState((prevState) => ({
      addEntryOpen: true,
      addEntrySession: prevState.addEntrySession + 1,
    }));
  };

  render() {
    const isBoardLoading = !this.state.timeSheetRequest;
    const isManager = isManagerTimesheetApprover(this.state.permission);
    const canApproveTimesheets = isTimesheetApprovalActor(
      this.state.permission,
      this.state.actingDelegations
    );
    const viewingOwnWeek = !!(
      this.state.selectedEmployee &&
      String(this.state.selectedEmployee.id) === String(commonUtils.getCurrentUserId())
    );
    const canUseEmployeeActions = viewingOwnWeek;
    const reopenOptions = collectApprovedSubmissionReopenOptions(
      this.state.timeSheetRequest
    );
    const canReopenWeek = canReopenTimesheetWeek(
      this.state.permission,
      this.state.actingDelegations,
      {
        viewingOwnWeek,
        timeSheetData: this.state.timeSheetRequest,
        currentUserId: commonUtils.getCurrentUserId(),
        employeeManagerId:
          this.state.selectedEmployee && this.state.selectedEmployee.managerId,
      }
    );
    const canReopenBatch = canReopenTimesheetSubmissionBatch(
      this.state.permission,
      this.state.actingDelegations,
      {
        viewingOwnWeek,
        reopenOptions,
      }
    );
    const canReopen = canReopenWeek || canReopenBatch;
    const canReviewPendingWeek =
      canApproveTimesheets &&
      !viewingOwnWeek &&
      !!(this.state.timeSheetRequest && this.state.timeSheetRequest.weekId) &&
      getTimesheetWeekStatus(this.state.timeSheetRequest) === "PENDING";
    const canAddEntry =
      canUseEmployeeActions &&
      canAddTimesheetEntry(this.state.timeSheetRequest, this.state.permission);
    const weekLabel = formatTimesheetWeekRange({
      weekStartDate: this.state.selectedDate
        ? this.state.selectedDate.clone().startOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT)
        : null,
      weekEndDate: this.state.selectedDate
        ? this.state.selectedDate.clone().endOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT)
        : null,
    });
    const {
      intelligenceEnabled,
      activeView,
      intelligence,
      billability,
      recommendation,
      intelligenceLoading,
      agentActionLog,
    } = this.state;

    return (
      <div className="lux-timesheet-page lux-register-page" data-testid="page-timesheet">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.timesheet}
          howToHref="/documentation/hrms/timesheet.html"
          howToTestId="timesheet-howto-link"
          actions={
            this.state.permission.enableTimeSheetEntry !== false && canAddEntry ? (
              <PageCreateButton
                createLink
                className="xs-hide"
                disabled={this.state.addEntryOpen === true}
                onClick={this.createItemClickHandler}
              >
                ADD TIME ENTRY
              </PageCreateButton>
            ) : null
          }
        />

        <PageInnerHeaderTimesheet
                  createItemHandler={this.createItemClickHandler}
                  syncLeavesHandler={this.syncLeavesHandler}
                  syncLeavesInProgress = {this.state.syncLeavesInProgress}
                  addEntryOpen={this.state.addEntryOpen}
                  goToBack={this.goToBack}
                  goToCurrent={this.goToCurrent}
                  goToNext={this.goToNext}
                  permission={this.state.permission}
                  showLeaveSynEnabled={this.state.selectedEmployee && this.state.selectedEmployee.extLeaveSyncEnabled === true}
                  currentStartOfTheWeek={dateUtils.getStartOftheWeek(dateUtils.getCurrentTime())}
                  startOfTheWeek={this.state.selectedDate && dateUtils.getStartOftheWeek(this.state.selectedDate)}
                  showEmployeeMenu={this.state.permission.switchEmployeesEnabled}
                  showUserTeamMenu={this.state.permission.switchUserTeamsEnabled}
                  handleEmployeesSelection={this.handleEmployeesSelection}
                  selectedEmployeeId={
                  this.state.selectedEmployee && this.state.selectedEmployee.id
                  }
                  applyEmployeeSelectionImmediately
                  userTeams={commonUtils.getUserTeams(this.props.userTeams)}
                  enableUserTeamSingleSelection={true}
                  handleUserTeamsSelection={this.handleUserTeamsSelection}
                  employees={this.props.employees}
                />

        <TimesheetSummaryPanel
          timeSheetData={this.state.timeSheetRequest}
          applicableDates={this.state.applicableDates}
          loading={this.props.timesheetLoading}
          addEntryOpen={this.state.addEntryOpen}
          employees={this.props.employees}
        />

        <TimesheetLockBanner
          timeSheetData={this.state.timeSheetRequest}
          employeeId={this.state.selectedEmployee && this.state.selectedEmployee.id}
          canUnlock={isManager || canReopen}
          unlockInProgress={this.state.unlockInProgress}
          onUnlock={this.handleUnlockCurrentWeek}
          canReopen={canReopen}
          reopenInProgress={this.state.reopenInProgress}
          onReopen={this.handleReopenCurrentWeek}
          reopenOptions={reopenOptions}
        />
        <TimesheetGovernanceBanner governance={this.resolveTimesheetGovernance()} />

        {isManager && (
          <TimesheetCompliancePanel
            defaulters={this.state.defaulters}
            weekLabel={weekLabel}
            isLoading={this.state.defaultersLoading}
            canLockPayroll={isManager}
            lockInProgress={this.state.lockInProgress}
            onLockPayroll={this.handleLockPayrollWeek}
          />
        )}

        {canApproveTimesheets && (
          <TimesheetPendingApprovals
            weeks={this.state.pendingWeeks}
            conflictCounts={this.state.conflictCounts}
            isLoading={this.state.pendingLoading || this.state.approvalActionInProgress}
            actingDelegations={this.state.actingDelegations}
            employees={this.props.employees}
            onApprove={this.handleApproveTimesheetWeek}
            onReject={this.handleRejectTimesheetWeek}
            onOpenConflicts={this.openConflictModal}
            onViewWeek={this.handleViewPendingWeek}
          />
        )}

        <TimesheetConflictModal
          show={this.state.conflictModal.show}
          week={this.state.conflictModal.week}
          conflicts={this.state.conflictModal.conflicts}
          loading={this.state.conflictModal.loading || this.state.approvalActionInProgress}
          resolverId={commonUtils.getCurrentUserId()}
          onResolve={this.handleResolveConflict}
          onRefresh={() => this.refreshConflictModal()}
          onClose={this.closeConflictModal}
        />

        <TimesheetDiscardConfirmDialog
          show={this.state.discardConfirm != null}
          type={(this.state.discardConfirm && this.state.discardConfirm.type) || "clear"}
          weekLabel={weekLabel}
          inProgress={this.state.discardInProgress}
          onConfirm={this.confirmDiscardTimesheet}
          onDismiss={this.closeDiscardConfirm}
        />

        {intelligenceEnabled && (
          <nav className="lux-ts-view-tabs" aria-label="Timesheet views">
            {[
              { id: "board", label: "Weekly grid", icon: "fe-grid" },
              { id: "intelligence", label: "Intelligence", icon: "fe-activity" },
            ].map((tab) => (
              <button
                key={tab.id}
                type="button"
                className={`lux-ts-view-tabs__btn${activeView === tab.id ? " is-active" : ""}`}
                onClick={() => this.handleViewChange(tab.id)}
              >
                <i className={`fe ${tab.icon}`} aria-hidden="true" />
                {tab.label}
              </button>
            ))}
          </nav>
        )}

        {intelligenceEnabled && activeView === "intelligence" && (
          <TimesheetIntelligencePanel
            intelligence={intelligence}
            billability={billability}
            recommendation={recommendation}
            defaulters={this.state.defaulters}
            pendingWeeks={this.state.pendingWeeks}
            loading={intelligenceLoading}
            agentActionLog={agentActionLog}
            onAgentAction={this.handleAgentDraftAction}
          />
        )}

        <div className="lux-ts-page__grid-shell">
                {!isBoardLoading && (!intelligenceEnabled || activeView === "board") && (
                  <TimesheetPageInputItem
                    permission={this.state.permission}
                    timeSheetRequest={
                      this.state.timeSheetRequest
                        ? {
                            ...this.state.timeSheetRequest,
                            deadlinePreview: this.state.deadlinePreview,
                          }
                        : { deadlinePreview: this.state.deadlinePreview }
                    }
                    onChange={this.updateTimeSheetRequest}
                    showSelectionWindow={this.state.addEntryOpen}
                    addEntrySession={this.state.addEntrySession}
                    addEntryOpen={this.state.addEntryOpen}
                    onOpenAddEntry={canAddEntry ? this.createItemClickHandler : undefined}
                    cancelShowSelectionWindow={this.cancelShowSelectionWindow}
                    selectedEmployee={this.state.selectedEmployee}
                    viewingOwnWeek={viewingOwnWeek}
                    resetTimeSheet={this.resetTimeSheet}
                    handleDiscardTimesheet={
                      canUseEmployeeActions ? this.handleDiscardTimesheet : undefined
                    }
                    discardInProgress={this.state.discardInProgress}
                    handleUpdateTimeSheet={
                      canUseEmployeeActions ? this.handleUpdateTimeSheet : undefined
                    }
                    handleSubmitTimesheet={
                      canUseEmployeeActions ? this.handleSubmitTimesheet : undefined
                    }
                    timesheetGovernance={this.resolveTimesheetGovernance()}
                    submitInProgress={this.state.submitInProgress}
                    applicableDates={this.state.applicableDates}
                    startOfTheWeek={this.state.selectedDate && dateUtils.getStartOftheWeek(this.state.selectedDate)}
                    intelligenceEnabled={intelligenceEnabled}
                    recommendation={recommendation}
                    recommendationLoading={intelligenceLoading}
                    canReviewPendingWeek={canReviewPendingWeek}
                    approvalActionInProgress={this.state.approvalActionInProgress}
                    approvalReviewContext={this.state.approvalReviewContext}
                    onDismissApprovalReview={this.handleDismissApprovalReview}
                  />
                )}
                {isBoardLoading && (!intelligenceEnabled || activeView === "board") && <TimesheetBoardSkeleton />}
        </div>

        <div className="lux-page-audit-footer lux-page-audit-footer--timesheet">
          {this.state.timeSheetRequest && this.state.timeSheetRequest.weekId && (
            <CollapsibleAuditPanel
              className="lux-audit-collapsible--compact lux-audit-collapsible--timesheet"
              panelKey={`timesheet-week-${this.state.timeSheetRequest.weekId}`}
              defaultExpanded={false}
              title={`Week audit · ${weekLabel}`}
              subtitle="Submit, approve, reject, and lock events"
              icon="fe-clock"
              auditProps={{
                scope: AUDIT_SCOPES.ENTITY,
                entityType: AUDIT_ENTITY_TYPES.TIMESHEET_WEEK,
                entityId: this.state.timeSheetRequest.weekId,
                employees: this.props.employees,
                compact: true,
                scrollable: true,
                pageSize: AUDIT_EMBEDDED_PAGE_SIZE,
                softEmptyOnError: true,
                viewMode: "activity",
                showEntityFilters: false,
                actionFilterOptions: AUDIT_TIMESHEET_ACTION_FILTER_OPTIONS,
                showToolbar: false,
                refreshKey: this.state.auditRefreshKey,
                emptyState: {
                  eyebrow: "Timesheet week",
                  title: "No audit events for this week",
                  description:
                    "Submission, approval, and lock actions will appear here after you save or submit this week.",
                  hints: [
                    "Field edits are recorded when audit logging is enabled",
                    "Delegate actions show acting-for metadata",
                    "Payroll lock events appear separately from approvals",
                  ],
                },
              }}
            />
          )}

          {viewingOwnWeek && this.state.selectedEmployee && (
            <CollapsibleAuditPanel
              className="lux-audit-collapsible--compact lux-audit-collapsible--timesheet"
              panelKey={`timesheet-employee-${this.state.selectedEmployee.id}`}
              defaultExpanded={false}
              title="Timesheet activity"
              subtitle="Your submissions and approvals across weeks"
              icon="fe-activity"
              auditProps={{
                scope: AUDIT_SCOPES.ACTOR,
                actorUserId: this.state.selectedEmployee.id,
                lockedEntityFilter: AUDIT_ENTITY_TYPES.TIMESHEET_WEEK,
                employees: this.props.employees,
                compact: true,
                scrollable: true,
                pageSize: AUDIT_EMBEDDED_PAGE_SIZE,
                softEmptyOnError: true,
                viewMode: "activity",
                showEntityFilters: false,
                actionFilterOptions: AUDIT_TIMESHEET_ACTION_FILTER_OPTIONS,
                showToolbar: false,
                refreshKey: this.state.auditRefreshKey,
                emptyState: {
                  eyebrow: "Timesheet actions",
                  title: "No timesheet activity yet",
                  description:
                    "Submissions, resubmissions, and approval decisions will appear here once you interact with your timesheet.",
                  hints: [
                    "Only timesheet workflow events are shown here",
                    "Week-level detail is in the panel beside this one",
                    "Immutable record for compliance reviews",
                  ],
                },
              }}
            />
          )}
        </div>
      </div>
    );
  }
}


const mapStateToProps = state => ({
  timesheetLoading: state.workItem.timesheetLoading,
  userTeams: state.workItem.userTeamsTimesheet,
  employees: state.employees.teamEmployees && commonUtils.getActiveEmployees(state.employees.teamEmployees),
});

const mapDispatchToProps = dispatch => ({
  loadTimeSheetData: workItemActions.loadTimeSheetData,
  addTimesheetData: workItemActions.addTimesheetData,
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  syncEmployeeLeaves: employeeActions.syncEmployeeLeaves
});

export default withRouter(
  connect(
    mapStateToProps,
    mapDispatchToProps
  )(TimesheetPage)
);
