import React from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "./luxSkeleton.constants";
import { getRegisterSkeletonRowKeys } from "./luxRegisterListSkeleton.utils";

/**
 * Full-width skeleton rows for legacy HTML tables (one skeleton cell per column).
 */
export default function LuxTableRowsSkeleton({
  rowCount = 10,
  columnCount = 8,
  cellHeight = 36,
}) {
  const keys = getRegisterSkeletonRowKeys(rowCount);

  return (
    <SkeletonTheme
      baseColor={LUX_SKELETON_THEME.baseColor}
      highlightColor={LUX_SKELETON_THEME.highlightColor}
    >
      {keys.map((key) => (
        <tr key={key} className="lux-table-skeleton-row" aria-hidden="true">
          {Array.from({ length: columnCount }, (_, colIdx) => (
            <td key={colIdx}>
              <Skeleton
                height={cellHeight}
                borderRadius={6}
                containerClassName="lux-table-skeleton-row__cell"
              />
            </td>
          ))}
        </tr>
      ))}
    </SkeletonTheme>
  );
}
