import React from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import { getDeliverableStatusMeta } from "./deliverableList.utils";

export default function WorkItemDeliverableContext({ taskInfo, isLoading }) {
  if (isLoading && !taskInfo) {
    return (
      <section className="lux-deliverable-context lux-workitem-context is-loading" aria-busy="true" aria-label="Loading deliverable context">
        <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
          <div className="lux-deliverable-context__skeleton">
            <Skeleton width={120} height={10} borderRadius={4} />
            <Skeleton width="55%" height={18} borderRadius={6} style={{ marginTop: 10 }} />
            <Skeleton width="40%" height={12} borderRadius={4} style={{ marginTop: 8 }} />
          </div>
        </SkeletonTheme>
      </section>
    );
  }

  if (!taskInfo) return null;

  const statusMeta = getDeliverableStatusMeta(taskInfo.status);
  const taskRef = taskInfo.itemIdUserTeamPrefix || taskInfo.id;
  const deliverablePath = `/project/deliverable/${taskRef}`;
  const projectRef =
    taskInfo.projectInfo &&
    (taskInfo.projectInfo.itemIdUserTeamPrefix || taskInfo.projectInfo.id);
  const projectDetailsPath = projectRef ? `/project/details/${projectRef}` : null;

  return (
    <section className="lux-deliverable-context lux-workitem-context" aria-label="Deliverable context">
      <LuxBackNav
        component={NavLink}
        to={deliverablePath}
        destinationLabel="Deliverable"
        currentLabel="Work items"
        navClassName="lux-deliverable-context__nav"
        aria-label="Breadcrumb"
      />

      <div className="lux-deliverable-context__body">
        <div className="lux-deliverable-context__icon" aria-hidden="true">
          <i className="fe fe-check-square" />
        </div>
        <div className="lux-deliverable-context__copy">
          <span className="lux-deliverable-context__eyebrow">Deliverable</span>
          <NavLink to={deliverablePath} className="lux-deliverable-context__title" title={taskInfo.name}>
            {taskInfo.name || taskRef}
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </NavLink>
          <p className="lux-deliverable-context__meta">
            {taskInfo.projectInfo && taskInfo.projectInfo.name && (
              <span>{taskInfo.projectInfo.name}</span>
            )}
            {projectDetailsPath && (
              <>
                <span className="lux-deliverable-context__dot">·</span>
                <NavLink to={projectDetailsPath} className="lux-deliverable-context__project-link">
                  View project
                </NavLink>
              </>
            )}
          </p>
        </div>
        <div className="lux-deliverable-context__aside">
          <span className={classNames("lux-deliverable-context__status", `is-${statusMeta.tone}`)}>
            {statusMeta.label}
          </span>
        </div>
      </div>
    </section>
  );
}
