import { shouldUseEmployeeFinance } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const EMPLOYEE_FINANCE_ROUTE_IDS = {
  BENEFITS: "benefits",
  COMPENSATION: "compensation",
  EMPLOYEE_FINANCE: "employee-finance",
};

export const EMPLOYEE_FINANCE_CANONICAL_ROUTES = {
  [EMPLOYEE_FINANCE_ROUTE_IDS.BENEFITS]: "/payroll/benefits",
  [EMPLOYEE_FINANCE_ROUTE_IDS.COMPENSATION]: "/payroll/compensation",
  [EMPLOYEE_FINANCE_ROUTE_IDS.EMPLOYEE_FINANCE]: "/payroll/employee-finance",
};

export const BENEFIT_PLAN_STATUSES = {
  ACTIVE: "ACTIVE",
  DRAFT: "DRAFT",
  SUNSET: "SUNSET",
};

export const BENEFIT_ENROLLMENT_STATUSES = {
  ENROLLED: "ENROLLED",
  PENDING: "PENDING",
  WAIVED: "WAIVED",
};

export const COMPENSATION_CHANGE_STATUSES = {
  DRAFT: "DRAFT",
  PENDING_APPROVAL: "PENDING_APPROVAL",
  APPROVED: "APPROVED",
  REJECTED: "REJECTED",
  EFFECTIVE: "EFFECTIVE",
};

export const ADVANCE_STATUSES = {
  PENDING: "PENDING",
  APPROVED: "APPROVED",
  REPAID: "REPAID",
  CANCELLED: "CANCELLED",
};

export const LOAN_STATUSES = {
  ACTIVE: "ACTIVE",
  PAID_OFF: "PAID_OFF",
  DEFAULTED: "DEFAULTED",
};

export const EMPLOYEE_FINANCE_AUDIT_CODES = {
  COMPENSATION_CHANGED: "COMPENSATION_CHANGED",
  BENEFIT_ASSIGNED: "BENEFIT_ASSIGNED",
  ADVANCE_APPROVED: "ADVANCE_APPROVED",
  LOAN_SCHEDULED: "LOAN_SCHEDULED",
};

export function isEmployeeFinanceEnabled() {
  return shouldUseEmployeeFinance();
}

export function shouldUseEmployeeFinanceApi() {
  return envconfig.USE_EMPLOYEE_FINANCE_API === true;
}

export function normalizeBenefitPlan(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "",
    code: row.code || "",
    category: row.category || "HEALTH",
    provider: row.provider || "",
    status: row.status || BENEFIT_PLAN_STATUSES.DRAFT,
    employerContributionUsd: row.employerContributionUsd != null ? Number(row.employerContributionUsd) : null,
    employeeContributionUsd: row.employeeContributionUsd != null ? Number(row.employeeContributionUsd) : null,
    enrolledCount: row.enrolledCount != null ? Number(row.enrolledCount) : 0,
    effectiveFrom: row.effectiveFrom || null,
    effectiveTo: row.effectiveTo || null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeBenefitEnrollment(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    planId: row.planId || null,
    planName: row.planName || "",
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    status: row.status || BENEFIT_ENROLLMENT_STATUSES.PENDING,
    enrolledAt: row.enrolledAt || null,
    coverageTier: row.coverageTier || "Individual",
  };
}

