const STORAGE_KEY = "tracopus.whatsNew.lastSeenVersion";

export function readLastSeenWhatsNewVersion() {
  try {
    if (typeof window === "undefined" || !window.localStorage) {
      return "";
    }
    return window.localStorage.getItem(STORAGE_KEY) || "";
  } catch (_error) {
    return "";
  }
}

export function writeLastSeenWhatsNewVersion(version) {
  try {
    if (typeof window === "undefined" || !window.localStorage) {
      return;
    }
    window.localStorage.setItem(STORAGE_KEY, String(version || ""));
  } catch (_error) {
    /* private mode / quota */
  }
}

export function shouldAutoOpenWhatsNew(currentVersion) {
  // Auto-open on login/home was noisy; What's New stays available from the footer version control.
  void currentVersion;
  return false;
}
