import React, { Component } from "react";
import { resolveEmployeeAvatarUrl } from "views/hrms/components/profile/profilePhoto.storage";

function employeeAvatarKey(employee) {
  if (!employee) {
    return "";
  }
  return `${employee.id || ""}:${employee.gender || ""}`;
}

class EmployeeImage extends Component {
  state = {
    src: resolveEmployeeAvatarUrl(this.props.employee),
  };

  componentDidMount() {
    this.photoListener = (event) => {
      const employeeId = this.props.employee && this.props.employee.id;
      if (employeeId && event.detail && event.detail.employeeId === employeeId) {
        this.syncAvatarSrc();
      }
    };
    window.addEventListener("famstack-profile-photo-updated", this.photoListener);
  }

  syncAvatarSrc = () => {
    const nextSrc = resolveEmployeeAvatarUrl(this.props.employee);
    if (nextSrc !== this.state.src) {
      this.setState({ src: nextSrc });
    }
  };

  componentDidUpdate(prevProps) {
    if (employeeAvatarKey(prevProps.employee) !== employeeAvatarKey(this.props.employee)) {
      this.syncAvatarSrc();
    }
  }

  componentWillUnmount() {
    window.removeEventListener("famstack-profile-photo-updated", this.photoListener);
  }

  render() {
    return <img className={this.props.classes} src={this.state.src} alt="" />;
  }
}

export default EmployeeImage;
