class MultiLevelValueSection extends Component {
    constructor() {
        super();
        this.state = {
            topOverridden: false,
            topSelectedItemValue: null,
            selectedItemValue: null,
            addNewValueEnabled: false,
            addNewValue: '',
            multiAddEnabled: false
        }
    }

    onChange = (fieldName, values) => {
        if (this.props.selectedItemValue) {
            this.props.values[this.props.selectedItemValue] = values;
            this.props.onChange(fieldName, this.props.values)
        } else {
            this.props.onChange(fieldName, values)
        }
    }
    componentDidUpdate() {
        if (this.props.configItemRequest.overridden !== this.state.topOverridden) {

            this.setState(prevState => ({
                topSelectedItemValue: null,
                selectedItemValue: null,
                topOverridden: this.props.configItemRequest.overridden
            }))
        }
        if (this.props.selectedItemValue !== this.state.topSelectedItemValue) {
            this.setState(prevState => ({
                selectedItemValue: null,
                addNewValueEnabled: false,
                addNewValue: '',
                multiAddEnabled: false,
                topSelectedItemValue: this.props.selectedItemValue
            }))
        }
    }

    onDelete = (valueToBeDeteleted) => {
        let updatedValues = this.getValue();
        delete updatedValues[valueToBeDeteleted];
        this.onChange("value", updatedValues)
    }

    onAddNewValueEnabled = (valueToBeDeteleted) => {
        this.setState(prevState => ({
            addNewValueEnabled: true
        }))
    }

    onAddNewValue = () => {
        let addNewValue = this.state.addNewValue.trim();
        if (addNewValue !== '') {
            if (this.state.multiAddEnabled) {
                let addNewValueArray = addNewValue.split(/[\n,]/).map(function (item) {
                    return item.trim();
                }).filter(Boolean);
                this.onChange("value", { ...addNewValueArray.reduce((a, v) => ({ ...a, [v]: {} }), {}), ...this.getValue() })
            } else {
                this.onChange("value", { [addNewValue]: {}, ...this.getValue() })
            }

            this.onClearAddNew();
        }
    }

    onClearAddNew = () => {
        this.setState(prevState => ({
            addNewValueEnabled: false,
            addNewValue: ''
        }))
    }

    onAddNewValueInputChange = (e) => {
        e.persist();
        if (validationUtils.validateAlphaNumbericWithCommaAndReturn(e.target.value)) {
            this.setState(prevState => ({
                addNewValue: e.target.value
            }));
        }
    }

    onToggleMultiAddEnabled = () => {
        this.setState(prevState => ({
            multiAddEnabled: !prevState.multiAddEnabled
        }))
    }
    toggleSelectItem = (value) => {
        this.setState(prevState => ({
            selectedItemValue: prevState.selectedItemValue === value ? null : value
        }))
    }

    getValue = () => {
        if (this.props.selectedItemValue && !this.props.isRoot && this.props.values) {
            return this.props.values[this.props.selectedItemValue]
        }
        return this.props.isRoot && this.props.values;
    }

    render() {
        const values = this.getValue();
        const { configItemRequest } = this.props;
        if (!configItemRequest) return null;

        return (
            <>
                <div className={getConfigBlockClasses(configItemRequest, "lux-ac-config-block--nested")}>
                    <div className="lux-ac-config-block__header lux-ac-config-block__header--nested">
                        <div className="lux-ac-config-block__title">
                            <span className="lux-ac-config-block__label">{this.props.levelLabel[this.props.level]}</span>
                            <span className="lux-ac-config-block__count">{values ? Object.keys(values).length : 0}</span>
                        </div>
                        {!configItemRequest.parentLocked && (
                            <div className="lux-appconfig-setting__actions">
                                {this.state.addNewValueEnabled && (
                                    <button type="button" className="lux-appconfig-icon-btn link" title="Toggle bulk add" onClick={this.onToggleMultiAddEnabled}>
                                        <i className={classNames("fe fe-list", { "text-muted": !this.state.multiAddEnabled })} />
                                    </button>
                                )}
                                {configItemRequest.overridden && (this.props.selectedItemValue || this.props.isRoot) && (
                                    <button type="button" className="lux-appconfig-icon-btn link" title="Add value" onClick={this.onAddNewValueEnabled}>
                                        <i className="fe fe-plus" />
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                    <div className="lux-ac-config-block__body appconfig-item multivalueitem">
                        <ul className="lux-ac-config-block__list">
                            {this.state.addNewValueEnabled && (this.props.selectedItemValue || this.props.isRoot) && (
                                <ConfigAddValueRow
                                    addNewValue={this.state.addNewValue}
                                    multiAddEnabled={this.state.multiAddEnabled}
                                    onValueChange={this.onAddNewValueInputChange}
                                    onSave={this.onAddNewValue}
                                    onClear={this.onClearAddNew}
                                    onToggleMulti={this.onToggleMultiAddEnabled}
                                    showMultiToggle
                                />
                            )}
                            {values && Object.keys(values).map((value, index) => (
                                <li
                                    key={value}
                                    onClick={() => this.toggleSelectItem(value)}
                                    className={classNames("lux-ac-config-block__list-item lux-ac-config-block__list-item--selectable multivalueitemvalue", {
                                        "is-selected": this.state.selectedItemValue === value,
                                    })}
                                >
                                    <span className="lux-ac-config-block__list-index">{index + 1}</span>
                                    <span className="lux-ac-config-block__list-value">{value}</span>
                                    {!configItemRequest.parentLocked && configItemRequest.overridden && (
                                        <button
                                            type="button"
                                            className="lux-appconfig-icon-btn link lux-ac-config-block__remove"
                                            title="Remove"
                                            onClick={(event) => {
                                                event.stopPropagation();
                                                this.onDelete(value);
                                            }}
                                        >
                                            <i className="fe fe-x" />
                                        </button>
                                    )}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
                {this.props.level > 1 && (
                    <MultiLevelValueSection
                        configItemRequest={configItemRequest}
                        selectedItemValue={this.state.selectedItemValue}
                        isRoot={false}
                        values={values}
                        levelLabel={this.props.levelLabel}
                        level={this.props.level - 1}
                        onChange={this.onChange}
                    />
                )}
            </>
        );
    }
}



class InvoiceDocumentJsonConfigItem extends Component {
    constructor() {
        super();
        this.state = {
            configItemRequest: null,
            draftText: "",
            parseError: null,
        };
    }

    componentDidMount() {
        this.syncFromProps(this.props.configItem);
    }

    componentDidUpdate(prevProps) {
        if (prevProps.configItem !== this.props.configItem) {
            this.syncFromProps(this.props.configItem);
        }
    }

    syncFromProps = (configItem) => {
        if (!configItem) return;
        this.setState({
            configItemRequest: { ...configItem },
            draftText: this.stringifyValue(configItem.value),
            parseError: null,
        });
    };

    stringifyValue = (value) => {
        const seedTemplate = {
            supplier: {
                name: "PROBENS CORP LLP",
                parentCompany: "",
                registration: "LLPIN: ACR-7095",
                address: [
                    "Building No. 16/216/C1, 2nd Floor,",
                    "Seaport Airport Road, Karingachira, Kochi Palace P O,",
                    "Ernakulam, Kerala – 682309",
                ],
                email: "info@infleca.com",
                phone: "+91 9496721720",
                website: "www.infleca.com",
                hours: "Monday to Friday · 9am to 5pm",
                logo: "/assets/images/invoice/infleca.png",
            },
            client: {
                name: "COURSE5 INTELLIGENCE Pvt Ltd",
                registration: "Registration Number 29AABCC6525A3ZZ",
                address: [
                    "103, C4, Brigade Tech Gardens,",
                    "ITPL MAIN ROAD, Kundalhalli village,",
                    "Bengaluru 560037 Karnataka",
                ],
                email: "Sebastian.Fernando@course5i.com",
                phone: "+91 8049313800",
            },
            payment: {
                method: "Direct Deposit (NEFT)",
                pan: "ABIFP1599C",
                gst: "32ABIFP1599C1ZA",
                lutArn: "AD320226000118S",
                accountName: "PROBENS CORP LLP",
                accountNumber: "10263297688",
                ifsc: "IDFB0080675",
                bank: "IDFC FIRST",
                branch: "Kochi-Kakanadu Branch",
                branchLocation: "Kerala 682301",
            },
            signatory: {
                name: "Neethu Mohanan",
                title: "Accounts Manager",
                image: "/assets/images/invoice/sign.png",
            },
            terms: "Payment should be made within 30 days by bank transfer. Per user ₹5, ₹1 = ₹80",
        };
        if (value == null || value === "") {
            return JSON.stringify(seedTemplate, null, 2) + "\n";
        }
        if (typeof value === "string") {
            try {
                return JSON.stringify(JSON.parse(value), null, 2);
            } catch (e) {
                return value;
            }
        }
        try {
            return JSON.stringify(value, null, 2);
        } catch (e) {
            return String(value);
        }
    };

    onChange = (fieldName, value) => {
        if (fieldName === "overridden") {
            const restored =
                this.props.configItem.parentValue && value === false
                    ? this.props.configItem.parentValue
                    : this.props.configItem.value;
            const next = {
                ...this.props.configItem,
                overridden: value,
                value: restored,
            };
            this.setState(
                {
                    configItemRequest: next,
                    draftText: this.stringifyValue(restored),
                    parseError: null,
                },
                () => this.props.onChange(this.props.selectedKey, this.state.configItemRequest)
            );
            return;
        }
        this.setState(
            (prev) => ({
                configItemRequest: {
                    ...prev.configItemRequest,
                    [fieldName]: value,
                },
            }),
            () => this.props.onChange(this.props.selectedKey, this.state.configItemRequest)
        );
    };

    onDraftChange = (event) => {
        const draftText = event.target.value;
        this.setState({ draftText, parseError: null });
    };

    applyJson = () => {
        const { draftText, configItemRequest } = this.state;
        if (!configItemRequest || !configItemRequest.overridden) {
            return;
        }
        try {
            const parsed = JSON.parse(draftText);
            if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
                this.setState({ parseError: "Root value must be a JSON object." });
                return;
            }
            const next = {
                ...configItemRequest,
                value: parsed,
            };
            this.setState(
                {
                    configItemRequest: next,
                    draftText: JSON.stringify(parsed, null, 2),
                    parseError: null,
                },
                () => this.props.onChange(this.props.selectedKey, this.state.configItemRequest)
            );
        } catch (e) {
            this.setState({
                parseError: e && e.message ? e.message : "Invalid JSON",
            });
        }
    };

    formatJson = () => {
        try {
            const parsed = JSON.parse(this.state.draftText);
            this.setState({
                draftText: JSON.stringify(parsed, null, 2),
                parseError: null,
            });
        } catch (e) {
            this.setState({
                parseError: e && e.message ? e.message : "Invalid JSON",
            });
        }
    };

    render() {
        const { configItemRequest, draftText, parseError } = this.state;
        if (!configItemRequest) return null;
        const canEdit = !!configItemRequest.overridden && !configItemRequest.locked;

        return (
            <div
                className={getConfigBlockClasses(configItemRequest, "lux-ac-config-block--invoice-json")}
                data-testid="appconfig-invoice-document-json"
            >
                <ConfigBlockHeader
                    label={configItemRequest.label || "Invoice document (JSON)"}
                    parentLocked={this.props.configItem.parentLocked}
                    configItemRequest={configItemRequest}
                    onChange={this.onChange}
                />
                <div className="lux-ac-config-block__body appconfig-item">
                    <p className="lux-ac-config-block__hint small text-muted mb-2">
                        Paste complete invoice identity JSON. Keys:{" "}
                        <code>supplier</code>, <code>client</code>, <code>payment</code>,{" "}
                        <code>signatory</code>, <code>terms</code>.
                    </p>
                    <textarea
                        className="form-control lux-appconfig-invoice-json__textarea"
                        rows={18}
                        spellCheck={false}
                        value={draftText}
                        disabled={!canEdit}
                        onChange={this.onDraftChange}
                        aria-label="Invoice document JSON"
                        data-testid="appconfig-invoice-document-json-editor"
                    />
                    {parseError ? (
                        <p className="text-danger small mt-2 mb-0" role="alert">
                            {parseError}
                        </p>
                    ) : null}
                    <div className="lux-appconfig-invoice-json__actions mt-2">
                        <button
                            type="button"
                            className="btn btn-sm btn-outline-secondary me-2"
                            disabled={!canEdit}
                            onClick={this.formatJson}
                        >
                            Format
                        </button>
                        <button
                            type="button"
                            className="btn btn-sm btn-primary"
                            disabled={!canEdit}
                            onClick={this.applyJson}
                            data-testid="appconfig-invoice-document-json-apply"
                        >
                            Apply JSON
                        </button>
                    </div>
                </div>
            </div>
        );
    }
}

class MultiMapValueConfigItem extends Component {
    constructor() {
        super();
        this.state = {
            configItemRequest: null,
            addNewValueEnabled: false,
            addNewValue: '',
            addNewKey: ''
        }
    }
    componentDidMount() {
        this.setState(prevState => ({
            configItemRequest: {
                ...this.props.configItem
            }
        }))
    }

    onChange = (fieldName, value) => {
        if ("overridden" === fieldName) {
            let oldvalues = this.props.configItem.parentValue && value === false ? this.props.configItem.parentValue : this.props.configItem.value
            this.setState(prevState => ({
                configItemRequest: {
                    ...this.props.configItem,
                    "overridden": value,
                    "value": oldvalues
                }
            }), () => {
                this.props.onChange(this.props.selectedKey, this.state.configItemRequest);
            })
        } else {
            this.setState(prevState => ({
                configItemRequest: {
                    ...prevState.configItemRequest,
                    [fieldName]: value
                }
            }), () => {
                this.props.onChange(this.props.selectedKey, this.state.configItemRequest);
            })
        }
    }

    onDelete = (keToBeDeteleted) => {
        let newValues = { ...this.state.configItemRequest.value };
        delete newValues[keToBeDeteleted];
        this.onChange("value", newValues)
    }

    onValueChange = (propertyName, value) => {
        this.onChange("value", {
            ...this.state.configItemRequest.value,
            [propertyName]: value,
        });
    }

    onAddNewValueEnabled = () => {
        this.setState(prevState => ({
            addNewValueEnabled: true
        }))
    }

    onAddNewValue = () => {
        this.onChange("value", {
            [this.state.addNewKey]: this.state.addNewValue,
            ...this.state.configItemRequest.value
        }
        );
        this.onClearAddNew();
    }

    onClearAddNew = () => {
        this.setState(prevState => ({
            addNewValueEnabled: false,
            addNewValue: '',
            addNewKey: ''
        }))
    }

    onAddNewValueInputChange = (e) => {
        e.persist();
        this.setState(prevState => ({
            addNewValue: e.target.value
        }))
    }


    onAddNewKeyInputChange = (e) => {
        e.persist();
        this.setState(prevState => ({
            addNewKey: e.target.value
        }))
    }

    render() {
        const { configItemRequest } = this.state;
        if (!configItemRequest) return null;

        return (
            <div className={getConfigBlockClasses(configItemRequest)}>
                <ConfigBlockHeader
                    label={configItemRequest.label}
                    parentLocked={this.props.configItem.parentLocked}
                    configItemRequest={configItemRequest}
                    onChange={this.onChange}
                    actions={
                        configItemRequest.overridden && (
                            <button type="button" className="lux-appconfig-icon-btn link" title="Add entry" onClick={this.onAddNewValueEnabled}>
                                <i className="fe fe-plus" />
                            </button>
                        )
                    }
                />
                <div className="lux-ac-config-block__body">
                    {this.state.addNewValueEnabled && (
                        <div className="lux-ac-config-block__kv-add">
                            <input type="text" value={this.state.addNewKey} className="lux-ac-config-block__input" placeholder="Key" onChange={this.onAddNewKeyInputChange} />
                            <input type="text" value={this.state.addNewValue} className="lux-ac-config-block__input" placeholder="Value" onChange={this.onAddNewValueInputChange} />
                            <div className="lux-ac-config-block__add-actions">
                                <button type="button" className="lux-appconfig-icon-btn link lux-ac-config-block__add-save" title="Save entry" onClick={this.onAddNewValue}>
                                    <i className="fe fe-check" />
                                </button>
                                <button type="button" className="lux-appconfig-icon-btn link" title="Cancel" onClick={this.onClearAddNew}>
                                    <i className="fe fe-x" />
                                </button>
                            </div>
                        </div>
                    )}
                    <ul className="lux-ac-config-block__kv-list">
                        {Object.keys(configItemRequest.value || {}).map((key) => (
                            <li key={key} className="lux-ac-config-block__kv-item">
                                <span className="lux-ac-config-block__kv-key">{key}</span>
                                {!this.props.configItem.parentLocked && configItemRequest.overridden ? (
                                    <input
                                        type="text"
                                        className="lux-ac-config-block__input lux-ac-config-block__kv-input"
                                        value={
                                            configItemRequest.value[key] == null
                                                ? ""
                                                : String(configItemRequest.value[key])
                                        }
                                        onChange={(e) => this.onValueChange(key, e.target.value)}
                                        aria-label={`${configItemRequest.label || "Config"} ${key}`}
                                    />
                                ) : (
                                    <span className="lux-ac-config-block__kv-value">
                                        {configItemRequest.value[key]}
                                    </span>
                                )}
                                {!this.props.configItem.parentLocked && configItemRequest.overridden && (
                                    <button type="button" className="lux-appconfig-icon-btn link lux-ac-config-block__remove" title="Remove" onClick={() => this.onDelete(key)}>
                                        <i className="fe fe-x" />
                                    </button>
                                )}
                            </li>
                        ))}
                    </ul>
                </div>
            </div>
        );
    }
}

