import { auditConstants } from '_constants/audit.constants';

const defaultTimelineState = {
  items: [],
  pageInfo: null,
  page: 1,
  pageSize: 25,
  isLoading: false,
  error: null,
  filters: { entityType: 'ALL' },
};

export function audit(state = { timelines: {} }, action) {
  const scopeKey = action.scopeKey;
  const current = (scopeKey && state.timelines[scopeKey]) || defaultTimelineState;

  switch (action.type) {
    case auditConstants.LOAD_TIMELINE_REQUEST:
      return {
        ...state,
        timelines: {
          ...state.timelines,
          [scopeKey]: {
            ...current,
            isLoading: true,
            error: null,
            page: action.page || current.page,
            pageSize: action.pageSize || current.pageSize,
          },
        },
      };

    case auditConstants.LOAD_TIMELINE_SUCCESS:
      return {
        ...state,
        timelines: {
          ...state.timelines,
          [scopeKey]: {
            ...current,
            isLoading: false,
            items: action.items || [],
            pageInfo: action.pageInfo || null,
            page: action.page || current.page,
            pageSize: action.pageSize || current.pageSize,
            error: null,
          },
        },
      };

    case auditConstants.LOAD_TIMELINE_FAILURE:
      return {
        ...state,
        timelines: {
          ...state.timelines,
          [scopeKey]: {
            ...current,
            isLoading: false,
            items: [],
            error: action.error,
          },
        },
      };

    case auditConstants.SET_TIMELINE_FILTERS:
      return {
        ...state,
        timelines: {
          ...state.timelines,
          [scopeKey]: {
            ...current,
            filters: { ...current.filters, ...action.filters },
          },
        },
      };

    case auditConstants.CLEAR_TIMELINE:
      return {
        ...state,
        timelines: {
          ...state.timelines,
          [scopeKey]: { ...defaultTimelineState },
        },
      };

    default:
      return state;
  }
}
