import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isExpenseManagementEnabled } from "config/expenses.config";
import { EXPENSE_PAGE_META } from "config/expenses-nav.config";
import { expensesService } from "_services/expenses.service";
import ExpensesLuxPage, {
  ExpenseActionButton,
  ExpenseInsightPanel,
  ExpenseLuxPanel,
} from "views/expenses/components/ExpensesLuxShared";
import ExpenseAnalyticsPanel from "views/expenses/components/ExpenseAnalyticsPanel";
import ExpenseFinanceQueuePanel from "views/expenses/components/ExpenseFinanceQueuePanel";
import ExpenseLeakageAgentPanel from "views/expenses/components/ExpenseLeakageAgentPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getLuxInlineAlertProps } from "_helpers/apiError.utils";
import { shouldHideRegisterOnLoadError } from "_helpers/registerListError.utils";

function buildFinanceFilters(filters = {}) {
  const next = {};
  if (filters.query) {
    next.query = filters.query;
  }
  if (filters.status && filters.status !== "ALL") {
    next.status = filters.status;
  }
  if (filters.category && filters.category !== "ALL") {
    next.category = filters.category;
  }
  if (filters.policyIssuesOnly) {
    next.policyIssuesOnly = true;
  }
  return next;
}

class FinanceExpensesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    exporting: false,
    dataSource: null,
    claims: [],
    leakageFlags: [],
    kpiCards: [],
    insights: [],
    categoryBreakdown: [],
    agingSeries: [],
    busyId: null,
    filters: {
      query: "",
      status: "ALL",
      category: "ALL",
      policyIssuesOnly: false,
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Expense approvals");
    }
    this.loadData();
  }

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await expensesService.getFinanceExpensesOverview(buildFinanceFilters(filters));
      const overview = result.payload || {};
      this.setState({
        loading: false,
        claims: overview.claims || [],
        leakageFlags: overview.leakageFlags || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        categoryBreakdown: overview.categoryBreakdown || [],
        agingSeries: overview.agingSeries || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  handleApprove = async (claimId) => {
    this.setState({ busyId: claimId });
    try {
      const claim = (this.state.claims || []).find((row) => row && row.id === claimId);
      await expensesService.approveExpenseClaim(
        claimId,
        "finance",
        claim && claim.userTeamId
      );
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ busyId: null });
    }
  };

  handleReject = async (claimId) => {
    this.setState({ busyId: claimId });
    try {
      const claim = (this.state.claims || []).find((row) => row && row.id === claimId);
      await expensesService.rejectExpenseClaim(
        claimId,
        "Rejected during finance review",
        claim && claim.userTeamId
      );
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ busyId: null });
    }
  };

  handleExport = async () => {
    this.setState({ exporting: true });
    try {
      const result = await expensesService.exportExpenses(buildFinanceFilters(this.state.filters));
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = result.filename || "expenses.csv";
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ exporting: false });
    }
  };

  render() {
    if (!isExpenseManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Finance expense approvals" />;
    }

    const {
      loading,
      loadError,
      exporting,
      dataSource,
      claims,
      leakageFlags,
      kpiCards,
      insights,
      categoryBreakdown,
      agingSeries,
      busyId,
      filters,
    } = this.state;
    const meta = EXPENSE_PAGE_META.finance;
    const hideBody = shouldHideRegisterOnLoadError(loadError, claims);
    const loadAlertProps = loadError
      ? getLuxInlineAlertProps(loadError, "Unable to load finance expense queue.")
      : null;

    return (
      <ExpensesLuxPage
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo finance expense queue"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <ExpenseActionButton to="/finance/project-financials" icon="fe fe-pie-chart" variant="ghost">
              Project financials
            </ExpenseActionButton>
            <ExpenseActionButton to="/payroll/reimbursements" icon="fe fe-dollar-sign" variant="ghost">
              Reimbursements
            </ExpenseActionButton>
            <ExpenseActionButton icon="fe fe-download" variant="ghost" onClick={this.handleExport} disabled={exporting}>
              {exporting ? "Exporting…" : "Export CSV"}
            </ExpenseActionButton>
            <ExpenseActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="primary">
              Approval inbox
            </ExpenseActionButton>
          </>
        }
      >
        <ExpenseInsightPanel insights={insights} />
        {loadAlertProps ? (
          <LuxInlineAlert
            {...loadAlertProps}
            onDismiss={() => this.setState({ loadError: null })}
          />
        ) : null}
        {hideBody ? null : (
        <>
        <ExpenseLuxPanel
          title="Finance approval queue"
          meta="Review policy compliance, approve claims, and route billable costs to project financials"
          icon="fe fe-check-circle"
          accent="indigo"
        >
          <ExpenseFinanceQueuePanel
            rows={claims}
            loading={loading}
            busyId={busyId}
            filters={filters}
            onFilterChange={this.handleFilterChange}
            onApprove={this.handleApprove}
            onReject={this.handleReject}
          />
        </ExpenseLuxPanel>
        <ExpenseLuxPanel
          title="Expense analytics"
          meta="Category spend and approval aging for finance oversight"
          icon="fe fe-bar-chart-2"
          accent="blue"
          actions={
            <ExpenseActionButton to="/analytics/finance" icon="fe fe-trending-up" variant="ghost">
              Financial analytics
            </ExpenseActionButton>
          }
        >
          <ExpenseAnalyticsPanel categoryBreakdown={categoryBreakdown} agingSeries={agingSeries} loading={loading} />
        </ExpenseLuxPanel>
        <ExpenseLuxPanel
          title="Expense Leakage Agent"
          meta="Duplicate, out-of-policy, and unbilled billable expense detection"
          icon="fe fe-shield"
          accent="violet"
          actions={
            <ExpenseActionButton to="/finance/revenue-leakage" icon="fe fe-arrow-right" variant="ghost">
              Revenue leakage
            </ExpenseActionButton>
          }
        >
          <ExpenseLeakageAgentPanel flags={leakageFlags} loading={loading} />
        </ExpenseLuxPanel>
        </>
        )}
      </ExpensesLuxPage>
    );
  }
}

export default FinanceExpensesPage;
