import React from "react";
import classNames from "classnames/bind";
import { DeveloperLuxPanel, DeveloperStatusBadge } from "views/developer/components/DeveloperLuxShared";

export default function MarketplaceCatalogPanel({ listings, loading, onInstall, busy }) {
  const rows = listings || [];

  return (
    <DeveloperLuxPanel title="Connector catalog" meta="Certified and beta listings" icon="fe fe-grid" accent="emerald" featured>
      {loading ? (
        <div className="lux-dev-skeleton lux-dev-skeleton--panel" />
      ) : !rows.length ? (
        <div className="lux-dev-empty">No marketplace listings available.</div>
      ) : (
        <div className="lux-dev-marketplace-grid">
          {rows.map((row) => (
            <article key={row.id} className={classNames("lux-dev-marketplace-card", row.tone && `is-${row.tone}`, row.installed && "is-installed")}>
              <div className="lux-dev-marketplace-card__head">
                <span className="lux-dev-marketplace-card__category">{row.category}</span>
                {row.certified ? <span className="lux-dev-marketplace-card__cert">Certified</span> : null}
              </div>
              <h3>{row.name}</h3>
              <p>{row.description}</p>
              <div className="lux-dev-marketplace-card__meta">
                <span>{row.vendor}</span>
                <span>{row.rating}★</span>
                <span>{row.installCount} installs</span>
                <DeveloperStatusBadge status={row.status} />
              </div>
              <div className="lux-dev-marketplace-card__actions">
                {row.installed ? (
                  <span className="lux-dev-marketplace-card__installed">Installed</span>
                ) : onInstall ? (
                  <button type="button" className="lux-onb-action lux-onb-action--primary lux-dev-action" onClick={() => onInstall(row)} disabled={busy}>
                    Install
                  </button>
                ) : null}
              </div>
            </article>
          ))}
        </div>
      )}
    </DeveloperLuxPanel>
  );
}
