function unwrapList(response) {
  if (!response) {
    return [];
  }
  if (Array.isArray(response)) {
    return response;
  }
  if (Array.isArray(response.payload)) {
    return response.payload;
  }
  return [];
}

function getEmployeesFromStore() {
  try {
    const state = store.getState();
    const employeesState = state && state.employees;
    if (!employeesState) {
      return [];
    }
    const all = employeesState.allEmployees;
    const team = employeesState.teamEmployees;
    if (Array.isArray(all) && all.length) {
      return all;
    }
    if (Array.isArray(team) && team.length) {
      return team;
    }
  } catch (error) {
    // ignore store access errors
  }
  return [];
}

async function loadEmployeesForRequesterEnrichment(scopedTeamIds) {
  const cached = getEmployeesFromStore();
  if (cached.length) {
    return cached;
  }
  try {
    if (scopedTeamIds && scopedTeamIds.length) {
      const teamRes = await employeeService.getTeamsEmployees(scopedTeamIds);
      const teamEmployees = unwrapList(teamRes);
      if (teamEmployees.length) {
        return teamEmployees;
      }
    }
    const allRes = await employeeService.getAllEmployees();
    return unwrapList(allRes);
  } catch (error) {
    console.warn("[UniversalApproval] Unable to load employees for requester enrichment.", error);
    return [];
  }
}

async function withRequesterEnrichment(items, scopedTeamIds) {
  const employees = await loadEmployeesForRequesterEnrichment(scopedTeamIds);
  const enriched = enrichApprovalInboxItems(items, employees);
  return enriched.map(enrichTimesheetApprovalInboxItem);
}

async function listInboxFromApi(filters) {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const managerId = commonUtils.getCurrentUserId();
  const userTeamIds = commonUtils.getCurrentUserTeamIds();
  const scopedTeamIds =
    userTeamIds && userTeamIds.length
      ? userTeamIds
      : userTeamId != null
        ? [userTeamId]
        : [];
  const response = await axiosUtils.getWithParam(`${urlConfig.APPROVALS_API_PATH}/inbox`, {
    userTeamId,
    userTeamIds: scopedTeamIds.length ? scopedTeamIds : undefined,
    managerId,
    ...filters,
  });
  const payload = await withRequesterEnrichment(
    unwrapList(response).map((row) => normalizeUniversalApprovalItem(row, "api")),
    scopedTeamIds
  );
  return { payload, source: "api" };
}

function unwrapLifecycleCases(res) {
  const payload = res && res.payload != null ? res.payload : res;
  return Array.isArray(payload) ? payload : [];
}

function stampLifecycleTeam(items, teamId) {
  return (items || []).map((item) => {
    if (!item) {
      return item;
    }
    const metadata = Object.assign({}, item.metadata || {}, { userTeamId: teamId });
    return Object.assign({}, item, { userTeamId: teamId, metadata });
  });
}

async function fetchLifecycleAcrossTeams(listFn, domain, scopedTeamIds) {
  if (!scopedTeamIds.length) {
    return [];
  }
  const batches = await Promise.all(
    scopedTeamIds.map(async (teamId) => {
      try {
        const cases = unwrapLifecycleCases(await listFn(teamId));
        return stampLifecycleTeam(extractLifecycleApprovalItems(cases, domain), teamId);
      } catch (error) {
        return [];
      }
    })
  );
  return batches.reduce((acc, batch) => acc.concat(batch || []), []);
}

async function fetchLiveDomainItems() {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const managerId = commonUtils.getCurrentUserId();
  const userTeamIds = commonUtils.getCurrentUserTeamIds();
  const scopedTeamIds =
    userTeamIds && userTeamIds.length
      ? userTeamIds
      : userTeamId != null
        ? [userTeamId]
        : [];
  if (!managerId) {
    return { items: [], allFetchesFailed: false };
  }

  const attendanceWindow = liveAttendanceWindow();

  const results = await Promise.allSettled([
    scopedTeamIds.length
      ? leaveService.listPending(scopedTeamIds, managerId).then((res) => unwrapList(res))
      : Promise.resolve([]),
    scopedTeamIds.length
      ? timesheetApprovalService.listPending(scopedTeamIds, managerId).then((res) => unwrapList(res))
      : Promise.resolve([]),
    scopedTeamIds.length
      ? attendanceRegularizationService
          .listPending(scopedTeamIds, managerId)
          .then((res) => {
            if (Array.isArray(res)) return res;
            return (res && res.payload) || [];
          })
      : Promise.resolve([]),
    scopedTeamIds.length
      ? employeeService
          .listPendingAttendance({
            userTeamIds: scopedTeamIds,
            startDate: attendanceWindow.startDate,
            endDate: attendanceWindow.endDate,
            approverId: managerId,
          })
          .then((res) => unwrapList(res))
      : Promise.resolve([]),
    fetchLifecycleAcrossTeams(
      (teamId) => onboardingService.listOnboardingCases(teamId),
      LIVE_APPROVAL_DOMAIN_IDS.ONBOARDING,
      scopedTeamIds
    ),
    fetchLifecycleAcrossTeams(
      (teamId) => onboardingService.listOffboardingCases(teamId),
      LIVE_APPROVAL_DOMAIN_IDS.OFFBOARDING,
      scopedTeamIds
    ),
  ]);

  const allFetchesFailed =
    scopedTeamIds.length > 0 &&
    results
      .slice(0, 4)
      .every((result) => result.status === "rejected");

  const items = mergeLiveApprovalResults([
    results[0].status === "fulfilled" ? normalizeLiveLeaveRows(results[0].value) : [],
    results[1].status === "fulfilled" ? normalizeLiveTimesheetRows(results[1].value) : [],
    results[2].status === "fulfilled" ? normalizeLiveRegularizationRows(results[2].value) : [],
    results[3].status === "fulfilled"
      ? (results[3].value || []).map(normalizeAttendanceApprovalItem).filter(Boolean)
      : [],
    results[4].status === "fulfilled" ? results[4].value : [],
    results[5].status === "fulfilled" ? results[5].value : [],
  ]);

  const enriched = await withRequesterEnrichment(items, scopedTeamIds);
  return {
    items: sortApprovalInboxItems(enriched),
    allFetchesFailed,
  };
}

function liveAttendanceWindow() {
  const end = new Date();
  const start = new Date(end);
  start.setDate(start.getDate() - 45);
  return {
    startDate: start.toISOString(),
    endDate: end.toISOString(),
  };
}

function assertApprovalActionUnavailable(item) {
  const sourceType = String((item && item.sourceType) || "").toLowerCase();
  if (sourceType === "preview" || sourceType === "mock") {
    throw new Error("Preview approval actions are disabled.");
  }
  throw new Error("Approval action is unavailable for this item.");
}

function optionalBulkVersion(value) {
  if (value == null || value === "") {
    return null;
  }
  const numeric = typeof value === "number" ? value : Number(value);
  return Number.isSafeInteger(numeric) && numeric >= 0 ? numeric : null;
}

function optionalBulkActorId(value) {
  const numeric = optionalBulkVersion(value);
  return numeric != null && numeric > 0 ? numeric : null;
}

function toBulkActionItem(item, action, comment) {
  if (!item || !item.domain || item.sourceId == null || item.sourceId === "") {
    throw new Error("Every bulk approval item requires a domain and source ID.");
  }
  const requestItem = {
    domain: String(item.domain).trim().toUpperCase(),
    sourceId: String(item.sourceId),
    action,
  };
  const normalizedComment = String(comment || "").trim();
  if (normalizedComment) {
    requestItem.comment = normalizedComment;
  }
  if (item.chainInstanceRef) {
    requestItem.chainInstanceRef = String(item.chainInstanceRef);
  }
  const expectedInstanceVersion = optionalBulkVersion(item.expectedInstanceVersion);
  const expectedStepVersion = optionalBulkVersion(item.expectedStepVersion);
  if (expectedInstanceVersion != null) {
    requestItem.expectedInstanceVersion = expectedInstanceVersion;
  }
  if (expectedStepVersion != null) {
    requestItem.expectedStepVersion = expectedStepVersion;
  }
  const actingOnBehalfOf = optionalBulkActorId(
    item.actingOnBehalfOf != null
      ? item.actingOnBehalfOf
      : item.actingAsDelegate
        ? item.authorityManagerId
        : null
  );
  if (actingOnBehalfOf != null) {
    requestItem.actingOnBehalfOf = actingOnBehalfOf;
  }
  return requestItem;
}

function normalizeBulkActionResponse(value, requestedCount, failFast) {
  const payload = value && typeof value === "object" ? value : {};
  const results = Array.isArray(payload.results)
    ? payload.results.map((result, index) => ({
        index: Number.isInteger(result && result.index) ? result.index : index,
        domain: result && result.domain ? String(result.domain) : null,
        sourceId: result && result.sourceId != null ? String(result.sourceId) : null,
        action: result && result.action ? String(result.action) : null,
        chainInstanceRef:
          result && result.chainInstanceRef ? String(result.chainInstanceRef) : null,
        success: Boolean(result && result.success === true),
        idempotent: Boolean(result && result.idempotent === true),
        outcome: result && result.outcome ? String(result.outcome) : null,
        errorType: result && result.errorType ? String(result.errorType) : null,
        message: result && result.message ? String(result.message).slice(0, 240) : null,
      }))
    : [];
  return {
    maxBatchSize:
      Number.isInteger(payload.maxBatchSize) && payload.maxBatchSize > 0
        ? payload.maxBatchSize
        : UNIVERSAL_APPROVAL_BULK_MAX,
    requestedCount:
      Number.isInteger(payload.requestedCount) ? payload.requestedCount : requestedCount,
    processedCount:
      Number.isInteger(payload.processedCount) ? payload.processedCount : results.length,
    successCount:
      Number.isInteger(payload.successCount)
        ? payload.successCount
        : results.filter((result) => result.success).length,
    failureCount:
      Number.isInteger(payload.failureCount)
        ? payload.failureCount
        : results.filter((result) => !result.success).length,
    failFast: payload.failFast === true || failFast === true,
    stoppedEarly: payload.stoppedEarly === true,
    results,
  };
}

async function bulkActOnItems(items, action, comment, options = {}) {
  const rows = Array.isArray(items) ? items : [];
  const normalizedAction = String(action || "").trim().toUpperCase();
  if (normalizedAction !== "APPROVE" && normalizedAction !== "REJECT") {
    throw new Error("Bulk approval action must be APPROVE or REJECT.");
  }
  if (!rows.length) {
    throw new Error("Select at least one approval item.");
  }
  if (rows.length > UNIVERSAL_APPROVAL_BULK_MAX) {
    throw new Error(`Bulk approval is limited to ${UNIVERSAL_APPROVAL_BULK_MAX} items.`);
  }
  if (normalizedAction === "REJECT" && !String(comment || "").trim()) {
    throw new Error("A rejection reason is required.");
  }
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const actorId = commonUtils.getCurrentUserId();
  if (userTeamId == null || userTeamId === "" || actorId == null || actorId === "") {
    throw new Error("A current team and approver are required for bulk approval.");
  }
  const failFast = options.failFast === true;
  const response = await axiosUtils.post(
    `${urlConfig.APPROVALS_API_PATH}/inbox/bulk?userTeamId=${encodeURIComponent(
      userTeamId
    )}&actorId=${encodeURIComponent(actorId)}`,
    {
      failFast,
      items: rows.map((item) => toBulkActionItem(item, normalizedAction, comment)),
    }
  );
  const payload = response && response.payload != null ? response.payload : response;
  return {
    payload: normalizeBulkActionResponse(payload, rows.length, failFast),
    source: "api",
  };
}

async function listInbox(filters = {}) {
  if (shouldUseUniversalApprovalApi() && isUniversalApprovalInboxEnabled()) {
    try {
      return await listInboxFromApi(filters);
    } catch (error) {
      console.warn("[UniversalApproval] API unavailable, falling back to client aggregation.", error);
      // Fall through to live domain aggregation instead of returning an empty inbox.
    }
  }

  const { items: liveItems, allFetchesFailed } = await fetchLiveDomainItems();
  if (liveItems.length) {
    return {
      payload: filterApprovalInboxItems(liveItems, filters),
      source: "live",
    };
  }

  if (allFetchesFailed) {
    return {
      payload: [],
      source: "api-error",
      error: "Unable to load approval inbox from live services.",
    };
  }

  return { payload: [], source: "empty" };
}

async function getItem(universalId) {
  const inbox = await listInbox({ status: "ALL" });
  const found = (inbox.payload || []).find((item) => item.id === universalId);
  if (found) {
    return { payload: found, source: inbox.source };
  }
  return { payload: null, source: "empty" };

}

async function approveItem(item, comment) {
  const approverId = commonUtils.getCurrentUserId();
  if (!item) {
    throw new Error("Approval item not found.");
  }

  if (item.sourceType === "live" || item.sourceType === "api") {
    if (item.domain === "LEAVE") {
      await leaveService.approveLeave(item.sourceId, approverId, comment || null);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "TIMESHEET") {
      await actOnTimesheetApproval(item, approverId, comment || null, false);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ATTENDANCE") {
      await employeeService.approveAttendance({
        id: item.sourceId,
        approverId,
        approvalComment: comment || null,
      });
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ATTENDANCE_REGULARIZATION") {
      const teamId =
        (item.metadata && item.metadata.userTeamId) ||
        item.userTeamId ||
        commonUtils.getCurrentUserTeamId();
      await attendanceRegularizationService.approveRegularization(
        item.sourceId,
        approverId,
        comment || null,
        teamId
      );
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ONBOARDING" || item.domain === "OFFBOARDING") {
      await approveLifecycleItem(item, approverId, comment);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "DOCUMENT") {
      const verifiedBy = commonUtils.getCurrentUserName() || "HR Admin";
      await documentVaultService.verifyDocument(item.sourceId, verifiedBy);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "EXPENSE") {
      const teamId =
        (item.metadata && item.metadata.userTeamId) ||
        item.userTeamId ||
        commonUtils.getCurrentUserTeamId();
      await expensesService.approveExpenseClaim(item.sourceId, "finance", teamId);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "PAYROLL_RUN") {
      await payrollService.updateRunStatus(item.sourceId, "Approved");
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "PROJECT_GOVERNANCE") {
      await projectGovernanceService.approveGate(item.sourceId, {
        decisionNotes: comment || null,
      });
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "STAFFING") {
      await actOnStaffingRequest(item, STAFFING_REQUEST_STATUSES.APPROVED);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "RCA_PUBLICATION") {
      await knowledgeRcaService.approveRca(item.sourceId);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ASSET_ACCESS") {
      await actOnAccessRequest(item, ACCESS_REQUEST_STATUSES.APPROVED);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "TICKET") {
      const result = await ticketManagementService.resolveTicket(item.sourceId);
      assertLiveWrite(result, "Unable to resolve ticket.");
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "PERFORMANCE_REVIEW") {
      const result = await performanceManagementService.submitManagerReview(item.sourceId, {
        managerSummary: comment || null,
      });
      assertLiveWrite(result, "Unable to submit manager review.");
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "FINAL_SETTLEMENT") {
      await approveLifecycleItem(
        { ...item, domain: "OFFBOARDING" },
        approverId,
        comment
      );
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "EMPLOYEE_ADVANCE") {
      const result = await employeeFinanceService.approveAdvance(item.sourceId, {
        userTeamId:
          (item.metadata && item.metadata.userTeamId) ||
          item.userTeamId ||
          commonUtils.getCurrentUserTeamId(),
      });
      assertLiveWrite(result, "Unable to approve advance.");
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.APPROVED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
  }

  assertApprovalActionUnavailable(item);
}

function recordApprovalAudit(item, actionType, comment) {
  if (!item) {
    return;
  }
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.APPROVAL,
    entityId: item.sourceId,
    entityRef: item.title || item.id,
    correlationId: item.id,
    metadata: {
      domain: item.domain,
      sourceType: item.sourceType,
      hasComment: Boolean(String(comment || "").trim()),
      caseId: item.metadata && item.metadata.caseId,
      taskId: item.metadata && item.metadata.taskId,
    },
  });
  if (actionType === AUDIT_ACTION_TYPES.APPROVED) {
    trackApprovalInboxAction(AnalyticsEvents.APPROVAL_INBOX_APPROVE, item.domain, item.sourceId);
  } else if (actionType === AUDIT_ACTION_TYPES.REJECTED) {
    trackApprovalInboxAction(AnalyticsEvents.APPROVAL_INBOX_REJECT, item.domain, item.sourceId);
  }
}

function resolveTimesheetApprovalTarget(item) {
  const metadata = (item && item.metadata) || {};
  const sourceId = String((item && item.sourceId) || "");
  if (metadata.submissionId != null && metadata.submissionId !== "") {
    return { kind: "submission", id: metadata.submissionId };
  }
  if (sourceId.toUpperCase().startsWith("SUBMISSION:")) {
    return { kind: "submission", id: sourceId.slice("SUBMISSION:".length) };
  }
  if (sourceId.toUpperCase().startsWith("WEEK:")) {
    return { kind: "week", id: sourceId.slice("WEEK:".length) };
  }
  if (metadata.weekId != null && metadata.weekId !== "") {
    return { kind: "week", id: metadata.weekId };
  }
  return { kind: "week", id: sourceId };
}

async function actOnTimesheetApproval(item, approverId, comment, isReject) {
  const target = resolveTimesheetApprovalTarget(item);
  if (!target.id) {
    throw new Error("Timesheet approval reference is missing.");
  }
  if (target.kind === "submission") {
    if (isReject) {
      return timesheetApprovalService.rejectSubmission(target.id, approverId, comment);
    }
    return timesheetApprovalService.approveSubmission(target.id, approverId, comment || null);
  }
  if (isReject) {
    return timesheetApprovalService.rejectWeek(target.id, approverId, comment);
  }
  return timesheetApprovalService.approveWeek(target.id, approverId, comment || null);
}

function resolveLifecycleTaskRef(item) {
  const metadata = (item && item.metadata) || {};
  const caseId = metadata.caseId;
  const taskId = metadata.taskId;
  if (caseId && taskId) {
    return { caseId, taskId, lifecycle: metadata.lifecycle || "onboarding" };
  }
  const parts = String(item.sourceId || "").split(":");
  if (parts.length >= 2) {
    return {
      caseId: parts[0],
      taskId: parts[1],
      lifecycle: item.domain === "OFFBOARDING" ? "offboarding" : "onboarding",
    };
  }
  return null;
}

async function approveLifecycleItem(item, approverId, comment) {
  const ref = resolveLifecycleTaskRef(item);
  if (!ref) {
    throw new Error("Lifecycle approval reference is missing.");
  }
  const actorName = commonUtils.getCurrentUserName() || "Approver";
  const teamId =
    (item.metadata && item.metadata.userTeamId) ||
    item.userTeamId ||
    commonUtils.getCurrentUserTeamId();
  if (ref.lifecycle === "offboarding") {
    await onboardingService.completeOffboardingTask(ref.caseId, ref.taskId, teamId);
    return;
  }
  await onboardingService.completeOnboardingTask(ref.caseId, ref.taskId, actorName, teamId);
}

function assertLiveWrite(result, message) {
  if (!result || result.source === "api-error" || result.payload == null) {
    throw new Error(message);
  }
}

async function actOnStaffingRequest(item, status) {
  const current = await resourcePlanningService.getStaffingRequest(item.sourceId);
  assertLiveWrite(current, "Staffing request not found.");
  const row = current.payload;
  const result = await resourcePlanningService.updateStaffingRequest(item.sourceId, {
    title: row.title,
    requesterId: row.requesterId,
    requesterName: row.requesterName,
    projectId: row.projectId,
    projectName: row.projectName,
    roleNeeded: row.roleNeeded,
    skillNeeded: row.skillNeeded,
    candidateEmployeeIds: row.candidateEmployeeIds,
    headcount: row.headcount,
    status,
    priority: row.priority,
    submittedAt: row.submittedAt,
    dueAt: row.dueAt,
    notes: row.notes,
  });
  assertLiveWrite(result, "Unable to update staffing request.");
}

async function actOnAccessRequest(item, status) {
  const result = await assetRegisterService.updateAccessRequestStatus(item.sourceId, status);
  assertLiveWrite(result, "Unable to update access request.");
}

async function rejectLifecycleItem(item, approverId, comment) {
  const ref = resolveLifecycleTaskRef(item);
  if (!ref) {
    throw new Error("Lifecycle approval reference is missing.");
  }
  const teamId =
    (item.metadata && item.metadata.userTeamId) ||
    item.userTeamId ||
    commonUtils.getCurrentUserTeamId();
  await onboardingService.rejectLifecycleApprovalTask(
    ref.caseId,
    ref.taskId,
    ref.lifecycle,
    comment,
    teamId
  );
}

async function rejectItem(item, comment) {
  const approverId = commonUtils.getCurrentUserId();
  if (!item) {
    throw new Error("Approval item not found.");
  }
  if (!String(comment || "").trim()) {
    throw new Error("A rejection comment is required.");
  }

  if (item.sourceType === "live" || item.sourceType === "api") {
    if (item.domain === "LEAVE") {
      await leaveService.rejectLeave(item.sourceId, approverId, comment);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "TIMESHEET") {
      await actOnTimesheetApproval(item, approverId, comment, true);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ATTENDANCE") {
      await employeeService.rejectAttendance({
        id: item.sourceId,
        approverId,
        approvalComment: comment,
      });
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ATTENDANCE_REGULARIZATION") {
      const teamId =
        (item.metadata && item.metadata.userTeamId) ||
        item.userTeamId ||
        commonUtils.getCurrentUserTeamId();
      await attendanceRegularizationService.rejectRegularization(
        item.sourceId,
        approverId,
        comment,
        teamId
      );
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ONBOARDING" || item.domain === "OFFBOARDING") {
      await rejectLifecycleItem(item, approverId, comment);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "DOCUMENT") {
      const rejectedBy = commonUtils.getCurrentUserName() || "HR Admin";
      await documentVaultService.rejectDocument(item.sourceId, rejectedBy);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "EXPENSE") {
      const teamId =
        (item.metadata && item.metadata.userTeamId) ||
        item.userTeamId ||
        commonUtils.getCurrentUserTeamId();
      await expensesService.rejectExpenseClaim(item.sourceId, comment, teamId);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "PAYROLL_RUN") {
      throw new Error(
        "Payroll run rejection is not supported from the inbox. Use payroll run workflow to return the run."
      );
    }
    if (item.domain === "PROJECT_GOVERNANCE") {
      await projectGovernanceService.rejectGate(item.sourceId, {
        decisionNotes: comment,
      });
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "STAFFING") {
      await actOnStaffingRequest(item, STAFFING_REQUEST_STATUSES.REJECTED);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "RCA_PUBLICATION") {
      await knowledgeRcaService.rejectRca(item.sourceId);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "ASSET_ACCESS") {
      await actOnAccessRequest(item, ACCESS_REQUEST_STATUSES.REJECTED);
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "TICKET") {
      throw new Error(
        "Ticket rejection is not supported from the inbox. Open the ticket to return it to the queue."
      );
    }
    if (item.domain === "PERFORMANCE_REVIEW") {
      throw new Error(
        "Performance review rejection is not supported from the inbox. Open the review to return it."
      );
    }
    if (item.domain === "FINAL_SETTLEMENT") {
      await rejectLifecycleItem(
        { ...item, domain: "OFFBOARDING" },
        approverId,
        comment
      );
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
    if (item.domain === "EMPLOYEE_ADVANCE") {
      const result = await employeeFinanceService.rejectAdvance(item.sourceId, comment, {
        userTeamId:
          (item.metadata && item.metadata.userTeamId) ||
          item.userTeamId ||
          commonUtils.getCurrentUserTeamId(),
      });
      assertLiveWrite(result, "Unable to reject advance.");
      recordApprovalAudit(item, AUDIT_ACTION_TYPES.REJECTED, comment);
      return { payload: { success: true, id: item.id }, source: "live" };
    }
  }

  assertApprovalActionUnavailable(item);
}

async function getAiSummary(item, slaState) {
  if (shouldUseApprovalAiSummaryApi() && item) {
    try {
      const userTeamId = commonUtils.getCurrentUserTeamId();
      const actorId = commonUtils.getCurrentUserId();
      const request = toApprovalAiSummaryRequest(item, slaState);
      const response = await axiosUtils.post(
        `${urlConfig.APPROVALS_API_PATH}/ai-summary?userTeamId=${userTeamId}&actorId=${actorId}`,
        request
      );
      const payload = normalizeApprovalAiSummary((response && response.payload) || response);
      if (payload) {
        return { payload, source: "api" };
      }
    } catch (e) {
      console.warn("[UniversalApproval] AI summary API unavailable.", e);
      return { payload: null, source: "api-error", error: e };

    }
  }
  if (shouldUseApprovalAiSummaryApi()) {
    return { payload: null, source: "api-error" };
  }
  return apiErrorResult(null);
}
