import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import { connect } from "react-redux";
import { workItemConstants } from "_constants";
import { accessUtils } from "_helpers";
import { store } from "_helpers";
import EmployeeImage from "./fragments/EmployeeImage";
import classNames from "classnames/bind";
import { employeeConstants } from "_constants";
import {
  GLOBAL_RAIL,
  GLOBAL_RAIL_TOOLS,
  isNavItemEnabled,
  shouldShowPlannedRailItem,
} from "config/navigation.config";
import {
  resolveRailBrandMark,
  getRailBrandUrlContext,
  shouldShowRailProductWordmark,
} from "config/brand-rail.utils";
import { appConfigConstants } from "_constants";
import { NAVIGATION_MENU_CHANGED } from "_services/navigation.service";
import { toggleOffcanvasNav } from "_helpers/luxPhone.utils";
import { brandUtils } from "_helpers";
import envconfig from "env.config";
import BrandNameLogo from "./fragments/BrandNameLogo";

/**
 * F01: Global header rail (lux-rail) — items in GLOBAL_RAIL are never duplicated in sidebar.
 * @see docs/additionalfeatures/temp plan/redesigned-menu.md §1
 */
class PageLeftMenubar extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getMenuAccessControl(),
    };
  }

  componentDidMount() {
    window.addEventListener(NAVIGATION_MENU_CHANGED, this.handleNavigationMenuChanged);
  }

  componentWillUnmount() {
    window.removeEventListener(NAVIGATION_MENU_CHANGED, this.handleNavigationMenuChanged);
  }

  handleNavigationMenuChanged = (event) => {
    const menuAccessControl =
      (event && event.detail && event.detail.menuAccessControl) ||
      accessUtils.getMenuAccessControl();
    this.setState({ permission: menuAccessControl });
  };

  toggleTodayActivitySidebar = () => {
    store.dispatch({ type: workItemConstants.SHOW_TODAYS_ACTIVITY_WINDOW });
  };

  toggleNotesOverlay = () => {
    const open = this.props.showNotesOverlay === true;
    store.dispatch({
      type: open
        ? workItemConstants.CLOSE_NOTES_OVERLAY_WINDOW
        : workItemConstants.SHOW_NOTES_OVERLAY_WINDOW,
    });
  };

  toggleUserDivSidebar = () => {
    store.dispatch({ type: employeeConstants.TOGGLE_USER_DIV_WINDOW });
  };

  isItemDisabled = (flagModule, flag) => {
    return !isNavItemEnabled(this.state.permission, flagModule, flag);
  };

  renderBrandImages = () => {
    const brand = resolveRailBrandMark(getRailBrandUrlContext());
    const isDark =
      typeof document !== "undefined" &&
      document.body &&
      document.body.classList.contains("lux-shell-dark");
    const showProductWordmark = shouldShowRailProductWordmark(brand);

    return (
      <>
        <img
          key={brand.id}
          className={classNames("lux-rail-brand-mark", brand.className)}
          src={brand.src}
          alt={brand.alt || ""}
          aria-hidden={brand.alt ? undefined : "true"}
          style={brand.widthPx ? { width: `${brand.widthPx}px` } : undefined}
        />
        {showProductWordmark ? (
          brandUtils.isTracopusApp() ? (
            <BrandNameLogo
              variant="rail"
              includeTagline
              showTagline
              showAiTagline={false}
              logoSurface={isDark ? "dark" : "light"}
              wrapperClassName="lux-rail-brand-lockup"
            />
          ) : (
            <span className="lux-rail-brand-lockup">
              <span className="lux-rail-brand-name">{envconfig.APP_NAME || brandUtils.getAppBrandName()}</span>
            </span>
          )
        ) : null}
      </>
    );
  };

  handleRailAction = (action) => {
    switch (action) {
      case "NOTES_OVERLAY":
        this.toggleNotesOverlay();
        break;
      case "TODAY_ACTIVITY":
        this.toggleTodayActivitySidebar();
        break;
      case "USER_PANEL":
        this.toggleUserDivSidebar();
        break;
      case "MENU_TOGGLE":
        toggleOffcanvasNav();
        break;
      case "SETTINGS":
        store.dispatch({ type: appConfigConstants.SHOW_SETTINGS_WINDOW });
        break;
      case "THEME":
        store.dispatch({ type: appConfigConstants.TOGGLE_LUX_THEME_PANEL });
        break;
      default:
        break;
    }
  };

  renderRailItem = (item) => {
    if (item.type === "planned") {
      if (!shouldShowPlannedRailItem(item)) {
        return null;
      }
      return (
        <span
          key={item.id}
          className={classNames(
            "nav-link icon lux-rail__icon-btn lux-rail__icon-btn--planned disabled colorlightgray",
            item.className
          )}
          title={`${item.title} (coming soon)`}
          aria-label={`${item.title} (coming soon)`}
          data-ga-action={item.gaAction}
          data-ga-category="navigation"
          data-ga-label={item.title}
        >
          <i className={item.icon} aria-hidden="true" />
        </span>
      );
    }

    if (item.type === "action") {
      const disabled = item.flag ? this.isItemDisabled(item.flagModule, item.flag) : false;
      if (item.flag && disabled) {
        return null;
      }
      const isNotes = item.action === "NOTES_OVERLAY";
      const active = isNotes && this.props.showNotesOverlay === true;
      return (
        <button
          key={item.id}
          type="button"
          className={classNames("nav-link icon lux-rail__icon-btn", item.className, {
            active,
            "lux-rail__notes-btn": isNotes,
            "disabled colorlightgray": disabled,
          })}
          onClick={() => this.handleRailAction(item.action)}
          data-ga-action={item.gaAction}
          data-ga-category="navigation"
          data-ga-label={item.title}
          title={item.title}
          aria-pressed={isNotes ? active : undefined}
        >
          <i className={item.icon} aria-hidden="true" />
        </button>
      );
    }

    const disabled = this.isItemDisabled(item.flagModule, item.flag);
    return (
      <NavLink
        key={item.id}
        to={item.path}
        className={classNames("nav-link icon lux-rail__icon-btn", item.className, {
          "disabled colorlightgray": disabled,
        })}
        activeClassName="active"
        data-ga-action={item.gaAction}
        data-ga-category="navigation"
        data-ga-label={item.title}
        title={item.title}
      >
        <i className={item.icon} aria-hidden="true" />
      </NavLink>
    );
  };

  renderToolItem = (item) => {
    if (item.id === "user") {
      return (
        <button
          key={item.id}
          type="button"
          className="link nav-link lux-rail__avatar-btn user_btn"
          onClick={() => this.handleRailAction(item.action)}
          data-ga-action={item.gaAction}
          data-ga-category="navigation"
          data-ga-label={item.title}
          title={item.title}
        >
          <EmployeeImage
            employee={this.props.authentication && this.props.authentication.user}
            classes="avatar"
          />
        </button>
      );
    }

    if (item.type === "link") {
      const disabled = this.isItemDisabled(item.flagModule, item.flag);
      if (item.flag && disabled) {
        return null;
      }
      return (
        <NavLink
          key={item.id}
          to={item.path}
          className={classNames("nav-link icon lux-rail__icon-btn", item.className, {
            "disabled colorlightgray": disabled,
          })}
          activeClassName="active"
          data-ga-action={item.gaAction}
          data-ga-category="navigation"
          data-ga-label={item.title}
          title={item.title}
        >
          <i className={item.icon} aria-hidden="true" />
        </NavLink>
      );
    }

    return (
      <button
        key={item.id}
        type="button"
        className={classNames("link nav-link icon lux-rail__icon-btn", item.className, {
          // Do not add legacy `settingbar` / `theme_btn` — core.js toggles `.open`
          // independently of Redux and leaves the workspace settings drawer stuck open.
          todayactivity: item.action === "TODAY_ACTIVITY",
          "lux-rail__menu-toggle": item.action === "MENU_TOGGLE",
        })}
        onClick={() => this.handleRailAction(item.action)}
        data-ga-action={item.gaAction}
        data-ga-category="navigation"
        data-ga-label={item.title}
        title={item.title}
      >
        {item.icon && <i className={item.icon} aria-hidden="true" />}
      </button>
    );
  };

  render() {
    const dashboardExplicitlyOff =
      this.state.permission &&
      this.state.permission.projectModules &&
      this.state.permission.projectModules.dashboardEnabled === false;

    return (
      <div id="header_top" className="header_top no-print lux-rail" data-tour="lux-rail">
        <div className="container">
          <div className="hleft">
            {dashboardExplicitlyOff ? (
              <NavLink
                to="/project/dashboard"
                className="header-brand"
                data-ga-action="nav_dashboard"
                data-ga-category="navigation"
                data-ga-label="Dashboard"
              >
                {this.renderBrandImages()}
              </NavLink>
            ) : (
              <button
                type="button"
                className="link header-brand"
                data-ga-action="nav_brand"
                data-ga-category="navigation"
                data-ga-label="Brand"
              >
                {this.renderBrandImages()}
              </button>
            )}

            <div className="dropdown lux-rail__nav">
              {GLOBAL_RAIL.map((item) => this.renderRailItem(item))}
            </div>
          </div>
          <div className="hright">
            <div className="dropdown lux-rail__tools">
              {GLOBAL_RAIL_TOOLS.map((item) => this.renderToolItem(item))}
            </div>
          </div>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  showNotesOverlay: state.workItem && state.workItem.showNotesOverlay,
  authentication: state.authentication,
});

export default connect(mapStateToProps)(PageLeftMenubar);
