import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAiWorkIntelligenceEnabled } from "config/ai-work-intelligence.config";
import { AI_CONSOLE_PAGE_META } from "config/ai-work-intelligence-nav.config";
import { buildAgentConsoleKpis, filterAgentsByPersona } from "config/ai-work-intelligence.utils";
import { canViewAiWorkIntelligence } from "config/ai-work-intelligence-security.utils";
import { aiWorkIntelligenceService } from "_services/aiWorkIntelligence.service";
import AiLuxPage, { AiActionButton, AiInsightPanel, AiLuxPanel } from "views/ai/components/AiLuxShared";
import AiHitlSnapshotStrip from "views/ai/components/AiHitlSnapshotStrip";
import AgentRegistryPanel, { AgentRunHistoryRegister } from "views/ai/components/AgentRegistryPanel";
import AgentRecommendationPanel from "views/ai/components/AgentRecommendationPanel";

class AIAgentConsolePage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    kpiCards: [],
    overview: null,
    llmAccess: null,
    insights: [],
    agents: [],
    runs: [],
    recommendations: [],
    selectedAgentId: null,
    selectedRecommendationId: null,
    runningAgentId: null,
    busyId: null,
  };

  componentDidMount() {
    this.loadData();
  }

  getActivePersona = () => {
    const personaCtx = this.props.personaContext || {};
    return personaCtx.activePersona || "EXECUTIVE";
  };

  loadData = async () => {
    const persona = this.getActivePersona();
    this.setState({ loading: true, loadError: null });
    try {
      const [overviewResult, agentsResult, runsResult, recsResult] = await Promise.all([
        aiWorkIntelligenceService.getAgentConsoleOverview({ persona }),
        aiWorkIntelligenceService.listAgents({ persona }),
        aiWorkIntelligenceService.listAgentRuns({ persona }),
        aiWorkIntelligenceService.listRecommendations({ persona }),
      ]);
      const overviewPayload = overviewResult.payload || {};
      const agents = filterAgentsByPersona(agentsResult.payload || [], persona);
      const recommendations = recsResult.payload || [];
      this.setState({
        loading: false,
        dataSource: overviewResult.source,
        overview: overviewPayload.overview || null,
        llmAccess: overviewPayload.llmAccess || null,
        kpiCards: buildAgentConsoleKpis(overviewPayload.overview),
        insights: overviewPayload.insights || [],
        agents,
        runs: runsResult.payload || [],
        recommendations,
        selectedAgentId: agents[0] ? agents[0].id : null,
        selectedRecommendationId: recommendations[0] ? recommendations[0].id : null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load AI agent console.",
      });
    }
  };

  handleRunAgent = async (agentId) => {
    const persona = this.getActivePersona();
    this.setState({ runningAgentId: agentId, loadError: null });
    try {
      const result = await aiWorkIntelligenceService.runAgent(agentId, { persona, scope: "portfolio" });
      const recommendation = result.payload && result.payload.recommendation;
      this.setState({
        selectedAgentId: agentId,
        selectedRecommendationId: recommendation ? recommendation.id : this.state.selectedRecommendationId,
      });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to run agent." });
    } finally {
      this.setState({ runningAgentId: null });
    }
  };

  handleDecide = async (recommendationId, decision, rationale) => {
    const persona = this.getActivePersona();
    this.setState({ busyId: recommendationId, loadError: null });
    try {
      await aiWorkIntelligenceService.decideRecommendation(recommendationId, decision, rationale, { persona });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to record decision." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  handleExport = async () => {
    const persona = this.getActivePersona();
    try {
      const result = await aiWorkIntelligenceService.exportRecommendationsCsv({ persona });
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "ai-recommendations.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to export recommendations." });
    }
  };

  render() {
    if (!isAiWorkIntelligenceEnabled()) {
      return <PersonaAccessDenied title="AI agent console" message="AI work intelligence is not enabled for this organization." />;
    }
    const persona = this.getActivePersona();
    if (!canViewAiWorkIntelligence(persona)) {
      return <PersonaAccessDenied title="AI agent console" message="Your persona cannot access AI work intelligence." />;
    }

    const {
      loading,
      loadError,
      dataSource,
      kpiCards,
      overview,
      llmAccess,
      insights,
      agents,
      runs,
      recommendations,
      selectedAgentId,
      selectedRecommendationId,
      runningAgentId,
      busyId,
    } = this.state;

    return (
      <AiLuxPage
        pageMeta={AI_CONSOLE_PAGE_META}
        pageId="agents"
        shellTitle="Agent console"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><AiActionButton icon="fe fe-download" onClick={this.handleExport}>
              Export CSV
            </AiActionButton>
          </>}
      >
        {loadError ? <p className="lux-ai-intel-error">{loadError}</p> : null}
        <AiInsightPanel insights={insights} />
        <AiHitlSnapshotStrip overview={overview} llmAccess={llmAccess} loading={loading} />

        <div className="lux-ai-intel-layout lux-ai-intel-layout--console">
          <AiLuxPanel
            title="Agent registry"
            meta="Run agents and inspect human-in-the-loop drafts"
            icon="fe fe-cpu"
            accent="violet"
            featured
          >
            <AgentRegistryPanel
              agents={agents}
              recommendations={recommendations}
              activePersona={persona}
              selectedAgentId={selectedAgentId}
              onSelectAgent={(agentId) => this.setState({ selectedAgentId: agentId })}
              onRunAgent={this.handleRunAgent}
              runningAgentId={runningAgentId}
              loading={loading}
            />
          </AiLuxPanel>

          <AiLuxPanel title="Recommendation queue" meta="Evidence, confidence, and decisions" icon="fe fe-inbox" accent="indigo">
            <AgentRecommendationPanel
              recommendations={recommendations}
              activePersona={persona}
              selectedRecommendationId={selectedRecommendationId}
              onSelectRecommendation={(id) => this.setState({ selectedRecommendationId: id })}
              onDecide={this.handleDecide}
              busyId={busyId}
              loading={loading}
              filterAgentId={selectedAgentId}
            />
          </AiLuxPanel>
        </div>

        <AiLuxPanel title="Run history" meta="Recent agent executions" icon="fe fe-clock" accent="emerald">
          <AgentRunHistoryRegister runs={runs} loading={loading} />
        </AiLuxPanel>
      </AiLuxPage>
    );
  }
}

export default AIAgentConsolePage;
