import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { PeopleRowAction } from "views/people/components/PeopleLuxShared";

function StatusBadge({ status }) {
  const normalized = String(status || "").toLowerCase();
  return (
    <span
      className={classNames("lux-doc-badge", {
        "is-success": normalized.includes("verified"),
        "is-warning": normalized.includes("pending"),
        "is-danger": normalized.includes("reject") || normalized.includes("expired"),
      })}
    >
      {status || "—"}
    </span>
  );
}

export default function DocumentVerificationQueue({ documents, loading, onVerify, onReject }) {
  if (loading) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="Loading verification queue"
        description="Fetching documents pending HR review."
      />
    );
  }

  if (!documents || documents.length === 0) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        icon="fe fe-check-circle"
        title="Verification queue clear"
        description="No documents are waiting for HR verification."
      />
    );
  }

  return (
    <div className="lux-doc-register-wrap">
      <table className="lux-doc-register">
        <thead>
          <tr>
            <th>Document</th>
            <th>Employee</th>
            <th>Type</th>
            <th>Uploaded</th>
            <th>Status</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {documents.map((row) => (
            <tr key={row.id}>
              <td>
                <strong>{row.title}</strong>
                {row.fileName && <span className="lux-doc-register__meta">{row.fileName}</span>}
              </td>
              <td>{row.employeeName || "—"}</td>
              <td>{row.typeLabel || row.type}</td>
              <td>{row.uploadedAt || "—"}</td>
              <td>
                <StatusBadge status={row.status} />
              </td>
              <td>
                <PeopleRowAction icon="fe fe-check" onClick={() => onVerify(row)}>
                  Verify
                </PeopleRowAction>
                {typeof onReject === "function" && (
                  <PeopleRowAction icon="fe fe-x" onClick={() => onReject(row)}>
                    Reject
                  </PeopleRowAction>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
