import React, { useState } from "react";

const DEFAULT_VISIBLE_COUNT = 3;

function AsideExpandableChipList({
  items,
  emptyLabel,
  initialVisible = DEFAULT_VISIBLE_COUNT,
}) {
  const [expanded, setExpanded] = useState(false);

  if (!items || !items.length) {
    return <p className="profile-aside-card__empty">{emptyLabel || "None recorded"}</p>;
  }

  const hasMore = items.length > initialVisible;
  const visibleItems = expanded || !hasMore ? items : items.slice(0, initialVisible);
  const hiddenCount = items.length - initialVisible;

  return (
    <div className="profile-aside-expandable">
      <div className="profile-chip-list profile-aside-chip-list">
        {visibleItems.map((item) => (
          <span key={item} className="profile-chip">
            {item}
          </span>
        ))}
      </div>
      {hasMore && (
        <button
          type="button"
          className="profile-aside-expand"
          onClick={() => setExpanded((prev) => !prev)}
          aria-expanded={expanded}
        >
          {expanded ? (
            <>
              <i className="fe fe-chevron-up" aria-hidden="true" />
              Show less
            </>
          ) : (
            <>
              <i className="fe fe-chevron-down" aria-hidden="true" />
              Show all ({items.length})
              {hiddenCount > 0 && (
                <span className="profile-aside-expand__meta">+{hiddenCount} more</span>
              )}
            </>
          )}
        </button>
      )}
    </div>
  );
}

export default AsideExpandableChipList;
