import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

function KpiCard({ label, value, suffix, hint, tone, icon, isPercent }) {
  const displayValue = isPercent ? parseInt(String(value).replace("%", ""), 10) : Number(value) || 0;

  return (
    <article className={classNames("lux-hrms-dash__kpi", tone && `is-${tone}`)}>
      <div className="lux-hrms-dash__kpi-top">
        <span className="lux-hrms-dash__kpi-label">{label}</span>
        {icon && (
          <span className="lux-hrms-dash__kpi-icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </span>
        )}
      </div>
      <strong className="lux-hrms-dash__kpi-value">
        <CountUp end={displayValue} duration={0.8} separator="," />
        {suffix && <small>{suffix}</small>}
        {isPercent && <small>%</small>}
      </strong>
      {hint && <span className="lux-hrms-dash__kpi-hint">{hint}</span>}
    </article>
  );
}

function OnboardingKpiStrip({ metrics, lifecycle = "onboarding" }) {
  const items =
    lifecycle === "offboarding"
      ? [
          { id: "active", label: "Active exits", value: metrics.active, hint: "In progress now", tone: "amber", icon: "fe-user-x" },
          { id: "blocked", label: "Blocked", value: metrics.blocked, hint: "Needs HR attention", tone: "rose", icon: "fe-alert-circle" },
          { id: "due", label: "Due this week", value: metrics.dueThisWeek, hint: "Last days approaching", tone: "primary", icon: "fe-calendar" },
          { id: "progress", label: "Avg progress", value: metrics.avgProgress, hint: "Across open cases", tone: "green", icon: "fe-trending-up", isPercent: true },
        ]
      : [
          { id: "active", label: "Active onboardings", value: metrics.active, hint: "In progress or ready", tone: "primary", icon: "fe-user-plus" },
          { id: "overdue", label: "Overdue tasks", value: metrics.overdueTasks, hint: "Past due date", tone: "rose", icon: "fe-clock" },
          { id: "ready", label: "Ready to start", value: metrics.ready, hint: "Day-one cleared", tone: "green", icon: "fe-check-circle" },
          { id: "readiness", label: "Avg readiness", value: metrics.avgReadiness, hint: "Checklist completion", tone: "violet", icon: "fe-activity", isPercent: true },
        ];

  return (
    <div className="lux-hrms-dash__kpi-strip lux-onb-kpi-strip" role="list">
      {items.map((item) => (
        <KpiCard key={item.id} {...item} />
      ))}
    </div>
  );
}

export default OnboardingKpiStrip;
