import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isDataRetentionAdminEnabled } from "config/data-retention.config";
import {
  buildRetentionDomainSeries,
  buildRetentionPolicyInsights,
  buildRetentionPolicyMetrics,
  buildRetentionStatusSeries,
  filterRetentionPolicies,
} from "config/data-retention.utils";
import { dataRetentionService } from "_services/dataRetention.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import DataRetentionRegister from "views/admin/components/DataRetentionRegister";
import DataRetentionDetailPanel from "views/admin/components/DataRetentionDetailPanel";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

const DOMAIN_FILTERS = ["ALL", "Compliance", "People", "Payroll", "Documents", "Finance", "HR"];

class DataRetentionPage extends Component {
  state = {
    policies: [],
    loading: true,
    loadError: null,
    dataSource: null,
    domainFilter: "ALL",
    statusFilter: "ALL",
    query: "",
    selectedId: null,
    savingKey: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Data retention");
    this.loadPolicies();
  }

  loadPolicies = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await dataRetentionService.listPolicies();
      const policies = result.payload || [];
      this.setState({
        policies,
        loading: false,
        dataSource: result.source || null,
        selectedId: this.state.selectedId || (policies[0] && policies[0].id) || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load retention policies.",
        policies: [],
      });
    }
  };

  getFilteredPolicies = () => {
    const { policies, domainFilter, statusFilter, query } = this.state;
    return filterRetentionPolicies(policies, {
      domain: domainFilter,
      status: statusFilter,
      query,
    });
  };

  getSelectedPolicy = () => {
    const { policies, selectedId } = this.state;
    return policies.find((row) => row.id === selectedId) || null;
  };

  handleSetRetentionDays = async (retentionDays) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    const savingKey = `${selectedId}:days`;
    this.setState({ savingKey });
    try {
      const result = await dataRetentionService.updateRetentionDays(selectedId, retentionDays);
      this.setState((prev) => ({
        policies: prev.policies.map((row) => (row.id === selectedId ? result.payload : row)),
        savingKey: null,
      }));
    } catch (e) {
      this.setState({ savingKey: null });
    }
  };

  handleToggleLegalHold = async (legalHold) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    const savingKey = `${selectedId}:hold`;
    this.setState({ savingKey });
    try {
      const result = await dataRetentionService.updateLegalHold(selectedId, legalHold);
      this.setState((prev) => ({
        policies: prev.policies.map((row) => (row.id === selectedId ? result.payload : row)),
        savingKey: null,
      }));
    } catch (e) {
      this.setState({ savingKey: null });
    }
  };

  handleToggleAutoPurge = async (autoPurge) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    const savingKey = `${selectedId}:purge`;
    this.setState({ savingKey });
    try {
      const result = await dataRetentionService.updateAutoPurge(selectedId, autoPurge);
      this.setState((prev) => ({
        policies: prev.policies.map((row) => (row.id === selectedId ? result.payload : row)),
        savingKey: null,
      }));
    } catch (e) {
      this.setState({ savingKey: null });
    }
  };

  renderInsights = () => {
    const { policies, loading } = this.state;
    if (loading) return null;
    const insights = buildRetentionPolicyInsights(policies);
    return (
      <div className="lux-retention-insights" role="list">
        {insights.map((insight) => (
          <article key={insight.id} className={classNames("lux-retention-insight-card", `is-${insight.tone}`)} role="listitem">
            <span className="lux-retention-insight-card__icon" aria-hidden="true">
              <i className={insight.icon} />
            </span>
            <div className="lux-retention-insight-card__copy">
              <strong>{insight.title}</strong>
              <p>{insight.copy}</p>
            </div>
          </article>
        ))}
      </div>
    );
  };

  render() {
    if (!isDataRetentionAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Data retention"
          reason="Data retention administration is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, domainFilter, statusFilter, query } = this.state;
    const filteredPolicies = this.getFilteredPolicies();
    const metrics = buildRetentionPolicyMetrics(this.state.policies);
    const domainSeries = buildRetentionDomainSeries(this.state.policies);
    const statusSeries = buildRetentionStatusSeries(this.state.policies);

    const kpiCards = [
      { id: "policies", label: "Policies", value: metrics.totalPolicies, hint: `${metrics.autoPurgeCount} auto-purge`, tone: "primary", icon: "fe fe-archive" },
      { id: "hold", label: "Legal holds", value: metrics.legalHoldCount, hint: "Purge suspended", tone: "rose", icon: "fe fe-alert-octagon" },
      { id: "records", label: "Records held", value: metrics.recordsHeld.toLocaleString(), hint: "Across entity types", tone: "blue", icon: "fe fe-database" },
      { id: "expiring", label: "Expiring soon", value: metrics.expiringSoon, hint: "Within 90 days", tone: "amber", icon: "fe fe-clock" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.dataRetention}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-data-retention"
        className="lux-register-page lux-retention-page"
        onRefresh={this.loadPolicies}
        refreshLoading={loading}
      >
        <LuxInlineAlert
          tone="warning"
          className="lux-retention-enforcement-banner"
          testId="retention-enforcement-banner"
        >
          <strong>Policy registry.</strong> Retention windows and legal holds are saved here; automated purge/scheduler
          enforcement is not guaranteed yet. Treat this as configuration until scheduler proof lands.
        </LuxInlineAlert>
{loadError && (
          <div className="lux-employee-360__error lux-retention__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadPolicies}>
              Retry
            </AdminActionButton>
          </div>
        )}

        {this.renderInsights()}

        <section className="lux-retention-analytics lux-hrms-dash__panel">
          <AdminPanelHead title="Retention analytics" subtitle="Record volume by domain and policy posture mix." />
          <div className="lux-retention-analytics__grid">
            <PolicyAnalyticsBarChart title="Records by domain" subtitle="Held record counts" series={domainSeries} />
            <PolicyAnalyticsBarChart title="Policy status" subtitle="Active vs legal hold vs archived" series={statusSeries} />
          </div>
        </section>

        <section className="lux-hrms-dash__panel lux-retention-panel">
          <AdminPanelHead
            title="Retention policy registry"
            subtitle="Select an entity type to adjust retention windows, legal holds, and auto-purge. Changes are audited when audit writes are enabled."
            actions={<AdminPanelLink to="/admin/security">Security settings</AdminPanelLink>}
          />

          <div className="lux-retention-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search entity or policy name"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filteredPolicies.length}</strong> polic{filteredPolicies.length === 1 ? "y" : "ies"}
              </span>
            </div>
            <div className="lux-retention-panel__filters">
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Domain</span>
                <div className="lux-hrms-dash__filter-group">
                  {DOMAIN_FILTERS.map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": domainFilter === value })}
                      onClick={() => this.setState({ domainFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Status</span>
                <div className="lux-hrms-dash__filter-group">
                  {["ALL", "ACTIVE", "LEGAL_HOLD", "ARCHIVED"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === value })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value === "LEGAL_HOLD" ? "Legal hold" : value.charAt(0) + value.slice(1).toLowerCase()}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-retention-panel__body">
            <div className="lux-retention-panel__grid">
              <div className="lux-retention-panel__register">
                {loading ? (
                  <LuxRegisterEmptyState title="Loading policies" description="Fetching retention policy registry." />
                ) : filteredPolicies.length === 0 ? (
                  <LuxRegisterEmptyState title="No policies match" description="Adjust filters or search." />
                ) : (
                  <DataRetentionRegister
                    policies={filteredPolicies}
                    selectedId={this.state.selectedId}
                    onSelect={(policy) => this.setState({ selectedId: policy.id })}
                  />
                )}
              </div>
              <DataRetentionDetailPanel
                policy={this.getSelectedPolicy()}
                savingKey={this.state.savingKey}
                onSetRetentionDays={this.handleSetRetentionDays}
                onToggleLegalHold={this.handleToggleLegalHold}
                onToggleAutoPurge={this.handleToggleAutoPurge}
              />
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default DataRetentionPage;
