import React from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { getAdapterKindLabel, getTransportLabel } from "config/integration-adapter.utils";
import { IntegrationActionButton } from "views/integrations/components/IntegrationsLuxShared";

function AdapterTestBadge({ status }) {
  const tone =
    status === "passed" ? "success" : status === "failed" ? "danger" : status === "running" ? "warning" : "neutral";
  return <span className={classNames("lux-integ-adapter-test", `is-${tone}`)}>{status}</span>;
}

export function AdapterTransportFilter({ value, onChange }) {
  const options = [
    { id: "ALL", label: "All transports" },
    { id: "api", label: "API" },
    { id: "webhook", label: "Webhook" },
    { id: "file", label: "File" },
    { id: "sftp", label: "SFTP" },
  ];
  return (
    <div className="lux-integ-filter-bar" role="tablist" aria-label="Transport filter">
      {options.map((option) => (
        <button
          key={option.id}
          type="button"
          role="tab"
          aria-selected={value === option.id}
          className={classNames("lux-integ-filter-bar__chip", { "is-active": value === option.id })}
          onClick={() => onChange(option.id)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

export default function AdapterRegister({
  adapters = [],
  loading,
  onSelect,
  selectedId,
  onTest,
  onSync,
  busyId,
  actionBusyId,
}) {
  if (loading) {
    return <div className="lux-integ-register__skeleton" aria-busy="true" />;
  }
  if (!adapters.length) {
    return (
      <div className="lux-integ-register__empty">
        <i className="fe fe-package lux-integ-register__empty-icon" aria-hidden="true" />
        <strong>No adapters registered</strong>
        <p>Adapter wrappers appear here once connectors are provisioned.</p>
      </div>
    );
  }

  return (
    <div className="lux-integ-adapter-grid">
      {adapters.map((row) => (
        <article
          key={row.id}
          className={classNames(
            "lux-integ-adapter-card",
            row.tone && `is-tone-${row.tone}`,
            row.testStatus && `is-test-${row.testStatus}`,
            { "is-selected": selectedId === row.id }
          )}
        >
          <header className="lux-integ-adapter-card__head">
            <span className="lux-integ-adapter-card__icon" aria-hidden="true">
              <i className={row.icon || "fe fe-package"} />
            </span>
            <div className="lux-integ-adapter-card__title">
              <strong>{row.name}</strong>
              <small>{getAdapterKindLabel(row.kind)} · v{row.version}</small>
            </div>
            <AdapterTestBadge status={row.testStatus} />
          </header>
          <p className="lux-integ-adapter-card__lede">{row.description}</p>
          <div className="lux-integ-adapter-card__chips">
            <span className="lux-integ-register__pill">{getTransportLabel(row.transport)}</span>
            {row.connectorName ? <span className="lux-integ-register__pill">{row.connectorName}</span> : null}
          </div>
          <div className="lux-integ-adapter-card__metric-grid">
            <article>
              <span>Success</span>
              <strong>{row.successRatePct}%</strong>
            </article>
            <article>
              <span>Records/run</span>
              <strong>{row.recordsPerRun}</strong>
            </article>
            <article>
              <span>Objects</span>
              <strong>{(row.capabilities || []).length}</strong>
            </article>
          </div>
          <div className="lux-integ-adapter-card__actions">
            <IntegrationActionButton
              variant="ghost"
              icon="fe fe-zap"
              disabled={actionBusyId === row.id}
              onClick={() => onTest && onTest(row)}
            >
              Test
            </IntegrationActionButton>
            <IntegrationActionButton
              variant="ghost"
              icon="fe fe-play"
              disabled={busyId === row.id}
              onClick={() => onSync && onSync(row)}
            >
              Sync
            </IntegrationActionButton>
            {onSelect ? (
              <button type="button" className="lux-integ-adapter-card__select" onClick={() => onSelect(row)}>
                <span>Details</span>
                <i className="fe fe-arrow-right" aria-hidden="true" />
              </button>
            ) : null}
          </div>
        </article>
      ))}
    </div>
  );
}

export function AdapterDetailDrawer({ adapter, testResult, syncResult, testing, syncing, onClose, onTest, onSync }) {
  if (!adapter) {
    return null;
  }

  const accent =
    adapter.testStatus === "failed" ? "danger" : adapter.testStatus === "passed" ? "success" : "blue";

  return createPortal(
    <div className="lux-integ-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-integ-drawer", "lux-integ-drawer--adapter", `lux-integ-drawer--${accent}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-integ-adapter-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <span className="lux-integ-drawer__accent" aria-hidden="true" />

        <header className="lux-integ-drawer__head">
          <div className="lux-integ-drawer__head-main">
            <span className="lux-integ-drawer__category-icon" aria-hidden="true">
              <i className={adapter.icon || "fe fe-package"} />
            </span>
            <div className="lux-integ-drawer__head-copy">
              <span className="lux-integ-drawer__eyebrow">
                {getAdapterKindLabel(adapter.kind)} · {getTransportLabel(adapter.transport)}
              </span>
              <h2 id="lux-integ-adapter-drawer-title">{adapter.name}</h2>
              <div className="lux-integ-drawer__badges">
                <AdapterTestBadge status={adapter.testStatus} />
                <span className="lux-integ-register__pill">v{adapter.version}</span>
              </div>
            </div>
          </div>
          <button type="button" className="lux-integ-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-integ-drawer__body">
          <div
            className={classNames(
              "lux-integ-drawer__banner",
              adapter.testStatus === "failed" ? "is-alert" : "is-success"
            )}
          >
            <span className="lux-integ-drawer__banner-icon" aria-hidden="true">
              <i className={adapter.testStatus === "failed" ? "fe fe-alert-triangle" : "fe fe-check-circle"} />
            </span>
            <div>
              <strong>{adapter.testStatus === "failed" ? "Connection test failed" : "Adapter ready"}</strong>
              <p>{adapter.configSummary}</p>
            </div>
          </div>

          <div className="lux-integ-drawer__metrics">
            <article className="lux-integ-drawer__metric is-green">
              <span>Success rate</span>
              <strong>{adapter.successRatePct}%</strong>
            </article>
            <article className="lux-integ-drawer__metric is-blue">
              <span>Records / run</span>
              <strong>{adapter.recordsPerRun}</strong>
            </article>
            <article className="lux-integ-drawer__metric is-indigo">
              <span>Objects</span>
              <strong>{(adapter.capabilities || []).length}</strong>
            </article>
          </div>

          {testResult ? (
            <section className={classNames("lux-integ-adapter-result", testResult.success ? "is-success" : "is-error")}>
              <header>
                <i className="fe fe-zap" aria-hidden="true" />
                <span>Connection test</span>
              </header>
              <p>{testResult.message}</p>
              {testResult.latencyMs != null ? (
                <small>Latency {testResult.latencyMs}ms</small>
              ) : null}
            </section>
          ) : null}

          {syncResult ? (
            <section className="lux-integ-adapter-result is-sync">
              <header>
                <i className="fe fe-play" aria-hidden="true" />
                <span>Sync triggered</span>
              </header>
              <p>{syncResult.message}</p>
              {syncResult.jobId ? <code>{syncResult.jobId}</code> : null}
            </section>
          ) : null}

          <section className="lux-integ-drawer__section">
            <h3>Capabilities</h3>
            <div className="lux-integ-adapter-capabilities">
              {(adapter.capabilities || []).map((cap) => (
                <span key={cap} className="lux-integ-adapter-cap">
                  {cap}
                </span>
              ))}
            </div>
          </section>

          <section className="lux-integ-drawer__section">
            <h3>Configuration</h3>
            <div className="lux-integ-drawer__facts">
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-settings" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Profile</span>
                  <span className="lux-integ-drawer__fact-value">{adapter.configSummary}</span>
                </div>
              </article>
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-link" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Linked connector</span>
                  <span className="lux-integ-drawer__fact-value">{adapter.connectorName || "Internal feed"}</span>
                </div>
              </article>
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-clock" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Last tested</span>
                  <span className="lux-integ-drawer__fact-value">
                    {adapter.lastTestedAt ? new Date(adapter.lastTestedAt).toLocaleString() : "—"}
                  </span>
                </div>
              </article>
            </div>
          </section>

          <section className="lux-integ-drawer__notes-card">
            <header>
              <i className="fe fe-align-left" aria-hidden="true" />
              <span>Adapter scope</span>
            </header>
            <p>{adapter.description}</p>
          </section>
        </div>

        <footer className="lux-integ-drawer__footer">
          <IntegrationActionButton variant="ghost" icon="fe fe-zap" disabled={testing} onClick={() => onTest && onTest(adapter)}>
            {testing ? "Testing…" : "Test connection"}
          </IntegrationActionButton>
          <IntegrationActionButton icon="fe fe-play" disabled={syncing} onClick={() => onSync && onSync(adapter)}>
            {syncing ? "Starting…" : "Trigger sync"}
          </IntegrationActionButton>
        </footer>
      </aside>
    </div>,
    document.body
  );
}
