import React, { useEffect, useState } from "react";
import { onboardingService } from "_services/onboarding.service";
import { formatLifecycleAuditEvent } from "config/onboarding.utils";

function LifecycleCaseAuditStrip({ caseId, lifecycle = "onboarding" }) {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!caseId) {
      setEvents([]);
      setLoading(false);
      return undefined;
    }
    let cancelled = false;
    setLoading(true);
    const load = lifecycle === "offboarding"
      ? onboardingService.getOffboardingCaseAudit(caseId)
      : onboardingService.getOnboardingCaseAudit(caseId);
    load
      .then((res) => {
        if (!cancelled) {
          setEvents(Array.isArray(res.payload) ? res.payload : []);
          setLoading(false);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setEvents([]);
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [caseId, lifecycle]);

  if (loading || !events.length) {
    return null;
  }

  return (
    <section className="lux-onb-detail__cta lux-onb-audit" aria-label="Case audit timeline">
      <div className="lux-onb-audit__head">
        <i className="fe fe-activity" aria-hidden />
        <div>
          <strong>Case activity</strong>
          <p className="lux-onb-detail__cta-hint">Audit trail for lifecycle mutations on this case.</p>
        </div>
      </div>
      <ol className="lux-onb-audit__list">
        {events.map((event) => {
          const formatted = formatLifecycleAuditEvent(event);
          return (
            <li key={event.id || `${formatted.at}-${formatted.label}`}>
              <span className="lux-onb-audit__date">{formatted.at}</span>
              <span className="lux-onb-audit__label">{formatted.label}</span>
              {formatted.detail && <span className="lux-onb-audit__detail">{formatted.detail}</span>}
            </li>
          );
        })}
      </ol>
    </section>
  );
}

export default LifecycleCaseAuditStrip;
