import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { getEmployeeDailyCapacityMinutes } from "../plannerCapacity.utils";
import { measurePlannerOverlayTop } from "../plannerOverlay.utils";
import { formatPlannerHours, getPlannerRosterEmployees } from "../planner.utils";

function employeeInitials(name) {
  const parts = String(name || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0] || ""}${parts[parts.length - 1][0] || ""}`.toUpperCase();
}

export default function PlannerCapacitySettings({
  open,
  onClose,
  employees,
  capacityOverrides,
  onSaveOverride,
}) {
  const roster = useMemo(() => getPlannerRosterEmployees(employees), [employees]);
  const [query, setQuery] = useState("");
  const [panelTop, setPanelTop] = useState(0);

  const syncPanelTop = useCallback(() => {
    setPanelTop(measurePlannerOverlayTop());
  }, []);

  useEffect(() => {
    if (!open) return undefined;
    syncPanelTop();
    window.addEventListener("resize", syncPanelTop);
    window.addEventListener("scroll", syncPanelTop, true);
    return () => {
      window.removeEventListener("resize", syncPanelTop);
      window.removeEventListener("scroll", syncPanelTop, true);
    };
  }, [open, syncPanelTop]);

  useEffect(() => {
    if (!open) setQuery("");
  }, [open]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (q.length < 2) return roster;
    return roster.filter((e) => (e.name || "").toLowerCase().includes(q));
  }, [roster, query]);

  const overrideCount = useMemo(() => {
    if (!capacityOverrides) return 0;
    return roster.filter((emp) => capacityOverrides[String(emp.id)] != null).length;
  }, [roster, capacityOverrides]);

  if (!open || typeof document === "undefined") return null;

  const panelStyle = {
    top: panelTop,
    height: `calc(100dvh - ${panelTop}px)`,
  };

  return createPortal(
    <div className="lux-planner-capacity-portal" role="presentation">
      <button
        type="button"
        className="lux-planner-capacity-portal__backdrop"
        aria-label="Close capacity settings"
        onClick={onClose}
      />
      <aside
        className={classNames("lux-planner-capacity-panel", { "is-open": open })}
        style={panelStyle}
        role="dialog"
        aria-modal="true"
        aria-label="Per-person capacity"
        data-testid="planner-capacity-settings"
      >
        <header className="lux-planner-capacity-panel__hero">
          <div className="lux-planner-capacity-panel__hero-bg" aria-hidden />
          <button
            type="button"
            className="lux-planner-capacity-panel__close"
            onClick={onClose}
            aria-label="Close"
          >
            <i className="fe fe-x" />
          </button>

          <div className="lux-planner-capacity-panel__hero-top">
            <span className="lux-planner-capacity-panel__mark" aria-hidden>
              <i className="fe fe-sliders" />
            </span>
            <div className="lux-planner-capacity-panel__hero-copy">
              <span className="lux-planner-capacity-panel__eyebrow">Team capacity</span>
              <h2>Per-person capacity</h2>
              <p>
                Set daily hours that drive roster and timeline utilization. Profile FTE fills in when
                no override is set.
              </p>
            </div>
          </div>

          <div className="lux-planner-capacity-panel__kpis" aria-label="Capacity summary">
            <article>
              <em>People</em>
              <strong>{roster.length}</strong>
            </article>
            <article className={overrideCount ? "is-accent" : ""}>
              <em>Overrides</em>
              <strong>{overrideCount}</strong>
            </article>
            <article>
              <em>Scope</em>
              <strong>Browser</strong>
            </article>
          </div>

          <label className="lux-planner-capacity-panel__search">
            <i className="fe fe-search" aria-hidden />
            <input
              type="search"
              placeholder="Search team member…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              aria-label="Search team member"
            />
          </label>
        </header>

        <div className="lux-planner-capacity-panel__body">
          <p className="lux-planner-capacity-intro">
            <i className="fe fe-info" aria-hidden />
            <span>
              Overrides stay in this browser only and do not change payroll or profile settings.
            </span>
          </p>
          <ul className="lux-planner-capacity-list">
            {filtered.length === 0 ? (
              <li className="lux-planner-capacity-list__empty">
                <i className="fe fe-users" aria-hidden />
                <strong>No matches</strong>
                <span>Try another name or clear the search.</span>
              </li>
            ) : (
              filtered.map((emp) => (
                <CapacityRow
                  key={emp.id}
                  employee={emp}
                  capacityOverrides={capacityOverrides}
                  onSaveOverride={onSaveOverride}
                />
              ))
            )}
          </ul>
        </div>
      </aside>
    </div>,
    document.body
  );
}

function CapacityRow({ employee, capacityOverrides, onSaveOverride }) {
  const defaultMins = getEmployeeDailyCapacityMinutes(employee, {});
  const storedOverride =
    capacityOverrides && capacityOverrides[String(employee.id)] != null
      ? capacityOverrides[String(employee.id)]
      : null;
  const [hours, setHours] = useState(
    storedOverride != null ? String(Math.round((storedOverride / 60) * 10) / 10) : ""
  );

  useEffect(() => {
    setHours(storedOverride != null ? String(Math.round((storedOverride / 60) * 10) / 10) : "");
  }, [storedOverride, employee.id]);

  const commit = () => {
    const trimmed = (hours || "").trim();
    if (trimmed === "") {
      onSaveOverride(employee.id, null);
      return;
    }
    const h = Number(trimmed);
    if (!Number.isNaN(h) && h >= 0 && h <= 24) {
      onSaveOverride(employee.id, Math.round(h * 60));
    }
  };

  const hasOverride = storedOverride != null;
  const effectiveMins =
    storedOverride != null ? storedOverride : defaultMins;
  const effectiveHours = Math.round((effectiveMins / 60) * 10) / 10;
  const meterPct = Math.min(100, Math.max(0, (effectiveHours / 8) * 100));

  return (
    <li className={classNames("lux-planner-capacity-card", { "has-override": hasOverride })}>
      <div className="lux-planner-capacity-card__person">
        <span className="lux-planner-capacity-card__avatar" aria-hidden>
          {employeeInitials(employee.name)}
        </span>
        <div className="lux-planner-capacity-card__copy">
          <div className="lux-planner-capacity-card__name-row">
            <strong>{employee.name}</strong>
            {hasOverride ? (
              <span className="lux-planner-capacity-card__badge">Override</span>
            ) : (
              <span className="lux-planner-capacity-card__badge is-profile">Profile</span>
            )}
          </div>
          <em>
            {employee.designation || "Team member"} · default {formatPlannerHours(defaultMins)}/day
          </em>
        </div>
        <div className="lux-planner-capacity-card__effective" title="Effective daily capacity">
          <strong>{effectiveHours}</strong>
          <span>h/day</span>
        </div>
      </div>

      <div className="lux-planner-capacity-card__meter" aria-hidden>
        <span style={{ width: `${Math.max(meterPct, effectiveHours > 0 ? 6 : 0)}%` }} />
      </div>

      <div className="lux-planner-capacity-card__control">
        <label>
          <span>Hours / day</span>
          <input
            type="number"
            min="0"
            max="24"
            step="0.5"
            placeholder={String(Math.round((defaultMins / 60) * 10) / 10)}
            value={hours}
            onChange={(e) => setHours(e.target.value)}
            onBlur={commit}
            onKeyDown={(e) => e.key === "Enter" && commit()}
          />
        </label>
        {hasOverride ? (
          <button
            type="button"
            className="lux-planner-capacity-card__reset"
            onClick={() => {
              setHours("");
              onSaveOverride(employee.id, null);
            }}
          >
            <i className="fe fe-refresh-cw" aria-hidden />
            Reset
          </button>
        ) : (
          <span className="lux-planner-capacity-card__hint">Leave blank for profile</span>
        )}
      </div>
    </li>
  );
}
