import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import {
  formatNotificationTimestamp,
  getMyWorkPriorityTone,
  getNotificationChannelLabel,
  getNotificationStatusTone,
  getNotificationTypeMeta,
} from "config/workspace.config";

export default function NotificationsRegister({ notifications, acting, onMarkRead }) {
  return (
    <div className="lux-notifications-register-wrap">
      <table className="lux-notifications-register">
        <thead>
          <tr>
            <th>Notification</th>
            <th>Module</th>
            <th>Channel</th>
            <th>When</th>
            <th>Status</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {notifications.map((row) => {
            const typeMeta = getNotificationTypeMeta(row.type);
            const isUnread = row.status === "UNREAD";
            const isHigh = String(row.priority).toUpperCase() === "HIGH";

            return (
              <tr
                key={row.id}
                className={classNames("lux-notifications-register__row", {
                  "is-unread": isUnread,
                  "is-attention": isUnread,
                  "is-urgent": isUnread && isHigh,
                })}
              >
                <td>
                  <div className="lux-notifications-register__primary">
                    <span
                      className={classNames(
                        "lux-notifications-register__avatar",
                        (row.tone || typeMeta.tone) && `is-${row.tone || typeMeta.tone}`
                      )}
                      aria-hidden="true"
                    >
                      <i className={row.icon || typeMeta.icon} />
                    </span>
                    <span className="lux-notifications-register__primary-copy">
                      <strong className="lux-notifications-register__primary-title">{row.title}</strong>
                      {row.body && <span className="lux-notifications-register__primary-meta">{row.body}</span>}
                      {row.actorName && (
                        <span className="lux-notifications-register__primary-meta">From {row.actorName}</span>
                      )}
                    </span>
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-notifications-register__chip", typeMeta.tone && `is-${typeMeta.tone}`)}>
                    <i className={typeMeta.icon} aria-hidden="true" />
                    {row.module || typeMeta.label}
                  </span>
                </td>
                <td>
                  <span className="lux-notifications-register__channel">{getNotificationChannelLabel(row.channel)}</span>
                </td>
                <td>
                  <span className="lux-notifications-register__when">{formatNotificationTimestamp(row.createdAt)}</span>
                </td>
                <td>
                  <div className="lux-notifications-register__status-col">
                    <span className={classNames("lux-doc-badge", `is-${getNotificationStatusTone(row.status)}`)}>
                      {row.status === "UNREAD" ? "Unread" : row.status === "ARCHIVED" ? "Archived" : "Read"}
                    </span>
                    {isHigh && (
                      <span className={classNames("lux-doc-badge", `is-${getMyWorkPriorityTone(row.priority)}`)}>
                        High
                      </span>
                    )}
                  </div>
                </td>
                <td>
                  <div className="lux-notifications-register__actions">
                    {isUnread && (
                      <button
                        type="button"
                        className="lux-notifications-register__btn is-ghost"
                        disabled={acting}
                        onClick={() => onMarkRead(row)}
                        aria-label={`Mark ${row.title} as read`}
                      >
                        <i className="fe fe-check" aria-hidden="true" />
                        Read
                      </button>
                    )}
                    {row.path && (
                      <Link to={row.path} className="lux-notifications-register__open" aria-label={`Open ${row.title}`}>
                        <i className="fe fe-chevron-right" aria-hidden="true" />
                      </Link>
                    )}
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
