import React, { Component } from "react";
import { learningService } from "_services/learning/learning.service";
import LearningLuxPage, {
  LearningActionButton,
  LearningField,
  LearningLuxPanel,
} from "views/learning/components/LearningLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class CoursesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { title: "", code: "", description: "" },
    moduleForm: { courseId: "", title: "", sortOrder: 0 },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Learning courses");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await learningService.listCourses();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load courses"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.title) return;
    this.setState({ saving: true });
    const result = await learningService.createCourse(form);
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { title: "", code: "", description: "" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  handleCreateModule = async (e) => {
    e.preventDefault();
    const { moduleForm } = this.state;
    if (!moduleForm.courseId || !moduleForm.title) return;
    this.setState({ saving: true });
    const result = await learningService.createModule({
      courseId: Number(moduleForm.courseId),
      title: moduleForm.title,
      sortOrder: Number(moduleForm.sortOrder) || 0,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ moduleForm: { courseId: "", title: "", sortOrder: 0 } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Module create failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form, moduleForm } = this.state;
    return (
      <LearningLuxPage
        testId="learning-courses-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "teal",
          icon: "fe fe-book-open",
          eyebrow: "People · Learning",
          titleLead: "Learning",
          titleAccent: "courses",
          lede: "Catalog courses and modules for assignments and compliance.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load courses">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <LearningLuxPanel title="Create course" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="lux-learning-form-grid lux-learning-form-grid--course">
              <LearningField label="Course title" hint="Visible name in learner and assignment views.">
                <input
                  className="form-control"
                  placeholder="Title"
                  value={form.title}
                  onChange={(e) => this.setState({ form: { ...form, title: e.target.value } })}
                />
              </LearningField>
              <LearningField label="Code">
                <input
                  className="form-control"
                  placeholder="Code"
                  value={form.code}
                  onChange={(e) => this.setState({ form: { ...form, code: e.target.value } })}
                />
              </LearningField>
              <LearningField label="Description">
                <input
                  className="form-control"
                  placeholder="Description"
                  value={form.description}
                  onChange={(e) => this.setState({ form: { ...form, description: e.target.value } })}
                />
              </LearningField>
              <div className="lux-learning-form-actions">
                <LearningActionButton type="submit" disabled={saving}>
                  Create course
                </LearningActionButton>
              </div>
            </div>
          </form>
        </LearningLuxPanel>
        <LearningLuxPanel
          title="Add module"
          meta="Optional quiz score on progress/complete (dedicated quiz player deferred)."
          icon="fe fe-layers"
        >
          <form className="lux-module-inline-form" onSubmit={this.handleCreateModule}>
            <div className="lux-learning-form-grid lux-learning-form-grid--module">
              <LearningField label="Course id">
                <input
                  className="form-control"
                  placeholder="Course id"
                  value={moduleForm.courseId}
                  onChange={(e) =>
                    this.setState({ moduleForm: { ...moduleForm, courseId: e.target.value } })
                  }
                />
              </LearningField>
              <LearningField label="Module title" hint="Appears in the learner course sequence.">
                <input
                  className="form-control"
                  placeholder="Module title"
                  value={moduleForm.title}
                  onChange={(e) =>
                    this.setState({ moduleForm: { ...moduleForm, title: e.target.value } })
                  }
                />
              </LearningField>
              <div className="lux-learning-form-actions">
                <LearningActionButton type="submit" variant="secondary" disabled={saving}>
                  Add module
                </LearningActionButton>
              </div>
            </div>
          </form>
        </LearningLuxPanel>
        <LearningLuxPanel title="Courses" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No courses yet"
              description="Create a course to begin building the learning catalog."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Active</th>
                    <th>Id</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.courseRef || r.id}>
                      <td>{r.courseRef}</td>
                      <td>{r.code}</td>
                      <td>{r.title}</td>
                      <td>
                        <span className={`lux-learning-status is-${r.active ? "active" : "inactive"}`}>
                          {r.active ? "Active" : "Inactive"}
                        </span>
                      </td>
                      <td>{r.id}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </LearningLuxPanel>
      </LearningLuxPage>
    );
  }
}

export default CoursesPage;
