import React, { Component } from "react";
import classNames from "classnames/bind";

export const ProfileViewConst = Object.freeze({
    PERSONAL: "Personal Information",
    LEAVE: "Leave",
    ACCESS: "Access Control",
    ACTIVITIES: "Account Activities",
    SECURITY: "Security Settings",
    PREFERENCE: "Preference",
    NOTIFICATIONS: "Notifications",
    APPROVAL_DELEGATION: "Approval Delegation",
});

const NAV_ITEMS = [
    { view: ProfileViewConst.PERSONAL, label: "Profile", icon: "fe fe-user" },
    { view: ProfileViewConst.LEAVE, label: "Leave", icon: "fe fe-calendar", leaveOnly: true },
    { view: ProfileViewConst.ACCESS, label: "Access", icon: "fe fe-key" },
    { view: ProfileViewConst.ACTIVITIES, label: "Activity", icon: "fe fe-activity" },
    { view: ProfileViewConst.SECURITY, label: "Security", icon: "fe fe-shield" },
    { view: ProfileViewConst.PREFERENCE, label: "Preferences", icon: "fe fe-sliders" },
    { view: ProfileViewConst.NOTIFICATIONS, label: "Alerts", icon: "fe fe-bell" },
    {
        view: ProfileViewConst.APPROVAL_DELEGATION,
        label: "Delegation",
        icon: "fe fe-user-check",
        delegationOnly: true,
    },
];

class ProfilePageNav extends Component {
    getVisibleNavItems = () => {
        const { showApprovalDelegation, showLeave } = this.props;
        return NAV_ITEMS.filter((item) => {
            if (item.delegationOnly && showApprovalDelegation !== true) return false;
            if (item.leaveOnly && showLeave !== true) return false;
            return true;
        });
    };

    render() {
        const { activeView, onSelect } = this.props;
        const navItems = this.getVisibleNavItems();

        return (
            <nav className="pd-nav profile-nav" aria-label="Profile sections">
                {navItems.map(({ view, label, icon }) => (
                    <button
                        key={view}
                        type="button"
                        className={classNames("pd-nav__item", { "is-active": activeView === view })}
                        onClick={() => onSelect(view)}
                    >
                        <i className={icon} />
                        <span>{label}</span>
                    </button>
                ))}
            </nav>
        );
    }
}

export default ProfilePageNav;
