import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { getMyWorkCategoryMeta, getMyWorkPriorityTone } from "config/workspace.config";

export default function MyWorkRegister({ items }) {
  return (
    <div className="lux-my-work-register-wrap">
      <table className="lux-my-work-register">
        <thead>
          <tr>
            <th>Work item</th>
            <th>Category</th>
            <th>Due</th>
            <th>Priority</th>
            <th>Status</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {items.map((item) => {
            const categoryMeta = getMyWorkCategoryMeta(item.category);
            const isHigh = String(item.priority).toUpperCase() === "HIGH";
            return (
              <tr
                key={item.id}
                className={classNames("lux-my-work-register__row", {
                  "is-high": isHigh,
                  "is-attention": isHigh,
                })}
              >
                <td>
                  {item.path ? (
                    <Link to={item.path} className="lux-my-work-register__primary">
                      <span className={classNames("lux-my-work-register__avatar", categoryMeta.tone && `is-${categoryMeta.tone}`)} aria-hidden="true">
                        <i className={item.icon || categoryMeta.icon} />
                      </span>
                      <span className="lux-my-work-register__primary-copy">
                        <strong className="lux-my-work-register__primary-title">{item.title}</strong>
                        {item.subtitle && <span className="lux-my-work-register__primary-meta">{item.subtitle}</span>}
                      </span>
                    </Link>
                  ) : (
                    <div className="lux-my-work-register__primary">
                      <span className={classNames("lux-my-work-register__avatar", categoryMeta.tone && `is-${categoryMeta.tone}`)} aria-hidden="true">
                        <i className={item.icon || categoryMeta.icon} />
                      </span>
                      <span className="lux-my-work-register__primary-copy">
                        <strong className="lux-my-work-register__primary-title">{item.title}</strong>
                        {item.subtitle && <span className="lux-my-work-register__primary-meta">{item.subtitle}</span>}
                      </span>
                    </div>
                  )}
                </td>
                <td>
                  <span className={classNames("lux-my-work-register__chip", categoryMeta.tone && `is-${categoryMeta.tone}`)}>
                    <i className={categoryMeta.icon} aria-hidden="true" />
                    {categoryMeta.label}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-my-work-register__due", { "is-soon": isHigh })}>
                    {item.dueLabel || "—"}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${getMyWorkPriorityTone(item.priority)}`)}>
                    {isHigh ? "High" : "Normal"}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", item.status === "OPEN" ? "is-warning" : "is-success")}>
                    {item.status === "OPEN" ? "Open" : item.status}
                  </span>
                </td>
                <td>
                  {item.path ? (
                    <Link to={item.path} className="lux-my-work-register__open" aria-label={`Open ${item.title}`}>
                      <i className="fe fe-chevron-right" aria-hidden="true" />
                    </Link>
                  ) : (
                    <span className="lux-my-work-register__open is-disabled" aria-hidden="true" />
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
