import React, { Component } from "react";
import { Link } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  isAnalyticsAiInsightsEnabled,
  isAnalyticsPlatformEnabled,
} from "config/analytics-platform.config";
import { ANALYTICS_DOMAIN_META, resolveDomainFromPath } from "config/analytics-platform-nav.config";
import { analyticsPlatformService } from "_services/analyticsPlatform.service";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import AnalyticsLuxPage, {
  AnalyticsActionButton,
  AnalyticsInsightPanel,
  AnalyticsLuxPanel,
} from "views/analytics/components/AnalyticsLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import AnalyticsAiInsightPanel from "views/analytics/components/AnalyticsAiInsightPanel";
import AnalyticsDrilldownStrip from "views/analytics/components/AnalyticsDrilldownStrip";
import AnalyticsSavedFiltersPanel from "views/analytics/components/AnalyticsSavedFiltersPanel";

class AnalyticsDomainDashboardPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    dashboard: null,
    savedFilters: [],
    aiInsight: null,
    aiInsightSource: null,
    activeFilter: null,
    filteredPreview: null,
  };

  componentDidMount() {
    this.loadDashboard();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.location.pathname !== this.props.location.pathname) {
      this.loadDashboard();
    }
  }

  resolveDomain = () => resolveDomainFromPath(this.props.location && this.props.location.pathname);

  loadDashboard = async () => {
    const domain = this.resolveDomain();
    if (!domain) {
      this.setState({ loading: false, loadError: "Unknown analytics domain." });
      return;
    }

    this.setState({ loading: true, loadError: null });
    try {
      const [dashboardResult, filtersResult] = await Promise.all([
        analyticsPlatformService.getDomainDashboard(domain),
        analyticsPlatformService.listSavedFilters({ domain }),
      ]);
      analyticsPlatformService.recordDashboardView(domain);

      let aiInsight = null;
      let aiInsightSource = null;
      if (isAnalyticsAiInsightsEnabled()) {
        const insightResult = await analyticsPlatformService.getAnalyticsAiInsight(domain, dashboardResult.payload);
        // Prefer live API insights; ignore empty/client invent when mock is off.
        const payload = insightResult && insightResult.payload;
        const hasInsight =
          payload &&
          typeof payload === "object" &&
          !Array.isArray(payload) &&
          (payload.summary || payload.recommendation || (payload.evidence && payload.evidence.length));
        if (hasInsight && (insightResult.source === "api" || insightResult.source === "mock")) {
          aiInsight = payload;
          aiInsightSource = insightResult.source;
        }
      }

      this.setState({
        loading: false,
        dashboard: dashboardResult.payload,
        dataSource: dashboardResult.source,
        savedFilters: filtersResult.payload || [],
        aiInsight,
        aiInsightSource,
        activeFilter: null,
        filteredPreview: null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load analytics dashboard.",
      });
    }
  };

  handleApplyFilter = async (filter) => {
    const domain = this.resolveDomain();
    this.setState({ activeFilter: filter, loading: true });
    try {
      const result = await analyticsPlatformService.runSavedFilter(filter.id);
      const dashboardResult = await analyticsPlatformService.getDomainDashboard(domain);
      const metrics = (dashboardResult.payload && dashboardResult.payload.metrics) || [];
      const metricIdSet = new Set(filter.metricIds || []);
      const scopedMetrics = metricIdSet.size
        ? metrics.filter((row) => metricIdSet.has(row.id))
        : metrics;

      this.setState({
        loading: false,
        filteredPreview: result.payload,
        dashboard: {
          ...dashboardResult.payload,
          metrics: scopedMetrics,
          chartSeries: scopedMetrics.slice(0, 6).map((metric) => {
            const match = (result.payload && result.payload.rows || []).find((row) => row.metricId === metric.id);
            return {
              label: metric.label,
              value: match ? (match.rawValue || 0) : 0,
              tone: match ? "primary" : "slate",
              meta: match ? match.trend : "—",
            };
          }),
        },
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to apply saved filter.",
      });
    }
  };

  handleSaveFilter = async (payload) => {
    const domain = this.resolveDomain();
    const result = await analyticsPlatformService.saveSavedFilter({ ...payload, domain });
    const filtersResult = await analyticsPlatformService.listSavedFilters({ domain });
    this.setState({ savedFilters: filtersResult.payload || [] });
    return result;
  };

  render() {
    if (!isAnalyticsPlatformEnabled()) {
      return <PersonaAccessDenied featureLabel="Analytics platform" />;
    }

    const domain = this.resolveDomain();
    const meta = domain ? ANALYTICS_DOMAIN_META[domain] : null;
    const {
      loading,
      loadError,
      dashboard,
      dataSource,
      savedFilters,
      aiInsight,
      aiInsightSource,
      activeFilter,
      filteredPreview,
    } = this.state;

    const metricSubtitle = activeFilter
      ? `Filtered by ${activeFilter.name}`
      : dataSource === "api"
        ? "Live catalog metrics · persona-scoped dashboard"
        : dataSource === "mock"
          ? "Demo values from metric catalog"
          : "Unavailable — live metrics could not be loaded";

    const aiPanelMeta =
      aiInsightSource === "api"
        ? "Live analytics AI insight"
        : aiInsightSource === "mock"
          ? "Demo insight"
          : "Unavailable";

    return (
      <AnalyticsLuxPage
        domain={domain}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        dataSource={dataSource}
        demoLabel="Demo analytics metrics"
        loading={loading}
        kpiCards={(dashboard && dashboard.kpiCards) || []}
        onRefresh={this.loadDashboard}
        refreshLoading={loading}
        heroActions={
          <>
            <AnalyticsActionButton to="/analytics/hub" icon="fe fe-grid" variant="ghost">
              Analytics hub
            </AnalyticsActionButton>
            {meta && meta.path !== "/analytics/executive" ? (
              <AnalyticsActionButton to="/analytics/executive" icon="fe fe-bar-chart-2" variant="ghost">
                Executive
              </AnalyticsActionButton>
            ) : null}
            <AnalyticsActionButton to="/analytics/report-builder" icon="fe fe-edit-3" variant="ghost">
              Report builder
            </AnalyticsActionButton>
            <AnalyticsActionButton to="/analytics/scheduled-reports" icon="fe fe-clock" variant="primary">
              Scheduled reports
            </AnalyticsActionButton>
          </>
        }
      >
        {loadError ? (
          <AnalyticsLuxPanel title="Dashboard load issue" meta={loadError} accent="rose">
            <AnalyticsActionButton icon="fe fe-refresh-cw" variant="primary" onClick={this.loadDashboard}>
              Retry
            </AnalyticsActionButton>
          </AnalyticsLuxPanel>
        ) : null}

        <AnalyticsLuxPanel
          title="Saved filters"
          meta={activeFilter ? `Active: ${activeFilter.name}` : "Apply persona-scoped metric views"}
          icon="fe fe-filter"
          accent="slate"
        >
          <AnalyticsSavedFiltersPanel
            savedFilters={savedFilters}
            domain={domain}
            loading={loading}
            onApplyFilter={this.handleApplyFilter}
            onSaveFilter={this.handleSaveFilter}
          />
        </AnalyticsLuxPanel>

        {isAnalyticsAiInsightsEnabled() && aiInsight ? (
          <AnalyticsLuxPanel
            title={aiInsightSource === "api" ? "AI insight" : "AI insight draft"}
            meta={aiPanelMeta}
            icon="fe fe-zap"
            accent="violet"
          >
            <AnalyticsAiInsightPanel insight={aiInsight} source={aiInsightSource} />
          </AnalyticsLuxPanel>
        ) : null}

        <AnalyticsInsightPanel insights={(dashboard && dashboard.insights) || []} />

        <AnalyticsLuxPanel
          title="Metric drill-down"
          meta="Jump from catalog metrics into delivery, finance, and resource modules"
          icon="fe fe-external-link"
          accent="blue"
        >
          <AnalyticsDrilldownStrip metrics={(dashboard && dashboard.metrics) || []} />
        </AnalyticsLuxPanel>

        <AnalyticsLuxPanel
          title="Metric comparison"
          meta={dashboard ? `${dashboard.metricCount} catalog metrics · persona-scoped dashboard config` : "Domain metrics"}
          icon="fe fe-trending-up"
          accent="indigo"
        >
          <PolicyAnalyticsBarChart
            title="Domain metrics"
            subtitle={metricSubtitle}
            series={(dashboard && dashboard.chartSeries) || []}
          />
        </AnalyticsLuxPanel>

        {filteredPreview ? (
          <AnalyticsLuxPanel
            title="Filter preview"
            meta={`${filteredPreview.rowCount} metrics from saved filter`}
            icon="fe fe-eye"
            accent="blue"
          >
            <div className="lux-analytics-metric-table-wrap">
              <table className="lux-analytics-metric-table">
                <thead>
                  <tr>
                    <th>Metric</th>
                    <th>Value</th>
                    <th>Trend</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredPreview.rows.map((row) => (
                    <tr key={row.metricId}>
                      <td>
                        <strong>{row.label}</strong>
                        {row.masked ? <span className="lux-analytics-metric-table__badge">Masked</span> : null}
                      </td>
                      <td>{row.value}</td>
                      <td>{row.trend}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </AnalyticsLuxPanel>
        ) : null}

        <AnalyticsLuxPanel
          title="Metric catalog"
          meta="Registered definitions with source module and drill-down paths"
          icon="fe fe-list"
          accent="slate"
        >
          <div className="lux-analytics-metric-table-wrap">
            <table className="lux-analytics-metric-table">
              <thead>
                <tr>
                  <th>Metric</th>
                  <th>Code</th>
                  <th>Source</th>
                  <th>Format</th>
                  <th>Drill-down</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr>
                    <td colSpan={5}>
                      <div className="lux-analytics-metric-table__skeleton" aria-busy="true" />
                    </td>
                  </tr>
                ) : !((dashboard && dashboard.metrics) || []).length ? (
                  <tr>
                    <td colSpan={5}>
                      <LuxRegisterEmptyState
                        className="lux-register-empty--compact"
                        title="No metrics in scope"
                        description="Adjust saved filters or connect live APIs to populate this dashboard."
                      />
                    </td>
                  </tr>
                ) : (
                  ((dashboard && dashboard.metrics) || []).map((row) => (
                    <tr key={row.id}>
                      <td>
                        <strong>{row.label}</strong>
                        {row.sensitive ? <span className="lux-analytics-metric-table__badge">Masked</span> : null}
                      </td>
                      <td>{row.code}</td>
                      <td>{row.sourceModule || "—"}</td>
                      <td>{row.format}</td>
                      <td>
                        {row.drilldownPath ? (
                          <Link to={row.drilldownPath} className="lux-analytics-metric-table__link">
                            Open
                          </Link>
                        ) : (
                          "—"
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </AnalyticsLuxPanel>
      </AnalyticsLuxPage>
    );
  }
}

export default AnalyticsDomainDashboardPage;
