async function enrollBenefit(payload = {}) {
  if (!shouldUseEmployeeFinanceApi()) {
    return apiErrorResult(null);
  }
  const query = employeeFinanceWriteTeamQuery({
    actorId: payload.actorId || commonUtils.getCurrentUserId(),
    userTeamId: payload.userTeamId,
  });
  const qs = Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
  const response = await axiosUtils.post(
    `${urlConfig.EMPLOYEE_FINANCE_API_PATH}/benefits/enrollments?${qs}`,
    payload
  );
  const row = (response && response.payload) || response;
  writeEmployeeFinanceAudit(
    AUDIT_ACTION_TYPES.CREATED,
    "Benefit enrollment saved",
    row && row.id,
    { code: EMPLOYEE_FINANCE_AUDIT_CODES.BENEFIT_ASSIGNED, planId: payload.planId }
  );
  return { payload: row, source: "api" };
}

