function unwrapFinanceList(result) {
  if (!result || result.source === "api-error") {
    return [];
  }
  return Array.isArray(result.payload) ? result.payload : [];
}

function rowsForEmployee(rows, employeeId) {
  const key = String(employeeId);
  return (rows || []).filter((row) => row && String(row.employeeId) === key);
}

async function getEmployeeFinanceProfile(employeeId, options = {}) {
  if (!shouldUseEmployeeFinanceApi()) {
    return apiErrorResult(null);
  }
  const persona = options.viewerPersona || "EMPLOYEE";
  const response = await axiosUtils.getWithParam(
    `${urlConfig.EMPLOYEE_FINANCE_API_PATH}/profiles/${employeeId}`,
    employeeFinanceWriteTeamQuery({ employeeName: options.employeeName, userTeamId: options.userTeamId })
  );
  const raw = (response && response.payload) || response;
  if (!raw) {
    return { payload: buildEmployeeFinanceTabBundle(null, [], [], []), source: "api" };
  }
  const isBundle = typeof raw === "object" && raw.profile && typeof raw.profile === "object";
  const profileRow = isBundle ? raw.profile : raw;
  const employeeKey = profileRow.employeeId != null ? profileRow.employeeId : employeeId;
  let advances = isBundle && Array.isArray(raw.advances) ? raw.advances : null;
  let loans = isBundle && Array.isArray(raw.loans) ? raw.loans : null;
  let deductions = isBundle && Array.isArray(raw.deductions) ? raw.deductions : null;
  if (advances == null || loans == null || deductions == null) {
    const [advRes, loanRes, dedRes] = await Promise.all([
      listAdvances().catch(() => ({ payload: [], source: "api-error" })),
      listLoans().catch(() => ({ payload: [], source: "api-error" })),
      listDeductionSchedules().catch(() => ({ payload: [], source: "api-error" })),
    ]);
    if (advances == null) {
      advances = rowsForEmployee(unwrapFinanceList(advRes), employeeKey);
    }
    if (loans == null) {
      loans = rowsForEmployee(unwrapFinanceList(loanRes), employeeKey);
    }
    if (deductions == null) {
      deductions = rowsForEmployee(unwrapFinanceList(dedRes), employeeKey);
    }
  }
  const maskedProfile = maskEmployeeFinanceProfile(
    normalizeEmployeeFinanceProfile(profileRow),
    persona
  );
  return {
    payload: buildEmployeeFinanceTabBundle(maskedProfile, advances || [], loans || [], deductions || []),
    source: "api",
  };
}

async function exportCompensation(filters = {}, options = {}) {
  const activePersona = options.activePersona || "ADMIN";
  if (!canExportEmployeeFinanceCompensation(activePersona)) {
    throw new Error("Compensation export is restricted for your role.");
  }
  const result = await listCompensationChanges(filters);
  const csv = exportCompensationCsv(result.payload || []);
  return {
    payload: csv,
    filename: `compensation-changes-${new Date().toISOString().slice(0, 10)}.csv`,
    source: result.source,
  };
}
