import React from "react";
import classNames from "classnames/bind";
import { ISSUE_STATUSES } from "config/project-governance.config";
import { getIssuePriorityTone, getIssueStatusTone } from "config/project-governance.utils";

export default function IssueRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register lux-gov-register--issues">
        <thead>
          <tr>
            <th>Issue</th>
            <th>Project</th>
            <th>Priority</th>
            <th>Owner</th>
            <th>Due</th>
            <th>Actions</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const priorityTone = getIssuePriorityTone(row.priority);
            const statusTone = getIssueStatusTone(row.status);
            const isOpen = row.status !== ISSUE_STATUSES.CLOSED && row.status !== ISSUE_STATUSES.RESOLVED;
            return (
              <tr
                key={row.id}
                className={classNames("lux-gov-register__row", {
                  "is-critical": row.priority === "P1" && isOpen,
                  "is-risk": row.status === ISSUE_STATUSES.IN_PROGRESS,
                })}
              >
                <td>
                  <button type="button" className="lux-gov-register__link" onClick={() => onSelect(row)}>
                    <strong>{row.title}</strong>
                    {row.description ? <span>{row.description}</span> : null}
                  </button>
                </td>
                <td>
                  <span className="lux-gov-register__project">{row.projectName}</span>
                  {row.projectCode ? <span className="lux-gov-register__meta">{row.projectCode}</span> : null}
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${priorityTone}`)}>{row.priority}</span>
                </td>
                <td>{row.ownerName || "—"}</td>
                <td>{row.dueDate || "—"}</td>
                <td>
                  <span className="lux-gov-register__chip">{row.actionCount || 0}</span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{row.status}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
