import React, { PureComponent } from "react";
import classNames from "classnames/bind";

const TYPE_META = {
  ACCOUNT: { label: "Account", icon: "fe fe-briefcase", tone: "indigo" },
  TEAM: { label: "Team", icon: "fe fe-users", tone: "sky" },
  CLIENT: { label: "Client", icon: "fe fe-user", tone: "teal" },
};

class AccountDirectoryRow extends PureComponent {
  renderChips = (item) => {
    const chips = [];
    if (item.source === "SALES_FORCE") {
      chips.push({ key: "sf", label: "Salesforce", tone: "sky", icon: "fe fe-cloud" });
    }
    if (item.itemType === "BILLABLE") {
      chips.push({ key: "bill", label: "Billable", tone: "green" });
    } else if (item.itemType === "NON_BILLABLE") {
      chips.push({ key: "nb", label: "Non-billable", tone: "slate" });
    }
    if (item.email) {
      chips.push({ key: "email", label: item.email, tone: "violet", icon: "fe fe-mail" });
    }
    return chips;
  };

  render() {
    const {
      item,
      parentItem,
      viewName,
      viewByAccounts,
      hierarchyEnabled,
      permission,
      onSelect,
      onOpenDetail,
      confirmRemoveId,
    } = this.props;

    if (!item || !parentItem) return null;

    const meta = TYPE_META[item.type] || {
      label: item.type || "Record",
      icon: "fe fe-folder",
      tone: "slate",
    };
    const canDrill =
      hierarchyEnabled !== false &&
      item.type !== "CLIENT" &&
      item.source !== "SALES_FORCE";
    const teams = Number(item.noOfTeams) || 0;
    const clients = Number(item.noOfClients) || 0;
    const isConfirmRemove = confirmRemoveId === item.id;
    const chips = this.renderChips(item);
    const desc =
      item.description && item.description.length > 120
        ? `${item.description.slice(0, 117)}…`
        : item.description;

    return (
      <article
        className={classNames("lux-acct-dir-row", `lux-acct-dir-row--${meta.tone}`, {
          "is-drillable": canDrill,
        })}
      >
        <div className={classNames("lux-acct-dir-row__avatar", `is-${meta.tone}`)}>
          {item.source === "SALES_FORCE" ? (
            <img src="/assets/images/custom/sf_nobg.png" alt="" className="lux-acct-dir-row__sf" />
          ) : (
            <i className={meta.icon} aria-hidden="true" />
          )}
        </div>

        <div className="lux-acct-dir-row__main">
          <div className="lux-acct-dir-row__title-row">
            {canDrill ? (
              <button type="button" className="lux-acct-dir-row__title" onClick={onSelect}>
                {item.name}
                <i className="fe fe-chevrons-right lux-acct-dir-row__drill-icon" aria-hidden="true" />
              </button>
            ) : (
              <h3 className="lux-acct-dir-row__title is-static">{item.name}</h3>
            )}
            <span className={classNames("lux-acct-dir-row__type-badge", `is-${meta.tone}`)}>
              {meta.label}
            </span>
            <span className="lux-acct-dir-row__id">#{item.id}</span>
          </div>

          <p className="lux-acct-dir-row__parent">
            <i className="fe fe-git-branch" aria-hidden="true" />
            Under <strong>{parentItem.name}</strong>
            {item.extAccountId && (
              <span className="lux-acct-dir-row__sf-id"> · SF {item.extAccountId}</span>
            )}
          </p>

          {desc && <p className="lux-acct-dir-row__desc">{desc}</p>}

          {chips.length > 0 && (
            <div className="lux-acct-dir-row__chips">
              {chips.map((chip) => (
                <span
                  key={chip.key}
                  className={classNames("lux-acct-dir-row__chip", `is-${chip.tone}`)}
                >
                  {chip.icon && <i className={chip.icon} aria-hidden="true" />}
                  {chip.label}
                </span>
              ))}
            </div>
          )}
        </div>

        <div className="lux-acct-dir-row__metrics" aria-label="Hierarchy counts">
          {(item.type === "ACCOUNT" || item.type === "TEAM") && (
            <>
              {item.type === "ACCOUNT" && (
                <div className="lux-acct-dir-row__metric">
                  <strong>{teams}</strong>
                  <span>Teams</span>
                </div>
              )}
              <div className="lux-acct-dir-row__metric">
                <strong>{clients}</strong>
                <span>Clients</span>
              </div>
            </>
          )}
          {item.type === "CLIENT" && (
            <div className="lux-acct-dir-row__metric lux-acct-dir-row__metric--solo">
              <i className="fe fe-check-circle" aria-hidden="true" />
              <span>End client</span>
            </div>
          )}
        </div>

        <div className="lux-acct-dir-row__actions lux-project-row__actions">
          <button
            type="button"
            className="lux-project-row__action"
            onClick={onOpenDetail}
            title="View details"
            aria-label={`View details for ${item.name}`}
          >
            <i className="fe fe-eye" aria-hidden="true" />
          </button>
          {canDrill && (
            <button
              type="button"
              className="lux-project-row__action"
              onClick={onSelect}
              title="Browse children"
              aria-label={`Browse ${item.name}`}
            >
              <i className="fe fe-chevrons-right" aria-hidden="true" />
            </button>
          )}
          {permission && permission.removeEnabled && viewByAccounts && (
            <button
              type="button"
              className={classNames("lux-project-row__action", "is-danger", {
                "is-confirm": isConfirmRemove,
              })}
              title={isConfirmRemove ? "Confirm remove" : "Remove record"}
              aria-label={isConfirmRemove ? `Confirm remove ${item.name}` : `Remove ${item.name}`}
              onClick={() => this.props.onRemoveRequest(item.id, isConfirmRemove)}
            >
              {isConfirmRemove ? (
                <i className="fe fe-check blink_text" aria-hidden="true" />
              ) : (
                <i className="fe fe-trash-2" aria-hidden="true" />
              )}
            </button>
          )}
          {permission && permission.deleteEnabled && !viewByAccounts && (
            <button
              type="button"
              className="lux-project-row__action is-danger"
              title="Detach from team"
              aria-label={`Detach ${item.name} from team`}
              onClick={() => this.props.onDetach(item.id)}
            >
              <i className="fe fe-link-2" aria-hidden="true" />
            </button>
          )}
        </div>
      </article>
    );
  }
}

export default AccountDirectoryRow;
