import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isWorkGraphEnabled } from "config/work-graph.config";
import { WORK_GRAPH_PAGE_META } from "config/work-graph-nav.config";
import { workGraphService } from "_services/workGraph.service";
import WorkGraphLuxPage, {
  WorkGraphActionButton,
  WorkGraphInsightPanel,
} from "views/workgraph/components/WorkGraphLuxShared";
import EntityRelationshipPanel from "views/workgraph/components/EntityRelationshipPanel";
import GraphVisualizationPanel from "views/workgraph/components/GraphVisualizationPanel";
import IndexEventsStrip from "views/workgraph/components/IndexEventsStrip";
import WorkGraphAiPanel from "views/workgraph/components/WorkGraphAiPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getLuxInlineAlertProps } from "_helpers/apiError.utils";
import { buildGraphAiContext } from "config/work-graph.utils";

class WorkGraphPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    nodes: [],
    edges: [],
    kpiCards: [],
    insights: [],
    indexEvents: [],
    selectedNode: null,
    related: [],
    relatedEdges: [],
    aiContext: null,
    aiSource: null,
    aiLoading: false,
    moduleFilter: "ALL",
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { moduleFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = moduleFilter !== "ALL" ? { module: moduleFilter } : {};
      const result = await workGraphService.getOverview(filters);
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        nodes: payload.nodes || [],
        edges: payload.edges || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        indexEvents: payload.indexEvents || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: getLuxInlineAlertProps(error, "Unable to load work graph."),
      });
    }
  };

  selectNode = async (node) => {
    const nodeId = node.id || node;
    this.setState({
      selectedNode: null,
      related: [],
      relatedEdges: [],
      aiContext: null,
      aiSource: null,
      aiLoading: true,
    });
    try {
      const [relResult, aiResult] = await Promise.all([
        workGraphService.getNodeRelationships(nodeId),
        workGraphService.getGraphAiContext(nodeId),
      ]);
      const relPayload = relResult.payload || {};
      const selectedNode = relPayload.node || node;
      const related = relPayload.related || [];
      const relatedEdges = relPayload.edges || [];
      const aiPayload =
        aiResult && aiResult.payload && typeof aiResult.payload === "object" && !Array.isArray(aiResult.payload)
          ? aiResult.payload
          : null;
      let aiContext = aiPayload;
      let aiSource = (aiResult && aiResult.source) || null;
      if (!aiContext && selectedNode) {
        aiContext = buildGraphAiContext(selectedNode, related, relatedEdges);
        aiSource = "local-rules";
      }
      this.setState({
        selectedNode,
        related,
        relatedEdges,
        aiContext,
        aiSource,
        aiLoading: false,
      });
    } catch (error) {
      this.setState({ aiLoading: false, aiContext: null, aiSource: null });
    }
  };

  handleExport = async () => {
    try {
      const result = await workGraphService.exportGraphCsv({});
      const csv = result.payload || "";
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "work-graph-export.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Export failed." });
    }
  };

  render() {
    if (!isWorkGraphEnabled()) {
      return <PersonaAccessDenied featureLabel="Work graph" />;
    }

    const {
      loading,
      loadError,
      dataSource,
      nodes,
      edges,
      kpiCards,
      insights,
      indexEvents,
      selectedNode,
      related,
      relatedEdges,
      aiContext,
      aiSource,
      aiLoading,
    } = this.state;

    return (
    <WorkGraphLuxPage
      pageMeta={WORK_GRAPH_PAGE_META}
      dataSource={dataSource}
      kpiCards={kpiCards}
      loading={loading}
      pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
      shellTitle="Work graph"
      heroActions={
        <WorkGraphActionButton icon="fe fe-download" onClick={this.handleExport}>
          Export CSV
        </WorkGraphActionButton>
      }
    >
      {loadError ? <LuxInlineAlert {...loadError} /> : null}
      <WorkGraphInsightPanel insights={insights} loading={loading} />
      <div className="lux-wg-page-grid">
        <GraphVisualizationPanel
          nodes={nodes}
          edges={edges}
          selectedId={selectedNode && selectedNode.id}
          onSelectNode={this.selectNode}
          loading={loading}
        />
        <div className="lux-wg-page-side">
          <EntityRelationshipPanel
            node={selectedNode}
            related={related}
            edges={relatedEdges}
            loading={aiLoading && !selectedNode}
            onSelectNode={this.selectNode}
          />
          <WorkGraphAiPanel
            context={aiContext}
            loading={aiLoading}
            source={aiSource}
            hasSelection={!!selectedNode}
          />
          <IndexEventsStrip events={indexEvents} loading={loading} />
        </div>
      </div>
    </WorkGraphLuxPage>
    );
  }
}

export default WorkGraphPage;
