import React from "react";
import classNames from "classnames/bind";

export default function LeaveImpactRecommendationPanel({ recommendation }) {
  if (!recommendation) {
    return null;
  }

  return (
    <section className="lux-leave-impact__section lux-leave-impact__ai">
      <h3>AI recommendation draft</h3>
      <p className="lux-leave-impact__ai-summary">{recommendation.summary}</p>
      <p className="lux-leave-impact__ai-rec">{recommendation.recommendation}</p>
      <div className="lux-leave-impact__ai-meta">
        <span className={classNames("lux-leave-impact__ai-confidence")}>
          Confidence {Math.round((recommendation.confidence || 0) * 100)}%
        </span>
        <span className="lux-leave-impact__ai-badge">Draft only</span>
      </div>
      <p className="lux-leave-impact__ai-disclaimer">{recommendation.disclaimer}</p>
    </section>
  );
}
