/**
 * First-login / admin-forced password change gate.
 * Backed by fs_employee_model.force_password_change_on_login (not need_password_reset).
 */
import { authGetItem, authSetItem, authRemoveItem } from "./authStorage.utils";

export const FORCE_PASSWORD_CHANGE_KEY = "forcePasswordChangeOnLogin";
export const FORCE_PASSWORD_CHANGE_EMAIL_KEY = "forcePasswordChangeEmail";
export const FORCE_PASSWORD_CHANGE_EMPLOYEE_ID_KEY = "forcePasswordChangeEmployeeId";
export const FORCE_PASSWORD_CHANGE_PATH = "/user/force-change-password";

export function isForcePasswordChangeRequired() {
  const value = authGetItem(FORCE_PASSWORD_CHANGE_KEY);
  return value === "1" || value === "true";
}

export function setForcePasswordChangeRequired(required) {
  if (required) {
    authSetItem(FORCE_PASSWORD_CHANGE_KEY, "1");
  } else {
    authSetItem(FORCE_PASSWORD_CHANGE_KEY, "0");
  }
}

export function clearForcePasswordChangeRequired() {
  authRemoveItem(FORCE_PASSWORD_CHANGE_KEY);
  authRemoveItem(FORCE_PASSWORD_CHANGE_EMAIL_KEY);
  authRemoveItem(FORCE_PASSWORD_CHANGE_EMPLOYEE_ID_KEY);
}

function rememberForceChangeIdentity(authPayload) {
  const email =
    (authPayload && authPayload.employee && authPayload.employee.email) ||
    (authPayload && authPayload.email) ||
    "";
  const employeeId =
    (authPayload && authPayload.employeeId) ||
    (authPayload && authPayload.employee && authPayload.employee.id) ||
    null;
  if (email) {
    authSetItem(FORCE_PASSWORD_CHANGE_EMAIL_KEY, String(email));
  }
  if (employeeId != null) {
    authSetItem(FORCE_PASSWORD_CHANGE_EMPLOYEE_ID_KEY, String(employeeId));
  }
}

/** Post-login destination when auth payload includes the force-change flag. */
export function resolvePostLoginPath(authPayload, fallbackPath = "/") {
  if (authPayload && authPayload.forcePasswordChangeOnLogin) {
    setForcePasswordChangeRequired(true);
    rememberForceChangeIdentity(authPayload);
    return FORCE_PASSWORD_CHANGE_PATH;
  }
  setForcePasswordChangeRequired(false);
  authRemoveItem(FORCE_PASSWORD_CHANGE_EMAIL_KEY);
  authRemoveItem(FORCE_PASSWORD_CHANGE_EMPLOYEE_ID_KEY);
  return fallbackPath || "/";
}
