import React from "react";
import classNames from "classnames/bind";
import { ACCESS_REQUEST_STATUSES } from "config/asset-register.config";
import {
  formatAccessRequestDate,
  getAccessRequestPriorityTone,
  getAccessRequestStatusTone,
  getAccessRequestTypeMeta,
  getRequesterInitials,
} from "config/access-request-admin.utils";

export default function AccessRequestRegister({ requests, acting, onStatusUpdate }) {
  return (
    <div className="lux-access-request-register-wrap">
      <table className="lux-access-request-register">
        <thead>
          <tr>
            <th>Request</th>
            <th>Requester</th>
            <th>Type</th>
            <th>Priority</th>
            <th>Submitted</th>
            <th>Status</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {requests.map((row) => {
            const typeMeta = getAccessRequestTypeMeta(row.type);
            const isPending = row.status === ACCESS_REQUEST_STATUSES.PENDING;
            const isApproved = row.status === ACCESS_REQUEST_STATUSES.APPROVED;
            const isHigh = String(row.priority).toUpperCase() === "HIGH";

            return (
              <tr
                key={row.id}
                className={classNames("lux-access-request-register__row", {
                  "is-attention": isPending,
                  "is-urgent": isPending && isHigh,
                })}
              >
                <td>
                  <div className="lux-access-request-register__primary">
                    <span className={classNames("lux-access-request-register__avatar", typeMeta.tone && `is-${typeMeta.tone}`)} aria-hidden="true">
                      <i className={typeMeta.icon} />
                    </span>
                    <span className="lux-access-request-register__primary-copy">
                      <strong className="lux-access-request-register__primary-title">{row.title}</strong>
                      {row.notes && <span className="lux-access-request-register__primary-meta">{row.notes}</span>}
                      {row.assetTag && (
                        <span className="lux-access-request-register__primary-meta">Asset tag · {row.assetTag}</span>
                      )}
                    </span>
                  </div>
                </td>
                <td>
                  <div className="lux-access-request-register__requester">
                    <span className="lux-access-request-register__requester-avatar" aria-hidden="true">
                      {getRequesterInitials(row.requesterName)}
                    </span>
                    <span>{row.requesterName || "—"}</span>
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-access-request-register__chip", typeMeta.tone && `is-${typeMeta.tone}`)}>
                    <i className={typeMeta.icon} aria-hidden="true" />
                    {typeMeta.label}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${getAccessRequestPriorityTone(row.priority)}`)}>
                    {row.priority || "NORMAL"}
                  </span>
                </td>
                <td>
                  <span className="lux-access-request-register__date">{formatAccessRequestDate(row.submittedAt)}</span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${getAccessRequestStatusTone(row.status)}`)}>
                    {row.status}
                  </span>
                </td>
                <td>
                  <div className="lux-access-request-register__actions">
                    {isPending && (
                      <>
                        <button
                          type="button"
                          className="lux-access-request-register__btn is-primary"
                          disabled={acting}
                          onClick={() => onStatusUpdate(row, ACCESS_REQUEST_STATUSES.APPROVED)}
                        >
                          <i className="fe fe-check" aria-hidden="true" />
                          Approve
                        </button>
                        <button
                          type="button"
                          className="lux-access-request-register__btn is-ghost"
                          disabled={acting}
                          onClick={() => onStatusUpdate(row, ACCESS_REQUEST_STATUSES.REJECTED)}
                        >
                          <i className="fe fe-x" aria-hidden="true" />
                          Reject
                        </button>
                      </>
                    )}
                    {isApproved && (
                      <button
                        type="button"
                        className="lux-access-request-register__btn is-primary"
                        disabled={acting}
                        onClick={() => onStatusUpdate(row, ACCESS_REQUEST_STATUSES.FULFILLED)}
                      >
                        <i className="fe fe-check-circle" aria-hidden="true" />
                        Fulfilled
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
