import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import { buildManagerComplianceRows } from "config/timesheet-intelligence.utils";
import TimesheetBillabilityPanel from "./TimesheetBillabilityPanel";
import TimesheetAgentDraftPanel from "./TimesheetAgentDraftPanel";

const METRICS = [
  { key: "complianceRate", label: "Team compliance", icon: "fe-check-circle", tone: "success", suffix: "%" },
  { key: "pendingApprovals", label: "Pending approvals", icon: "fe-inbox", tone: "pending" },
  { key: "defaulterCount", label: "Defaulters", icon: "fe-alert-circle", tone: "warning" },
  { key: "openConflicts", label: "Open conflicts", icon: "fe-shuffle", tone: "warning" },
  { key: "billableUtilizationPct", label: "Billable util.", icon: "fe-trending-up", tone: "info", suffix: "%" },
  { key: "dataQualityIssues", label: "Data quality", icon: "fe-alert-triangle", tone: "danger" },
];

const COMPLIANCE_META = {
  defaulter: { icon: "fe-user-x", tag: "Defaulter", tone: "warning" },
  pending: { icon: "fe-inbox", tag: "Pending approval", tone: "pending" },
};

function MetricCard({ label, value, tone, icon, suffix }) {
  return (
    <article className={classNames("lux-ts-intel__metric", `is-${tone || "neutral"}`)}>
      <i className={classNames("fe", icon, "lux-ts-intel__metric-icon")} aria-hidden="true" />
      <div>
        <span>{label}</span>
        <strong>
          <CountUp end={value || 0} duration={0.5} />
          {suffix || ""}
        </strong>
      </div>
    </article>
  );
}

export default function TimesheetIntelligencePanel({
  intelligence,
  billability,
  recommendation,
  defaulters,
  pendingWeeks,
  loading,
  agentActionLog,
  onAgentAction,
}) {
  if (loading && !intelligence) {
    return (
      <section className="lux-ts-intel is-loading" aria-busy="true" aria-label="Loading timesheet intelligence">
        <div className="lux-ts-intel__skeleton" />
      </section>
    );
  }
  if (!intelligence) {
    return null;
  }

  const complianceRows = buildManagerComplianceRows(defaulters, pendingWeeks);

  return (
    <section className="lux-ts-intel" aria-label="Timesheet intelligence">
      <div className="lux-ts-intel__glow" aria-hidden="true" />

      <header className="lux-ts-intel__hero">
        <div className="lux-ts-intel__hero-copy">
          <LuxSummaryEyebrow variant="timesheet" className="lux-ts-intel__eyebrow">
            Timesheet intelligence
          </LuxSummaryEyebrow>
          <h3 className="lux-ts-intel__title">Manager compliance dashboard</h3>
          <p className="lux-ts-intel__subtitle">
            Approval backlog, defaulters, billability mix, and draft recommendations.
            Accept or reject records a session decision only and does not change timesheet hours or status.
          </p>
        </div>
        <div className="lux-ts-intel__hero-aside">
          {intelligence.source && (
            <span className={classNames("lux-ts-intel__source", `is-${intelligence.source}`)}>
              {intelligence.source === "api" ? "Live API" : "Client computed"}
            </span>
          )}
          <span className="lux-ts-intel__hero-badge">
            <i className="fe fe-layers" aria-hidden="true" />
            {complianceRows.length} queue item{complianceRows.length === 1 ? "" : "s"}
          </span>
        </div>
      </header>

      <div className="lux-ts-intel__highlights">
        <article className="lux-ts-intel__highlight">
          <span>Week utilization</span>
          <strong>
            <CountUp end={intelligence.utilizationPct || 0} duration={0.5} />%
          </strong>
        </article>
        <article className="lux-ts-intel__highlight">
          <span>Days needing attention</span>
          <strong>
            <CountUp end={intelligence.daysNeedingAttention || 0} duration={0.5} />
          </strong>
        </article>
        <article className="lux-ts-intel__highlight">
          <span>Week status</span>
          <strong className="is-status">{intelligence.weekStatus || "—"}</strong>
        </article>
      </div>

      <div className="lux-ts-intel__metrics">
        {METRICS.map((metric) => (
          <MetricCard
            key={metric.key}
            label={metric.label}
            icon={metric.icon}
            tone={metric.tone}
            suffix={metric.suffix}
            value={intelligence[metric.key]}
          />
        ))}
      </div>

      <section className="lux-ts-intel__compliance">
        <div className="lux-ts-intel__card-glow" aria-hidden="true" />
        <header className="lux-ts-intel__section-head">
          <div>
            <h4>
              <i className="fe fe-users" aria-hidden="true" />
              Compliance queue
            </h4>
            <p>Defaulters and pending approvals requiring manager action</p>
          </div>
        </header>

        {complianceRows.length === 0 ? (
          <p className="lux-ts-intel__empty">All clear — no defaulters or pending approvals in queue.</p>
        ) : (
          <ul className="lux-ts-intel__compliance-list">
            {complianceRows.map((row) => {
              const meta = COMPLIANCE_META[row.type] || COMPLIANCE_META.pending;
              return (
                <li key={row.id} className={classNames("lux-ts-intel__compliance-card", `is-${meta.tone}`)}>
                  <div className="lux-ts-intel__compliance-icon">
                    <i className={classNames("fe", meta.icon)} aria-hidden="true" />
                  </div>
                  <div className="lux-ts-intel__compliance-copy">
                    <strong>{row.employeeName}</strong>
                    <span>{row.label}</span>
                  </div>
                  <div className="lux-ts-intel__compliance-tags">
                    <span className={classNames("lux-ts-intel__tag", `is-${meta.tone}`)}>{meta.tag}</span>
                    <em>{row.status}</em>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </section>

      <div className="lux-ts-intel__insights">
        <TimesheetBillabilityPanel billability={billability} />
        <TimesheetAgentDraftPanel
          recommendation={recommendation}
          actionLog={agentActionLog}
          onAction={onAgentAction}
          source={intelligence && intelligence.source}
        />
      </div>
    </section>
  );
}
