import React from "react";
import { formatSimulationAdjustmentLabel } from "config/resource-planning.utils";

export default function SimulationAdjustmentList({ adjustments, context, onRemove }) {
  if (!adjustments || adjustments.length === 0) {
    return (
      <div className="lux-simulation-adjustments__empty">
        <i className="fe fe-sliders" aria-hidden="true" />
        <p>Add adjustments or load a template to model a what-if scenario.</p>
      </div>
    );
  }

  return (
    <ol className="lux-simulation-adjustments">
      {adjustments.map((adjustment, index) => (
        <li key={`${adjustment.type}-${index}`} className="lux-simulation-adjustments__item">
          <span className="lux-simulation-adjustments__marker" aria-hidden="true">
            {index + 1}
          </span>
          <span className="lux-simulation-adjustments__copy">
            {formatSimulationAdjustmentLabel(adjustment, context)}
          </span>
          {onRemove && (
            <button
              type="button"
              className="lux-simulation-adjustments__remove"
              onClick={() => onRemove(index)}
              aria-label="Remove adjustment"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          )}
        </li>
      ))}
    </ol>
  );
}
