import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAssetRegisterEnabled, ASSET_STATUSES } from "config/asset-register.config";
import {
  buildAssetRegisterMetrics,
  filterAssets,
  getOffboardingAssetBlockers,
} from "config/asset-register.utils";
import { assetRegisterService } from "_services/assetRegister.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import AssetAssignmentDrawer from "views/people/components/assets/AssetAssignmentDrawer";
import AssetAnalyticsPanel from "views/people/components/assets/AssetAnalyticsPanel";
import OffboardingAssetBlockersPanel from "views/people/components/assets/OffboardingAssetBlockersPanel";
import { PeopleActionButton, PeopleRowAction } from "views/people/components/PeopleLuxShared";
import { ASSET_REGISTER_PAGE_META } from "config/people-module-nav.config";

class EmployeeAssetsPage extends Component {
  state = {
    assets: [],
    loading: true,
    loadError: null,
    dataSource: null,
    activeView: "register",
    statusFilter: "ALL",
    query: "",
    drawerOpen: false,
    drawerMode: "assign",
    selectedAsset: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Assets");
    this.loadAssets();
  }

  loadAssets = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await assetRegisterService.listAssets();
      this.setState({
        assets: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load asset register.",
        assets: [],
      });
    }
  };

  openDrawer = (asset, mode) => {
    this.setState({ selectedAsset: asset, drawerMode: mode, drawerOpen: true });
  };

  handleAssign = async (asset, assignee) => {
    await assetRegisterService.assignAsset(asset.id, assignee);
    await this.loadAssets();
  };

  handleReturn = async (asset) => {
    await assetRegisterService.returnAsset(asset.id);
    await this.loadAssets();
  };

  getFilteredAssets = () => {
    const { assets, statusFilter, query } = this.state;
    return filterAssets(assets, {
      status: statusFilter === "ALL" ? null : statusFilter,
      query,
    });
  };

  renderKpiStrip = () => {
    const { assets, loading } = this.state;
    const metrics = buildAssetRegisterMetrics(assets);
    const cards = [
      { id: "total", label: "Assets", value: metrics.total, hint: "Inventory", tone: "primary" },
      { id: "assigned", label: "Assigned", value: metrics.assigned, hint: `${metrics.utilizationPct}% utilized`, tone: "green" },
      { id: "available", label: "Available", value: metrics.available, hint: "Ready to assign", tone: "slate" },
      { id: "blockers", label: "Offboarding blockers", value: metrics.blockers, hint: "Must return", tone: "rose" },
    ];

    return (
      <div className="lux-hrms-dash__kpi-strip lux-asset-kpi-strip" role="list" aria-busy={loading}>
        {cards.map((card) => (
          <article
            key={card.id}
            className={classNames("lux-hrms-dash__kpi lux-asset-kpi", card.tone && `is-${card.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            <strong className="lux-hrms-dash__kpi-value">{loading ? "—" : card.value}</strong>
            <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
          </article>
        ))}
      </div>
    );
  };

  renderRegister = () => {
    const { loading } = this.state;
    const rows = this.getFilteredAssets();

    if (loading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="Loading assets"
          description="Fetching asset register."
        />
      );
    }

    if (rows.length === 0) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-monitor"
          title="No assets found"
          description="Company laptops, access cards, and software licenses appear here."
        />
      );
    }

    return (
      <div className="lux-doc-register-wrap">
        <table className="lux-doc-register">
          <thead>
            <tr>
              <th>Asset</th>
              <th>Tag</th>
              <th>Type</th>
              <th>Assignee</th>
              <th>Status</th>
              <th>Warranty</th>
              <th aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.id}>
                <td>
                  <strong>{row.name}</strong>
                  {row.location && <span className="lux-doc-register__meta">{row.location}</span>}
                </td>
                <td>{row.tag || "—"}</td>
                <td>{row.typeLabel || row.type}</td>
                <td>
                  {row.assigneeName || "—"}
                  {row.assigneeId && (
                    <Link className="lux-doc-register__link" to={`/people/employees/${row.assigneeId}/360`}>
                      View 360
                    </Link>
                  )}
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", {
                    "is-success": row.status === ASSET_STATUSES.ASSIGNED,
                    "is-warning": row.status === ASSET_STATUSES.IN_REPAIR,
                    "is-slate": row.status === ASSET_STATUSES.AVAILABLE,
                  })}
                  >
                    {row.status}
                  </span>
                </td>
                <td>{row.warrantyExpiresAt || "—"}</td>
                <td>
                  {row.status === ASSET_STATUSES.AVAILABLE ? (
                    <PeopleRowAction icon="fe fe-user-plus" onClick={() => this.openDrawer(row, "assign")}>
                      Assign
                    </PeopleRowAction>
                  ) : (
                    <PeopleRowAction variant="secondary" icon="fe fe-rotate-ccw" onClick={() => this.openDrawer(row, "return")}>
                      Return
                    </PeopleRowAction>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  render() {
    if (!isAssetRegisterEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Assets"
          reason="Asset register is not enabled for your organization."
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      activeView,
      statusFilter,
      query,
      assets,
      drawerOpen,
      drawerMode,
      selectedAsset,
    } = this.state;
    const metrics = buildAssetRegisterMetrics(assets);
    const blockers = getOffboardingAssetBlockers(assets).filter((row) => row.offboardingBlocker || row.status === ASSET_STATUSES.ASSIGNED);

    return (
      <div className="lux-asset-page lux-people-page lux-register-page" data-testid="page-assets">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
                  meta={ASSET_REGISTER_PAGE_META}
                  actions={
                    <PeopleActionButton to="/admin/access-requests" variant="ghost" icon="fe fe-shield">
                      Access requests
                    </PeopleActionButton>
                  }
                />

        <div className="lux-register-page__body">
        {this.renderKpiStrip()}

        {loadError ? <LuxInlineAlert message={loadError} tone="danger" /> : null}

        <section className="lux-hrms-dash__panel lux-asset-panel">
          <header className="lux-hrms-dash__panel-head lux-appr-toolbar">
            <LuxSegmentNav
              items={[
                { id: "register", label: "Register", icon: "fe fe-layers" },
                { id: "analytics", label: "Analytics", icon: "fe fe-bar-chart-2" },
                { id: "blockers", label: "Offboarding blockers", icon: "fe fe-alert-triangle", count: blockers.length },
              ]}
              activeId={activeView}
              onChange={(next) => this.setState({ activeView: next })}
              ariaLabel="Asset views"
              tabList
              testId="asset-view-nav"
            />
          </header>

          {activeView === "register" && (
            <>
              <div className="lux-appr-toolbar lux-appr-toolbar__row">
                <div className="lux-appr-toolbar__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    className="lux-appr-toolbar__search-input"
                    placeholder="Search assets, tags, or assignees"
                    value={query}
                    onChange={(event) => this.setState({ query: event.target.value })}
                  />
                </div>
                <div className="lux-hrms-dash__filter-group">
                  {["ALL", ASSET_STATUSES.ASSIGNED, ASSET_STATUSES.AVAILABLE, ASSET_STATUSES.IN_REPAIR].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-hrms-dash__panel-body">{this.renderRegister()}</div>
            </>
          )}

          {activeView === "analytics" && (
            <div className="lux-hrms-dash__panel-body">
              <AssetAnalyticsPanel metrics={metrics} assets={assets} />
            </div>
          )}

          {activeView === "blockers" && (
            <div className="lux-hrms-dash__panel-body">
              <OffboardingAssetBlockersPanel blockers={blockers} />
            </div>
          )}
        </section>

        <AssetAssignmentDrawer
          open={drawerOpen}
          asset={selectedAsset}
          mode={drawerMode}
          onClose={() => this.setState({ drawerOpen: false, selectedAsset: null })}
          onAssign={this.handleAssign}
          onReturn={this.handleReturn}
        />
        </div>
      </div>
    );
  }
}

export default EmployeeAssetsPage;
