/**
 * F21-T1/T2 — Client-side workspace home aggregation (mock + API-ready).
 */
import { UNIVERSAL_APPROVAL_STATUSES } from "config/universal-approval.config";
import { buildMyWorkQueueMetrics } from "config/workspace.config";
import { buildNotificationMetrics } from "config/workspace.config";
import { buildApprovalInboxMetrics } from "config/universal-approval.utils";
import { buildPersonalizationInsights, buildPersonalizationMetrics } from "config/workspace-personalization.utils";

const WIDGET_VALUE_BY_ID = {
  "my-tasks": (m) => m.openWork,
  "team-approvals": (m) => m.pendingApprovals,
  "hr-approvals": (m) => m.pendingApprovals,
  "pending-timesheets": (m) => m.timesheetApprovals,
  "team-attendance": (m) => m.attendanceApprovals,
  "onboarding-queue": (m) => m.onboardingWork,
  "offboarding-queue": (m) => m.offboardingWork,
  "paychecks": (m) => m.paycheckAlerts,
  documents: (m) => m.documentTasks,
  "attendance-today": (m) => m.attendanceTasks,
  "timesheet-status": (m) => m.timesheetTasks,
  "leave-balance": () => null,
  "audit-alerts": (m) => m.unreadNotifications,
};

export function buildWorkspaceHomeMetrics({ workItems = [], notifications = [], approvals = [] } = {}) {
  const workMetrics = buildMyWorkQueueMetrics(workItems);
  const notificationMetrics = buildNotificationMetrics(notifications);
  const approvalMetrics = buildApprovalInboxMetrics(approvals);

  const openWork = (workItems || []).filter((row) => row.status === "OPEN");
  const approvalWork = openWork.filter((row) => row.category === "APPROVAL");
  const timesheetTasks = openWork.filter((row) => row.category === "TIMESHEET").length;
  const attendanceTasks = openWork.filter((row) => row.category === "ATTENDANCE").length;
  const onboardingWork = openWork.filter((row) => row.category === "ONBOARDING").length;

  const pendingApprovals = (approvals || []).filter(
    (row) => row.status === UNIVERSAL_APPROVAL_STATUSES.PENDING
  );
  const timesheetApprovals = pendingApprovals.filter((row) => row.domain === "TIMESHEET").length;
  const attendanceApprovals = pendingApprovals.filter(
    (row) => row.domain === "ATTENDANCE_REGULARIZATION"
  ).length;
  const leaveApprovals = pendingApprovals.filter((row) => row.domain === "LEAVE").length;

  return {
    openWork: workMetrics.open,
    highPriorityWork: workMetrics.highPriority,
    workCategories: workMetrics.categories,
    dueSoonWork: workMetrics.dueSoon,
    unreadNotifications: notificationMetrics.unread,
    highPriorityNotifications: notificationMetrics.highPriority,
    notificationTypes: notificationMetrics.types,
    pendingApprovals: approvalMetrics.pending,
    highPriorityApprovals: approvalMetrics.highPriority,
    approvalDomains: approvalMetrics.domainCount,
    delegateApprovals: approvalMetrics.delegateCount,
    timesheetApprovals,
    attendanceApprovals,
    leaveApprovals,
    timesheetTasks,
    attendanceTasks,
    onboardingWork,
    offboardingWork: 0,
    documentTasks: openWork.filter((row) => String(row.title || "").toLowerCase().includes("document")).length,
    paycheckAlerts: (notifications || []).filter((row) => row.type === "PAYROLL" && row.status === "UNREAD").length,
  };
}

export function buildWorkspaceHomePayload({
  workItems = [],
  notifications = [],
  approvals = [],
  favorites = [],
  savedViews = [],
  activePersona = "EMPLOYEE",
} = {}) {
  const metrics = buildWorkspaceHomeMetrics({ workItems, notifications, approvals });
  const personalizationMetrics = buildPersonalizationMetrics(favorites, savedViews);
  const baseInsights = buildWorkspaceHomeInsights(metrics, { workItems, notifications, approvals });
  const personalizationInsights = buildPersonalizationInsights(favorites, savedViews);
  const signals = {
    expiringDocuments: metrics.documentTasks || 0,
    payrollExceptions: metrics.paycheckAlerts || 0,
    benchResources: (workItems || []).filter((row) => String(row.title || "").toLowerCase().includes("bench")).length,
  };
  const dashboard = { metrics, signals };
  return {
    activePersona,
    metrics: { ...metrics, ...personalizationMetrics },
    signals,
    insights: [...baseInsights, ...personalizationInsights].slice(0, 4),
    attentionItems: buildWorkspaceHomeAttentionItems(activePersona, {
      workItems,
      notifications,
      approvals,
      metrics,
      dashboard,
    }),
    approvalShortcuts: getPendingApprovalShortcuts(approvals, 5),
    favorites: favorites || [],
    savedViews: savedViews || [],
    recentWork: (workItems || []).filter((row) => row.status === "OPEN").slice(0, 4),
    recentNotifications: (notifications || []).filter((row) => row.status === "UNREAD").slice(0, 3),
  };
}

export function buildWorkspaceHomeInsights(metrics, { workItems, notifications, approvals } = {}) {
  const insights = [];
  const pending = (approvals || []).filter((row) => row.status === UNIVERSAL_APPROVAL_STATUSES.PENDING);

  if (metrics.highPriorityApprovals > 0) {
    insights.push({
      id: "urgent-approvals",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${metrics.highPriorityApprovals} urgent approval(s)`,
      copy: "High-priority leave, timesheet, or attendance requests need a decision.",
      path: "/workspace/approvals",
    });
  } else if (metrics.pendingApprovals > 0) {
    insights.push({
      id: "pending-approvals",
      tone: "mint",
      icon: "fe fe-inbox",
      title: `${metrics.pendingApprovals} approval(s) in your inbox`,
      copy: "Review pending requests across leave, timesheet, and attendance.",
      path: "/workspace/approvals",
    });
  }

  if (metrics.highPriorityWork > 0) {
    insights.push({
      id: "high-work",
      tone: "amber",
      icon: "fe fe-check-square",
      title: `${metrics.highPriorityWork} high-priority work item(s)`,
      copy: "Open tasks with due dates are waiting in your queue.",
      path: "/workspace/my-work",
    });
  }

  if (metrics.unreadNotifications > 0) {
    insights.push({
      id: "notifications",
      tone: "blue",
      icon: "fe fe-bell",
      title: `${metrics.unreadNotifications} unread notification(s)`,
      copy: metrics.highPriorityNotifications > 0
        ? `${metrics.highPriorityNotifications} flagged as high priority.`
        : "Catch up on alerts across people, payroll, and projects.",
      path: "/workspace/notifications",
    });
  }

  const timesheetDue = (workItems || []).find(
    (row) => row.category === "TIMESHEET" && row.status === "OPEN"
  );
  if (timesheetDue && insights.length < 3) {
    insights.push({
      id: "timesheet-due",
      tone: "amber",
      icon: "fe fe-calendar",
      title: "Timesheet due soon",
      copy: timesheetDue.subtitle || "Submit your hours before the payroll lock.",
      path: timesheetDue.path || "/people/timesheet",
    });
  }

  if (insights.length === 0 && (workItems || []).length > 0) {
    insights.push({
      id: "on-track",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "You're on track",
      copy: "No urgent approvals or high-priority tasks flagged right now.",
      path: "/workspace/my-work",
    });
  }

  return insights.slice(0, 3);
}

export function buildWorkspaceHomeAttentionItems(activePersona, { metrics, approvals, dashboard } = {}) {
  const items = [];
  const signals = (dashboard && dashboard.signals) || {};

  if (metrics.pendingApprovals > 0) {
    items.push({
      id: "approvals",
      label: `${metrics.pendingApprovals} approval(s) need your decision`,
      hint: "Universal inbox",
      icon: "fe fe-inbox",
      path: "/workspace/approvals",
      tone: "blue",
    });
  }
  if (signals.expiringDocuments > 0) {
    items.push({
      id: "documents",
      label: `${signals.expiringDocuments} document(s) expiring soon`,
      hint: "Document vault",
      icon: "fe fe-file-text",
      path: "/people/documents",
      tone: "amber",
    });
  }
  if (signals.payrollExceptions > 0) {
    items.push({
      id: "payroll",
      label: `${signals.payrollExceptions} payroll exception(s) open`,
      hint: "Payroll runs",
      icon: "fe fe-dollar-sign",
      path: "/payroll/dashboard",
      tone: "rose",
    });
  }
  if (signals.benchResources > 0) {
    items.push({
      id: "bench",
      label: `${signals.benchResources} resource(s) on bench`,
      hint: "Capacity planning",
      icon: "fe fe-users",
      path: "/project/capacity",
      tone: "violet",
    });
  }
  if (metrics.highPriorityWork > 0) {
    items.push({
      id: "work",
      label: `${metrics.highPriorityWork} high-priority task(s) due soon`,
      hint: "My work queue",
      icon: "fe fe-check-square",
      path: "/workspace/my-work",
      tone: "primary",
    });
  }
  if (metrics.unreadNotifications > 0) {
    items.push({
      id: "notifications",
      label: `${metrics.unreadNotifications} unread notification(s)`,
      hint: "Notification center",
      icon: "fe fe-bell",
      path: "/workspace/notifications",
      tone: "green",
    });
  }

  if (items.length > 0) {
    return items.slice(0, 6);
  }

  const personaFallback = {
    EMPLOYEE: [
      { id: "ts", label: "Submit this week's timesheet before Friday", icon: "fe fe-calendar", path: "/people/timesheet" },
    ],
    MANAGER: [
      { id: "approvals", label: "Review team approvals in your inbox", icon: "fe fe-inbox", path: "/workspace/approvals" },
    ],
    HR_ADMIN: [
      { id: "onboarding", label: "Check onboarding checklists in progress", icon: "fe fe-user-plus", path: "/people/onboarding" },
    ],
    EXECUTIVE: [
      { id: "portfolio", label: "Review portfolio health signals", icon: "fe fe-activity", path: "/project/dashboard" },
    ],
    ADMIN: [
      { id: "audit", label: "Review security audit events", icon: "fe fe-shield", path: "/admin/audit" },
    ],
  };

  return (personaFallback[activePersona] || personaFallback.EMPLOYEE).slice(0, 3);
}

export function enrichPersonaWidgets(widgets, metrics) {
  return (widgets || []).map((widget) => {
    const resolver = WIDGET_VALUE_BY_ID[widget.id];
    const value = resolver ? resolver(metrics) : null;
    if (value == null || value === 0) {
      return widget;
    }
    return { ...widget, value };
  });
}

export function getPendingApprovalShortcuts(approvals, limit = 5) {
  return (approvals || [])
    .filter((row) => row.status === UNIVERSAL_APPROVAL_STATUSES.PENDING)
    .sort((a, b) => {
      const priorityRank = { HIGH: 0, NORMAL: 1, LOW: 2 };
      const aRank = priorityRank[a.priority] != null ? priorityRank[a.priority] : 1;
      const bRank = priorityRank[b.priority] != null ? priorityRank[b.priority] : 1;
      if (aRank !== bRank) {
        return aRank - bRank;
      }
      return String(a.submittedAt || "").localeCompare(String(b.submittedAt || ""));
    })
    .slice(0, limit)
    .map((row) => ({
      id: row.id,
      domain: row.domain,
      domainLabel: row.domainLabel,
      domainIcon: row.domainIcon,
      moduleTone: row.moduleTone,
      requester: row.requester,
      subject: row.subject,
      priority: row.priority,
      dueLabel: row.dueLabel,
      path: "/workspace/approvals",
    }));
}

export function buildWorkspaceHomeKpiCards(metrics, { approvalsEnabled, notificationsEnabled, myWorkEnabled } = {}) {
  const cards = [
    {
      id: "work",
      label: "Open work",
      value: metrics.openWork,
      hint: `${metrics.highPriorityWork} high priority`,
      tone: "amber",
      icon: "fe fe-check-square",
      path: "/workspace/my-work",
      hidden: myWorkEnabled === false,
    },
    {
      id: "approvals",
      label: "Pending approvals",
      value: metrics.pendingApprovals,
      hint: `${metrics.approvalDomains} domain(s)`,
      tone: "mint",
      icon: "fe fe-inbox",
      path: "/workspace/approvals",
      hidden: approvalsEnabled === false,
    },
    {
      id: "notifications",
      label: "Unread alerts",
      value: metrics.unreadNotifications,
      hint: `${metrics.highPriorityNotifications} urgent`,
      tone: "blue",
      icon: "fe fe-bell",
      path: "/workspace/notifications",
      hidden: notificationsEnabled === false,
    },
    {
      id: "due",
      label: "Due soon",
      value: metrics.dueSoonWork,
      hint: "Work items with dates",
      tone: "rose",
      icon: "fe fe-clock",
      path: "/workspace/my-work",
      hidden: myWorkEnabled === false,
    },
  ];

  return cards.filter((card) => card.hidden !== true);
}
