import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { HRMS_ROADMAP_MODULES } from "./employeeDashboard.utils";

function statusLabel(status) {
  if (status === "shipped") return "Live";
  if (status === "coming-soon") return "Coming soon";
  return "Planned";
}

function EmployeeDashboardRoadmap() {
  return (
    <section className="lux-hrms-dash__roadmap" aria-label="HRMS module shortcuts">
      <div className="lux-hrms-dash__section-head">
        <div>
          <span className="lux-hrms-dash__section-eyebrow">People workspace</span>
          <h2 className="lux-hrms-dash__section-title">Connected HRMS modules</h2>
          <p className="lux-hrms-dash__section-desc">
            Jump into leave, performance, payroll, and related People workflows from the same
            command center.
          </p>
        </div>
      </div>
      <div className="lux-hrms-dash__roadmap-grid">
        {HRMS_ROADMAP_MODULES.map((mod) => {
          const cardBody = (
            <>
              <span className="lux-hrms-dash__roadmap-icon" aria-hidden="true">
                <i className={`fe ${mod.icon}`} />
              </span>
              <div className="lux-hrms-dash__roadmap-copy">
                <div className="lux-hrms-dash__roadmap-top">
                  <h3>{mod.title}</h3>
                  <span
                    className={classNames("lux-hrms-dash__roadmap-badge", {
                      "is-soon": mod.status === "coming-soon",
                      "is-planned": mod.status === "planned",
                      "is-live": mod.status === "shipped",
                    })}
                  >
                    {statusLabel(mod.status)}
                  </span>
                </div>
                <p>{mod.description}</p>
              </div>
            </>
          );

          if (mod.path && mod.status === "shipped") {
            return (
              <Link
                key={mod.key}
                to={mod.path}
                className={classNames("lux-hrms-dash__roadmap-card", `is-${mod.tone}`)}
              >
                {cardBody}
              </Link>
            );
          }

          return (
            <article
              key={mod.key}
              className={classNames("lux-hrms-dash__roadmap-card", `is-${mod.tone}`)}
            >
              {cardBody}
            </article>
          );
        })}
      </div>
    </section>
  );
}

export default EmployeeDashboardRoadmap;
