import React, { Component } from "react";
import classNames from "classnames/bind";
import { ANALYTICS_DOMAINS, REPORT_STATUSES } from "config/analytics-platform.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { AnalyticsActionButton } from "views/analytics/components/AnalyticsLuxShared";

const DOMAIN_OPTIONS = [
  { value: "", label: "All domains" },
  ...Object.values(ANALYTICS_DOMAINS).map((domain) => ({
    value: domain,
    label: domain.charAt(0).toUpperCase() + domain.slice(1),
  })),
];

const STATUS_TONE = {
  [REPORT_STATUSES.SAVED]: "green",
  [REPORT_STATUSES.DRAFT]: "amber",
  [REPORT_STATUSES.ARCHIVED]: "slate",
};

const EMPTY_FORM = {
  name: "",
  description: "",
  domain: "",
  metricIds: [],
};

function downloadCsv(csv, filename) {
  if (!csv) return;
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename || `report-${Date.now()}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

export default class ReportBuilderPanel extends Component {
  state = {
    selectedReportId: null,
    form: { ...EMPTY_FORM },
    saving: false,
    previewing: false,
    exporting: false,
    saveError: null,
    previewError: null,
  };

  componentDidUpdate(prevProps) {
    const reports = this.props.savedReports || [];
    if (!this.state.selectedReportId && reports.length) {
      this.selectReport(reports[0]);
    }
    if (prevProps.savedReports !== this.props.savedReports && reports.length) {
      const stillExists = reports.find((row) => row.id === this.state.selectedReportId);
      if (!stillExists) {
        this.selectReport(reports[0]);
      }
    }
  }

  selectReport = (report) => {
    if (!report) return;
    this.setState({
      selectedReportId: report.id,
      form: {
        name: report.name,
        description: report.description || "",
        domain: report.domain || "",
        metricIds: report.metricIds || [],
      },
      saveError: null,
      previewError: null,
    });
    if (this.props.onPreviewReport) {
      this.props.onPreviewReport(report.id);
    }
  };

  handleFormChange = (field) => (event) => {
    const value = event.target.value;
    this.setState((prev) => ({
      form: {
        ...prev.form,
        [field]: value,
        ...(field === "domain" ? { metricIds: [] } : {}),
      },
      saveError: null,
      previewError: null,
    }));
  };

  toggleMetric = (metricId) => {
    this.setState((prev) => {
      const ids = new Set(prev.form.metricIds);
      if (ids.has(metricId)) {
        ids.delete(metricId);
      } else {
        ids.add(metricId);
      }
      return { form: { ...prev.form, metricIds: Array.from(ids) }, saveError: null, previewError: null };
    });
  };

  applyTemplate = (template) => {
    this.setState({
      form: {
        name: template.name,
        description: template.description || "",
        domain: template.domain || "",
        metricIds: template.metricIds || [],
      },
      saveError: null,
      previewError: null,
    });
  };

  handlePreview = async () => {
    const { form } = this.state;
    const { onRunQuery } = this.props;
    if (!onRunQuery) return;
    if (!form.metricIds.length) {
      this.setState({ previewError: "Select at least one metric to preview." });
      return;
    }
    this.setState({ previewing: true, previewError: null });
    try {
      await onRunQuery({
        domain: form.domain || null,
        metricIds: form.metricIds,
      });
      this.setState({ previewing: false });
    } catch (error) {
      this.setState({
        previewing: false,
        previewError: (error && error.message) || "Unable to preview report.",
      });
    }
  };

  handleSave = async (event) => {
    event.preventDefault();
    const { form } = this.state;
    const { onSaveReport } = this.props;
    if (!onSaveReport) return;

    this.setState({ saving: true, saveError: null });
    try {
      const result = await onSaveReport({
        id: this.state.selectedReportId,
        name: form.name,
        description: form.description,
        domain: form.domain || null,
        metricIds: form.metricIds,
        status: REPORT_STATUSES.SAVED,
      });
      this.setState({ saving: false, selectedReportId: result.payload.id });
    } catch (error) {
      this.setState({
        saving: false,
        saveError: (error && error.message) || "Unable to save report.",
      });
    }
  };

  handleExport = async () => {
    const { form } = this.state;
    const { onExportReport } = this.props;
    if (!onExportReport || !form.metricIds.length) return;

    this.setState({ exporting: true });
    try {
      const result = await onExportReport(
        { domain: form.domain || null, metricIds: form.metricIds },
        form.name || "analytics-report"
      );
      if (result && result.payload) {
        downloadCsv(result.payload, result.filename);
      }
      this.setState({ exporting: false });
    } catch (error) {
      this.setState({ exporting: false, previewError: (error && error.message) || "Export failed." });
    }
  };

  renderPreview(preview) {
    if (!preview || !preview.rows || !preview.rows.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No preview yet"
          description="Select metrics and run preview to see catalog values before saving or exporting."
        />
      );
    }

    return (
      <div className="lux-report-builder__preview">
        <header>
          <span>{preview.rowCount} metrics</span>
          <span>Generated {preview.generatedAt}</span>
        </header>
        <table className="lux-report-builder__preview-table">
          <thead>
            <tr>
              <th>Metric</th>
              <th>Value</th>
              <th>Trend</th>
              <th>Domain</th>
              <th>Source</th>
            </tr>
          </thead>
          <tbody>
            {preview.rows.map((row) => (
              <tr key={row.metricId} className={row.sensitive ? "is-sensitive" : ""}>
                <td>
                  <strong>{row.label}</strong>
                  <small>{row.code}</small>
                </td>
                <td>{row.value}</td>
                <td>{row.trend}</td>
                <td>{row.domain}</td>
                <td>{row.sourceModule}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  render() {
    const { savedReports = [], templates = [], availableMetrics = [], preview, loading } = this.props;
    const { selectedReportId, form, saving, previewing, exporting, saveError, previewError } = this.state;

    const filteredMetrics = form.domain
      ? availableMetrics.filter((row) => row.domain === form.domain)
      : availableMetrics;

    if (loading) {
      return <div className="lux-report-builder__skeleton" aria-busy="true" />;
    }

    return (
      <div className="lux-report-builder">
        <div className="lux-report-builder__sidebar">
          <span className="lux-report-builder__label">Saved reports</span>
          <div className="lux-report-builder__report-list">
            {savedReports.length ? (
              savedReports.map((row) => (
                <button
                  key={row.id}
                  type="button"
                  className={classNames("lux-report-builder__report-card", selectedReportId === row.id && "is-active")}
                  onClick={() => this.selectReport(row)}
                >
                  <strong>{row.name}</strong>
                  <small>{row.description}</small>
                  <span className={classNames("lux-report-builder__badge", `is-${STATUS_TONE[row.status] || "slate"}`)}>
                    {row.status}
                  </span>
                </button>
              ))
            ) : (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="No saved reports"
                description="Compose a metric selection and save your first cross-domain report."
              />
            )}
          </div>

          {templates.length ? (
            <>
              <span className="lux-report-builder__label">Templates</span>
              <div className="lux-report-builder__template-list">
                {templates.map((row) => (
                  <button key={row.id} type="button" className="lux-report-builder__template" onClick={() => this.applyTemplate(row)}>
                    <strong>{row.name}</strong>
                    <small>{row.description}</small>
                  </button>
                ))}
              </div>
            </>
          ) : null}
        </div>

        <div className="lux-report-builder__main">
          <form className="lux-report-builder__form" onSubmit={this.handleSave}>
            <div className="lux-report-builder__form-grid">
              <label>
                Report name
                <input type="text" value={form.name} onChange={this.handleFormChange("name")} required />
              </label>
              <label>
                Domain filter
                <select value={form.domain} onChange={this.handleFormChange("domain")}>
                  {DOMAIN_OPTIONS.map((opt) => (
                    <option key={opt.value || "all"} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </label>
              <label className="is-wide">
                Description
                <input type="text" value={form.description} onChange={this.handleFormChange("description")} />
              </label>
            </div>

            <span className="lux-report-builder__label">Metrics ({form.metricIds.length} selected)</span>
            <div className="lux-report-builder__metric-grid">
              {filteredMetrics.map((metric) => (
                <label key={metric.id} className={classNames("lux-report-builder__metric", form.metricIds.includes(metric.id) && "is-selected")}>
                  <input
                    type="checkbox"
                    checked={form.metricIds.includes(metric.id)}
                    onChange={() => this.toggleMetric(metric.id)}
                  />
                  <span>
                    <strong>{metric.label}</strong>
                    <small>
                      {metric.domain} · {metric.sourceModule}
                      {metric.sensitive ? " · masked" : ""}
                    </small>
                  </span>
                </label>
              ))}
            </div>

            {saveError ? <p className="lux-report-builder__error">{saveError}</p> : null}
            {previewError ? <p className="lux-report-builder__error">{previewError}</p> : null}

            <div className="lux-report-builder__actions">
              <AnalyticsActionButton icon="fe fe-eye" variant="ghost" onClick={this.handlePreview} disabled={previewing}>
                {previewing ? "Previewing…" : "Preview"}
              </AnalyticsActionButton>
              <AnalyticsActionButton
                icon="fe fe-download"
                variant="ghost"
                onClick={this.handleExport}
                disabled={exporting || !form.metricIds.length}
              >
                {exporting ? "Exporting…" : "Export CSV"}
              </AnalyticsActionButton>
              <AnalyticsActionButton icon="fe fe-save" variant="primary" buttonType="submit" disabled={saving}>
                {saving ? "Saving…" : "Save report"}
              </AnalyticsActionButton>
            </div>
          </form>

          <div className="lux-report-builder__preview-wrap">
            <span className="lux-report-builder__label">Preview</span>
            {this.renderPreview(preview)}
          </div>
        </div>
      </div>
    );
  }
}
