import React from "react";
import classNames from "classnames/bind";
import {
  RETENTION_PERIOD_PRESETS,
  RETENTION_STATUS_LABELS,
} from "config/data-retention.config";
import { formatRetentionPeriod, getRetentionDomainMeta } from "config/data-retention.utils";

function formatDate(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export default function DataRetentionDetailPanel({
  policy,
  savingKey,
  onSetRetentionDays,
  onToggleLegalHold,
  onToggleAutoPurge,
}) {
  if (!policy) {
    return (
      <div className="lux-retention-detail lux-retention-detail--empty">
        <span className="lux-retention-detail__empty-icon" aria-hidden="true">
          <i className="fe fe-archive" />
        </span>
        <strong>Select a retention policy</strong>
        <p>Configure purge windows, legal holds, and archival rules per entity type.</p>
      </div>
    );
  }

  const meta = getRetentionDomainMeta(policy.domain);

  return (
    <aside className="lux-retention-detail">
      <header className="lux-retention-detail__head">
        <div className="lux-retention-detail__identity">
          <span className={classNames("lux-retention-detail__avatar", meta.tone && `is-${meta.tone}`)} aria-hidden="true">
            <i className={meta.icon} />
          </span>
          <div>
            <h3>{policy.name}</h3>
            <p>
              {policy.entityType} · {policy.domain} · {policy.owner}
            </p>
          </div>
        </div>
        <span
          className={classNames("lux-retention-detail__status", {
            "is-hold": policy.legalHold,
            "is-archived": policy.status === "ARCHIVED",
          })}
        >
          {policy.legalHold ? RETENTION_STATUS_LABELS.LEGAL_HOLD : RETENTION_STATUS_LABELS[policy.status]}
        </span>
      </header>

      <p className="lux-retention-detail__copy">{policy.description}</p>

      <dl className="lux-retention-detail__meta">
        <div>
          <dt>Records held</dt>
          <dd>{(policy.recordsHeld || 0).toLocaleString()}</dd>
        </div>
        <div>
          <dt>Next purge</dt>
          <dd>{policy.legalHold ? "Suspended" : formatDate(policy.nextPurgeAt)}</dd>
        </div>
        <div>
          <dt>Current window</dt>
          <dd>{formatRetentionPeriod(policy.retentionDays)}</dd>
        </div>
        <div>
          <dt>Auto-purge</dt>
          <dd>{policy.autoPurge ? "Enabled" : "Manual"}</dd>
        </div>
      </dl>

      <div className="lux-retention-detail__section">
        <div className="lux-retention-detail__section-head">
          <h4>Retention window</h4>
          <span>{formatRetentionPeriod(policy.retentionDays)}</span>
        </div>
        <div className="lux-retention-detail__preset-group" role="group" aria-label="Retention period presets">
          {RETENTION_PERIOD_PRESETS.map((preset) => (
            <button
              key={preset.id}
              type="button"
              className={classNames("lux-retention-detail__preset-btn", {
                "is-active": policy.retentionDays === preset.days,
              })}
              disabled={savingKey === `${policy.id}:days` || policy.legalHold}
              onClick={() => onSetRetentionDays && onSetRetentionDays(preset.days)}
            >
              {preset.label}
            </button>
          ))}
        </div>
      </div>

      <div className="lux-retention-detail__toggles">
        <label className="lux-retention-detail__toggle">
          <input
            type="checkbox"
            checked={policy.legalHold}
            disabled={savingKey === `${policy.id}:hold`}
            onChange={(e) => onToggleLegalHold && onToggleLegalHold(e.target.checked)}
          />
          <span>
            <strong>Legal hold</strong>
            <em>Suspend purge and archive jobs</em>
          </span>
        </label>
        <label className="lux-retention-detail__toggle">
          <input
            type="checkbox"
            checked={policy.autoPurge}
            disabled={savingKey === `${policy.id}:purge` || policy.legalHold}
            onChange={(e) => onToggleAutoPurge && onToggleAutoPurge(e.target.checked)}
          />
          <span>
            <strong>Auto-purge</strong>
            <em>Run scheduled deletion when window elapses</em>
          </span>
        </label>
      </div>
    </aside>
  );
}
