import React from "react";
import classNames from "classnames/bind";
import { RISK_STATUSES } from "config/project-governance.config";
import { getRiskSeverityTone, getRiskStatusTone } from "config/project-governance.utils";

export default function RiskRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register lux-gov-register--risks">
        <thead>
          <tr>
            <th>Risk</th>
            <th>Project</th>
            <th>Category</th>
            <th>Severity</th>
            <th>Owner</th>
            <th>Due</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const severityTone = getRiskSeverityTone(row.severity);
            const statusTone = getRiskStatusTone(row.status);
            return (
              <tr
                key={row.id}
                className={classNames("lux-gov-register__row", {
                  "is-critical": row.severity === "CRITICAL" && row.status !== RISK_STATUSES.CLOSED,
                  "is-risk": row.status === RISK_STATUSES.ESCALATED,
                })}
              >
                <td>
                  <button type="button" className="lux-gov-register__link" onClick={() => onSelect(row)}>
                    <strong>{row.title}</strong>
                    {row.mitigationPlan ? <span>{row.mitigationPlan}</span> : null}
                  </button>
                </td>
                <td>
                  <span className="lux-gov-register__project">{row.projectName}</span>
                  {row.projectCode ? <span className="lux-gov-register__meta">{row.projectCode}</span> : null}
                </td>
                <td>{row.category || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${severityTone}`)}>{row.severity}</span>
                </td>
                <td>{row.ownerName || "—"}</td>
                <td>{row.dueDate || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{row.status}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
