import React, { Component } from "react";
import { dossierService } from "_services/dossier/dossier.service";
import DossierLuxPage, {
  DossierActionButton,
  DossierLuxPanel,
} from "views/dossiers/components/DossierLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class DossierExportPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dossier: null,
    hold: null,
    exportResult: null,
    busy: false,
  };

  get dossierRef() {
    const match = this.props.match;
    return match && match.params ? match.params.id : undefined;
  }

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Dossier export");
    }
    this.load();
  }

  load = async () => {
    const ref = this.dossierRef;
    this.setState({ loading: true, loadError: null });
    const [dossierRes, holdRes] = await Promise.all([
      dossierService.getDossier(ref),
      dossierService.getRetentionHoldStatus(ref),
    ]);
    if (dossierRes.source !== "api") {
      this.setState({
        loading: false,
        loadError: dossierRes.error || new Error("Unable to load dossier"),
      });
      return;
    }
    this.setState({
      loading: false,
      dossier: dossierRes.payload,
      hold: holdRes.source === "api" ? holdRes.payload : null,
    });
  };

  handleExport = async () => {
    this.setState({ busy: true, loadError: null });
    const result = await dossierService.exportPackage(this.dossierRef);
    this.setState({ busy: false });
    if (result.source === "api") {
      this.setState({ exportResult: result.payload });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Export failed") });
    }
  };

  render() {
    const { loading, loadError, dossier, hold, exportResult, busy } = this.state;
    const ref = this.dossierRef;
    return (
      <DossierLuxPage
        testId="dossier-export-page"
        dataSource={dossier ? "api" : loadError ? "api-error" : null}
        loading={loading}
        pageMeta={{
          tone: "slate",
          icon: "fe fe-download",
          eyebrow: "Projects · Dossier",
          titleLead: "Export",
          titleAccent: "package",
          lede: "Export records package metadata (Vault refs only). Blobs remain in Document Vault.",
        }}
        heroActions={
          <DossierActionButton
            to={`/dossiers/${encodeURIComponent(ref)}`}
            icon="fe fe-arrow-left"
            variant="ghost"
          >
            Dossier
          </DossierActionButton>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load dossier">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
        {!loading && !dossier && !loadError ? (
          <LuxRegisterEmptyState title="Dossier not found" description="No dossier loaded for this reference." showCreate={false} />
        ) : null}
        {dossier ? (
          <DossierLuxPanel title={`Export — ${ref}`} icon="fe fe-package">
            <div className="mb-3">
              <div>
                Status: <strong>{dossier.status}</strong>
              </div>
              {hold ? (
                <div>
                  Hold flag: <strong>{hold.holdFlag ? "ON" : "OFF"}</strong>
                  <div className="small text-muted">{hold.note}</div>
                </div>
              ) : null}
            </div>
            <DossierActionButton
              type="button"
              disabled={
                busy ||
                (dossier.status !== "APPROVED" &&
                  dossier.status !== "BASELINED" &&
                  dossier.status !== "EXPORTED")
              }
              onClick={this.handleExport}
            >
              {busy ? "Exporting…" : "Generate export package"}
            </DossierActionButton>
          </DossierLuxPanel>
        ) : null}
        {exportResult ? (
          <DossierLuxPanel title="Export result" icon="fe fe-code">
            <pre className="mb-0" data-testid="dossier-export-result">
              {JSON.stringify(exportResult, null, 2)}
            </pre>
          </DossierLuxPanel>
        ) : null}
      </DossierLuxPage>
    );
  }
}

export default DossierExportPage;
