import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";

const ACTION_META = {
  critical: { icon: "fe fe-alert-circle", hint: "Critical health interventions" },
  risks: { icon: "fe fe-shield", hint: "Portfolio risk register" },
  timeline: { icon: "fe fe-calendar", hint: "Delivery timeline recovery" },
  scenarios: { icon: "fe fe-sliders", hint: "What-if portfolio modeling" },
};

const KPI_ICONS = {
  health: "fe fe-activity",
  slippage: "fe fe-clock",
  risks: "fe fe-alert-triangle",
  issues: "fe fe-flag",
  programs: "fe fe-layers",
  portfolios: "fe fe-briefcase",
};

function downloadCsv(csv, filename) {
  if (!csv) return;
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename || `portfolio-briefing-${Date.now()}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

function healthTone(score) {
  if (score >= 80) return "green";
  if (score >= 60) return "amber";
  return "rose";
}

function BriefingHealthRing({ score }) {
  const tone = healthTone(score);
  return (
    <div className={classNames("lux-portfolio-briefing__health", `is-${tone}`)} aria-label={`Portfolio health ${score} percent`}>
      <span className="lux-portfolio-briefing__health-glow" aria-hidden="true" />
      <strong>{score}%</strong>
      <span>Portfolio health</span>
    </div>
  );
}

function BriefingSkeleton() {
  return (
    <div className="lux-portfolio-briefing lux-portfolio-briefing--loading" aria-busy="true">
      <div className="lux-portfolio-briefing__hero lux-portfolio-briefing__skeleton-block" />
      <div className="lux-portfolio-briefing__metrics">
        <span className="lux-portfolio-briefing__skeleton-chip" />
        <span className="lux-portfolio-briefing__skeleton-chip" />
        <span className="lux-portfolio-briefing__skeleton-chip" />
        <span className="lux-portfolio-briefing__skeleton-chip" />
      </div>
      <div className="lux-portfolio-briefing__story">
        <span className="lux-portfolio-briefing__skeleton-line" />
        <span className="lux-portfolio-briefing__skeleton-line" />
        <span className="lux-portfolio-briefing__skeleton-line lux-portfolio-briefing__skeleton-line--short" />
      </div>
    </div>
  );
}

export default function PortfolioExecutiveBriefingPanel({ briefing, loading, onExport }) {
  if (loading) {
    return <BriefingSkeleton />;
  }

  if (!briefing) {
    return (
      <div className="lux-portfolio-briefing__empty">
        <span className="lux-portfolio-briefing__empty-icon" aria-hidden="true">
          <i className="fe fe-file-text" />
        </span>
        <strong>Executive briefing pending</strong>
        <p>Leadership narrative, steering KPIs, and recommended actions will generate once portfolio roll-up data loads.</p>
      </div>
    );
  }

  const handleExport = async () => {
    if (onExport) {
      const result = await onExport();
      if (result && result.payload) {
        downloadCsv(result.payload, result.filename);
      }
    }
  };

  const kpis = (briefing.kpis || []).slice(0, 4);
  const paragraphs = briefing.paragraphs || [];
  const actions = briefing.recommendedActions || [];

  return (
    <div className="lux-portfolio-briefing">
      <div className="lux-portfolio-briefing__ambient" aria-hidden="true">
        <span className="lux-portfolio-briefing__orb lux-portfolio-briefing__orb--a" />
        <span className="lux-portfolio-briefing__orb lux-portfolio-briefing__orb--b" />
      </div>

      <header className="lux-portfolio-briefing__hero">
        <BriefingHealthRing score={briefing.healthScore} />
        <div className="lux-portfolio-briefing__hero-main">
          <span className="lux-portfolio-briefing__kicker">
            <i className="fe fe-briefcase" aria-hidden="true" />
            Steering pack · Generated {briefing.generatedAt}
          </span>
          <p className="lux-portfolio-briefing__lead">{paragraphs[0] || briefing.summary}</p>
          <div className="lux-portfolio-briefing__badges">
            <span className="lux-portfolio-briefing__badge">Leadership narrative</span>
            <span className="lux-portfolio-briefing__badge is-muted">{actions.length} steering actions</span>
          </div>
        </div>
        <div className="lux-portfolio-briefing__hero-actions">
          <ResourcesActionButton icon="fe fe-download" variant="ghost" onClick={handleExport}>
            Export briefing
          </ResourcesActionButton>
        </div>
      </header>

      {kpis.length ? (
        <div className="lux-portfolio-briefing__metrics" role="list" aria-label="Executive briefing metrics">
          {kpis.map((metric) => (
            <article
              key={metric.id}
              className={classNames("lux-portfolio-briefing__metric", metric.tone && `is-${metric.tone}`)}
              role="listitem"
            >
              <span className="lux-portfolio-briefing__metric-icon" aria-hidden="true">
                <i className={KPI_ICONS[metric.id] || "fe fe-bar-chart-2"} />
              </span>
              <div className="lux-portfolio-briefing__metric-copy">
                <span className="lux-portfolio-briefing__metric-label">{metric.label}</span>
                <strong>
                  {metric.value}
                  {metric.unit || ""}
                </strong>
                {metric.hint ? <small>{metric.hint}</small> : null}
              </div>
            </article>
          ))}
        </div>
      ) : null}

      {paragraphs.length > 1 ? (
        <section className="lux-portfolio-briefing__story" aria-label="Briefing narrative">
          <header className="lux-portfolio-briefing__story-head">
            <span className="lux-portfolio-briefing__label">Executive narrative</span>
            <span className="lux-portfolio-briefing__story-count">{paragraphs.length} insight blocks</span>
          </header>
          <div className="lux-portfolio-briefing__story-grid">
            {paragraphs.map((paragraph, index) => (
              <article key={index} className="lux-portfolio-briefing__story-card">
                <span className="lux-portfolio-briefing__story-index" aria-hidden="true">
                  {String(index + 1).padStart(2, "0")}
                </span>
                <p>{paragraph}</p>
              </article>
            ))}
          </div>
        </section>
      ) : null}

      {actions.length ? (
        <section className="lux-portfolio-briefing__actions">
          <header className="lux-portfolio-briefing__actions-head">
            <span className="lux-portfolio-briefing__label">Recommended steering actions</span>
            <span className="lux-portfolio-briefing__actions-note">Linked drill-down routes for this steering cycle</span>
          </header>
          <div className="lux-portfolio-briefing__action-grid">
            {actions.map((action) => {
              const meta = ACTION_META[action.id] || { icon: "fe fe-arrow-right", hint: "Open workspace" };
              return (
                <Link
                  key={action.id}
                  to={action.path}
                  className={classNames("lux-portfolio-briefing__action", action.tone && `is-${action.tone}`)}
                >
                  <span className="lux-portfolio-briefing__action-icon" aria-hidden="true">
                    <i className={meta.icon} />
                  </span>
                  <span className="lux-portfolio-briefing__action-copy">
                    <strong>{action.label}</strong>
                    <small>{meta.hint}</small>
                  </span>
                  <i className="fe fe-chevron-right lux-portfolio-briefing__action-chevron" aria-hidden="true" />
                </Link>
              );
            })}
          </div>
        </section>
      ) : null}

      <footer className="lux-portfolio-briefing__foot">
        <i className="fe fe-info" aria-hidden="true" />
        <span>Draft steering narrative from portfolio roll-ups. Full AI agent workflow is coming in a future release.</span>
      </footer>
    </div>
  );
}
