import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { PROGRAM_STATUSES } from "config/portfolio-control-tower.config";

const STATUS_TONE = {
  [PROGRAM_STATUSES.ON_TRACK]: "green",
  [PROGRAM_STATUSES.AT_RISK]: "amber",
  [PROGRAM_STATUSES.OFF_TRACK]: "rose",
  [PROGRAM_STATUSES.COMPLETE]: "slate",
};

function healthTone(score) {
  if (score == null) return "slate";
  if (score >= 80) return "green";
  if (score >= 60) return "amber";
  return "rose";
}

export default function PortfolioHierarchyPanel({ hierarchy, loading }) {
  if (loading) {
    return <div className="lux-portfolio-hierarchy__loading">Loading program hierarchy…</div>;
  }

  if (!hierarchy || !hierarchy.programs || !hierarchy.programs.length) {
    return <div className="lux-portfolio-hierarchy__empty">No program hierarchy linked to this portfolio.</div>;
  }

  return (
    <div className="lux-portfolio-hierarchy">
      {hierarchy.programs.map((program) => (
        <article key={program.id} className="lux-portfolio-hierarchy__program">
          <header className="lux-portfolio-hierarchy__program-head">
            <div>
              <strong>{program.name}</strong>
              <span>{program.code}</span>
            </div>
            <div className="lux-portfolio-hierarchy__meta">
              <span className={classNames("lux-portfolio-badge", `is-${STATUS_TONE[program.status] || "slate"}`)}>
                {program.status ? program.status.replace(/_/g, " ") : "—"}
              </span>
              <span className={classNames("lux-portfolio-hierarchy__health", `is-${healthTone(program.healthScore)}`)}>
                {program.healthScore != null ? `${program.healthScore}%` : "—"}
              </span>
            </div>
          </header>

          {(program.initiatives || []).length ? (
            <div className="lux-portfolio-hierarchy__initiatives">
              <span className="lux-portfolio-hierarchy__label">Initiatives</span>
              <ul>
                {program.initiatives.map((row) => (
                  <li key={row.id}>
                    <strong>{row.name}</strong>
                    <small>{row.status || "Active"}</small>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}

          <div className="lux-portfolio-hierarchy__projects">
            <span className="lux-portfolio-hierarchy__label">Governed projects</span>
            <div className="lux-portfolio-hierarchy__project-grid">
              {(program.projects || []).map((project) => (
                <div key={project.projectId} className="lux-portfolio-hierarchy__project">
                  <div>
                    <strong>{project.projectName}</strong>
                    <small>{project.projectCode || project.projectId}</small>
                  </div>
                  <span className={classNames("lux-portfolio-hierarchy__health", `is-${healthTone(project.healthScore)}`)}>
                    {project.healthScore != null ? `${project.healthScore}%` : "—"}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </article>
      ))}
      <p className="lux-portfolio-hierarchy__foot">
        Open the <Link to="/project/governance">governance hub</Link> for gate and decision drill-down per project.
      </p>
    </div>
  );
}
