import { shouldUseAnalyticsPlatform } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const ANALYTICS_DOMAINS = {
  EXECUTIVE: "executive",
  WORKFORCE: "workforce",
  DELIVERY: "delivery",
  RESOURCE: "resource",
  PAYROLL: "payroll",
  FINANCE: "finance",
  APPROVALS: "approvals",
  RISK: "risk",
};

export const METRIC_FORMATS = {
  NUMBER: "NUMBER",
  PERCENT: "PERCENT",
  CURRENCY: "CURRENCY",
  DAYS: "DAYS",
  COUNT: "COUNT",
};

export const CHART_TYPES = {
  BAR: "BAR",
  LINE: "LINE",
  KPI: "KPI",
  HEATMAP: "HEATMAP",
};

export const DASHBOARD_WIDGET_TYPES = {
  KPI_STRIP: "KPI_STRIP",
  BAR_CHART: "BAR_CHART",
  INSIGHT_STRIP: "INSIGHT_STRIP",
  METRIC_TABLE: "METRIC_TABLE",
};

export const REPORT_STATUSES = {
  DRAFT: "DRAFT",
  SAVED: "SAVED",
  ARCHIVED: "ARCHIVED",
};

export const REPORT_OUTPUT_FORMATS = {
  TABLE: "TABLE",
  CSV: "CSV",
  CHART: "CHART",
};

export const SCHEDULE_FREQUENCIES = {
  DAILY: "DAILY",
  WEEKLY: "WEEKLY",
  MONTHLY: "MONTHLY",
};

export const SCHEDULE_STATUSES = {
  ACTIVE: "ACTIVE",
  PAUSED: "PAUSED",
  FAILED: "FAILED",
};

export const EXPORT_JOB_STATUSES = {
  QUEUED: "QUEUED",
  RUNNING: "RUNNING",
  COMPLETE: "COMPLETE",
  FAILED: "FAILED",
};

export function isAnalyticsAiInsightsEnabled() {
  return envconfig.ANALYTICS_AI_INSIGHTS_ENABLED === true;
}

/** ANA-004 — production delivery remains fail-closed until staging proof. */
export function isScheduledReportsDeliveryEnabled() {
  return false;
}

export function isAnalyticsPlatformEnabled() {
  return shouldUseAnalyticsPlatform();
}

export function shouldUseAnalyticsPlatformApi() {
  return envconfig.USE_ANALYTICS_PLATFORM_API === true;
}

export function isAnalyticsDomainEnabled(domain) {
  if (!isAnalyticsPlatformEnabled()) {
    return false;
  }
  const flags = envconfig.ANALYTICS_DOMAIN_FLAGS || {};
  if (flags[domain] === false) {
    return false;
  }
  return true;
}

export function normalizeMetricDefinition(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    domain: row.domain,
    code: row.code || row.id,
    label: row.label || row.name || "Metric",
    description: row.description || "",
    format: row.format || METRIC_FORMATS.NUMBER,
    unit: row.unit || "",
    sourceModule: row.sourceModule || "",
    drilldownPath: row.drilldownPath || null,
    sensitive: row.sensitive === true,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeDashboardConfig(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    domain: row.domain,
    name: row.name || "Dashboard",
    description: row.description || "",
    personaScope: row.personaScope || "ORG",
    widgets: Array.isArray(row.widgets) ? row.widgets : [],
    metricIds: Array.isArray(row.metricIds) ? row.metricIds : [],
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeDashboardWidget(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    type: row.type || DASHBOARD_WIDGET_TYPES.KPI_STRIP,
    title: row.title || "",
    subtitle: row.subtitle || "",
    metricIds: Array.isArray(row.metricIds) ? row.metricIds : [],
    chartType: row.chartType || CHART_TYPES.BAR,
  };
}

export function normalizeSavedReport(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Untitled report",
    description: row.description || "",
    domain: row.domain || null,
    status: row.status || REPORT_STATUSES.SAVED,
    metricIds: Array.isArray(row.metricIds) ? row.metricIds : [],
    outputFormat: row.outputFormat || REPORT_OUTPUT_FORMATS.TABLE,
    personaScope: row.personaScope || "ORG",
    ownerName: row.ownerName || "",
    updatedAt: row.updatedAt || null,
    createdAt: row.createdAt || null,
  };
}

export function normalizeReportQuery(row) {
  if (!row) {
    return null;
  }
  return {
    domain: row.domain || null,
    metricIds: Array.isArray(row.metricIds) ? row.metricIds : [],
    filters: row.filters || {},
    outputFormat: row.outputFormat || REPORT_OUTPUT_FORMATS.TABLE,
  };
}

export function normalizeScheduledReport(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    reportId: row.reportId || null,
    reportName: row.reportName || row.name || "Scheduled report",
    frequency: row.frequency || SCHEDULE_FREQUENCIES.WEEKLY,
    status: row.status || SCHEDULE_STATUSES.ACTIVE,
    recipients: Array.isArray(row.recipients) ? row.recipients : [],
    nextRunAt: row.nextRunAt || null,
    lastRunAt: row.lastRunAt || null,
    outputFormat: row.outputFormat || REPORT_OUTPUT_FORMATS.CSV,
    ownerName: row.ownerName || "",
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeReportExportJob(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    reportId: row.reportId || null,
    reportName: row.reportName || "",
    status: row.status || EXPORT_JOB_STATUSES.QUEUED,
    outputFormat: row.outputFormat || REPORT_OUTPUT_FORMATS.CSV,
    rowCount: row.rowCount != null ? row.rowCount : null,
    requestedAt: row.requestedAt || null,
    completedAt: row.completedAt || null,
    downloadReady: row.downloadReady === true,
  };
}

export function normalizeSavedFilter(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Saved filter",
    domain: row.domain || null,
    metricIds: Array.isArray(row.metricIds) ? row.metricIds : [],
    filters: row.filters || {},
    isDefault: row.isDefault === true,
    ownerName: row.ownerName || "",
    updatedAt: row.updatedAt || null,
  };
}
