import React from "react";
import { getAppBrandName } from "_helpers/brand.utils";
import {
  AUDIT_ENTITY_TYPES,
  AUDIT_PROFILE_ACTIVITY_FILTER_OPTIONS,
  AUDIT_SCOPES,
  AUDIT_VIEW_MODES,
} from "_constants/audit.constants";
import CollapsibleAuditPanel from "views/common/fragments/CollapsibleAuditPanel";
import ProfileSection from "./ProfileSection";

const TRACKED_ACTIVITY_TYPES = [
  {
    icon: "fe fe-log-in",
    label: "Sign-in & sessions",
    description: "Logins, logouts, and session timeouts",
  },
  {
    icon: "fe fe-clock",
    label: "Timesheet & attendance",
    description: "Submissions, edits, and approvals",
  },
  {
    icon: "fe fe-layers",
    label: "Projects & tasks",
    description: "Assignments and status updates you perform",
  },
  {
    icon: "fe fe-shield",
    label: "Security events",
    description: "Password updates and permission changes",
  },
];

const TRACKED_HISTORY_TYPES = [
  {
    icon: "fe fe-user",
    label: "Profile fields",
    description: "Name, contact, org placement, and employment details",
  },
  {
    icon: "fe fe-key",
    label: "Access & roles",
    description: "Role assignments and permission changes on this record",
  },
  {
    icon: "fe fe-edit-3",
    label: "Field-level diffs",
    description: "Before and after values for each saved change",
  },
];

function ProfileAccountActivityView({ employee, readOnly }) {
  if (!employee) return null;

  const appName = getAppBrandName();
  const employeeId = employee.id;

  return (
    <div className="profile-settings profile-activity lux-settings-tab__stack">
      {!readOnly && (
        <p className="profile-settings-banner is-preview" role="note">
          <i className="fe fe-shield" aria-hidden="true" />
          {appName} records workspace actions and profile changes below. Expand each panel when
          you need the audit trail — visibility is controlled by your organisation.
        </p>
      )}

      {readOnly && (
        <p className="profile-settings-banner is-muted" role="note">
          <i className="fe fe-eye" aria-hidden="true" />
          Read-only audit view for this employee. Activity shows actions they performed; History
          shows data changes on their profile record.
        </p>
      )}

      <CollapsibleAuditPanel
        panelKey={`profile-activity-${employeeId}`}
        title="Account activity"
        subtitle="Actions performed by this user across projects, HR, and security"
        icon="fe-activity"
        auditProps={{
          scope: AUDIT_SCOPES.ACTOR,
          actorUserId: employeeId,
          viewMode: AUDIT_VIEW_MODES.ACTIVITY,
          entityFilterOptions: AUDIT_PROFILE_ACTIVITY_FILTER_OPTIONS,
          showEntityFilters: true,
          emptyState: {
            eyebrow: "Your audit feed",
            title: "No activity recorded yet",
            description: readOnly
              ? "No audit events are available for this employee in the selected period."
              : "When audit logging is enabled, sign-ins, approvals, and workflow actions will appear here.",
            hints: [
              "Filter by projects, timesheets, attendance, or leaves",
              "Delegate approvals show who acted on whose behalf",
              "Data-only field saves appear under History",
            ],
          },
        }}
      />

      <CollapsibleAuditPanel
        panelKey={`profile-history-${employeeId}`}
        title="Profile history"
        subtitle="Data changes on this employee record — fields, roles, and org details"
        icon="fe-clock"
        auditProps={{
          scope: AUDIT_SCOPES.ENTITY,
          entityType: AUDIT_ENTITY_TYPES.EMPLOYEE,
          entityId: employeeId,
          viewMode: AUDIT_VIEW_MODES.HISTORY,
          showEntityFilters: false,
          emptyState: {
            eyebrow: "Profile record",
            title: "No profile changes recorded yet",
            description:
              "Edits to personal details, manager, role, and other profile fields will appear here when audit logging is active.",
            hints: [
              "Each event shows before and after field values",
              "Role and access updates are listed separately",
              "History starts from audit go-live — not legacy feeds",
            ],
          },
        }}
      />

      <ProfileSection
        title="What we track"
        subtitle="Activity vs history on this profile"
        icon="fe fe-list"
      >
        <div className="profile-activity__track-grid">
          <div>
            <h4 className="profile-activity__track-heading">Activity</h4>
            <ul className="profile-activity__types">
              {TRACKED_ACTIVITY_TYPES.map((item) => (
                <li key={item.label} className="profile-activity__type">
                  <span className="profile-activity__type-icon">
                    <i className={item.icon} aria-hidden="true" />
                  </span>
                  <span className="profile-activity__type-copy">
                    <strong>{item.label}</strong>
                    <span>{item.description}</span>
                  </span>
                </li>
              ))}
            </ul>
          </div>
          <div>
            <h4 className="profile-activity__track-heading">History</h4>
            <ul className="profile-activity__types">
              {TRACKED_HISTORY_TYPES.map((item) => (
                <li key={item.label} className="profile-activity__type">
                  <span className="profile-activity__type-icon">
                    <i className={item.icon} aria-hidden="true" />
                  </span>
                  <span className="profile-activity__type-copy">
                    <strong>{item.label}</strong>
                    <span>{item.description}</span>
                  </span>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </ProfileSection>
    </div>
  );
}

export default ProfileAccountActivityView;
