import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { WorkspacePanelHead } from "views/workspace/components/WorkspaceLuxShared";

const WIDGET_TONE_CLASS = {
  primary: "primary",
  blue: "blue",
  green: "green",
  mint: "green",
  success: "green",
  info: "blue",
  warning: "amber",
  danger: "rose",
  neutral: "slate",
  amber: "amber",
  rose: "rose",
  violet: "violet",
  slate: "slate",
};

export default function WorkspaceRoleWidgetsPanel({ widgets = [], loading, activePersonaLabel }) {
  if (widgets.length === 0) {
    return null;
  }

  return (
    <section className="lux-hrms-dash__panel lux-workspace-home-panel lux-workspace-home-panel--widgets" aria-label="Role widgets">
      <WorkspacePanelHead
        title="Role widgets"
        subtitle={`${activePersonaLabel} signals and shortcuts`}
      />
      <div className="lux-hrms-dash__panel-body">
        <div className="lux-workspace-widgets__grid">
          {widgets.map((widget) => {
            const tone = WIDGET_TONE_CLASS[widget.tone] || "primary";
            const body = (
              <>
                <span className={classNames("lux-workspace-widgets__icon", `is-${tone}`)} aria-hidden="true">
                  <i className={widget.icon || "fe fe-grid"} />
                </span>
                <span className="lux-workspace-widgets__copy">
                  <strong>{widget.title}</strong>
                  <small>{widget.hint}</small>
                  {widget.value != null && (
                    <em className={classNames("lux-workspace-widgets__value", `is-${tone}`)}>
                      {loading ? "—" : widget.value}
                    </em>
                  )}
                </span>
                {widget.path && (
                  <i className="fe fe-arrow-right lux-workspace-widgets__chevron" aria-hidden="true" />
                )}
              </>
            );

            if (widget.path) {
              return (
                <Link
                  key={widget.id}
                  to={widget.path}
                  className={classNames("lux-workspace-widgets__card", `is-${tone}`)}
                >
                  {body}
                </Link>
              );
            }

            return (
              <article key={widget.id} className={classNames("lux-workspace-widgets__card", `is-${tone}`)}>
                {body}
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
}
