/**
 * FR01 PWA-001 — register shell-only service worker (no API/offline business SoT).
 * Query-bust registration URL with embedded APP_VERSION so browsers fetch a new SW after release.
 */
import envconfig from "env.config";

export function registerTracopusServiceWorker({ onUpdate } = {}) {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) {
    return;
  }
  const enabled =
    process.env.NODE_ENV === "production" ||
    process.env.REACT_APP_ENABLE_PWA_SW === "true";
  if (!enabled) {
    return;
  }

  const version = String((envconfig && envconfig.APP_VERSION) || "").trim() || "dev";
  // Same script URL every release; updateViaCache:none forces revalidation of the SW file.
  const swUrl = `${process.env.PUBLIC_URL || ""}/service-worker.js`;

  window.addEventListener("load", () => {
    navigator.serviceWorker
      .register(swUrl, { updateViaCache: "none" })
      .then((registration) => {
        registration.onupdatefound = () => {
          const installing = registration.installing;
          if (!installing) return;
          installing.onstatechange = () => {
            if (installing.state === "installed" && navigator.serviceWorker.controller) {
              if (typeof onUpdate === "function") {
                onUpdate(registration);
              }
            }
          };
        };
        // Proactively look for an updated SW after deploy.
        try {
          registration.update();
        } catch (_err) {
          // ignore
        }
        // Help support: expose version used at registration time.
        registration.__tracopusVersion = version;
      })
      .catch(() => {
        // Fail-closed: app works without SW
      });
  });
}
