import React, { Component } from "react";
import classNames from "classnames/bind";
import { RISK_SEVERITIES, RISK_STATUSES } from "config/project-governance.config";
import { GOVERNANCE_PAGE_IDS } from "config/project-governance-nav.config";
import { getRiskSeverityTone, getRiskStatusTone } from "config/project-governance.utils";
import GovernanceLuxDrawerShell from "views/project/components/GovernanceLuxDrawerShell";
import {
  GovernanceDrawerBanner,
  GovernanceDrawerCard,
  GovernanceDrawerField,
  GovernanceDrawerMeta,
  GovernanceDrawerModuleLink,
  GovernanceDrawerStatStrip,
  buildGovernanceQuickLinks,
} from "views/project/components/GovernanceLuxDrawerShared";

export default class RiskDrawer extends Component {
  state = {
    severity: RISK_SEVERITIES.MEDIUM,
    status: RISK_STATUSES.OPEN,
    mitigationPlan: "",
    dueDate: "",
    ownerName: "",
    saving: false,
    escalating: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    const { risk, open } = this.props;
    if (open && risk && risk !== prevProps.risk) {
      this.setState({
        severity: risk.severity || RISK_SEVERITIES.MEDIUM,
        status: risk.status || RISK_STATUSES.OPEN,
        mitigationPlan: risk.mitigationPlan || "",
        dueDate: risk.dueDate || "",
        ownerName: risk.ownerName || "",
        saving: false,
        escalating: false,
        error: null,
      });
    }
  }

  handleSave = async () => {
    const { risk, onSave, onClose } = this.props;
    const { severity, status, mitigationPlan, dueDate, ownerName } = this.state;
    if (!risk || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onSave(risk.id, {
        severity,
        status,
        mitigationPlan,
        dueDate: dueDate || null,
        ownerName,
      });
      onClose();
    } catch (e) {
      this.setState({
        saving: false,
        error: (e && e.message) || "Unable to update risk.",
      });
    }
  };

  handleEscalate = async () => {
    const { risk, onEscalate, onClose } = this.props;
    if (!risk || !onEscalate) {
      return;
    }
    this.setState({ escalating: true, error: null });
    try {
      await onEscalate(risk.id, { mitigationPlan: this.state.mitigationPlan });
      onClose();
    } catch (e) {
      this.setState({
        escalating: false,
        error: (e && e.message) || "Unable to escalate risk.",
      });
    }
  };

  render() {
    const { open, risk, onClose } = this.props;
    const { severity, status, mitigationPlan, dueDate, ownerName, saving, escalating, error } = this.state;
    if (!open || !risk) {
      return null;
    }

    const severityTone = getRiskSeverityTone(risk.severity);
    const statusTone = getRiskStatusTone(risk.status);
    const canEscalate = risk.status !== RISK_STATUSES.ESCALATED && risk.status !== RISK_STATUSES.CLOSED;

    return (
      <GovernanceLuxDrawerShell
        open={open}
        onClose={onClose}
        accent="warning"
        icon="fe-alert-triangle"
        eyebrow="Delivery risk"
        title={risk.title}
        subtitle={risk.projectName}
        quickLinks={buildGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.RISKS, [
          { to: "/project/governance", label: "Governance hub", hint: "Steering", icon: "fe fe-shield" },
        ])}
        ariaLabel={`Risk ${risk.title}`}
        footer={
          <div className="lux-gov-drawer__foot-bar">
            <GovernanceDrawerModuleLink to="/project/risks" label="Open risk register" onNavigate={onClose} />
            <div className="lux-onb-drawer__foot-actions">
              {canEscalate ? (
                <button
                  type="button"
                  className="lux-onb-action lux-onb-action--ghost is-danger"
                  onClick={this.handleEscalate}
                  disabled={escalating || saving}
                >
                  {escalating ? "Escalating…" : "Escalate"}
                </button>
              ) : null}
              <button type="button" className="lux-onb-action lux-onb-action--ghost" onClick={onClose}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-onb-action lux-onb-action--primary"
                onClick={this.handleSave}
                disabled={saving || escalating}
              >
                {saving ? "Saving…" : "Save risk"}
              </button>
            </div>
          </div>
        }
      >
        <GovernanceDrawerStatStrip
          stats={[
            { label: "Severity", value: risk.severity, tone: severityTone },
            { label: "Status", value: risk.status, tone: statusTone },
            { label: "Owner", value: risk.ownerName || "Unassigned" },
          ]}
        />

        <GovernanceDrawerCard title="Exposure summary" subtitle="Category, severity, and escalation context">
          <GovernanceDrawerMeta
            items={[
              { label: "Category", value: risk.category || "—" },
              {
                label: "Severity",
                value: <span className={classNames("lux-doc-badge", `is-${severityTone}`)}>{risk.severity}</span>,
              },
              {
                label: "Status",
                value: <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{risk.status}</span>,
              },
              { label: "Escalated", value: risk.escalatedAt || "Not escalated" },
            ]}
          />
          {risk.description ? (
            <GovernanceDrawerBanner icon="fe-file-text">{risk.description}</GovernanceDrawerBanner>
          ) : null}
        </GovernanceDrawerCard>

        <GovernanceDrawerCard title="Mitigation plan" subtitle="Owner, response plan, and target dates">
          <GovernanceDrawerField label="Owner">
            <input value={ownerName} onChange={(e) => this.setState({ ownerName: e.target.value })} />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Severity">
            <select value={severity} onChange={(e) => this.setState({ severity: e.target.value })}>
              {Object.values(RISK_SEVERITIES).map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Status">
            <select value={status} onChange={(e) => this.setState({ status: e.target.value })}>
              {Object.values(RISK_STATUSES).map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Mitigation plan">
            <textarea
              rows={3}
              value={mitigationPlan}
              onChange={(e) => this.setState({ mitigationPlan: e.target.value })}
            />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Due date">
            <input type="date" value={dueDate || ""} onChange={(e) => this.setState({ dueDate: e.target.value })} />
          </GovernanceDrawerField>
          {error ? <p className="lux-gov-drawer__error">{error}</p> : null}
        </GovernanceDrawerCard>
      </GovernanceLuxDrawerShell>
    );
  }
}
