import React, { Component } from "react";
import Skeleton from "react-loading-skeleton";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import Select, { components as selectComponents } from "react-select";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { projectActions } from "_actions";
import { workItemActions } from "_actions";
import { appConfigActions } from "_actions";

const TYPE_OPTIONS = [
  {
    value: "project",
    label: "Project",
    title: "Billable project",
    hint: "Log client or delivery project time",
    icon: "fe-briefcase",
    tone: "green",
  },
  {
    value: "nonProject",
    label: "Non Billable",
    title: "Non-billable",
    hint: "Leave, holiday, or internal work",
    icon: "fe-layers",
    tone: "blue",
  },
];

const MENU_Z_INDEX = 1000020;

function RichSelectOption(props) {
  const { data, isSelected, isFocused } = props;
  return (
    <selectComponents.Option {...props}>
      <span
        className={classNames("lux-ts-add-entry__opt", {
          "is-selected": isSelected,
          "is-focused": isFocused,
        })}
      >
        <span className="lux-ts-add-entry__opt-icon" aria-hidden="true">
          <i className={`fe ${data.icon || "fe-circle"}`} />
        </span>
        <span className="lux-ts-add-entry__opt-copy">
          <strong>{data.label}</strong>
          {data.meta && <span>{data.meta}</span>}
        </span>
        {isSelected && (
          <span className="lux-ts-add-entry__opt-check" aria-hidden="true">
            <i className="fe fe-check" />
          </span>
        )}
      </span>
    </selectComponents.Option>
  );
}

function RichSingleValue(props) {
  const { data } = props;
  return (
    <selectComponents.SingleValue {...props}>
      <span className="lux-ts-add-entry__value">
        <i className={`fe ${data.icon || "fe-circle"}`} aria-hidden="true" />
        <span>{data.label}</span>
      </span>
    </selectComponents.SingleValue>
  );
}

class TimesheetAddEntryModal extends Component {
  constructor() {
    super();
    this.state = {
      typeSelectionOption: null,
      categorySelectionOption: null,
      projectSelectionOption: null,
      deliverableSelectionOption: null,
      nonBillableCategoryLoaded: false,
      reloadProjectAlways: true,
      startOfTheWeek: null,
    };
  }

  componentDidMount() {
    this.setState({ startOfTheWeek: this.props.startOfTheWeek });
    document.addEventListener("keydown", this.handleKeyDown);
    if (this.props.show) {
      this.lockPageScroll(true);
    }
  }

  componentDidUpdate(prevProps) {
    if (this.props.show !== prevProps.show) {
      this.lockPageScroll(this.props.show);
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
    this.lockPageScroll(false);
  }

  lockPageScroll = (lock) => {
    if (typeof document === "undefined") return;
    const body = document.body;
    if (lock) {
      this.scrollbarGap = window.innerWidth - document.documentElement.clientWidth;
      body.classList.add("lux-ts-add-entry-open");
      if (this.scrollbarGap > 0) {
        body.style.paddingRight = `${this.scrollbarGap}px`;
      }
    } else {
      body.classList.remove("lux-ts-add-entry-open");
      body.style.paddingRight = "";
    }
  };

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      this.handleCancel();
    }
  };

  reloadProjectListService = () => {
    if (
      this.state.startOfTheWeek !== this.props.startOfTheWeek ||
      !this.props.projectsForTimesheet ||
      this.state.reloadProjectAlways
    ) {
      const selectedCurrentUserId = this.props.selectedEmployee.id;
      const selectedUserTeamId = this.props.selectedEmployee.userTeamId;
      const dateMoment = dateUtils.toDateToMoment(this.props.startOfTheWeek);
      const startDate = dateMoment.format(dateUtils.SERVER_DATE_FORMAT);
      const endDate = dateUtils.addXDays(dateMoment, 7).format(dateUtils.SERVER_DATE_FORMAT);
      const isOnlyUserTeams = this.props.permission.listOnlyCurrentTeamProject;
      store.dispatch(
        this.props.getProjectList({
          userTeamIds: [selectedUserTeamId],
          currentUserId: selectedCurrentUserId,
          startDate,
          endDate,
          isOnlyUserTeams,
        })
      );
      this.setState({ startOfTheWeek: this.props.startOfTheWeek });
    }
  };

  onTypeSelectionOption = (typeSelectionOption) => {
    this.setState({
      typeSelectionOption,
      categorySelectionOption: null,
      projectSelectionOption: null,
      deliverableSelectionOption: null,
    });
    if (typeSelectionOption.value === "project") {
      this.reloadProjectListService();
    } else if (this.state.nonBillableCategoryLoaded === false) {
      store.dispatch(
        this.props.initializeNonProjectWorkItem(
          this.props.permission.timeSheetNonBillableShowAllAccountsEnabled === true,
          this.props.selectedEmployee.userTeamId
        )
      );
      store.dispatch(appConfigActions.getAllTeams(true));
      this.setState({ nonBillableCategoryLoaded: true });
    }
  };

  onChangeCategorySelection = (categorySelectionOption) => {
    this.setState({ categorySelectionOption });
  };

  onChangeProjectSelection = (projectSelectionOption) => {
    this.setState({
      projectSelectionOption,
      deliverableSelectionOption: null,
    });
  };

  onChangeDeliverableSelection = (deliverableSelectionOption) => {
    this.setState({ deliverableSelectionOption });
  };

  handleAddProjectForTimeEntry = () => {
    this.props.handleAddProjectForTimeEntry(
      this.state.typeSelectionOption,
      this.state.categorySelectionOption,
      this.state.projectSelectionOption,
      this.state.deliverableSelectionOption
    );
    this.setState({
      projectSelectionOption: null,
      categorySelectionOption: null,
      deliverableSelectionOption: null,
      typeSelectionOption: null,
    });
    this.props.cancelShowSelectionWindow();
  };

  handleCancel = () => {
    this.props.cancelShowSelectionWindow();
  };

  getCategoryOptions = () => {
    if (!this.props.nonProjectAppConfig) return [];
    const config = this.props.nonProjectAppConfig.find((item) => item.name === "taskActCategory");
    const configOptions = config
      ? commonUtils.convertConfigListToSelectObject(config.value) || []
      : [];
    return [
      { value: "HOLIDAY", label: "Holiday", icon: "fe-sun", meta: "Public or company holiday" },
      { value: "LEAVE", label: "Leave", icon: "fe-calendar", meta: "Personal or approved leave" },
      ...configOptions.map((item) => ({
        ...item,
        icon: "fe-tag",
        meta: "Non-billable category",
      })),
    ];
  };

  getProjectOptions = () => {
    const { projectsForTimesheet } = this.props;
    if (!projectsForTimesheet) return [];
    return commonUtils.convertObjectToSelectObject(projectsForTimesheet).map((item) => ({
      ...item,
      icon: "fe-folder",
      meta: [item.code, item.category].filter(Boolean).join(" · ") || "Billable project",
    }));
  };

  getDeliverableOptions = () => {
    const project = this.state.projectSelectionOption;
    if (!project) return [];
    let deliverables = project.taskInfoList || [];
    if (this.props.permission && this.props.permission.restrictedBySkillsEnabled === true) {
      const employeeSkills = commonUtils.getEmployeeSkills(this.props.selectedEmployee);
      deliverables = deliverables.filter(
        (deliverable) =>
          !deliverable.restrictedByEmployeeSkills ||
          employeeSkills.some((skill) => deliverable.restrictedByEmployeeSkills.includes(skill))
      );
      deliverables = deliverables.filter(
        (deliverable) =>
          !deliverable.restrictedByEmployeeIds ||
          deliverable.restrictedByEmployeeIds.includes(this.props.selectedEmployee.id)
      );
    }
    return commonUtils.convertObjectToSelectObject(deliverables).map((item) => ({
      ...item,
      icon: "fe-flag",
      meta:
        [item.serviceLine, item.taskCategory, item.status].filter(Boolean).join(" · ") ||
        "Deliverable",
    }));
  };

  renderTypeCards = () => (
    <div className="lux-ts-add-entry__type-grid" role="radiogroup" aria-label="Entry type">
      {TYPE_OPTIONS.map((option) => {
        const isActive =
          this.state.typeSelectionOption && this.state.typeSelectionOption.value === option.value;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={isActive}
            className={classNames("lux-ts-add-entry__type-card", `is-${option.tone}`, {
              "is-active": isActive,
            })}
            onClick={() => this.onTypeSelectionOption({ value: option.value, label: option.label })}
          >
            <span className="lux-ts-add-entry__type-top">
              <span className="lux-ts-add-entry__type-icon" aria-hidden="true">
                <i className={`fe ${option.icon}`} />
              </span>
              {isActive && (
                <span className="lux-ts-add-entry__type-check" aria-hidden="true">
                  <i className="fe fe-check" />
                </span>
              )}
            </span>
            <strong>{option.title}</strong>
            <span className="lux-ts-add-entry__type-hint">{option.hint}</span>
          </button>
        );
      })}
    </div>
  );

  selectMenuStyles = {
    menuPortal: (base) => ({ ...base, zIndex: MENU_Z_INDEX }),
    control: (base, state) => ({
      ...base,
      minHeight: 38,
      borderRadius: 11,
      borderWidth: 1,
      borderColor: state.isFocused ? "#818cf8" : "#cbd5e1",
      boxShadow: state.isFocused
        ? "0 0 0 3px rgba(91, 95, 244, 0.14)"
        : "0 1px 3px rgba(15, 23, 42, 0.05)",
      background: "linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)",
      cursor: "pointer",
    }),
    valueContainer: (base) => ({
      ...base,
      padding: "2px 10px",
      fontSize: "0.8125rem",
      fontWeight: 700,
    }),
    placeholder: (base) => ({
      ...base,
      color: "#94a3b8",
      fontWeight: 500,
      fontSize: "0.8125rem",
    }),
    singleValue: (base) => ({
      ...base,
      color: "#0f172a",
      fontWeight: 700,
      margin: 0,
    }),
    option: (base) => ({
      ...base,
      padding: 0,
      backgroundColor: "transparent",
      color: "inherit",
      cursor: "pointer",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: 12,
      overflow: "hidden",
      border: "1px solid rgba(226, 232, 240, 0.98)",
      boxShadow: "0 18px 40px rgba(15, 23, 42, 0.2), 0 3px 10px rgba(15, 23, 42, 0.08)",
      marginTop: 4,
      zIndex: MENU_Z_INDEX,
      background: "#fff",
    }),
    menuList: (base) => ({
      ...base,
      padding: "0.28rem",
      maxHeight: 220,
    }),
    indicatorSeparator: () => ({ display: "none" }),
    dropdownIndicator: (base, state) => ({
      ...base,
      color: state.isFocused ? "#5b5ff4" : "#64748b",
      padding: "0 10px",
    }),
  };

  selectComponents = {
    Option: RichSelectOption,
    SingleValue: RichSingleValue,
  };

  renderLuxurySelect = ({
    inputId,
    placeholder,
    value,
    onChange,
    options,
    loading,
    loadingLabel,
  }) => {
    if (loading) {
      return (
        <div className="lux-ts-add-entry__hint" aria-busy="true">
          <Skeleton height={38} borderRadius={11} />
          <span>{loadingLabel}</span>
        </div>
      );
    }
    return (
      <Select
        inputId={inputId}
        className="lux-ts-add-entry__select"
        isSearchable
        isClearable={false}
        placeholder={placeholder}
        classNamePrefix="custom-select"
        isMulti={false}
        menuPlacement="auto"
        menuPosition="fixed"
        menuPortalTarget={document.body}
        menuShouldScrollIntoView={false}
        styles={this.selectMenuStyles}
        components={this.selectComponents}
        value={value}
        onChange={onChange}
        options={options}
      />
    );
  };

  render() {
    if (!this.props.show) return null;
    if (typeof document === "undefined") return null;

    const { selectedEmployee, projectsForTimesheet } = this.props;
    const typeValue =
      this.state.typeSelectionOption && this.state.typeSelectionOption.value;
    const deliverableOptions = this.getDeliverableOptions();
    const canAdd = !!(
      this.state.categorySelectionOption ||
      (this.state.projectSelectionOption &&
        (this.state.deliverableSelectionOption || deliverableOptions.length === 0))
    );
    const employeeLabel =
      (selectedEmployee && (selectedEmployee.name || selectedEmployee.empName)) || "Employee";

    const stepCount = typeValue
      ? typeValue === "project"
        ? this.state.projectSelectionOption
          ? 3
          : 2
        : 2
      : 1;
    const selectionLabel =
      (this.state.deliverableSelectionOption && this.state.deliverableSelectionOption.label) ||
      (this.state.projectSelectionOption && this.state.projectSelectionOption.label) ||
      (this.state.categorySelectionOption && this.state.categorySelectionOption.label);

    return createPortal(
      <div className="lux-ts-add-entry" role="dialog" aria-modal="true" aria-label="Add time entry">
        <button
          type="button"
          className="lux-ts-add-entry__backdrop"
          onClick={this.handleCancel}
          aria-label="Close add time entry"
        />
        <div className="lux-ts-add-entry__panel">
          <div className="lux-ts-add-entry__accent" aria-hidden="true" />
          <header className="lux-ts-add-entry__head">
            <div className="lux-ts-add-entry__head-main">
              <span className="lux-ts-add-entry__kicker">
                <i className="fe fe-plus-circle" aria-hidden="true" />
                New row
              </span>
              <h3 className="lux-ts-add-entry__title">Add time entry</h3>
              <p className="lux-ts-add-entry__sub">
                Choose what to log for <strong>{employeeLabel}</strong> this week
              </p>
              <div className="lux-ts-add-entry__progress" aria-hidden="true">
                <span className={classNames("lux-ts-add-entry__progress-dot", { "is-on": true })} />
                <span className="lux-ts-add-entry__progress-line" />
                <span
                  className={classNames("lux-ts-add-entry__progress-dot", {
                    "is-on": stepCount >= 2,
                  })}
                />
                {typeValue === "project" && (
                  <>
                    <span className="lux-ts-add-entry__progress-line" />
                    <span
                      className={classNames("lux-ts-add-entry__progress-dot", {
                        "is-on": stepCount >= 3,
                      })}
                    />
                  </>
                )}
              </div>
            </div>
            <button
              type="button"
              className="lux-ts-add-entry__close"
              onClick={this.handleCancel}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-ts-add-entry__body">
            <section
              className={classNames("lux-ts-add-entry__section", {
                "is-dimmed": !!typeValue,
              })}
            >
              <div className="lux-ts-add-entry__section-head">
                <span className="lux-ts-add-entry__step">Step 1</span>
                <h4 className="lux-ts-add-entry__section-title">What are you logging?</h4>
              </div>
              {this.renderTypeCards()}
            </section>

            {typeValue === "project" && (
              <section className="lux-ts-add-entry__section lux-ts-add-entry__section--elevate lux-ts-add-entry__section--reveal">
                <div className="lux-ts-add-entry__section-head">
                  <span className="lux-ts-add-entry__step">Step 2</span>
                  <h4 className="lux-ts-add-entry__section-title">Select project</h4>
                </div>
                <div className="lux-ts-add-entry__field lux-ts-add-entry__field--select">
                  <label className="lux-ts-add-entry__label" htmlFor="lux-ts-add-entry-project">
                    <i className="fe fe-folder" aria-hidden="true" />
                    Project
                  </label>
                  {this.renderLuxurySelect({
                    inputId: "lux-ts-add-entry-project",
                    placeholder: "Search and select a project…",
                    value: this.state.projectSelectionOption,
                    onChange: this.onChangeProjectSelection,
                    options: this.getProjectOptions(),
                    loading: !projectsForTimesheet,
                    loadingLabel: "Loading projects…",
                  })}
                </div>

                {this.state.projectSelectionOption && (
                  <div className="lux-ts-add-entry__field lux-ts-add-entry__field--select lux-ts-add-entry__field--nested">
                    <div className="lux-ts-add-entry__section-head">
                      <span className="lux-ts-add-entry__step">Step 3</span>
                      <h4 className="lux-ts-add-entry__section-title">Select deliverable</h4>
                    </div>
                    <label className="lux-ts-add-entry__label" htmlFor="lux-ts-add-entry-deliverable">
                      <i className="fe fe-flag" aria-hidden="true" />
                      Deliverable
                    </label>
                    {deliverableOptions.length > 0 ? (
                      this.renderLuxurySelect({
                        inputId: "lux-ts-add-entry-deliverable",
                        placeholder: "Search and select a deliverable…",
                        value: this.state.deliverableSelectionOption,
                        onChange: this.onChangeDeliverableSelection,
                        options: deliverableOptions,
                      })
                    ) : (
                      <div className="lux-ts-add-entry__empty">
                        <i className="fe fe-alert-circle" aria-hidden="true" />
                        <span>No deliverables available for this project.</span>
                      </div>
                    )}
                  </div>
                )}
              </section>
            )}

            {typeValue === "nonProject" && (
              <section className="lux-ts-add-entry__section lux-ts-add-entry__section--elevate lux-ts-add-entry__section--reveal">
                <div className="lux-ts-add-entry__section-head">
                  <span className="lux-ts-add-entry__step">Step 2</span>
                  <h4 className="lux-ts-add-entry__section-title">Select category</h4>
                </div>
                <div className="lux-ts-add-entry__field lux-ts-add-entry__field--select">
                  <label className="lux-ts-add-entry__label" htmlFor="lux-ts-add-entry-category">
                    <i className="fe fe-tag" aria-hidden="true" />
                    Category
                  </label>
                  {this.renderLuxurySelect({
                    inputId: "lux-ts-add-entry-category",
                    placeholder: "Leave, holiday, or non-billable category…",
                    value: this.state.categorySelectionOption,
                    onChange: this.onChangeCategorySelection,
                    options: this.getCategoryOptions(),
                    loading: !this.props.nonProjectAppConfig,
                    loadingLabel: "Loading categories…",
                  })}
                </div>
              </section>
            )}
          </div>

          <footer className="lux-ts-add-entry__foot">
            <p className="lux-ts-add-entry__foot-note">
              {canAdd ? (
                <>
                  Ready to add <strong>{selectionLabel}</strong>
                  {this.state.projectSelectionOption && this.state.deliverableSelectionOption
                    ? ` on ${this.state.projectSelectionOption.label}`
                    : ""}{" "}
                  — enter hours per day on the new grid row.
                </>
              ) : typeValue === "project" && this.state.projectSelectionOption ? (
                "Select a deliverable to continue."
              ) : (
                "Pick a type, then choose a project or category to continue."
              )}
            </p>
            <div className="lux-ts-add-entry__actions">
              <button
                type="button"
                className="lux-ts-add-entry__btn lux-ts-add-entry__btn--ghost"
                onClick={this.handleCancel}
              >
                Cancel
              </button>
              <button
                type="button"
                className="lux-ts-add-entry__btn lux-ts-add-entry__btn--primary"
                disabled={!canAdd}
                onClick={this.handleAddProjectForTimeEntry}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                Add to timesheet
              </button>
            </div>
          </footer>
        </div>
      </div>,
      document.body
    );
  }
}

const mapStateToProps = (state) => ({
  projectsForTimesheet: state.projects.projectsForTimesheet,
  nonProjectAppConfig: state.workItem.nonProjectAppConfig,
});

const mapDispatchToProps = () => ({
  getProjectList: projectActions.getProjectListForTimesheet,
  initializeNonProjectWorkItem: workItemActions.initializeNonProjectWorkItem,
});

export default connect(mapStateToProps, mapDispatchToProps)(TimesheetAddEntryModal);
