/**
 * EH22 / CFA-LEAVE-P7 — bulk leave-balance import (LeaveBalanceEngine ADJUST_HR).
 * Dry-run: pass { dryRun: true } — validates rows only (also sends ?dryRun=true).
 * Live write: { dryRun: false } or omit dryRun.
 */
async function importLeaveBalances(userTeamId, actorId, rows, options = {}) {
  const body = { rows: rows || [] };
  const dryRun = options && options.dryRun === true;
  if (dryRun) {
    body.dryRun = true;
  }
  let url = `${urlConfig.LEAVE_BALANCE_IMPORT_PATH}?userTeamId=${userTeamId}&actorId=${actorId}`;
  if (dryRun) {
    url += "&dryRun=true";
  }
  return axiosUtils.post(url, body);
}

