import React, { useMemo } from "react";
import { Link, NavLink } from "react-router-dom";
import classNames from "classnames/bind";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import { buildProjectEffortChart } from "../plannerSummary.charts";
import { formatPlannerSummaryHours } from "../plannerSummary.utils";
import { normalizeWorkItemStatus } from "../planner.utils";

const RANK_STYLES = ["gold", "silver", "bronze"];

const STATUS_CHIP_COLORS = {
  ASSIGNED: "#3b82f6",
  INPROGRESS: "#f59e0b",
  COMPLETED: "#10b981",
  CLOSED: "#64748b",
  NEW: "#0ea5e9",
  ONGOING: "#8b5cf6",
};

function enrichProjects(projects) {
  const list = projects || [];
  const totalMinutes = list.reduce((sum, p) => sum + (p.minutes || 0), 0);
  return list.map((p, index) => ({
    ...p,
    rank: index + 1,
    sharePct: totalMinutes > 0 ? Math.round((p.minutes / totalMinutes) * 100) : 0,
    hoursRounded: Math.round((p.minutes / 60) * 10) / 10,
    isNavigable: p.id !== "none" && p.id != null && p.detailsPath,
  }));
}

function StatusMix({ statuses }) {
  const entries = Object.entries(statuses || {}).sort((a, b) => b[1] - a[1]).slice(0, 3);
  if (entries.length === 0) return null;
  return (
    <div className="lux-planner-projects__statuses">
      {entries.map(([key, count]) => (
        <span
          key={key}
          className="lux-planner-projects__status-chip"
          style={{ borderColor: STATUS_CHIP_COLORS[normalizeWorkItemStatus(key)] || "#94a3b8" }}
        >
          {normalizeWorkItemStatus(key).toLowerCase()} · {count}
        </span>
      ))}
    </div>
  );
}

export default function PlannerTopProjectsPanel({ projects, isLoading, totalHorizonMinutes }) {
  const enriched = useMemo(() => enrichProjects(projects), [projects]);
  const chart = useMemo(() => buildProjectEffortChart(enriched), [enriched]);
  const totalHours = Math.round(((totalHorizonMinutes || enriched.reduce((s, p) => s + p.minutes, 0)) / 60) * 10) / 10;

  if (!isLoading && enriched.length === 0) {
    return (
      <section className="lux-planner-projects lux-planner-projects--empty">
        <div className="lux-planner-projects__head">
          <span className="lux-planner-projects__eyebrow">Portfolio focus</span>
          <h3>Top projects by planned effort</h3>
          <p>No project-tagged work in this horizon yet.</p>
        </div>
      </section>
    );
  }

  return (
    <section className="lux-planner-projects">
      <div className="lux-planner-projects__head">
        <div className="lux-planner-projects__head-main">
          <span className="lux-planner-projects__eyebrow">Portfolio focus</span>
          <h3>Top projects by planned effort</h3>
          <p>Where planned hours concentrate — use this to rebalance the team before adding new commitments.</p>
        </div>
        <div className="lux-planner-projects__head-stat">
          <span>Total planned</span>
          <strong>{isLoading ? "—" : `${totalHours}h`}</strong>
          <small>in selected horizon</small>
        </div>
      </div>

      <div className="lux-planner-projects__body">
        <div className="lux-planner-projects__chart-panel">
          <div className="lux-planner-projects__chart-label">
            <i className="fe fe-bar-chart-2" aria-hidden />
            Effort distribution
          </div>
          {isLoading ? (
            <div className="lux-planner-projects__chart-skeleton" />
          ) : (
            <DashboardApexChart {...chart} />
          )}
        </div>

        <div className="lux-planner-projects__ranked">
          <div className="lux-planner-projects__ranked-label">
            <i className="fe fe-award" aria-hidden />
            Ranked breakdown
          </div>
          <ul className="lux-planner-projects__list">
            {enriched.map((p) => (
              <li key={p.id} className="lux-planner-projects__row">
                <div
                  className={classNames("lux-planner-projects__rank", {
                    [`is-${RANK_STYLES[p.rank - 1]}`]: p.rank <= 3,
                  })}
                >
                  {p.rank <= 3 ? <i className="fe fe-award" /> : p.rank}
                </div>

                <div className="lux-planner-projects__row-main">
                  <div className="lux-planner-projects__row-top">
                    <strong className="text-truncate" title={p.name}>
                      {p.name}
                    </strong>
                    <span className="lux-planner-projects__share">{p.sharePct}%</span>
                  </div>

                  <div className="lux-planner-projects__bar-track">
                    <div
                      className="lux-planner-projects__bar-fill"
                      style={{ width: `${Math.max(p.sharePct, 4)}%` }}
                    />
                  </div>

                  <div className="lux-planner-projects__meta">
                    <span>
                      <i className="fe fe-clock" />
                      {formatPlannerSummaryHours(p.minutes)}
                    </span>
                    <span>
                      <i className="fe fe-users" />
                      {p.peopleCount} people
                    </span>
                    <span>
                      <i className="fe fe-layers" />
                      {p.items.length} items
                    </span>
                  </div>

                  <StatusMix statuses={p.statuses} />
                </div>

                <div className="lux-planner-projects__row-actions">
                  {p.isNavigable ? (
                    <NavLink
                      to={`/project/details/${p.detailsPath}`}
                      className="lux-planner-projects__open"
                    >
                      <i className="fe fe-briefcase" />
                      <span>
                        <strong>Open project</strong>
                        <small>Details &amp; deliverables</small>
                      </span>
                      <i className="fe fe-chevron-right" />
                    </NavLink>
                  ) : (
                    <div className="lux-planner-projects__open is-muted">
                      <i className="fe fe-inbox" />
                      <span>
                        <strong>Non-project work</strong>
                        <small>Internal / uncategorized</small>
                      </span>
                    </div>
                  )}
                </div>
              </li>
            ))}
          </ul>

          <div className="lux-planner-projects__foot">
            <Link to="/project/reports" className="lux-planner-projects__report-link">
              <i className="fe fe-pie-chart" />
              Resource allocation report
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}
