import React from "react";
import { Link } from "react-router-dom";
import {
  buildPayrollReadinessAiBrief,
  normalizePayrollReadinessBrief,
} from "config/payroll-readiness-ai.utils";
import {
  isPayrollReadinessAiEnabled,
  shouldUsePayrollReadinessAiApi,
} from "config/payroll-readiness-ai.config";
import { shouldFallbackToMock } from "config/mock-fallback.utils";
import { payrollService } from "_services/payroll.service";

function extractLopSummary(brief) {
  if (!brief || !Array.isArray(brief.evidence)) {
    return null;
  }
  const lopLine = brief.evidence.find((item) => /LOP|unpaid leave days/i.test(String(item)));
  if (!lopLine) {
    return null;
  }
  const match = String(lopLine).match(/([\d.]+)/);
  return {
    label: lopLine,
    days: match ? match[1] : null,
  };
}

export default class PayrollReadinessAgentPanel extends React.Component {
  state = {
    brief: null,
    loading: false,
    loadError: null,
    source: "client",
  };

  componentDidMount() {
    this.loadBrief();
  }

  componentDidUpdate(prevProps) {
    const prevRunId = prevProps.run && prevProps.run.id;
    const nextRunId = this.props.run && this.props.run.id;
    const prevCount = (prevProps.exceptions || []).length;
    const nextCount = (this.props.exceptions || []).length;
    if (prevRunId !== nextRunId || prevCount !== nextCount) {
      this.loadBrief();
    }
  }

  loadBrief = async () => {
    const { run, exceptions } = this.props;
    if (!run || !isPayrollReadinessAiEnabled()) {
      return;
    }

    this.setState({ loading: true, loadError: null });
    try {
      if (shouldUsePayrollReadinessAiApi() && run.id) {
        const result = await payrollService.getReadinessBrief(run.id, run, exceptions);
        if (result.source === "api-error") {
          this.setState({
            brief: null,
            loading: false,
            source: "api-error",
            loadError: "Unable to load readiness brief.",
          });
          return;
        }
        if (result.payload) {
          this.setState({
            brief: result.payload,
            loading: false,
            source: result.source || "api",
            loadError: null,
          });
          return;
        }
        if (!shouldFallbackToMock()) {
          this.setState({
            brief: null,
            loading: false,
            source: "api-error",
            loadError: "Unable to load readiness brief.",
          });
          return;
        }
      }
      if (!shouldFallbackToMock() && shouldUsePayrollReadinessAiApi()) {
        this.setState({
          brief: null,
          loading: false,
          source: "api-error",
          loadError: "Unable to load readiness brief.",
        });
        return;
      }
      const draft = buildPayrollReadinessAiBrief(run, exceptions, { source: "client" });
      this.setState({
        brief: normalizePayrollReadinessBrief(draft),
        loading: false,
        source: "client",
        loadError: null,
      });
    } catch (e) {
      if (!shouldFallbackToMock()) {
        this.setState({
          brief: null,
          loading: false,
          loadError: "Unable to load readiness brief.",
          source: "api-error",
        });
        return;
      }
      const draft = buildPayrollReadinessAiBrief(run, exceptions, { source: "client" });
      this.setState({
        brief: normalizePayrollReadinessBrief(draft),
        loading: false,
        loadError: null,
        source: "client",
      });
    }
  };

  renderInsightList(title, icon, items, tone) {
    if (!items || items.length === 0) {
      return null;
    }
    return (
      <section className={`lux-payroll-ai-panel__section lux-payroll-ai-panel__section--${tone}`}>
        <h4 className="lux-payroll-ai-panel__section-title">
          <i className={`fe ${icon}`} aria-hidden="true" /> {title}
        </h4>
        <ul className="lux-payroll-ai-panel__list lux-payroll-ai-panel__list--rich">
          {items.map((item) => (
            <li key={item.id}>
              <strong>{item.message}</strong>
              {item.employeeName ? <span className="lux-payroll-ai-panel__chip">{item.employeeName}</span> : null}
              <small>{item.fixHint}</small>
            </li>
          ))}
        </ul>
      </section>
    );
  }

  render() {
    if (!isPayrollReadinessAiEnabled()) {
      return null;
    }

    const { loading, loadError, brief, source } = this.state;
    if (loading && !brief) {
      return (
        <div className="lux-payroll-ai-panel lux-payroll-ai-panel--loading" aria-busy="true">
          <p className="lux-payroll-ai-panel__headline">Generating readiness brief…</p>
        </div>
      );
    }
    if (!brief) {
      if (source === "api-error" || loadError) {
        return (
          <div className="lux-payroll-ai-panel" aria-label="Payroll readiness assistant">
            <p className="lux-payroll-ai-panel__headline">Readiness brief unavailable</p>
            <p className="lux-payroll-ai-panel__note">{loadError || "Unable to load readiness brief."}</p>
          </div>
        );
      }
      return null;
    }

    const confidencePct = Math.round((brief.confidence || 0) * 100);
    const lopSummary = extractLopSummary(brief);

    return (
      <div className="lux-payroll-ai-panel" aria-label="Payroll readiness assistant">
        <p className="lux-payroll-ai-panel__headline">{brief.headline}</p>
        <p className="lux-payroll-ai-panel__summary">{brief.summary}</p>

        <div className="lux-payroll-ai-panel__meta">
          <span className="lux-payroll-ai-panel__confidence">Confidence {confidencePct}%</span>
          <span className="lux-payroll-ai-panel__badge">
            {source === "api"
              ? "Live"
              : source === "mock"
                ? "Demo"
                : "Unavailable"}
          </span>
        </div>

        {lopSummary ? (
          <section className="lux-payroll-ai-panel__section lux-payroll-ai-panel__section--warning" data-testid="eh04-lop-summary">
            <h4 className="lux-payroll-ai-panel__section-title">
              <i className="fe fe-calendar" aria-hidden="true" /> LOP / unpaid leave
            </h4>
            <p className="lux-payroll-ai-panel__note">{lopSummary.label}</p>
            <p className="lux-payroll-ai-panel__action">
              <Link to="/people/leaves">Open leave payroll extract</Link>
              {" "}to review unpaid leave before calculate.
            </p>
          </section>
        ) : null}

        {brief.nextBestAction ? (
          <p className="lux-payroll-ai-panel__action">{brief.nextBestAction}</p>
        ) : null}

        {this.renderInsightList("Blockers", "fe-alert-triangle", brief.blockers, "blocker")}
        {this.renderInsightList("Warnings", "fe-alert-circle", brief.warnings, "warning")}

        <section className="lux-payroll-ai-panel__section">
          <h4 className="lux-payroll-ai-panel__section-title">
            <i className="fe fe-check-square" aria-hidden="true" /> Suggested checks
          </h4>
          <ul className="lux-payroll-ai-panel__list lux-payroll-ai-panel__list--rich">
            {(brief.suggestions || []).map((item) => (
              <li key={item.id}>
                <strong>{item.title}</strong>
                <small>{item.detail}</small>
              </li>
            ))}
          </ul>
        </section>

        {(brief.evidence || []).length > 0 && (
          <section className="lux-payroll-ai-panel__section lux-payroll-ai-panel__section--evidence">
            <h4 className="lux-payroll-ai-panel__section-title">
              <i className="fe fe-layers" aria-hidden="true" /> Evidence
            </h4>
            <ul className="lux-payroll-ai-panel__evidence">
              {brief.evidence.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>
          </section>
        )}

        <footer className="lux-payroll-ai-panel__foot">
          <span className="lux-payroll-ai-panel__eyebrow">
            {source === "api" ? "Live" : source === "mock" ? "Demo" : "Unavailable"}
          </span>
          {loadError ? <p className="lux-payroll-ai-panel__note">{loadError}</p> : null}
          <p className="lux-payroll-ai-panel__note">{brief.disclaimer}</p>
        </footer>
      </div>
    );
  }
}
