import React from "react";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getLuxInlineAlertProps } from "_helpers/apiError.utils";

/**
 * Admin module load/error alert — mirrors FinanceLoadAlert.
 */
export default function AdminLoadAlert({ error, fallback, onDismiss, tone, className, testId }) {
  if (!error) {
    return null;
  }
  const alertProps = getLuxInlineAlertProps(error, fallback);
  return (
    <LuxInlineAlert
      {...alertProps}
      tone={tone || alertProps.tone}
      className={className}
      testId={testId}
      onDismiss={onDismiss}
    />
  );
}
