import React from "react";
import classNames from "classnames";
import { Link } from "react-router-dom";
import DataSourceIndicator from "views/common/fragments/DataSourceIndicator";
import LuxHeaderDropdownPanel, {
  LuxHeaderDropdownEmpty,
  LuxHeaderDropdownItem,
} from "views/common/fragments/LuxHeaderDropdownPanel";
import {
  HEADER_HEALTH_ISSUE_LIMIT,
  SETTINGS_HEALTH_PATH,
  getServiceIssueHint,
} from "views/hrms/components/settings/settingsTab.utils";

function issueKindLabel(kind) {
  return kind === "server" ? "Server" : "Integration";
}

function pulseSubtitle(pulse, hasIssues) {
  if (!hasIssues) {
    const total = pulse.total || 0;
    return total > 0
      ? `${total} monitored ${total === 1 ? "endpoint" : "endpoints"} reporting healthy`
      : "No integration issues reported";
  }
  const parts = [];
  if (pulse.integrationDownCount > 0) {
    parts.push(
      `${pulse.integrationDownCount} integration${pulse.integrationDownCount === 1 ? "" : "s"}`
    );
  }
  if (pulse.serverDownCount > 0) {
    parts.push(`${pulse.serverDownCount} server${pulse.serverDownCount === 1 ? "" : "s"}`);
  }
  return `${parts.join(" and ")} need attention`;
}

export default function HeaderHealthPulse({ dataSource, pulse, onNavigate }) {
  const hasPulse = Boolean(pulse && pulse.ready);
  const hasIssues = hasPulse && pulse.downCount > 0;
  const source = dataSource || (hasPulse ? "api" : null);

  if (!hasPulse) {
    return <DataSourceIndicator dataSource={source} className="lux-header__live-dot" />;
  }

  const visibleIssues = (pulse.issues || []).slice(0, HEADER_HEALTH_ISSUE_LIMIT);
  const extraCount = Math.max(0, (pulse.issues || []).length - visibleIssues.length);
  const goToHealth = onNavigate ? onNavigate(SETTINGS_HEALTH_PATH) : undefined;

  return (
    <div
      className={classNames("dropdown", "lux-header-dropdown-wrap", "lux-header__live-pulse", {
        "is-down": hasIssues,
      })}
    >
      <button
        type="button"
        className="lux-header__live-pulse-btn"
        data-toggle="dropdown"
        aria-haspopup="true"
        aria-expanded="false"
        aria-label={hasIssues ? pulseSubtitle(pulse, true) : "All monitored services operational"}
        title={hasIssues ? pulseSubtitle(pulse, true) : "Connected to live API"}
        data-testid="header-live-pulse"
        data-ga-action="header_health_pulse"
        data-ga-category="navigation"
        data-ga-label={hasIssues ? "Service issues" : "Service health"}
      >
        <DataSourceIndicator
          dataSource={source}
          healthStatus={hasIssues ? "down" : "live"}
          decorative
          className="lux-header__live-dot"
          title={hasIssues ? pulseSubtitle(pulse, true) : "Connected to live API"}
        />
      </button>
      <LuxHeaderDropdownPanel
        icon={hasIssues ? "fe fe-alert-triangle" : "fe fe-check-circle"}
        eyebrow="Platform status"
        title={hasIssues ? "Services need attention" : "All systems operational"}
        subtitle={pulseSubtitle(pulse, hasIssues)}
        tone={hasIssues ? "health-down" : "health"}
        footer={
          <Link
            to={SETTINGS_HEALTH_PATH}
            className={classNames("lux-header-dropdown__foot-link", hasIssues && "is-urgent")}
            onClick={goToHealth}
            data-ga-action="header_open_service_health"
            data-ga-category="navigation"
            data-ga-label="Service health"
          >
            Open service health
          </Link>
        }
      >
        {hasIssues ? (
          <>
            {visibleIssues.map((issue) => (
              <LuxHeaderDropdownItem
                key={issue.id}
                as={Link}
                to={SETTINGS_HEALTH_PATH}
                onClick={goToHealth}
                icon={issue.kind === "server" ? "fe fe-server" : "fe fe-link"}
                iconTone="rose"
                title={issue.name}
                hint={`${issueKindLabel(issue.kind)} · ${getServiceIssueHint(issue)}`}
                data-ga-action="header_health_issue_open"
                data-ga-category="navigation"
                data-ga-label={issue.name}
              />
            ))}
            {extraCount > 0 ? (
              <p className="lux-header-health__more">
                +{extraCount} more in Service health
              </p>
            ) : null}
          </>
        ) : (
          <LuxHeaderDropdownEmpty
            icon="fe fe-check-circle"
            title="Integrations are healthy"
            hint="The live-dot stays green while monitored endpoints report UP."
          />
        )}
      </LuxHeaderDropdownPanel>
    </div>
  );
}
