import React, { Component } from "react";
import { Link, withRouter } from "react-router-dom";
import classNames from "classnames";
import { store } from "_helpers";
import { userActions } from "_actions";
import { connect } from "react-redux";
import { itemAdditionalActions } from "_actions";
import { itemAdditionalConstants } from "_constants";
import { history } from "_helpers";
import { commonUtils } from "_helpers";
import { userUtils } from "_helpers";
import envconfig from "env.config";
import { resolveSidebarModuleLabel } from "config/sidebar-menu.config";
import { getEmployeeDetailsPathname } from "views/hrms/profileDetailsNavigation.utils";
import PersonaSwitcher from "components/persona/PersonaSwitcher";
import ScopeBadge from "components/persona/ScopeBadge";
import { MicrosoftLoginoutSection } from "views/user/components/MicrosoftLogoutSection";
import LuxHeaderDropdownPanel, {
    LuxHeaderDropdownEmpty,
    LuxHeaderDropdownItem,
    LuxHeaderDropdownQueueItem,
} from "views/common/fragments/LuxHeaderDropdownPanel";
import HeaderHealthPulse from "views/common/fragments/HeaderHealthPulse";
import {
  HEADER_NOTIFICATION_POPOVER_LIMIT,
  HEADER_WORK_POPOVER_LIMIT,
  buildHeaderNotificationBadge,
  buildHeaderWorkBadge,
  mapMyWorkToHeaderItem,
  mapNotificationToHeaderItem,
  sortMyWorkForHeader,
  sortNotificationsForHeader,
} from "config/headerWorkspace.utils";
import {
  loadHeaderPopoverData,
  isSyntheticHeaderNotification,
  readDismissedHeaderNotificationIds,
  applyHeaderNotificationDismissals,
  markAllHeaderNotificationsRead,
  dismissHeaderNotification,
} from "_services/headerWorkspace.service";
import { workspaceService } from "_services/workspace.service";
import "views/common/headerWorkspace.css";
import {
  isOffcanvasNavOpen,
  LUX_OFFCANVAS_CHANGED,
  toggleOffcanvasNav,
} from "_helpers/luxPhone.utils";

const HEADER_POLL_MS = 60000;

class PageHeader extends Component {
    constructor() {
        super();
        this.state = {
            searchText: "",
            workItems: [],
            notifications: [],
            dismissedHeaderNotificationIds: readDismissedHeaderNotificationIds(),
            headerLoading: false,
            headerActing: false,
            headerLoadError: null,
            navOpen: false,
        };
        this._headerPollTimer = null;
    }

    componentDidMount() {
        this.loadHeaderWorkspace();
        this._headerPollTimer = window.setInterval(this.loadHeaderWorkspace, HEADER_POLL_MS);
        this.syncNavOpen = (event) => {
            const open =
                event && event.detail && typeof event.detail.open === "boolean"
                    ? event.detail.open
                    : isOffcanvasNavOpen();
            this.setState({ navOpen: open });
        };
        this.setState({ navOpen: isOffcanvasNavOpen() });
        window.addEventListener(LUX_OFFCANVAS_CHANGED, this.syncNavOpen);
    }

    componentWillUnmount() {
        if (this._headerPollTimer) {
            window.clearInterval(this._headerPollTimer);
        }
        if (this.syncNavOpen) {
            window.removeEventListener(LUX_OFFCANVAS_CHANGED, this.syncNavOpen);
        }
    }

    componentDidUpdate(prevProps) {
        if (
            prevProps.searchText !== this.props.searchText &&
            this.props.searchText !== this.state.searchText
        ) {
            this.setState({ searchText: this.props.searchText || "" });
        }
    }

    loadHeaderWorkspace = async () => {
        this.setState({ headerLoading: true, headerLoadError: null });
        try {
            const result = await loadHeaderPopoverData();
            const dismissedIds =
                this.state.dismissedHeaderNotificationIds.size > 0
                    ? this.state.dismissedHeaderNotificationIds
                    : readDismissedHeaderNotificationIds();
            this.setState({
                headerLoading: false,
                workItems: result.workItems,
                notifications: applyHeaderNotificationDismissals(result.notifications, dismissedIds),
                dismissedHeaderNotificationIds: dismissedIds,
                headerLoadError:
                    result.workItems.length === 0 &&
                    result.notifications.length === 0 &&
                    result.workspaceApiBlocked &&
                    result.pendingApprovals.length === 0
                        ? "Workspace queue is disabled for this org. Enable My Work / Notifications in Application Config, or open Approvals."
                        : null,
            });
        } catch (error) {
            this.setState({
                headerLoading: false,
                headerLoadError: (error && error.message) || "Unable to load workspace header data",
                workItems: [],
                notifications: [],
            });
        }
    };

    handleMarkAllNotificationsRead = async (event) => {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }
        const { notifications, dismissedHeaderNotificationIds } = this.state;
        const persistableUnread = notifications.filter(
            (row) => row.status === "UNREAD" && !isSyntheticHeaderNotification(row)
        );

        this.setState({ headerActing: true, headerLoadError: null });
        try {
            if (persistableUnread.length) {
                try {
                    await workspaceService.markAllNotificationsRead();
                } catch (_error) {
                    // Fall back to local dismiss when workspace notifications API is unavailable.
                }
            }
            const result = markAllHeaderNotificationsRead(notifications, dismissedHeaderNotificationIds);
            this.setState({
                notifications: result.notifications,
                dismissedHeaderNotificationIds: result.dismissedIds,
            });
        } catch (error) {
            this.setState({
                headerLoadError: (error && error.message) || "Unable to mark notifications as read",
            });
        } finally {
            this.setState({ headerActing: false });
        }
    };

    handleNotificationOpen = (row) => async () => {
        if (!row || row.status !== "UNREAD") {
            return;
        }
        if (isSyntheticHeaderNotification(row)) {
            this.setState((prev) => {
                const result = dismissHeaderNotification(
                    prev.notifications,
                    prev.dismissedHeaderNotificationIds,
                    row.id
                );
                return {
                    notifications: result.notifications,
                    dismissedHeaderNotificationIds: result.dismissedIds,
                };
            });
            return;
        }
        try {
            await workspaceService.markNotificationRead(row.id);
            this.setState((prev) => {
                const result = dismissHeaderNotification(
                    prev.notifications,
                    prev.dismissedHeaderNotificationIds,
                    row.id
                );
                return {
                    notifications: result.notifications,
                    dismissedHeaderNotificationIds: result.dismissedIds,
                };
            });
        } catch (error) {
            // Navigation still proceeds.
        }
    };

    closeHeaderDropdown = (event) => {
        const root =
            event && event.currentTarget
                ? event.currentTarget.closest(".lux-header-dropdown-wrap")
                : null;
        if (!root) {
            return;
        }
        root.classList.remove("show");
        const menu = root.querySelector(".dropdown-menu");
        if (menu) {
            menu.classList.remove("show");
        }
        const toggle = root.querySelector("[data-toggle='dropdown']");
        if (toggle) {
            toggle.setAttribute("aria-expanded", "false");
        }
    };

    handleHeaderPopoverNavigate = (path, onNavigate) => (event) => {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }
        this.closeHeaderDropdown(event);
        if (onNavigate) {
            onNavigate();
        }
        history.push(path);
    };

    handleLogout = (e) => {
        e.preventDefault();
        store.dispatch(this.props.logout());
    }

    onSearchTextChange = (searchText) => {
        this.setState({
            searchText: searchText
        })
    }

    runHeaderSearch = () => {
        const query = (this.state.searchText || "").trim();
        if (!query) return;
        this.props.onSearchInputChange(query);
        this.props.getSearchResults(query);
        history.push("/project/search");
    };

    search = (event) => {
        if (event.key === "Enter") {
            event.preventDefault();
            this.runHeaderSearch();
        }
    };

    getWorkspaceKicker = () => {
        const path = (this.props.location && this.props.location.pathname) || history.location.pathname;
        const moduleLabel = resolveSidebarModuleLabel(path);
        if (moduleLabel) {
            return `${moduleLabel} Workspace`;
        }
        return `${envconfig.APP_NAME || "Tracopus"} Workspace`;
    }

    renderIconMenuTrigger = ({ label, icon, badgeCount = 0, urgent = false, disabled = false, gaAction }) => {
        const showBadge = badgeCount > 0;
        const badgeTone = urgent ? "danger" : label === "Tasks" ? "success" : "primary";

        return (
            <button
                type="button"
                disabled={disabled}
                className="lux-header__icon-btn lux-header__icon-btn--menu"
                data-toggle="dropdown"
                aria-haspopup="true"
                aria-expanded="false"
                aria-label={showBadge ? `${label}, ${badgeCount} open` : label}
                data-ga-action={gaAction}
                data-ga-category="navigation"
                data-ga-label={label}
            >
                <span className="lux-header__icon-btn-shell" aria-hidden="true">
                    <i className={icon} />
                </span>
                {showBadge ? (
                    <span
                        className={classNames("lux-header__icon-badge", "has-count", `is-${badgeTone}`)}
                        aria-hidden="true"
                    >
                        {badgeCount > 9 ? "9+" : badgeCount}
                    </span>
                ) : null}
            </button>
        );
    };

    renderTasksDropdownBody = () => {
        const { workItems, headerLoading, headerLoadError } = this.state;
        const openItems = sortMyWorkForHeader(workItems)
            .slice(0, HEADER_WORK_POPOVER_LIMIT)
            .map(mapMyWorkToHeaderItem);

        if (headerLoading && openItems.length === 0) {
            return (
                <LuxHeaderDropdownEmpty
                    icon="fe fe-loader"
                    title="Loading tasks"
                    hint="Fetching your work queue…"
                />
            );
        }

        if (headerLoadError && openItems.length === 0) {
            return (
                <LuxHeaderDropdownEmpty
                    icon="fe fe-alert-circle"
                    title="Tasks unavailable"
                    hint={headerLoadError}
                />
            );
        }

        if (openItems.length === 0) {
            return (
                <LuxHeaderDropdownEmpty
                    icon="fe fe-check-circle"
                    title="All caught up"
                    hint="No open tasks in your queue"
                />
            );
        }

        return openItems.map((item) => (
            <LuxHeaderDropdownQueueItem
                key={item.id}
                as={Link}
                to={item.path}
                onClick={this.handleHeaderPopoverNavigate(item.path)}
                icon={item.icon}
                iconTone={item.iconTone}
                title={item.title}
                hint={item.hint}
                meta={item.meta}
                urgent={item.urgent}
                badge={item.isApproval ? "Approval" : item.urgent ? "High" : null}
                data-ga-action="header_task_open"
                data-ga-category="navigation"
                data-ga-label={item.title}
            />
        ));
    };

    renderNotificationsDropdownBody = () => {
        const { notifications, headerLoading, headerLoadError } = this.state;
        const unreadItems = sortNotificationsForHeader(notifications)
            .slice(0, HEADER_NOTIFICATION_POPOVER_LIMIT)
            .map(mapNotificationToHeaderItem);

        if (headerLoading && unreadItems.length === 0) {
            return (
                <LuxHeaderDropdownEmpty
                    icon="fe fe-loader"
                    title="Loading notifications"
                    hint="Fetching alerts…"
                />
            );
        }

        if (headerLoadError && unreadItems.length === 0) {
            return (
                <LuxHeaderDropdownEmpty
                    icon="fe fe-alert-circle"
                    title="Notifications unavailable"
                    hint={headerLoadError}
                />
            );
        }

        if (unreadItems.length === 0) {
            return (
                <LuxHeaderDropdownEmpty
                    icon="fe fe-bell-off"
                    title="You're up to date"
                    hint="System alerts and mentions show up here"
                />
            );
        }

        return unreadItems.map((item) => (
            <LuxHeaderDropdownQueueItem
                key={item.id}
                as={Link}
                to={item.path}
                onClick={this.handleHeaderPopoverNavigate(item.path, () => {
                    this.handleNotificationOpen(item.raw)();
                })}
                icon={item.icon}
                iconTone={item.iconTone}
                title={item.title}
                hint={item.hint}
                meta={item.meta}
                urgent={item.urgent}
                badge={item.isApproval ? "Approval" : item.urgent ? "Urgent" : null}
                data-ga-action="header_notification_open"
                data-ga-category="navigation"
                data-ga-label={item.title}
            />
        ));
    };

    render() {
        const userName = userUtils.getCurrentUserName() || "Account";
        const userEmail = userUtils.getCurrentUserEmail();
        const { workItems, notifications, headerActing } = this.state;
        const workBadge = buildHeaderWorkBadge(workItems);
        const notificationBadge = buildHeaderNotificationBadge(notifications);
        const unreadNotificationCount = notificationBadge.count;

        return (
            <div id="page_top" className="section-body sticky-top no-print lux-header-bar" data-tour="lux-header">
                <div className="container-fluid">
                    <div className="page-header">
                        <div className="lux-header__left">
                            <button
                                type="button"
                                className="link nav-link icon lux-header__menu-btn"
                                aria-label="Open navigation menu"
                                aria-expanded={this.state.navOpen ? "true" : "false"}
                                aria-controls="left-sidebar"
                                data-testid="lux-header-menu"
                                data-ga-action="header_menu_toggle"
                                data-ga-category="navigation"
                                data-ga-label="Menu toggle"
                                onClick={() => this.setState({ navOpen: toggleOffcanvasNav() })}
                            >
                                <i className="fe fe-menu" aria-hidden="true" />
                            </button>
                            <div className="lux-header__titles">
                                <div className="lux-header__kicker-row">
                                    <span className="lux-header__kicker">{this.getWorkspaceKicker()}</span>
                                    <PersonaSwitcher className="lux-header__persona-switcher" />
                                    <ScopeBadge className="lux-header__scope-badge xs-hide" />
                                </div>
                                <h1 className="page-title">{this.props.pageName}</h1>
                            </div>
                            <button type="button" id="header-grid-view-tab" className={this.props.showHeaderViewActions ? 'link grid-view-link active d-block d-sm-none ' : 'd-none'} data-toggle="tab" href="#Grid-View" aria-label="Grid view" data-ga-action="header_grid_view" data-ga-category="navigation" data-ga-label="Grid view"><i className="fe fe-grid mr-0 fa-lg" aria-hidden="true" /></button>
                            <button type="button" id="header-list-view-tab" className={this.props.showHeaderViewActions ? 'link list-view-link d-block d-sm-none' : 'd-none'} data-toggle="tab" href="#List-View" aria-label="List view" data-ga-action="header_list_view" data-ga-category="navigation" data-ga-label="List view"><i className="fe fe-list mr-0 fa-lg" aria-hidden="true" /></button>
                            <button type="button" className={this.props.showHeaderCreateActions ? 'link create-link d-block d-sm-none ' : 'd-none'} aria-label="Create" data-ga-action="header_create" data-ga-category="engagement" data-ga-label="Create"><i className="fe fe-plus-circle fa-lg" aria-hidden="true" /></button>
                        </div>
                        <div className="lux-header__actions">
                            <HeaderHealthPulse
                                dataSource={this.props.pageDataSource}
                                pulse={this.props.pageHealthPulse}
                                onNavigate={this.handleHeaderPopoverNavigate}
                            />
                            <button
                                type="button"
                                className="lux-header__icon-btn xs-hide fullscreen_btn"
                                data-ga-action="header_fullscreen"
                                data-ga-category="engagement"
                                data-ga-label="Fullscreen"
                                aria-label="Toggle fullscreen"
                                title="Toggle fullscreen"
                            >
                                <span className="lux-header__icon-btn-shell" aria-hidden="true">
                                    <i className="fe fe-maximize" />
                                </span>
                            </button>

                            <div className="input-icon xs-hide">
                                <span className="input-icon-addon" aria-hidden="true">
                                    <i className="fe fe-search"></i>
                                </span>
                                <input autoComplete="off" type="search" value={this.state.searchText || ''} className="form-control search" placeholder="Search tasks, projects, people..." aria-label="Search tasks, projects, and people" onChange={(e) => this.onSearchTextChange(e.target.value)} onKeyDown={(e) => this.search(e)} />
                            </div>
                            <div className="headernotification lux-header__dropdowns d-flex">
                                <div className="dropdown lux-header-dropdown-wrap">
                                    {this.renderIconMenuTrigger({
                                        label: "Tasks",
                                        icon: "fe fe-check-square",
                                        badgeCount: workBadge.count,
                                        urgent: workBadge.urgent,
                                        gaAction: "header_tasks_dropdown",
                                    })}
                                    <LuxHeaderDropdownPanel
                                        icon="fe fe-check-square"
                                        eyebrow="Workspace"
                                        title="My work queue"
                                        tone="tasks"
                                        footer={
                                            <>
                                                {workBadge.approvalCount > 0 ? (
                                                    <Link
                                                        to="/workspace/approvals"
                                                        className="lux-header-dropdown__foot-link is-urgent"
                                                        onClick={this.handleHeaderPopoverNavigate("/workspace/approvals")}
                                                        data-ga-action="header_open_approvals"
                                                        data-ga-category="navigation"
                                                        data-ga-label="Approvals from tasks menu"
                                                    >
                                                        {workBadge.approvalCount} approval{workBadge.approvalCount === 1 ? "" : "s"} need action
                                                    </Link>
                                                ) : null}
                                                <Link
                                                    to="/workspace/my-work"
                                                    className="lux-header-dropdown__foot-link"
                                                    data-ga-action="header_open_my_work"
                                                    data-ga-category="navigation"
                                                    data-ga-label="View all tasks"
                                                >
                                                    View all tasks
                                                </Link>
                                            </>
                                        }
                                    >
                                        {this.renderTasksDropdownBody()}
                                    </LuxHeaderDropdownPanel>
                                </div>

                                <div className="dropdown lux-header-dropdown-wrap">
                                    {this.renderIconMenuTrigger({
                                        label: "Notifications",
                                        icon: "fe fe-bell",
                                        badgeCount: notificationBadge.count,
                                        urgent: notificationBadge.urgent,
                                        gaAction: "header_notifications_dropdown",
                                    })}
                                    <LuxHeaderDropdownPanel
                                        icon="fe fe-bell"
                                        eyebrow="Alerts"
                                        title="Notifications"
                                        tone="notifications"
                                        widthClass="lux-header-dropdown--wide"
                                        footer={
                                            <>
                                                <button
                                                    type="button"
                                                    className="lux-header-dropdown__foot-action"
                                                    disabled={headerActing || unreadNotificationCount === 0}
                                                    onClick={this.handleMarkAllNotificationsRead}
                                                    data-ga-action="header_mark_all_read"
                                                    data-ga-category="engagement"
                                                    data-ga-label="Notifications"
                                                >
                                                    Mark all as read
                                                </button>
                                                <Link
                                                    to="/workspace/notifications"
                                                    className="lux-header-dropdown__foot-link"
                                                    data-ga-action="header_open_notifications"
                                                    data-ga-category="navigation"
                                                    data-ga-label="View all notifications"
                                                >
                                                    View all notifications
                                                </Link>
                                            </>
                                        }
                                    >
                                        {this.renderNotificationsDropdownBody()}
                                    </LuxHeaderDropdownPanel>
                                </div>

                                <div className="dropdown lux-header-dropdown-wrap">
                                    {this.renderIconMenuTrigger({
                                        label: "User menu",
                                        icon: "fe fe-user",
                                        badgeCount: 0,
                                        gaAction: "header_user_dropdown",
                                    })}
                                    <LuxHeaderDropdownPanel
                                        icon="fe fe-user"
                                        eyebrow="Signed in"
                                        title={userName}
                                        subtitle={userEmail}
                                        tone="account"
                                        widthClass="lux-header-dropdown--account"
                                    >
                                        <span className="lux-header-dropdown__section-label">Account</span>
                                        <LuxHeaderDropdownItem
                                            as={Link}
                                            to={getEmployeeDetailsPathname(commonUtils.getCurrentUserId())}
                                            icon="fe fe-user"
                                            title="Profile"
                                            hint="View your profile and preferences"
                                            data-ga-action="header_profile"
                                            data-ga-category="navigation"
                                            data-ga-label="Profile"
                                        />
                                        <LuxHeaderDropdownItem
                                            as={Link}
                                            to="/people/settings"
                                            icon="fe fe-settings"
                                            title="Settings"
                                            hint="Workspace configuration"
                                            data-ga-action="header_settings"
                                            data-ga-category="navigation"
                                            data-ga-label="Settings"
                                        />
                                        <span className="lux-header-dropdown__divider" aria-hidden="true" />
                                        {userUtils.getLoginType() === 'MS' ?
                                            <MicrosoftLoginoutSection /> :
                                            <LuxHeaderDropdownItem
                                                icon="fe fe-log-out"
                                                iconTone="danger"
                                                title="Sign out"
                                                hint="End your current session"
                                                onClick={this.handleLogout}
                                                data-ga-action="logout"
                                                data-ga-category="auth"
                                                data-ga-label="Sign out"
                                            />
                                        }
                                    </LuxHeaderDropdownPanel>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div >
        );
    }
}
const mapStateToProps = state => ({
    authentication: state.authentication,
    searchText: state.itemAdditional.searchText,
    searchResults: state.itemAdditional.searchResults
});

const mapDispatchToProps = dispatch => ({
    logout: userActions.logout,
    getSearchResults: (searchText) => dispatch(itemAdditionalActions.getSearchResults(searchText)),
    onSearchInputChange: (searchText) =>
        dispatch({ type: itemAdditionalConstants.SEARCH_INPUT_CHANGE, searchText }),
});

export default withRouter(
    connect(
        mapStateToProps,
        mapDispatchToProps
    )(PageHeader)
);
