import React from "react";
import { shouldFallbackToMock } from "config/mock-fallback.utils";
import { WorkGraphLuxPanel } from "views/workgraph/components/WorkGraphLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function resolveMeta(source) {
  if (source === "api") {
    return "Live AI context";
  }
  if (source === "local-rules") {
    return "Graph rules · from loaded relationships";
  }
  if (source === "mock" || shouldFallbackToMock()) {
    return "Preview mode";
  }
  return "Node intelligence";
}

/**
 * Prefer live `/work-graph/nodes/{id}/ai-context`.
 * When API is down, pages may pass `local-rules` context built from the loaded graph.
 * Never label customer UI as "stub".
 */
export default function WorkGraphAiPanel({
  context,
  loading,
  source,
  hasSelection = false,
}) {
  if (loading) {
    return (
      <WorkGraphLuxPanel
        title="Node intelligence"
        meta="Loading"
        icon="fe fe-cpu"
        accent="violet"
      >
        <div className="lux-wg-skeleton lux-wg-skeleton--panel" />
      </WorkGraphLuxPanel>
    );
  }

  if (!context) {
    if (!hasSelection) {
      return null;
    }
    return (
      <WorkGraphLuxPanel
        title="Node intelligence"
        meta="Unavailable"
        icon="fe fe-cpu"
        accent="violet"
      >
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          variant="default"
          title="Intelligence unavailable"
          description="Live AI context could not be loaded for this node. Relationship data on the left still comes from the Work Graph index."
          hints={[
            "Retry by selecting the node again",
            "Export CSV still works from the page toolbar",
          ]}
          showCreate={false}
        />
      </WorkGraphLuxPanel>
    );
  }

  if (source !== "api" && source !== "local-rules" && !shouldFallbackToMock()) {
    return null;
  }

  const suggestions = context.suggestions || [];
  const meta = resolveMeta(source);

  return (
    <WorkGraphLuxPanel title="Node intelligence" meta={meta} icon="fe fe-cpu" accent="violet">
      <p className="lux-wg-ai-summary">{context.summary}</p>
      {suggestions.length > 0 ? (
        <ul className="lux-wg-ai-list">
          {suggestions.map((line, index) => (
            <li key={String(index)}>{line}</li>
          ))}
        </ul>
      ) : null}
    </WorkGraphLuxPanel>
  );
}
