import React from "react";
import classNames from "classnames/bind";

const ITEM_TONE = {
  COMPLETE: "green",
  PASSED: "green",
  IN_PROGRESS: "blue",
  PLANNED: "slate",
  AT_RISK: "amber",
  BLOCKED: "rose",
  FAILED: "rose",
};

export default function PortfolioRoadmapPanel({ roadmaps = [], loading }) {
  if (loading) {
    return <div className="lux-portfolio-roadmap__loading">Loading program roadmaps…</div>;
  }

  if (!roadmaps.length) {
    return <div className="lux-portfolio-roadmap__empty">No roadmap lanes available for linked programs.</div>;
  }

  return (
    <div className="lux-portfolio-roadmap">
      {roadmaps.map((program) => (
        <article key={program.programId} className="lux-portfolio-roadmap__program">
          <header>
            <strong>{program.programName}</strong>
            <span>Phase · {program.roadmapPhase || "Deliver"}</span>
          </header>
          <div className="lux-portfolio-roadmap__lanes">
            {(program.lanes || []).map((lane) => (
              <div key={`${program.programId}-${lane.phase}`} className="lux-portfolio-roadmap__lane">
                <span className="lux-portfolio-roadmap__phase">{lane.phase}</span>
                <div className="lux-portfolio-roadmap__items">
                  {(lane.items || []).length ? (
                    lane.items.map((item) => (
                      <div
                        key={item.id}
                        className={classNames("lux-portfolio-roadmap__item", `is-${ITEM_TONE[item.status] || "slate"}`)}
                      >
                        <span className="lux-portfolio-roadmap__item-type">{item.type}</span>
                        <strong>{item.label}</strong>
                        <small>
                          {item.projectName ? `${item.projectName} · ` : ""}
                          {item.date || "TBD"}
                        </small>
                      </div>
                    ))
                  ) : (
                    <span className="lux-portfolio-roadmap__lane-empty">—</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </article>
      ))}
    </div>
  );
}
