import {
  TICKET_CATEGORIES,
  TICKET_PRIORITIES,
  TICKET_SLA_STATUSES,
  TICKET_STATUSES,
} from "config/ticket-management.config";

export function normalizeTicket(row) {
  if (!row) {
    return null;
  }
  const statusRaw = String(row.status || "").toLowerCase().replace(/\s+/g, "_");
  const status =
    statusRaw === "in_progress" || statusRaw === "inprogress"
      ? TICKET_STATUSES.IN_PROGRESS
      : statusRaw === "waiting"
        ? TICKET_STATUSES.WAITING
        : statusRaw === "resolved"
          ? TICKET_STATUSES.RESOLVED
          : statusRaw === "closed"
            ? TICKET_STATUSES.CLOSED
            : TICKET_STATUSES.OPEN;
  const slaRaw = String(row.slaStatus || row.sla || "").toLowerCase();
  const slaStatus =
    slaRaw === "at_risk" || slaRaw === "atrisk"
      ? TICKET_SLA_STATUSES.AT_RISK
      : slaRaw === "breached"
        ? TICKET_SLA_STATUSES.BREACHED
        : TICKET_SLA_STATUSES.ON_TRACK;
  return {
    id: row.id,
    number: row.number || row.id,
    title: row.title || "Untitled ticket",
    description: row.description || "",
    status,
    statusLabel: row.status || status,
    priority: row.priority || TICKET_PRIORITIES.P3,
    queue: row.queue || "support",
    queueLabel: row.queueLabel || row.queue || "Support",
    slaStatus,
    category: row.category || TICKET_CATEGORIES.QUESTION,
    assigneeName: row.assigneeName || "",
    requesterName: row.requesterName || "",
    projectId: row.projectId || null,
    projectName: row.projectName || "",
    clientName: row.clientName || "",
    billableHours: Number(row.billableHours) || 0,
    effortHours: Number(row.effortHours) || 0,
    linkedWorkItemId: row.linkedWorkItemId || null,
    linkedTimesheetId: row.linkedTimesheetId || null,
    externalSource: row.externalSource || "internal",
    externalRef: row.externalRef || "",
    createdAt: row.createdAt || null,
    dueAt: row.dueAt || null,
    resolvedAt: row.resolvedAt || null,
    tone: row.tone || "indigo",
  };
}

export function buildTicketKpis(tickets) {
  const rows = (tickets || []).map(normalizeTicket).filter(Boolean);
  const open = rows.filter(
    (row) => row.status !== TICKET_STATUSES.RESOLVED && row.status !== TICKET_STATUSES.CLOSED
  ).length;
  const breached = rows.filter((row) => row.slaStatus === TICKET_SLA_STATUSES.BREACHED).length;
  const p1 = rows.filter((row) => row.priority === TICKET_PRIORITIES.P1).length;
  const billable = rows.reduce((sum, row) => sum + row.billableHours, 0);
  return [
    { id: "open", label: "Open tickets", value: open, icon: "fe fe-life-buoy", tone: "indigo" },
    { id: "p1", label: "P1 critical", value: p1, icon: "fe fe-alert-octagon", tone: "rose" },
    { id: "sla", label: "SLA breached", value: breached, icon: "fe fe-clock", tone: "amber" },
    { id: "billable", label: "Billable hrs", value: billable, icon: "fe fe-dollar-sign", tone: "green" },
  ];
}

export function buildTicketInsights(tickets) {
  const rows = (tickets || []).map(normalizeTicket).filter(Boolean);
  const breached = rows.filter((row) => row.slaStatus === TICKET_SLA_STATUSES.BREACHED);
  const insights = [];
  if (breached.length) {
    insights.push({
      id: "sla-breach",
      title: "SLA breaches detected",
      copy: `${breached.length} ticket(s) breached SLA — escalate or reassign from the queue board.`,
      tone: "danger",
    });
  }
  const infra = rows.filter((row) => row.category === TICKET_CATEGORIES.INFRASTRUCTURE && row.status === TICKET_STATUSES.OPEN);
  if (infra.length >= 2) {
    insights.push({
      id: "infra-cluster",
      title: "Recurring infrastructure issues",
      copy: `${infra.length} open infrastructure tickets — review RCA links and integration health.`,
      tone: "warning",
    });
  }
  return insights;
}

export function buildTicketAnalytics(tickets) {
  const rows = (tickets || []).map(normalizeTicket).filter(Boolean);
  const byCategory = {};
  rows.forEach((row) => {
    byCategory[row.category] = (byCategory[row.category] || 0) + 1;
  });
  const categories = Object.keys(byCategory).map((key) => ({
    id: key,
    label: key,
    count: byCategory[key],
  }));
  const avgResolutionHrs = rows.length
    ? Math.round(rows.reduce((sum, row) => sum + row.effortHours, 0) / rows.length * 10) / 10
    : 0;
  return {
    backlog: rows.filter((row) => row.status === TICKET_STATUSES.OPEN || row.status === TICKET_STATUSES.IN_PROGRESS).length,
    slaCompliancePct: rows.length
      ? Math.round((rows.filter((row) => row.slaStatus === TICKET_SLA_STATUSES.ON_TRACK).length / rows.length) * 100)
      : 100,
    avgResolutionHrs,
    billableSupportHrs: rows.reduce((sum, row) => sum + row.billableHours, 0),
    categories,
  };
}

export function filterTickets(tickets, filters) {
  const f = filters || {};
  const employeeId = f.employeeId != null ? String(f.employeeId) : null;
  return (tickets || [])
    .map((raw) => {
      const row = normalizeTicket(raw);
      if (!row) {
        return null;
      }
      return {
        ...row,
        requesterEmployeeId: raw.requesterEmployeeId || raw.requesterId || "",
        assigneeEmployeeId: raw.assigneeEmployeeId || "",
        ownerEmployeeId: raw.ownerEmployeeId || "",
        resolverEmployeeId: raw.resolverEmployeeId || "",
      };
    })
    .filter(Boolean)
    .filter((row) => !f.status || f.status === "ALL" || row.status === f.status)
    .filter((row) => !f.priority || f.priority === "ALL" || row.priority === f.priority)
    .filter((row) => !f.queue || f.queue === "ALL" || row.queue === f.queue)
    .filter((row) => !f.assignee || row.assigneeName === f.assignee)
    .filter((row) => {
      if (!employeeId) {
        return true;
      }
      return (
        String(row.requesterEmployeeId) === employeeId ||
        String(row.assigneeEmployeeId) === employeeId ||
        String(row.ownerEmployeeId) === employeeId ||
        String(row.resolverEmployeeId) === employeeId
      );
    })
    .filter((row) => {
      if (!f.query) {
        return true;
      }
      const q = String(f.query).toLowerCase();
      return (
        String(row.title).toLowerCase().includes(q) ||
        String(row.number).toLowerCase().includes(q) ||
        String(row.projectName).toLowerCase().includes(q)
      );
    });
}

export function getTicketPriorityTone(priority) {
  if (priority === TICKET_PRIORITIES.P1) {
    return "rose";
  }
  if (priority === TICKET_PRIORITIES.P2) {
    return "amber";
  }
  if (priority === TICKET_PRIORITIES.P3) {
    return "blue";
  }
  return "slate";
}

export function getTicketSlaTone(slaStatus) {
  if (slaStatus === TICKET_SLA_STATUSES.BREACHED) {
    return "rose";
  }
  if (slaStatus === TICKET_SLA_STATUSES.AT_RISK) {
    return "amber";
  }
  return "green";
}

export function exportTicketsCsv(tickets) {
  const rows = (tickets || []).map(normalizeTicket).filter(Boolean);
  const header = "number,title,status,priority,queue,sla,assignee,project,billableHours";
  const body = rows
    .map((row) =>
      [row.number, row.title, row.status, row.priority, row.queue, row.slaStatus, row.assigneeName, row.projectName, row.billableHours]
        .map((cell) => `"${String(cell || "").replace(/"/g, '""')}"`)
        .join(",")
    )
    .join("\n");
  return `${header}\n${body}`;
}
