export function isActingDelegate(record) {
  return !!(record && record.actingAsDelegate === true);
}

export function resolveAuthorityManagerName(authorityManagerId, context) {
  if (authorityManagerId == null) return null;
  const managerKey = String(authorityManagerId);
  const actingDelegations = (context && context.actingDelegations) || [];
  const delegation = actingDelegations.find(
    (item) => item && String(item.delegatorId) === managerKey
  );
  if (delegation && delegation.delegatorName) {
    return delegation.delegatorName;
  }

  const employees = (context && context.employees) || [];
  const employee = employees.find((item) => item && String(item.id) === managerKey);
  if (employee && employee.name) {
    return employee.name;
  }

  return null;
}

export function formatActingForLabel(managerName, authorityManagerId) {
  if (managerName) {
    return `Acting for ${managerName}`;
  }
  if (authorityManagerId != null) {
    return `Acting for manager #${authorityManagerId}`;
  }
  return "Acting as delegate";
}

export function buildActingForBadge(record, context) {
  if (!isActingDelegate(record)) {
    return null;
  }
  const managerName = resolveAuthorityManagerName(record.authorityManagerId, context);
  return {
    label: formatActingForLabel(managerName, record.authorityManagerId),
    managerName: managerName,
    authorityManagerId: record.authorityManagerId,
  };
}

export function hasActingDelegateRecords(records) {
  return (records || []).some((record) => isActingDelegate(record));
}

export function getPendingInboxEyebrow(records) {
  const list = records || [];
  if (!list.length) {
    return "Manager approvals";
  }
  const actingCount = list.filter((record) => isActingDelegate(record)).length;
  if (actingCount === list.length) {
    return "Delegate coverage";
  }
  if (actingCount > 0) {
    return "Approvals";
  }
  return "Manager approvals";
}

function isManagerTimesheetApprover(permission) {
  return !!(permission && permission.enableTimeSheetApproval === true);
}

export function isDelegateOnlyApprover(permission, actingDelegations) {
  if (isManagerTimesheetApprover(permission)) {
    return false;
  }
  if (!permission || permission.approvalDelegationEnabled !== true) {
    return false;
  }
  return !!(actingDelegations && actingDelegations.length);
}

export function buildApprovalInboxContext(actingDelegations, employees) {
  return {
    actingDelegations: actingDelegations || [],
    employees: employees || [],
  };
}

export function resolveEmployeeName(employeeId, context) {
  if (employeeId == null) return null;
  const employeeKey = String(employeeId);
  const employees = (context && context.employees) || [];
  const employee = employees.find((item) => item && String(item.id) === employeeKey);
  return employee && employee.name ? employee.name : null;
}

function formatEmployeeLabel(employeeId, context, fallbackPrefix) {
  const name = resolveEmployeeName(employeeId, context);
  if (name) {
    return name;
  }
  if (employeeId != null) {
    return `${fallbackPrefix} #${employeeId}`;
  }
  return fallbackPrefix;
}

export function buildApprovalAuthorityHistory(record, context) {
  if (!record || !record.approvalAuthorityType) {
    return null;
  }

  const authorityType = String(record.approvalAuthorityType).toUpperCase();
  const approverLabel = formatEmployeeLabel(record.approvedBy, context, "Approver");

  if (authorityType === "DELEGATE") {
    const managerLabel = formatEmployeeLabel(record.approvedOnBehalfOf, context, "Manager");
    return {
      authorityType,
      label: `Approved by ${approverLabel} (acting for ${managerLabel})`,
      approverId: record.approvedBy,
      onBehalfOfId: record.approvedOnBehalfOf,
    };
  }

  if (authorityType === "AUTO") {
    return {
      authorityType,
      label: `Auto-approved by ${approverLabel}`,
      approverId: record.approvedBy,
      onBehalfOfId: null,
    };
  }

  return {
    authorityType,
    label: `Approved by ${approverLabel}`,
    approverId: record.approvedBy,
    onBehalfOfId: null,
  };
}
