import React, { useEffect } from "react";
import AuthBrandPanel from "./AuthBrandPanel";
import startAuthFitScale from "./authFitScale";

/** Cache-bust so login layout is not stuck on an old luxury.css. */
const AUTH_LAYOUT_HREF = "/assets/css/auth-layout.css?v=20260915f";

const AuthPageShell = ({ children }) => {
    useEffect(() => {
        if (typeof document === "undefined") {
            return undefined;
        }
        let link = document.querySelector('link[data-auth-layout="1"]');
        if (!link) {
            link = document.createElement("link");
            link.rel = "stylesheet";
            link.setAttribute("data-auth-layout", "1");
            document.head.appendChild(link);
        }
        if (link.getAttribute("href") !== AUTH_LAYOUT_HREF) {
            link.setAttribute("href", AUTH_LAYOUT_HREF);
        }
        return undefined;
    }, []);

    useEffect(() => startAuthFitScale(), []);

    return (
        <div className="auth-screen lux-auth-shell">
            <div className="auth-screen__backdrop" aria-hidden="true" />
            <div className="auth-screen__layout">
                <AuthBrandPanel />
                <div className="auth-screen__form">
                    <div className="auth-screen__form-inner">
                        {children}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AuthPageShell;
