import React from "react";
import PropTypes from "prop-types";
import BrandNameLogo from "views/common/fragments/BrandNameLogo";

function AuthLoginCard({ eyebrow, title, subtitle, children, footer }) {
  return (
    <div className="card auth-login__card">
      <span className="auth-login__card-glow" aria-hidden="true" />
      <span className="auth-login__card-ring" aria-hidden="true" />
      <div className="auth-login__card-inner">
        <div className="auth-login__fit">
          <header className="auth-login__head">
            <BrandNameLogo variant="card" wrapperClassName="auth-login__brand" />
            {eyebrow && <p className="auth-login__eyebrow">{eyebrow}</p>}
            <h1 className="auth-login__title card-title">{title}</h1>
            {subtitle && <p className="auth-login__subtitle">{subtitle}</p>}
          </header>
          <div className="card-body auth-login__body">{children}</div>
          {footer && <footer className="auth-login__foot">{footer}</footer>}
        </div>
      </div>
    </div>
  );
}

AuthLoginCard.propTypes = {
  eyebrow: PropTypes.string,
  title: PropTypes.string.isRequired,
  subtitle: PropTypes.string,
  children: PropTypes.node,
  footer: PropTypes.node,
};

AuthLoginCard.defaultProps = {
  eyebrow: "Secure access",
  subtitle: null,
  children: null,
  footer: null,
};

export default AuthLoginCard;
