import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { withRouter } from "react-router-dom";
import { onboardingService } from "_services/onboarding.service";
import { offerService } from "_services/offer.service";
import { requisitionService } from "_services/requisition.service";
import { shouldUseOfferApi, shouldUseRequisitionApi } from "config/offer-requisition.config";
import { getOnboardingCasePath, getOffboardingCasePath } from "config/onboarding.utils";
import LifecycleActionLink from "./LifecycleActionLink";

const DRAWER_CLOSE_MS = 280;

const COPY = {
  onboarding: {
    drawerTone: "primary",
    icon: "fe-user-plus",
    eyebrow: "New hire case",
    title: "Start onboarding case",
    subtitle: "Spawn a checklist from an approved template for a new hire.",
    intro:
      "Pick a checklist template, enter the candidate details, and we will create a tracked onboarding case with all template tasks assigned.",
    subjectLabel: "Candidate name",
    subjectPlaceholder: "Jordan Lee",
    dateLabel: "Start date",
    emailPlaceholder: "jordan.lee@company.com",
    createLabel: "Create case",
    creatingLabel: "Creating…",
    footHint: "You will be taken to the new case checklist after creation.",
    templatesPath: "/people/onboarding/templates",
    listTemplates: () => onboardingService.listOnboardingTemplates(),
    createCase: (payload) => onboardingService.createOnboardingCase(payload),
    casePath: getOnboardingCasePath,
    buildPayload: ({
      templateCode,
      subjectName,
      email,
      roleTitle,
      department,
      location,
      dateValue,
      offerRef,
      requisitionRef,
      sourceType,
    }) => ({
      templateCode,
      candidateName: subjectName.trim(),
      candidateEmail: email.trim() || null,
      roleTitle: roleTitle.trim() || null,
      department: department.trim() || null,
      location: location.trim() || null,
      startDate: dateValue || null,
      offerRef: offerRef && offerRef.trim() ? offerRef.trim() : null,
      requisitionRef: requisitionRef && requisitionRef.trim() ? requisitionRef.trim() : null,
      sourceType: sourceType || "DIRECT",
    }),
    validate: (templateCode, subjectName) => {
      if (!templateCode || !subjectName.trim()) {
        return "Select a template and enter the candidate name.";
      }
      return null;
    },
  },
  offboarding: {
    drawerTone: "warning",
    icon: "fe-user-x",
    eyebrow: "Exit case",
    title: "Start exit case",
    subtitle: "Spawn an offboarding checklist from an approved exit template.",
    intro:
      "Pick an exit template, confirm the employee and last working day, and we will open a tracked offboarding case with settlement and access tasks.",
    subjectLabel: "Employee name",
    subjectPlaceholder: "Noah Patel",
    dateLabel: "Last working day",
    emailPlaceholder: "noah.patel@company.com",
    createLabel: "Create exit case",
    creatingLabel: "Creating…",
    footHint: "You will be taken to the exit case checklist after creation.",
    templatesPath: "/people/offboarding/templates",
    listTemplates: () => onboardingService.listOffboardingTemplates(),
    createCase: (payload) => onboardingService.createOffboardingCase(payload),
    casePath: getOffboardingCasePath,
    buildPayload: ({
      templateCode,
      subjectName,
      email,
      roleTitle,
      department,
      location,
      dateValue,
      exitReason,
    }) => ({
      templateCode,
      employeeName: subjectName.trim(),
      employeeEmail: email.trim() || null,
      roleTitle: roleTitle.trim() || null,
      department: department.trim() || null,
      location: location.trim() || null,
      lastDay: dateValue || null,
      exitReason: exitReason.trim() || "Resignation",
    }),
    validate: (templateCode, subjectName) => {
      if (!templateCode || !subjectName.trim()) {
        return "Select a template and enter the employee name.";
      }
      return null;
    },
  },
};

function CaseField({ label, icon, highlight, children, className }) {
  return (
    <label
      className={classNames("lux-onb-template-author__field", className, {
        "is-highlight": highlight,
        "is-wide": className === "is-wide",
      })}
    >
      <span>
        {icon && <i className={classNames("fe", icon)} aria-hidden="true" />}
        {label}
      </span>
      {children}
    </label>
  );
}

function CreateLifecycleCasePanel({
  open,
  onClose,
  onCreated,
  initialTemplateCode = "",
  history,
  lifecycle = "onboarding",
}) {
  const copy = COPY[lifecycle] || COPY.onboarding;
  const isOffboarding = lifecycle === "offboarding";

  const [templates, setTemplates] = useState([]);
  const [templateCode, setTemplateCode] = useState("");
  const [subjectName, setSubjectName] = useState("");
  const [email, setEmail] = useState("");
  const [roleTitle, setRoleTitle] = useState("");
  const [department, setDepartment] = useState("");
  const [location, setLocation] = useState("");
  const [dateValue, setDateValue] = useState("");
  const [exitReason, setExitReason] = useState("Resignation");
  const [offerRef, setOfferRef] = useState("");
  const [requisitionRef, setRequisitionRef] = useState("");
  const [sourceType, setSourceType] = useState("DIRECT");
  const [offers, setOffers] = useState([]);
  const [requisitions, setRequisitions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);
  const [closing, setClosing] = useState(false);

  const selectedTemplate = useMemo(
    () => templates.find((item) => item.code === templateCode) || null,
    [templates, templateCode]
  );

  const requestClose = useCallback(() => {
    setClosing(true);
    window.setTimeout(() => {
      setClosing(false);
      setError(null);
      onClose();
    }, DRAWER_CLOSE_MS);
  }, [onClose]);

  useEffect(() => {
    if (!open) {
      return undefined;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    setSubmitting(false);
    setSubjectName("");
    setEmail("");
    setDateValue("");
    setExitReason("Resignation");
    setOfferRef("");
    setRequisitionRef("");
    setSourceType("DIRECT");
    setOffers([]);
    setRequisitions([]);
    const loadMasters = Promise.all([
      !isOffboarding && shouldUseOfferApi()
        ? offerService.listOffers().then((res) => (res && res.source === "api" && Array.isArray(res.payload) ? res.payload : []))
        : Promise.resolve([]),
      !isOffboarding && shouldUseRequisitionApi()
        ? requisitionService
            .listRequisitions()
            .then((res) => (res && res.source === "api" && Array.isArray(res.payload) ? res.payload : []))
        : Promise.resolve([]),
    ]);
    Promise.all([copy.listTemplates(), loadMasters])
      .then(([res, masterLists]) => {
        if (cancelled) {
          return;
        }
        const list = Array.isArray(res.payload) ? res.payload : [];
        setTemplates(list);
        setOffers(masterLists[0] || []);
        setRequisitions(masterLists[1] || []);
        const preferred = initialTemplateCode || (list[0] && list[0].code) || "";
        if (preferred) {
          setTemplateCode(preferred);
          const selected = list.find((item) => item.code === preferred) || list[0];
          if (selected) {
            setDepartment(selected.department || "");
            setRoleTitle(selected.roleFilter || "");
            setLocation(selected.locationFilter || "");
          }
        } else {
          setTemplateCode("");
          setDepartment("");
          setRoleTitle("");
          setLocation("");
        }
        setLoading(false);
      })
      .catch(() => {
        if (!cancelled) {
          setError("Unable to load checklist templates.");
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [open, initialTemplateCode, lifecycle, isOffboarding]);

  const handleTemplateChange = (event) => {
    const code = event.target.value;
    setTemplateCode(code);
    const selected = templates.find((item) => item.code === code);
    if (selected) {
      setDepartment(selected.department || "");
      setRoleTitle(selected.roleFilter || "");
      setLocation(selected.locationFilter || "");
    }
  };

  const handleSubmit = async (event) => {
    if (event && event.preventDefault) {
      event.preventDefault();
    }
    const validationError = copy.validate(templateCode, subjectName);
    if (validationError) {
      setError(validationError);
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      const res = await copy.createCase(
        copy.buildPayload({
          templateCode,
          subjectName,
          email,
          roleTitle,
          department,
          location,
          dateValue,
          exitReason,
          offerRef,
          requisitionRef,
          sourceType,
        })
      );
      if (!res.payload || !res.payload.id) {
        throw new Error("Case was not created.");
      }
      if (onCreated) {
        await onCreated(res.payload);
      }
      requestClose();
      if (history && history.push) {
        history.push(copy.casePath(res.payload.id));
      }
    } catch (submitError) {
      setError(submitError.message || "Unable to create case.");
      setSubmitting(false);
    }
  };

  if (!open) {
    return null;
  }

  return createPortal(
    <div
      className={classNames("lux-onb-drawer-backdrop", { "is-closing": closing })}
      role="presentation"
      onClick={requestClose}
    >
      <aside
        className={classNames(
          "lux-onb-drawer",
          `lux-onb-drawer--${copy.drawerTone}`,
          "lux-onb-case-start",
          "lux-onb-template-author",
          { "is-exit": isOffboarding, "is-closing": closing }
        )}
        role="dialog"
        aria-labelledby="lux-onb-create-case-title"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="lux-onb-drawer__accent" aria-hidden="true" />

        <header className="lux-onb-drawer__head">
          <div className="lux-onb-drawer__head-main">
            <div className="lux-onb-drawer__category-icon" aria-hidden="true">
              <i className={classNames("fe", copy.icon)} />
            </div>
            <div className="lux-onb-drawer__head-copy">
              <h2 id="lux-onb-create-case-title">{copy.title}</h2>
              <p className="lux-onb-drawer__task-id">{copy.subtitle}</p>
            </div>
          </div>
          <button type="button" className="lux-onb-drawer__close" onClick={requestClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden />
          </button>
        </header>

        <div className="lux-onb-drawer__body lux-onb-case-start__scroll">
          <form
            id="lux-onb-case-start-form"
            className="lux-onb-template-author__body lux-onb-case-start__form"
            onSubmit={handleSubmit}
            noValidate
          >
          {loading && (
            <p className="lux-onb-case-start__loading">
              <i className="fe fe-loader" aria-hidden="true" />
              Loading templates…
            </p>
          )}

          {!loading && selectedTemplate && (
            <div className="lux-onb-case-start__highlights">
              <article className="lux-onb-template-author__highlight">
                <span>Template tasks</span>
                <strong>{selectedTemplate.taskCount || 0}</strong>
              </article>
              <article className="lux-onb-template-author__highlight is-required">
                <span>Department</span>
                <strong className="is-text">{selectedTemplate.department || "Any"}</strong>
              </article>
              <article className="lux-onb-template-author__highlight is-self">
                <span>Location</span>
                <strong className="is-text">{selectedTemplate.locationFilter || "Any"}</strong>
              </article>
            </div>
          )}

          {error && (
            <p className="lux-onb-template-author__error" role="alert">
              <i className="fe fe-alert-circle" aria-hidden="true" />
              {error}
            </p>
          )}

          {!loading && !templates.length && (
            <div className="lux-onb-case-start__empty">
              <i className="fe fe-layers" aria-hidden="true" />
              <div>
                <strong>No templates available</strong>
                <p>Create a checklist template before starting a case.</p>
              </div>
              <LifecycleActionLink to={copy.templatesPath} variant="ghost" icon="fe-plus">
                Create template
              </LifecycleActionLink>
            </div>
          )}

          {templates.length > 0 && (
            <>
              <section className="lux-onb-template-author__card lux-onb-case-start__card">
                <header className="lux-onb-template-author__card-head">
                  <div>
                    <h3>
                      <i className="fe fe-layers" aria-hidden="true" />
                      Checklist template
                    </h3>
                    <p>Tasks from this template copy into the new case.</p>
                  </div>
                </header>

                <CaseField label="Template" icon="fe-bookmark" highlight className="is-wide">
                  <select
                    className="lux-onb-template-author__input"
                    value={templateCode}
                    onChange={handleTemplateChange}
                    disabled={loading || submitting}
                  >
                    {templates.map((template) => (
                      <option key={template.code} value={template.code}>
                        {template.name} ({template.taskCount} tasks)
                      </option>
                    ))}
                  </select>
                </CaseField>

                {selectedTemplate && selectedTemplate.description && (
                  <p className="lux-onb-case-start__template-desc">{selectedTemplate.description}</p>
                )}
              </section>

              <section className="lux-onb-template-author__card lux-onb-case-start__card lux-onb-case-start__card--person">
                <header className="lux-onb-template-author__card-head">
                  <div>
                    <h3>
                      <i className="fe fe-user" aria-hidden="true" />
                      {isOffboarding ? "Employee details" : "Candidate details"}
                    </h3>
                    <p>Who this case is for and how to reach them.</p>
                  </div>
                </header>

                <CaseField label={copy.subjectLabel} icon="fe-user" highlight className="is-wide">
                  <input
                    className="lux-onb-template-author__input"
                    value={subjectName}
                    onChange={(event) => setSubjectName(event.target.value)}
                    disabled={submitting}
                    placeholder={copy.subjectPlaceholder}
                    required
                  />
                </CaseField>

                <div className="lux-onb-template-author__grid">
                  <CaseField label="Email" icon="fe-mail">
                    <input
                      className="lux-onb-template-author__input"
                      type="email"
                      value={email}
                      onChange={(event) => setEmail(event.target.value)}
                      disabled={submitting}
                      placeholder={copy.emailPlaceholder}
                    />
                  </CaseField>
                  <CaseField label="Role" icon="fe-briefcase">
                    <input
                      className="lux-onb-template-author__input"
                      value={roleTitle}
                      onChange={(event) => setRoleTitle(event.target.value)}
                      disabled={submitting}
                      placeholder="Software Engineer"
                    />
                  </CaseField>
                </div>
              </section>

              <section className="lux-onb-template-author__card lux-onb-case-start__card lux-onb-case-start__card--schedule">
                <header className="lux-onb-template-author__card-head">
                  <div>
                    <h3>
                      <i className="fe fe-calendar" aria-hidden="true" />
                      Schedule &amp; targeting
                    </h3>
                    <p>Key dates and org filters for this case.</p>
                  </div>
                </header>

                <div className="lux-onb-template-author__grid">
                  <CaseField label={copy.dateLabel} icon="fe-calendar" highlight>
                    <input
                      className="lux-onb-template-author__input"
                      type="date"
                      value={dateValue}
                      onChange={(event) => setDateValue(event.target.value)}
                      disabled={submitting}
                    />
                  </CaseField>
                  {isOffboarding ? (
                    <CaseField label="Exit reason" icon="fe-log-out">
                      <select
                        className="lux-onb-template-author__input"
                        value={exitReason}
                        onChange={(event) => setExitReason(event.target.value)}
                        disabled={submitting}
                      >
                        {["Resignation", "Termination", "Retirement", "Role change", "Other"].map((reason) => (
                          <option key={reason} value={reason}>
                            {reason}
                          </option>
                        ))}
                      </select>
                    </CaseField>
                  ) : (
                    <CaseField label="Department" icon="fe-grid">
                      <input
                        className="lux-onb-template-author__input"
                        value={department}
                        onChange={(event) => setDepartment(event.target.value)}
                        disabled={submitting}
                        placeholder="Engineering"
                      />
                    </CaseField>
                  )}
                </div>

                <div className="lux-onb-template-author__grid">
                  {isOffboarding && (
                    <CaseField label="Department" icon="fe-grid">
                      <input
                        className="lux-onb-template-author__input"
                        value={department}
                        onChange={(event) => setDepartment(event.target.value)}
                        disabled={submitting}
                        placeholder="Engineering"
                      />
                    </CaseField>
                  )}
                  <CaseField label="Location" icon="fe-map-pin" className={isOffboarding ? undefined : "is-wide"}>
                    <input
                      className="lux-onb-template-author__input"
                      value={location}
                      onChange={(event) => setLocation(event.target.value)}
                      disabled={submitting}
                      placeholder="US"
                    />
                  </CaseField>
                </div>
              </section>

              {!isOffboarding && (
                <section className="lux-onb-template-author__card lux-onb-case-start__card lux-onb-case-start__card--source">
                  <header className="lux-onb-template-author__card-head">
                    <div>
                      <h3>
                        <i className="fe fe-link" aria-hidden="true" />
                        Offer / requisition linkage
                      </h3>
                      <p>Optional refs when this case starts from an offer or requisition.</p>
                    </div>
                  </header>

                  <CaseField label="Source type" icon="fe-git-branch" highlight className="is-wide">
                    <select
                      className="lux-onb-template-author__input"
                      value={sourceType}
                      onChange={(event) => setSourceType(event.target.value)}
                      disabled={submitting}
                    >
                      <option value="DIRECT">Direct</option>
                      <option value="OFFER">Offer</option>
                      <option value="REQUISITION">Requisition</option>
                    </select>
                  </CaseField>

                  <div className="lux-onb-template-author__grid">
                    <CaseField label="Offer ref" icon="fe-file-text">
                      {offers.length > 0 ? (
                        <select
                          className="lux-onb-template-author__input"
                          value={offerRef}
                          onChange={(event) => setOfferRef(event.target.value)}
                          disabled={submitting || sourceType === "DIRECT"}
                          data-testid="offer-ref-select"
                        >
                          <option value="">Select offer…</option>
                          {offers.map((offer) => (
                            <option key={offer.offerRef || offer.id} value={offer.offerRef || ""}>
                              {offer.offerRef}
                              {offer.title ? ` — ${offer.title}` : ""}
                            </option>
                          ))}
                        </select>
                      ) : (
                        <input
                          className="lux-onb-template-author__input"
                          value={offerRef}
                          onChange={(event) => setOfferRef(event.target.value)}
                          disabled={submitting || sourceType === "DIRECT"}
                          placeholder="OFF-2026-001"
                          data-testid="offer-ref-input"
                        />
                      )}
                    </CaseField>
                    <CaseField label="Requisition ref" icon="fe-clipboard">
                      {requisitions.length > 0 ? (
                        <select
                          className="lux-onb-template-author__input"
                          value={requisitionRef}
                          onChange={(event) => setRequisitionRef(event.target.value)}
                          disabled={submitting || sourceType === "DIRECT"}
                          data-testid="requisition-ref-select"
                        >
                          <option value="">Select requisition…</option>
                          {requisitions.map((req) => (
                            <option key={req.requisitionRef || req.id} value={req.requisitionRef || ""}>
                              {req.requisitionRef}
                              {req.title ? ` — ${req.title}` : ""}
                            </option>
                          ))}
                        </select>
                      ) : (
                        <input
                          className="lux-onb-template-author__input"
                          value={requisitionRef}
                          onChange={(event) => setRequisitionRef(event.target.value)}
                          disabled={submitting || sourceType === "DIRECT"}
                          placeholder="REQ-2026-001"
                          data-testid="requisition-ref-input"
                        />
                      )}
                    </CaseField>
                  </div>
                </section>
              )}
            </>
          )}
          </form>
        </div>

        <footer className="lux-onb-drawer__foot">
          <div className="lux-onb-drawer__foot-actions">
            <LifecycleActionLink variant="ghost" onClick={requestClose}>
              Cancel
            </LifecycleActionLink>
            <LifecycleActionLink
              variant="primary"
              icon="fe-plus"
              type="submit"
              form="lux-onb-case-start-form"
              disabled={
                submitting || loading || !templates.length || !templateCode || !subjectName.trim()
              }
            >
              {submitting ? copy.creatingLabel : copy.createLabel}
            </LifecycleActionLink>
          </div>
          <p className="lux-onb-drawer__foot-hint">{copy.footHint}</p>
        </footer>
      </aside>
    </div>,
    document.body
  );
}

export default withRouter(CreateLifecycleCasePanel);
