import moment from "moment";
import dateUtils from "_helpers/date.utils";

const STATUS_COMPLETED = ["COMPLETED", "CLOSED"];
const STATUS_ACTIVE = ["INPROGRESS", "ASSIGNED", "NEW"];

const STATUS_LABELS = {
  NEW: "New",
  ASSIGNED: "Assigned",
  INPROGRESS: "In progress",
  COMPLETED: "Completed",
  CLOSED: "Closed",
};

const STATUS_TONES = {
  NEW: "sky",
  ASSIGNED: "indigo",
  INPROGRESS: "amber",
  COMPLETED: "green",
  CLOSED: "slate",
};

const PRIORITY_LABELS = {
  URGENT: "Urgent",
  HIGH: "High",
  MEDIUM: "Medium",
  LOW: "Low",
};

const PRIORITY_TONES = {
  URGENT: "rose",
  HIGH: "amber",
  MEDIUM: "indigo",
  LOW: "slate",
};

const CHECKLIST_LABELS = {
  COMPLETED: "Checklist done",
  INPROGRESS: "In progress",
  NOT_STARTED: "Not started",
  NONE: "No checklist",
};

const TYPE_LABELS = {
  PROJECT: "Project billable",
  NON_PROJECT: "Non-project",
};

function pct(count, total) {
  if (!total) return 0;
  return Math.round((count / total) * 100);
}

function buildMixSegments(counts, total, labelMap = {}, toneMap = {}) {
  return Object.entries(counts)
    .filter(([, count]) => count > 0)
    .map(([key, count]) => ({
      key,
      label: labelMap[key] || key,
      count,
      pct: pct(count, total),
      tone: toneMap[key] || "slate",
    }))
    .sort((a, b) => b.count - a.count);
}

function resolveChecklistBucket(item) {
  const status = (item.checklistStatus || "").toUpperCase();
  if (status === "COMPLETED") return "COMPLETED";
  if (status === "INPROGRESS") return "INPROGRESS";
  if (item.checklistData && Object.keys(item.checklistData).length) return "NOT_STARTED";
  return "NONE";
}

function buildLoggedHoursTrend(items) {
  const buckets = {};
  items.forEach((item) => {
    const status = (item.status || "NEW").toUpperCase();
    if (!STATUS_COMPLETED.includes(status)) return;
    const time = item.actualStartTime || item.estStartTime;
    if (!time) return;
    const key = moment(time).format("YYYY-MM-DD");
    if (!buckets[key]) {
      buckets[key] = { key, label: moment(time).format("MMM D"), hours: 0, count: 0 };
    }
    buckets[key].hours += Math.round(((Number(item.durationInMins) || 0) / 60) * 10) / 10;
    buckets[key].count += 1;
  });
  return Object.values(buckets)
    .sort((a, b) => a.key.localeCompare(b.key))
    .slice(-10);
}

export function getWorkItemStatusMeta(status) {
  const key = (status || "NEW").toUpperCase();
  const map = {
    NEW: { label: "New", tone: "sky", icon: "fe fe-square" },
    ASSIGNED: { label: "Assigned", tone: "indigo", icon: "fe fe-loader" },
    INPROGRESS: { label: "In progress", tone: "amber", icon: "fe fe-loader", spin: true },
    COMPLETED: { label: "Completed", tone: "green", icon: "fe fe-check-circle" },
    CLOSED: { label: "Closed", tone: "slate", icon: "fe fe-minus-circle" },
    PAUSED: { label: "Paused", tone: "rose", icon: "fe fe-pause-circle" },
  };
  return map[key] || { label: status || "—", tone: "slate", icon: "fe fe-circle" };
}

export function getWorkItemPriorityMeta(priority) {
  const key = (priority || "MEDIUM").toUpperCase();
  const map = {
    URGENT: { label: "Urgent", level: 1, tone: "rose" },
    HIGH: { label: "High", level: 2, tone: "amber" },
    MEDIUM: { label: "Medium", level: 3, tone: "indigo" },
    LOW: { label: "Low", level: 4, tone: "slate" },
  };
  return map[key] || map.MEDIUM;
}

export function buildWorkItemActivitySummary(workItems, pendingItems) {
  const items = workItems || [];
  const pending = pendingItems || [];
  let loggedMins = 0;
  let completed = 0;
  let active = 0;
  let inProgress = 0;
  let estimatedMins = 0;
  let urgentCount = 0;
  let checklistOpen = 0;
  let billableCount = 0;
  const statusCounts = {};
  const priorityCounts = {};
  const categoryCounts = {};
  const typeCounts = {};
  const checklistCounts = { COMPLETED: 0, INPROGRESS: 0, NOT_STARTED: 0, NONE: 0 };
  const ownerCounts = {};
  const stageCounts = { newCount: 0, assignedCount: 0, inProgressCount: 0, completedCount: 0 };

  items.forEach((item) => {
    const status = (item.status || "NEW").toUpperCase();
    statusCounts[status] = (statusCounts[status] || 0) + 1;
    if (status === "NEW") stageCounts.newCount += 1;
    if (status === "ASSIGNED") stageCounts.assignedCount += 1;
    if (status === "INPROGRESS") {
      stageCounts.inProgressCount += 1;
      inProgress += 1;
    }
    if (STATUS_COMPLETED.includes(status)) stageCounts.completedCount += 1;

    const priorityKey = (item.taskPriority || "MEDIUM").toUpperCase();
    priorityCounts[priorityKey] = (priorityCounts[priorityKey] || 0) + 1;
    if (priorityKey === "URGENT" || priorityKey === "HIGH") urgentCount += 1;

    const categoryKey = item.taskActCategory || "Other";
    categoryCounts[categoryKey] = (categoryCounts[categoryKey] || 0) + 1;

    const typeKey = item.taskType || "OTHER";
    typeCounts[typeKey] = (typeCounts[typeKey] || 0) + 1;
    if (typeKey === "PROJECT") billableCount += 1;

    const checklistKey = resolveChecklistBucket(item);
    checklistCounts[checklistKey] = (checklistCounts[checklistKey] || 0) + 1;
    if (checklistKey === "INPROGRESS" || checklistKey === "NOT_STARTED") checklistOpen += 1;

    const ownerKey = (item.ownerDetails && item.ownerDetails.name) || "Unassigned";
    ownerCounts[ownerKey] = (ownerCounts[ownerKey] || 0) + 1;

    if (STATUS_COMPLETED.includes(status)) {
      completed += 1;
      loggedMins += Number(item.durationInMins) || 0;
    } else if (STATUS_ACTIVE.includes(status)) {
      active += 1;
    }
    estimatedMins += Number(item.estDurationInMins) || 0;
  });

  const total = items.length;
  const completionRate = total ? Math.round((completed / total) * 100) : 0;
  const activeRate = total ? Math.round((active / total) * 100) : 0;
  const utilizationRate =
    estimatedMins > 0 ? Math.min(100, Math.round((loggedMins / estimatedMins) * 100)) : 0;
  const loggedHoursNum = Math.round((loggedMins / 60) * 10) / 10;
  const estimatedHoursNum = Math.round((estimatedMins / 60) * 10) / 10;

  const statusMix = buildMixSegments(statusCounts, total, STATUS_LABELS, STATUS_TONES);
  const priorityMix = buildMixSegments(priorityCounts, total, PRIORITY_LABELS, PRIORITY_TONES);
  const categoryMix = buildMixSegments(categoryCounts, total).slice(0, 8);
  const typeMix = buildMixSegments(typeCounts, total, TYPE_LABELS, { PROJECT: "indigo", NON_PROJECT: "teal", OTHER: "slate" });
  const checklistMix = buildMixSegments(checklistCounts, total, CHECKLIST_LABELS, {
    COMPLETED: "green",
    INPROGRESS: "indigo",
    NOT_STARTED: "amber",
    NONE: "slate",
  });
  const ownerMix = buildMixSegments(ownerCounts, total).slice(0, 8);

  const outcomeMix = buildMixSegments(
    {
      COMPLETED: completed,
      INPROGRESS: inProgress,
      OPEN: Math.max(total - completed - inProgress, 0),
    },
    total,
    { COMPLETED: "Completed", INPROGRESS: "In progress", OPEN: "New / assigned" },
    { COMPLETED: "green", INPROGRESS: "amber", OPEN: "sky" }
  );

  const openCount = Math.max(total - completed, 0);
  const hoursVarianceNum = Math.round((loggedHoursNum - estimatedHoursNum) * 10) / 10;
  let hoursVarianceLabel = "On plan";
  let hoursVarianceTone = "even";
  if (hoursVarianceNum > 0.05) {
    hoursVarianceLabel = `${hoursVarianceNum}h over plan`;
    hoursVarianceTone = "over";
  } else if (hoursVarianceNum < -0.05) {
    hoursVarianceLabel = `${Math.abs(hoursVarianceNum)}h under plan`;
    hoursVarianceTone = "under";
  }

  return {
    total,
    completed,
    active,
    inProgress,
    pending: pending.length,
    loggedHours: dateUtils.minuteToHourString(loggedMins) || "0h 0m",
    estimatedHours: dateUtils.minuteToHourString(estimatedMins) || "0h 0m",
    loggedMins,
    estimatedMins,
    loggedHoursNum,
    estimatedHoursNum,
    completionRate,
    activeRate,
    utilizationRate,
    urgentCount,
    checklistOpen,
    billableCount,
    stageCounts,
    statusMix,
    priorityMix,
    categoryMix,
    typeMix,
    checklistMix,
    ownerMix,
    outcomeMix,
    openCount,
    completionMetrics: {
      rate: completionRate,
      completed,
      open: openCount,
      total,
      fractionLabel: total ? `${completed} of ${total} finished` : "No activities",
      explain: "Activities marked Completed or Closed in the current filter and selected period.",
    },
    hoursMetrics: {
      rate: utilizationRate,
      loggedHours: dateUtils.minuteToHourString(loggedMins) || "0h 0m",
      loggedHoursNum,
      estimatedHours: dateUtils.minuteToHourString(estimatedMins) || "0h 0m",
      estimatedHoursNum,
      varianceNum: hoursVarianceNum,
      varianceLabel: hoursVarianceLabel,
      varianceTone: hoursVarianceTone,
      explain: "Logged hours are from completed work; estimated hours are planned duration on all filtered activities.",
    },
    loggedHoursTrend: buildLoggedHoursTrend(items),
    funnel: [
      { key: "new", label: "New", count: stageCounts.newCount, tone: "sky" },
      { key: "assigned", label: "Assigned", count: stageCounts.assignedCount, tone: "indigo" },
      { key: "progress", label: "In progress", count: stageCounts.inProgressCount, tone: "amber" },
      { key: "completed", label: "Completed", count: stageCounts.completedCount, tone: "green" },
    ],
    kpis: [
      { key: "total", label: "Activities", value: total, hint: "In current filter", tone: "indigo", icon: "fe fe-activity" },
      { key: "completed", label: "Completed", value: completed, hint: `${completionRate}% done`, tone: "green", icon: "fe fe-check-circle" },
      { key: "active", label: "In delivery", value: active, hint: "New, assigned, open", tone: "amber", icon: "fe fe-clock" },
      { key: "pending", label: "Pending inbox", value: pending.length, hint: "Open deliverables", tone: "rose", icon: "fe fe-inbox" },
      { key: "logged", label: "Logged hours", value: loggedHoursNum, hint: `Est. ${estimatedHoursNum}h`, tone: "teal", icon: "fe fe-watch" },
      { key: "utilization", label: "Hours util.", value: utilizationRate, hint: "Actual vs estimated", tone: "violet", icon: "fe fe-trending-up" },
    ],
    highlights: [
      { key: "urgent", label: "Urgent / high", value: urgentCount, hint: "Needs attention", tone: "rose", icon: "fe fe-alert-triangle" },
      { key: "checklist", label: "Checklists open", value: checklistOpen, hint: "Not fully complete", tone: "indigo", icon: "fe fe-check-square" },
      { key: "billable", label: "Billable work", value: billableCount, hint: "Project activities", tone: "sky", icon: "fe fe-briefcase" },
      { key: "inprogress", label: "In progress now", value: inProgress, hint: "Actively being worked", tone: "amber", icon: "fe fe-loader" },
    ],
    insights: [
      {
        key: "status",
        title: "Status spread",
        subtitle: "Where filtered activities sit in the lifecycle",
        icon: "fe fe-layers",
        mix: statusMix,
        emptyLabel: "No activities in the current filter.",
      },
      {
        key: "priority",
        title: "Priority load",
        subtitle: "Urgency across the selected period",
        icon: "fe fe-flag",
        mix: priorityMix,
        emptyLabel: "No priority data for this filter.",
      },
      {
        key: "scope",
        title: "Work scope",
        subtitle: "Billable project vs non-project mix",
        icon: "fe fe-pie-chart",
        mix: typeMix,
        emptyLabel: "No scope breakdown available.",
      },
    ],
  };
}

export function groupWorkItemsDurationMins(items) {
  if (!items || !items.length) return 0;
  return items.reduce((sum, item) => sum + (Number(item.durationInMins) || 0), 0);
}

export const ACTIVITY_PAGE_SIZE_OPTIONS = [10, 25, 50, 100];
export const ACTIVITY_DEFAULT_PAGE_SIZE = 25;

function groupKeysForSort(items, sortBy) {
  if (!items || !items.length) return [];
  if (sortBy === "PROJECT") {
    const groups = items.reduce((acc, item) => {
      const key = item.projectId || "nonProject";
      if (!acc[key]) acc[key] = true;
      return acc;
    }, {});
    return Object.keys(groups);
  }
  if (sortBy === "DELIVERABLE") {
    const groups = items.reduce((acc, item) => {
      const key = item.taskId || item.taskActCategory || "other";
      if (!acc[key]) acc[key] = true;
      return acc;
    }, {});
    return Object.keys(groups);
  }
  return null;
}

function itemsForGroupKeys(items, sortBy, groupKeys) {
  const keySet = new Set(groupKeys);
  if (sortBy === "PROJECT") {
    return items.filter((item) => keySet.has(item.projectId || "nonProject"));
  }
  if (sortBy === "DELIVERABLE") {
    return items.filter((item) => keySet.has(item.taskId || item.taskActCategory || "other"));
  }
  return items;
}

export function getChecklistStatusMeta(item) {
  const bucket = resolveChecklistBucket(item);
  const tones = { COMPLETED: "green", INPROGRESS: "indigo", NOT_STARTED: "amber", NONE: "slate" };
  const icons = {
    COMPLETED: "fe fe-check-square",
    INPROGRESS: "fe fe-loader",
    NOT_STARTED: "fe fe-square",
    NONE: "fe fe-minus",
  };
  return {
    key: bucket,
    label: CHECKLIST_LABELS[bucket],
    tone: tones[bucket],
    icon: icons[bucket],
    open: bucket === "INPROGRESS" || bucket === "NOT_STARTED",
    spin: bucket === "INPROGRESS",
  };
}

export function getPendingDueMeta(dueTime) {
  if (!dueTime) {
    return { label: "No due date", tone: "slate", overdue: false, dueSoon: false, dueLabel: "—" };
  }
  const due = moment(dueTime);
  const now = moment();
  const days = due.diff(now, "days", true);
  const dueLabel = due.format("DD MMM YYYY");

  if (days < 0) {
    const overdueDays = Math.ceil(Math.abs(days));
    return {
      label: overdueDays === 1 ? "1 day overdue" : `${overdueDays} days overdue`,
      tone: "rose",
      overdue: true,
      dueSoon: false,
      dueLabel,
    };
  }
  if (days < 1) {
    return { label: "Due today", tone: "amber", overdue: false, dueSoon: true, dueLabel };
  }
  if (days <= 1) {
    return { label: "Due tomorrow", tone: "amber", overdue: false, dueSoon: true, dueLabel };
  }
  if (days <= 3) {
    return { label: `Due in ${Math.ceil(days)} days`, tone: "amber", overdue: false, dueSoon: true, dueLabel };
  }
  return { label: due.format("DD MMM"), tone: "slate", overdue: false, dueSoon: false, dueLabel };
}

export function summarizePendingItems(items) {
  const list = items || [];
  let overdue = 0;
  let dueSoon = 0;
  let checklistOpen = 0;
  let urgent = 0;
  const statusCounts = {};

  list.forEach((item) => {
    const dueMeta = getPendingDueMeta(item.taskEstCompletionTime || item.estStartTime);
    if (dueMeta.overdue) overdue += 1;
    if (dueMeta.dueSoon) dueSoon += 1;

    const checklist = getChecklistStatusMeta(item);
    if (checklist.open) checklistOpen += 1;

    const priority = (item.taskPriority || "MEDIUM").toUpperCase();
    if (priority === "URGENT" || priority === "HIGH") urgent += 1;

    const status = (item.status || "NEW").toUpperCase();
    statusCounts[status] = (statusCounts[status] || 0) + 1;
  });

  return { total: list.length, overdue, dueSoon, checklistOpen, urgent, statusCounts };
}

export function paginateActivityRegister(items, sortBy, page, pageSize = ACTIVITY_DEFAULT_PAGE_SIZE) {
  const list = items || [];
  const groupKeys = groupKeysForSort(list, sortBy);
  const total = groupKeys ? groupKeys.length : list.length;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const start = (safePage - 1) * pageSize;

  let pageItems;
  if (groupKeys) {
    const pageGroupKeys = groupKeys.slice(start, start + pageSize);
    pageItems = itemsForGroupKeys(list, sortBy, pageGroupKeys);
  } else {
    pageItems = list.slice(start, start + pageSize);
  }

  return {
    items: pageItems,
    page: safePage,
    pageSize,
    total,
    totalPages,
    rangeStart: total ? start + 1 : 0,
    rangeEnd: Math.min(start + pageSize, total),
  };
}
