import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames";
import { getVisibleSidebarItems } from "config/sidebar-menu.config";
import PlannedMenuIndicator from "components/navigation/PlannedMenuIndicator";
import {
  getPendingSidebarPath,
  navigateWithOptimisticSidebarSelection,
  subscribePendingSidebarPath,
} from "components/navigation/sidebarNavSelection.utils";

class Menu extends Component {
  state = {
    expanded: null,
    pendingPath: getPendingSidebarPath(),
  };

  componentDidMount() {
    this.unsubscribePending = subscribePendingSidebarPath((path) => {
      this.setState({ pendingPath: path });
    });
  }

  componentWillUnmount() {
    if (this.unsubscribePending) {
      this.unsubscribePending();
    }
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.activePersona !== this.props.activePersona ||
      prevProps.location.pathname !== this.props.location.pathname
    ) {
      this.setState({
        expanded: null,
        pendingPath: getPendingSidebarPath(),
      });
    }
  }

  getSelectionPath = () => {
    return (
      getPendingSidebarPath() ||
      this.state.pendingPath ||
      this.props.location.pathname ||
      ""
    );
  };

  handleNavClick = (path) => (event) => {
    navigateWithOptimisticSidebarSelection({ event, path });
  };

  isPathExcluded = (path) => {
    const excludes = this.props.pathExclude || [];
    return excludes.some((ex) => path === ex || path.startsWith(ex + "/"));
  };

  isPathPrefixed = (path) => {
    const prefixes = this.props.pathPrefixes || [];
    if (this.props.layoutName && prefixes.length === 0) {
      return path === this.props.layoutName || path.startsWith(this.props.layoutName + "/");
    }
    return prefixes.some((prefix) => path === prefix || path.startsWith(prefix + "/"));
  };

  pathMatchesItem = (pathname, itemPath) => {
    if (!itemPath) {
      return false;
    }
    return pathname === itemPath || pathname.startsWith(`${itemPath}/`);
  };

  isActiveChildRoute = () => {
    const path = this.getSelectionPath();
    return this.getVisibleItems().some(
      (item) =>
        this.pathMatchesItem(path, item.path) ||
        this.pathMatchesItem(path, item.aliasPath)
    );
  };

  activeRoute() {
    const path = this.getSelectionPath();
    if (this.isPathExcluded(path)) {
      return false;
    }
    if (this.isActiveChildRoute()) {
      return true;
    }
    return this.isPathPrefixed(path);
  }

  isExpanded = () => {
    if (this.state.expanded !== null) {
      return this.state.expanded;
    }
    return this.activeRoute();
  };

  getVisibleItems = () => {
    if (this.props.menuItems && this.props.menuItems.length > 0) {
      return getVisibleSidebarItems(
        { items: this.props.menuItems },
        this.props.menuAccessControl,
        this.props.activePersona
      );
    }
    return this.props.routes.filter(
      (prop) =>
        prop.layout === this.props.layoutName &&
        prop.showInMenu &&
        this.props.menuAccessControl &&
        this.props.menuAccessControl[prop.layout.substring(1) + "Modules"][
          prop.path.substring(1) + "Enabled"
        ] === true
    );
  };

  getChildRouteCount = () => this.getVisibleItems().length;

  handleToggle = (event) => {
    event.preventDefault();
    this.setState((prev) => ({
      expanded: prev.expanded === null ? !this.activeRoute() : !prev.expanded,
    }));
  };

  handlePlannedItemClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  renderMenuItem = (item, key) => {
    if (this.props.menuItems) {
      if (item.planned === true) {
        return (
          <li key={key}>
            <span
              className="nav-link list-b lux-nav__child lux-nav__child--planned lux-nav__child--disabled"
              role="menuitem"
              aria-disabled="true"
              title={`${item.name} (coming soon)`}
              onClick={this.handlePlannedItemClick}
            >
              <span>{item.name}</span>
              <PlannedMenuIndicator label="Planned feature" />
            </span>
          </li>
        );
      }

      const isActive = this.pathMatchesItem(this.getSelectionPath(), item.path);
      return (
        <li className={isActive ? "active" : ""} key={key}>
          <NavLink
            to={item.path}
            className={classNames("nav-link list-b lux-nav__child", {
              active: isActive,
            })}
            title={item.name}
            onClick={this.handleNavClick(item.path)}
          >
            <span>{item.name}</span>
          </NavLink>
        </li>
      );
    }

    const legacyPath = item.layout + item.path;
    const isActive = this.pathMatchesItem(this.getSelectionPath(), legacyPath);
    return (
      <li className={isActive ? "active" : ""} key={key}>
        <NavLink
          to={legacyPath}
          className={classNames("nav-link list-b lux-nav__child", {
            active: isActive,
          })}
          onClick={this.handleNavClick(legacyPath)}
        >
          <span>{item.name}</span>
        </NavLink>
      </li>
    );
  };

  render() {
    const isExpanded = this.isExpanded();
    const visibleItems = this.getVisibleItems();
    const childCount = visibleItems.length;

    if (childCount === 0) {
      return null;
    }

    return (
      <li className={classNames("lux-nav__group", { active: isExpanded })}>
        <a
          href="#sidebar"
          className="has-arrow arrow-c lux-nav__parent"
          aria-expanded={isExpanded}
          onClick={this.handleToggle}
        >
          <span className="lux-nav__icon">
            <i className={this.props.icon} />
          </span>
          <span className="lux-nav__label">{this.props.menuName}</span>
          <span className="lux-nav__count">{childCount}</span>
        </a>
        <ul
          className={isExpanded ? "collapse in lux-nav__children" : "collapse lux-nav__children"}
          aria-expanded={isExpanded}
        >
          {visibleItems.map((item, key) => this.renderMenuItem(item, key))}
        </ul>
      </li>
    );
  }
}

export default Menu;
