import React from "react";
import classNames from "classnames/bind";
import { getHookStatusMeta } from "config/onboarding.hooks";
import { LIFECYCLE_HOOK_STATUSES } from "config/onboarding.schema";

function LifecycleHookBanner({ task, lifecycle = "onboarding" }) {
  if (!task || !task.hookStatus || task.hookStatus === LIFECYCLE_HOOK_STATUSES.NOT_APPLICABLE) {
    return null;
  }

  const meta = getHookStatusMeta(task.hookStatus);
  const isFailed = task.hookStatus === LIFECYCLE_HOOK_STATUSES.FAILED;
  const isPending = task.hookStatus === LIFECYCLE_HOOK_STATUSES.PENDING;

  return (
    <div
      className={classNames("lux-onb-hook-banner", `is-${meta.tone}`, {
        "is-failed": isFailed,
        "is-pending": isPending,
      })}
      role="status"
    >
      <span className="lux-onb-hook-banner__icon" aria-hidden>
        <i className={`fe ${isFailed ? "fe-alert-triangle" : isPending ? "fe-clock" : "fe-link"}`} />
      </span>
      <div className="lux-onb-hook-banner__copy">
        <strong>{meta.label}</strong>
        <span>
          {task.integrationType
            ? `${task.integrationType}${task.integrationRef ? ` · ${task.integrationRef}` : ""}`
            : lifecycle === "offboarding"
              ? "Exit integration hook"
              : "Onboarding integration hook"}
        </span>
        {task.hookLastError && <span className="lux-onb-hook-banner__error">{task.hookLastError}</span>}
      </div>
    </div>
  );
}

export default LifecycleHookBanner;
