import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isComplianceExportAdminEnabled } from "config/compliance-pack.config";
import {
  buildCompliancePackInsights,
  buildCompliancePackMetrics,
  buildComplianceReadinessSeries,
  buildComplianceVolumeSeries,
  filterCompliancePackSections,
  toggleComplianceSectionSelection,
} from "config/compliance-pack.utils";
import { compliancePackService } from "_services/compliancePack.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import CompliancePackRegister from "views/admin/components/CompliancePackRegister";
import CompliancePackDetailPanel from "views/admin/components/CompliancePackDetailPanel";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

class ComplianceExportPage extends Component {
  state = {
    sections: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    selectedIds: [],
    selectedSectionId: null,
    exporting: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Compliance export");
    this.loadSections();
  }

  loadSections = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await compliancePackService.listSections();
      const sections = result.payload || [];
      const defaultSelected = sections.filter((row) => row.ready).map((row) => row.id);
      this.setState({
        sections,
        loading: false,
        dataSource: result.source || null,
        selectedIds: this.state.selectedIds.length ? this.state.selectedIds : defaultSelected,
        selectedSectionId: this.state.selectedSectionId || (sections[0] && sections[0].id) || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load compliance pack sections.",
        sections: [],
      });
    }
  };

  getFilteredSections = () => {
    return filterCompliancePackSections(this.state.sections, this.state.query);
  };

  getSelectedSection = () => {
    const { sections, selectedSectionId } = this.state;
    return sections.find((row) => row.id === selectedSectionId) || null;
  };

  handleToggleSection = (sectionId) => {
    this.setState((prev) => ({
      selectedIds: toggleComplianceSectionSelection(prev.selectedIds, sectionId),
      selectedSectionId: sectionId,
    }));
  };

  handleSelectAll = () => {
    const { sections } = this.state;
    this.setState({ selectedIds: sections.map((row) => row.id) });
  };

  handleClearSelection = () => {
    this.setState({ selectedIds: [] });
  };

  handleExport = async () => {
    const { selectedIds } = this.state;
    if (!selectedIds.length) return;
    this.setState({ exporting: true });
    try {
      await compliancePackService.exportPack(selectedIds);
    } catch (e) {
      this.setState({ loadError: "Unable to generate compliance pack." });
    } finally {
      this.setState({ exporting: false });
    }
  };

  render() {
    if (!isComplianceExportAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Compliance export"
          reason="Compliance pack export is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, query, selectedIds, exporting } = this.state;
    const filteredSections = this.getFilteredSections();
    const metrics = buildCompliancePackMetrics(this.state.sections);
    const insights = loading ? [] : buildCompliancePackInsights(this.state.sections, selectedIds);
    const readinessSeries = buildComplianceReadinessSeries(this.state.sections);
    const volumeSeries = buildComplianceVolumeSeries(this.state.sections);

    const kpiCards = [
      { id: "readiness", label: "Readiness", value: `${metrics.readinessPct}%`, hint: `${metrics.readySections}/${metrics.totalSections} sections`, tone: "green", icon: "fe fe-check-circle" },
      { id: "selected", label: "Selected", value: selectedIds.length, hint: "Included in export", tone: "primary", icon: "fe fe-layers" },
      { id: "records", label: "Records", value: metrics.recordCount.toLocaleString(), hint: "Across all domains", tone: "blue", icon: "fe fe-database" },
      { id: "gaps", label: "Gaps", value: metrics.notReady, hint: "Sections needing data", tone: metrics.notReady ? "amber" : "slate", icon: "fe fe-alert-triangle" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.compliance}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-compliance-export"
        className="lux-register-page lux-compliance-page"
        onRefresh={this.loadSections}
        refreshLoading={loading}
      >
        {loadError && (
          <div className="lux-employee-360__error lux-compliance__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadSections}>
              Retry
            </AdminActionButton>
          </div>
        )}

        <AdminInsightStrip insights={insights} />

        {!loading && (readinessSeries.length > 0 || volumeSeries.length > 0) && (
          <section className="lux-compliance-analytics lux-hrms-dash__panel">
            <AdminPanelHead title="Pack analytics" subtitle="Readiness posture and record volume by governance domain." />
            <div className="lux-compliance-analytics__grid">
              <PolicyAnalyticsBarChart title="Readiness mix" subtitle="Ready vs gaps" series={readinessSeries} />
              <PolicyAnalyticsBarChart title="Records by section" subtitle="Included domain volume" series={volumeSeries} />
            </div>
          </section>
        )}

        <section className="lux-hrms-dash__panel lux-compliance-panel">
          <AdminPanelHead
            title="Compliance pack builder"
            subtitle="Select sections to include. Export generates a signed JSON manifest with domain payloads."
            actions={
              <>
                <AdminPanelLink to="/admin/audit">Audit trail</AdminPanelLink>
                <button type="button" className="lux-admin-panel-link" onClick={this.handleClearSelection} disabled={!selectedIds.length}>
                  Clear selection
                </button>
              </>
            }
          />

          <div className="lux-compliance-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search pack sections"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{selectedIds.length}</strong> of <strong>{filteredSections.length}</strong> selected
              </span>
            </div>
          </div>

          <div className="lux-compliance-panel__body">
            <div className="lux-compliance-panel__grid">
              <div className="lux-compliance-panel__register">
                {loading ? (
                  <LuxRegisterEmptyState title="Loading sections" description="Fetching compliance pack registry." />
                ) : filteredSections.length === 0 ? (
                  <LuxRegisterEmptyState title="No sections match" description="Adjust search." />
                ) : (
                  <CompliancePackRegister
                    sections={filteredSections}
                    selectedIds={selectedIds}
                    onToggle={this.handleToggleSection}
                  />
                )}
              </div>
              <CompliancePackDetailPanel
                section={this.getSelectedSection()}
                selectedCount={selectedIds.length}
                exporting={exporting}
                onExport={this.handleExport}
              />
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default ComplianceExportPage;
