/** Section links rendered inside LuxModuleIntro hero (aligned with Workflow / Knowledge). */
export function PayrollHubNav({ className }) {
  return (
    <AdminHubTabs
      tabs={PAYROLL_HUB_TABS}
      ariaLabel="Payroll sections"
      className={classNames("lux-payroll-hub-nav", className)}
    />
  );
}

/**
 * Shared payroll page shell: hero with actions + section nav (no separate PageInnerHeader link row).
 */
export function PayrollLuxPage({
  pageMeta,
  dataSource,
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  testId,
  children,
  className,
  showHubNav = true,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "green",
    icon: "fe fe-dollar-sign",
    eyebrow: "Payroll",
    titleLead: "Payroll",
    titleAccent: "workspace",
    lede: "Runs, groups, structures, and employee finance.",
  };

  return (
    <div
      className={classNames(
        "lux-payroll-page",
        "lux-register-page",
        "lux-payroll-lux",
        meta.tone && `is-${meta.tone}`,
        className
      )}
      {...(testId ? { "data-testid": testId } : {})}
    >
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={showHubNav ? <PayrollHubNav /> : undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <PayrollKpiStrip cards={kpiCards} loading={loading} />
        ) : null}
        {children}
      </div>
    </div>
  );
}

export function PayrollHeroActions({ dataSource, demoLabel, children }) {
  useReportPageDataSource(dataSource);
  return (
    <div className="lux-payroll-hero__actions">
      <div className="lux-payroll-hero__buttons">{children}</div>
    </div>
  );
}

export function PayrollKpiStrip({ cards, loading, className }) {
  return (
    <LuxKpiStrip
      cards={cards}
      loading={loading}
      className={classNames("lux-payroll-kpi-strip", className)}
    />
  );
}

export function PayrollStatusBadge({ status }) {
  if (!status) {
    return <span className="lux-doc-badge is-slate">—</span>;
  }
  return (
    <span className={classNames("lux-doc-badge", `is-${getPayrollRunStatusTone(status)}`)}>
      {status}
    </span>
  );
}

export function PayrollQuickNav({ links = PAYROLL_QUICK_LINKS }) {
  return (
    <section className="lux-payroll-quick-nav" aria-label="Payroll quick navigation">
      <header className="lux-hrms-dash__section-head">
        <div>
          <span className="lux-hrms-dash__section-eyebrow">Navigate</span>
          <h2 className="lux-hrms-dash__section-title">Payroll workspace</h2>
        </div>
      </header>
      <div className="lux-hrms-dash__quick-grid">
        {links.map((item) => (
          <Link
            key={item.path}
            to={item.path}
            className={classNames(
              "lux-hrms-dash__quick-card lux-payroll-quick-card",
              item.tone && `is-${item.tone}`
            )}
          >
            <span className="lux-hrms-dash__quick-icon">
              <i className={item.icon} aria-hidden="true" />
            </span>
            <span className="lux-hrms-dash__quick-label">{item.label}</span>
            <span className="lux-payroll-quick-card__desc">{item.desc}</span>
          </Link>
        ))}
      </div>
    </section>
  );
}

export function PayrollLifecycleStepper({ status }) {
  const steps = buildPayrollRunLifecycleSteps(status);
  return (
    <nav className="lux-payroll-lifecycle" aria-label="Payroll run lifecycle">
      <ol className="lux-payroll-lifecycle__steps">
        {steps.map((step, index) => (
          <li
            key={step.id}
            className={classNames("lux-payroll-lifecycle__step", `is-${step.state}`)}
          >
            <span className="lux-payroll-lifecycle__marker" aria-hidden="true">
              {step.state === "complete" ? <i className="fe fe-check" /> : index + 1}
            </span>
            <span className="lux-payroll-lifecycle__label">{step.label}</span>
          </li>
        ))}
      </ol>
    </nav>
  );
}

export function PayrollActionButton({
  to,
  onClick,
  children,
  icon,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
  form,
  title,
  "data-testid": dataTestId,
}) {
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );

  if (to) {
    return (
      <Link
        to={to}
        className={classNames("lux-onb-action", "lux-payroll-action", `lux-onb-action--${variant}`, className)}
        data-testid={dataTestId}
      >
        {content}
      </Link>
    );
  }

  const classes = classNames("lux-onb-action lux-payroll-action", `lux-onb-action--${variant}`, className);
  return (
    <button
      type={type}
      className={classes}
      onClick={onClick}
      disabled={disabled}
      form={form}
      title={title}
      data-testid={dataTestId}
    >
      {content}
    </button>
  );
}

export function PayrollPanelLink({ to, onClick, children }) {
  if (to) {
    return (
      <Link to={to} className="lux-payroll-panel-link">
        {children}
        <i className="fe fe-arrow-right" aria-hidden="true" />
      </Link>
    );
  }
  return (
    <button type="button" className="lux-payroll-panel-link" onClick={onClick}>
      {children}
      <i className="fe fe-arrow-right" aria-hidden="true" />
    </button>
  );
}

export function PayrollPanelHead({ title, subtitle, actions, children }) {
  return (
    <header className={classNames("lux-hrms-dash__panel-head", { "lux-hrms-dash__panel-head--stack": subtitle })}>
      <div>
        <h2 className="lux-hrms-dash__panel-title">{title}</h2>
        {subtitle && <p className="lux-hrms-dash__panel-sub">{subtitle}</p>}
        {children}
      </div>
      {actions && <div className="lux-hrms-dash__panel-actions">{actions}</div>}
    </header>
  );
}
