/**
 * Auth fit-to-height.
 *
 * The login screen has to fit the viewport on every display: no scrollbars and
 * nothing clipped. The stylesheet owns the composition; this measures the
 * natural height of the brand column and of the login card content and
 * publishes a scale factor (--auth-brand-fit / --auth-card-fit) for it to use.
 *
 * offsetHeight is read on purpose: it reports the untransformed layout height,
 * so measuring an already scaled element cannot drift or feed back on itself.
 */

const TARGETS = [
    {
        box: ".auth-screen__brand",
        content: ".auth-screen__brand-content",
        prop: "--auth-brand-fit",
        minScale: 0.55,
    },
    {
        box: ".auth-login__card-inner",
        content: ".auth-login__fit",
        prop: "--auth-card-fit",
        minScale: 0.6,
    },
];

const contentBoxHeight = (el) => {
    const styles = window.getComputedStyle(el);
    const padding = (parseFloat(styles.paddingTop) || 0) + (parseFloat(styles.paddingBottom) || 0);
    return el.clientHeight - padding;
};

const scaleFor = (available, natural, minScale) => {
    if (!natural || available <= 0 || available >= natural) {
        return 1;
    }
    return Math.max(minScale, Math.floor((available / natural) * 1000) / 1000);
};

const startAuthFitScale = () => {
    if (typeof window === "undefined" || typeof document === "undefined") {
        return () => {};
    }

    let frame = 0;
    let stopped = false;
    let resizeObserver = null;
    const watched = new Set();

    const watch = (el) => {
        if (!resizeObserver || !el || watched.has(el)) {
            return;
        }
        watched.add(el);
        resizeObserver.observe(el);
    };

    const measure = () => {
        frame = 0;
        TARGETS.forEach(({ box, content, prop, minScale }) => {
            const boxEl = document.querySelector(box);
            const contentEl = document.querySelector(content);
            if (!boxEl || !contentEl) {
                return;
            }
            watch(boxEl);
            watch(contentEl);
            const scale = scaleFor(contentBoxHeight(boxEl), contentEl.offsetHeight, minScale);
            boxEl.style.setProperty(prop, String(scale));
        });
    };

    const schedule = () => {
        if (stopped || frame) {
            return;
        }
        frame = window.requestAnimationFrame(measure);
    };

    if (typeof ResizeObserver === "function") {
        resizeObserver = new ResizeObserver(schedule);
    }

    // Login content mounts after the shell, and banners/validation change height later.
    const mutationObserver = new MutationObserver(schedule);
    mutationObserver.observe(document.body, { childList: true, subtree: true });

    window.addEventListener("resize", schedule);
    window.addEventListener("orientationchange", schedule);
    if (document.fonts && document.fonts.ready && typeof document.fonts.ready.then === "function") {
        document.fonts.ready.then(schedule).catch(() => {});
    }
    schedule();

    return () => {
        stopped = true;
        if (frame) {
            window.cancelAnimationFrame(frame);
        }
        window.removeEventListener("resize", schedule);
        window.removeEventListener("orientationchange", schedule);
        mutationObserver.disconnect();
        if (resizeObserver) {
            resizeObserver.disconnect();
        }
        TARGETS.forEach(({ box, prop }) => {
            const boxEl = document.querySelector(box);
            if (boxEl) {
                boxEl.style.removeProperty(prop);
            }
        });
    };
};

export default startAuthFitScale;
