import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";

class ReactionInput extends Component {
  onChange = (value) => {
    this.props.onChange({ ...this.props.questionConfig, answer: value });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card">
          <div className="reactions">
            <LuxFeedbackQuestionLabel questionConfig={questionConfig} as="p" />
            <div className="reaction_inner">
              <EmojiImage
                name="Cool"
                image="cool"
                onChange={this.onChange}
                value={questionConfig.answer || ""}
                readonly={readonly}
              />
              <EmojiImage
                name="Sad"
                image="sad"
                onChange={this.onChange}
                value={questionConfig.answer || ""}
                readonly={readonly}
              />
              <EmojiImage
                name="Shock"
                image="shock"
                onChange={this.onChange}
                value={questionConfig.answer || ""}
                readonly={readonly}
              />
              <EmojiImage
                name="Wink"
                image="wink"
                onChange={this.onChange}
                value={questionConfig.answer || ""}
                readonly={readonly}
              />
              <EmojiImage
                name="Happy"
                image="happy"
                onChange={this.onChange}
                value={questionConfig.answer || ""}
                readonly={readonly}
              />
            </div>
            <div className="info-text">
              <i className="fa fa-solid fa-circle-info" aria-hidden="true" />
              <h5>
                Your mood selection helps us understand the overall sentiment of this
                engagement alongside your detailed ratings.
              </h5>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

class EmojiImage extends Component {
  constructor() {
    super();
    this.state = { mouseOver: false };
  }

  onMouseOver = () => {
    if (this.props.readonly === false) {
      this.setState({ mouseOver: true });
    }
  };

  onMouseOut = () => {
    if (this.props.readonly === false) {
      this.setState({ mouseOver: false });
    }
  };

  getImageName = () => {
    return this.props.image + (this.state.mouseOver === true ? ".gif" : ".png");
  };

  onChange = () => {
    if (this.props.readonly === false) {
      this.props.onChange(this.props.name);
    }
  };

  render() {
    const selected =
      this.state.mouseOver === true || this.props.value === this.props.name;
    return (
      <div
        className="emoji"
        onMouseOver={this.onMouseOver}
        onMouseOut={this.onMouseOut}
        onClick={this.onChange}
        role="button"
        tabIndex={this.props.readonly ? -1 : 0}
        aria-pressed={this.props.value === this.props.name}
        aria-label={this.props.name}
      >
        <div className={`emoji_img ${selected ? "colorgreen" : ""}`}>
          <img src={`/assets/images/custom/emoji/${this.getImageName()}`} alt="" />
        </div>
        <span>{this.props.name}</span>
      </div>
    );
  }
}
export default ReactionInput;
