export function isLiveApprovalDomain(domainId) {
  const normalized = String(domainId || "").toUpperCase();
  const entry = LIVE_APPROVAL_DOMAIN_REGISTRY.find((row) => row.id === normalized);
  return Boolean(entry && entry.live === true);
}

export function getLiveApprovalDomains() {
  return LIVE_APPROVAL_DOMAIN_REGISTRY.filter((row) => row.live === true);
}

export function isLifecycleApprovalTask(task) {
  if (!task) {
    return false;
  }
  if (task.status === "completed" || task.status === "skipped") {
    return false;
  }
  if (task.requiresApproval === true) {
    return true;
  }
  if (task.assigneeType === "manager") {
    return task.status === "pending" || task.status === "in_progress" || task.status === "blocked";
  }
  const title = String(task.title || "").toLowerCase();
  if (title.indexOf("approval") >= 0 || title.indexOf("settlement") >= 0) {
    return task.status === "pending" || task.status === "in_progress" || task.status === "blocked";
  }
  return false;
}

export function extractLifecycleApprovalItems(cases, domain) {
  const rows = cases || [];
  const items = [];

  rows.forEach((caseData) => {
    if (!caseData || !Array.isArray(caseData.tasks)) {
      return;
    }
    caseData.tasks.forEach((task) => {
      if (!isLifecycleApprovalTask(task)) {
        return;
      }
      const normalized = normalizeLifecycleApprovalItem(caseData, task, domain);
      if (normalized) {
        items.push(normalized);
      }
    });
  });

  return items;
}

export function normalizeLiveLeaveRows(rows) {
  return (rows || [])
    .map((row) => normalizeLeaveApprovalItem(row))
    .filter(Boolean);
}

export function normalizeLiveTimesheetRows(rows) {
  return (rows || [])
    .map((row) => normalizeTimesheetApprovalItem(row))
    .filter(Boolean);
}

export function normalizeLiveRegularizationRows(rows) {
  return (rows || [])
    .map((row) => normalizeRegularizationApprovalItem(row))
    .filter(Boolean);
}

export function mergeLiveApprovalResults(resultSets) {
  const items = [];
  (resultSets || []).forEach((set) => {
    if (Array.isArray(set)) {
      set.forEach((item) => {
        if (item) {
          items.push(item);
        }
      });
    }
  });
  return items;
}
