import React from "react";
import { KnowledgeLuxPanel } from "views/knowledge/components/KnowledgeLuxShared";

function AiRcaContent({ draft }) {
  return (
    <>
      <p className="lux-krca-ai-summary">{draft.summary}</p>
      {draft.rootCauseHint ? (
        <div className="lux-krca-ai-hint">
          <strong>Root cause hint</strong>
          <p>{draft.rootCauseHint}</p>
        </div>
      ) : null}
      <ul className="lux-krca-ai-list">
        {(draft.correctiveActions || []).map((line, index) => (
          <li key={`c-${index}`}>
            <i className="fe fe-tool" aria-hidden="true" />
            Corrective: {line}
          </li>
        ))}
        {(draft.preventiveActions || []).map((line, index) => (
          <li key={`p-${index}`}>
            <i className="fe fe-shield" aria-hidden="true" />
            Preventive: {line}
          </li>
        ))}
      </ul>
      <p className="lux-krca-ai-confidence">
        <span>Confidence</span>
        <strong>{Math.round((draft.confidence || 0) * 100)}%</strong>
      </p>
    </>
  );
}

export default function KnowledgeAiRcaPanel({ draft, loading, embedded }) {
  if (loading) {
    if (embedded) {
      return (
        <section className="lux-krca-ai lux-krca-ai--embedded">
          <div className="lux-krca-skeleton lux-krca-skeleton--panel" />
        </section>
      );
    }
    return (
      <KnowledgeLuxPanel title="AI RCA suggestions" meta="Loading suggestions…" icon="fe fe-cpu" accent="violet">
        <div className="lux-krca-skeleton lux-krca-skeleton--panel" />
      </KnowledgeLuxPanel>
    );
  }

  if (!draft) {
    return null;
  }

  if (embedded) {
    return (
      <section className="lux-krca-ai lux-krca-ai--embedded">
        <header>
          <i className="fe fe-cpu" aria-hidden="true" />
          AI RCA suggestions
        </header>
        <AiRcaContent draft={draft} />
      </section>
    );
  }

  return (
    <KnowledgeLuxPanel title="AI RCA suggestions" meta="Human approval required" icon="fe fe-cpu" accent="violet">
      <AiRcaContent draft={draft} />
    </KnowledgeLuxPanel>
  );
}
