export const REGISTER_DEFAULT_PAGE_SIZE = 25;
export const REGISTER_PAGE_SIZE_OPTIONS = [10, 25, 50, 100];

/** Hide register pagination when everything fits the default page (25) or a single page. */
export function shouldShowRegisterPagination(
  pagination,
  minTotal = REGISTER_DEFAULT_PAGE_SIZE
) {
  if (!pagination || pagination.total <= 0) return false;
  if (pagination.total < minTotal) return false;
  if (pagination.totalPages <= 1) return false;
  return true;
}

export function paginateRegisterList(items, page, pageSize = REGISTER_DEFAULT_PAGE_SIZE) {
  const list = items || [];
  const total = list.length;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const start = (safePage - 1) * pageSize;

  return {
    items: list.slice(start, start + pageSize),
    page: safePage,
    pageSize,
    total,
    totalPages,
    rangeStart: total === 0 ? 0 : start + 1,
    rangeEnd: Math.min(start + pageSize, total),
  };
}

function formatDateRangeKey(dateRangeValue) {
  if (!dateRangeValue || !dateRangeValue.start || !dateRangeValue.end) return "";
  const start =
    typeof dateRangeValue.start.format === "function"
      ? dateRangeValue.start.format("YYYY-MM-DD")
      : String(dateRangeValue.start);
  const end =
    typeof dateRangeValue.end.format === "function"
      ? dateRangeValue.end.format("YYYY-MM-DD")
      : String(dateRangeValue.end);
  return `${start}|${end}`;
}

function getFilterShowSelected(filterOptions) {
  return filterOptions && filterOptions.SHOW ? filterOptions.SHOW.selected : undefined;
}

function getFilterSortSelected(filterOptions) {
  return filterOptions && filterOptions.SORT ? filterOptions.SORT.selected : undefined;
}

export function shouldResetRegisterPage(prev, next) {
  const prevFilter = prev.filterOptions;
  const nextFilter = next.filterOptions;
  const filterChanged =
    prevFilter !== nextFilter &&
    (prevFilter == null ||
      nextFilter == null ||
      getFilterShowSelected(prevFilter) !== getFilterShowSelected(nextFilter) ||
      getFilterSortSelected(prevFilter) !== getFilterSortSelected(nextFilter) ||
      (prevFilter && prevFilter.filterText) !== (nextFilter && nextFilter.filterText) ||
      formatDateRangeKey(prevFilter && prevFilter.dateRangeValue) !==
        formatDateRangeKey(nextFilter && nextFilter.dateRangeValue));

  const countChanged = (prev.items || []).length !== (next.items || []).length;
  return filterChanged || countChanged;
}
