const STORAGE_PREFIX = 'lux-audit-panel:';

export function readAuditPanelPrefs(panelKey) {
  if (!panelKey || typeof window === 'undefined') {
    return {};
  }
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}${panelKey}`);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch (e) {
    return {};
  }
}

export function writeAuditPanelPrefs(panelKey, patch) {
  if (!panelKey || typeof window === 'undefined') {
    return;
  }
  const current = readAuditPanelPrefs(panelKey);
  try {
    localStorage.setItem(
      `${STORAGE_PREFIX}${panelKey}`,
      JSON.stringify({ ...current, ...patch })
    );
  } catch (e) {
    // ignore quota errors
  }
}

export function readAuditPanelExpanded(panelKey, defaultExpanded = false) {
  const prefs = readAuditPanelPrefs(panelKey);
  if (typeof prefs.expanded === 'boolean') {
    return prefs.expanded;
  }
  return defaultExpanded;
}

export function readAuditPanelEntityFilter(panelKey, fallback = 'ALL') {
  const prefs = readAuditPanelPrefs(panelKey);
  return prefs.entityFilter || fallback;
}

export function readAuditPanelActionFilter(panelKey, fallback = 'ALL') {
  const prefs = readAuditPanelPrefs(panelKey);
  return prefs.actionFilter || fallback;
}
