import React, { Component } from "react";
import { recruitingService } from "_services/recruiting/recruiting.service";
import RecruitingLuxPage, {
  RecruitingActionButton,
  RecruitingLuxPanel,
} from "views/recruiting/components/RecruitingLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class RequisitionsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { title: "", roleTitle: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Requisitions");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await recruitingService.listRequisitions();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load requisitions"),
      });
    }
  };

  runRequisitionAction = async (actionPromise, failLabel) => {
    this.setState({ loadError: null });
    const result = await actionPromise;
    if (result && result.source === "api") {
      await this.load();
      return;
    }
    this.setState({
      loadError: (result && result.error) || new Error(failLabel),
    });
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.title) return;
    this.setState({ saving: true });
    const result = await recruitingService.createRequisition({
      title: form.title,
      roleTitle: form.roleTitle || null,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { title: "", roleTitle: "" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <RecruitingLuxPage
        testId="recruiting-requisitions-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        loading={loading}
        onRefresh={this.load}
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-file-text",
          eyebrow: "People · ATS",
          titleLead: "Job",
          titleAccent: "requisitions",
          lede: "Create and advance requisitions through draft, submit, and approval.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Requisition action unavailable">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <RecruitingLuxPanel title="Create requisition" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-4">
                <input
                  className="form-control"
                  placeholder="Title"
                  value={form.title}
                  onChange={(e) => this.setState({ form: { ...form, title: e.target.value } })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Role title"
                  value={form.roleTitle}
                  onChange={(e) => this.setState({ form: { ...form, roleTitle: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <RecruitingActionButton type="submit" disabled={saving}>
                  Create DRAFT
                </RecruitingActionButton>
              </div>
            </div>
          </form>
        </RecruitingLuxPanel>
        <RecruitingLuxPanel title="Requisitions" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No requisitions yet"
              description="Create a draft requisition to start the ATS pipeline."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Title</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.requisitionRef || r.id}>
                      <td>{r.requisitionRef}</td>
                      <td>{r.title}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(r.status || "draft").toLowerCase()}`}>
                          {r.status || "Draft"}
                        </span>
                      </td>
                      <td>
                        {r.status === "DRAFT" || r.status === "OPEN" ? (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              this.runRequisitionAction(
                                recruitingService.submitRequisition(r.requisitionRef),
                                "Unable to submit requisition"
                              )
                            }
                          >
                            Submit
                          </RecruitingActionButton>
                        ) : null}
                        {r.status === "SUBMITTED" ? (
                          <>
                            <RecruitingActionButton
                              type="button"
                              variant="ghost"
                              className="lux-onb-action--compact"
                              onClick={() =>
                                this.runRequisitionAction(
                                  recruitingService.approveRequisition(r.requisitionRef),
                                  "Unable to approve requisition"
                                )
                              }
                            >
                              Approve
                            </RecruitingActionButton>
                            <RecruitingActionButton
                              type="button"
                              variant="ghost"
                              className="lux-onb-action--compact"
                              onClick={() =>
                                this.runRequisitionAction(
                                  recruitingService.rejectRequisition(r.requisitionRef),
                                  "Unable to reject requisition"
                                )
                              }
                            >
                              Reject
                            </RecruitingActionButton>
                          </>
                        ) : null}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </RecruitingLuxPanel>
      </RecruitingLuxPage>
    );
  }
}

export default RequisitionsPage;
