import React, { Component } from "react";
import { connect } from "react-redux";
import { bidRequestsActions } from "_actions";
import CreateBidRequestsSidebarSection from "./CreateBidRequestsSidebarSection";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";

class CreateBidRequestsSidebar extends Component {
  render() {
    const { editMode, duplicateMode, show } = this.props;
    const ready =
      show &&
      ((editMode && this.props.selectedBidRequestsInfo) ||
        (duplicateMode && this.props.selectedBidRequestsInfo) ||
        (!editMode && !duplicateMode));

    const title = editMode
      ? "Update bid request"
      : duplicateMode
      ? "Duplicate bid request"
      : "Create bid request";

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={this.props.closeActionHandler}
        panelId="createbidRequestsidebar"
        className="lux-create-panel--bid create_bid_request_right_sidebar"
        kicker="Sales workspace"
        title={title}
        subtitle={
          editMode || duplicateMode
            ? "Same data whether you use full form or guided steps."
            : "Full form for speed, or guided steps with progress tracking."
        }
      >
        {ready && (
          <CreateBidRequestsSidebarSection
            handleSubmit={this.props.handleSubmit}
            editMode={editMode}
            duplicateMode={duplicateMode}
            selectedBidRequestsInfo={this.props.selectedBidRequestsInfo}
          />
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  fieldConfig: state.bidRequests.fieldConfig,
  createConfig: state.bidRequests.createConfig,
  allEmployees: state.employees.allEmployees,
  creating: state.bidRequests.creating,
  updating: state.bidRequests.updating,
  screeningQuestions: state.bidRequests.screeningQuestions,
  additionalQuestions: state.bidRequests.additionalQuestions,
  quotaInformation: state.bidRequests.quotaInformation,
  studyTypeConfig: state.bidRequests.studyTypeConfig,
});

const mapDispatchToProps = (dispatch) => ({
  getModuleConfig: bidRequestsActions.getModuleConfig,
});

export default connect(mapStateToProps, mapDispatchToProps)(CreateBidRequestsSidebar);
