import React, { Component } from "react";
import classNames from "classnames/bind";
import { SIMULATION_ADJUSTMENT_TYPES } from "config/resource-planning.config";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import SimulationAdjustmentList from "views/resources/components/SimulationAdjustmentList";

const SHIFT_PRESETS = [-20, -10, 10];

class SimulationScenarioPanel extends Component {
  state = {
    addMode: "FULFILL",
    selectedRequestId: "",
    selectedBenchId: "",
    selectedAllocationId: "",
    benchProjectName: "Aurora Platform Modernization",
    benchAllocationPct: 80,
    shiftDelta: -10,
  };

  componentDidUpdate(prevProps) {
    const { staffingRequests, benchRecords, allocations } = this.props;
    if (staffingRequests !== prevProps.staffingRequests && !this.state.selectedRequestId) {
      const first = (staffingRequests || [])[0];
      if (first) {
        this.setState({ selectedRequestId: first.id });
      }
    }
    if (benchRecords !== prevProps.benchRecords && !this.state.selectedBenchId) {
      const first = (benchRecords || []).find((row) => row.status === "ON_BENCH");
      if (first) {
        this.setState({ selectedBenchId: first.id });
      }
    }
    if (allocations !== prevProps.allocations && !this.state.selectedAllocationId) {
      const first = (allocations || [])[0];
      if (first) {
        this.setState({ selectedAllocationId: first.id });
      }
    }
  }

  loadTemplate = (template) => {
    const { onAdjustmentsChange, onRun } = this.props;
    if (onAdjustmentsChange) {
      onAdjustmentsChange(template.adjustments || [], template.name);
    }
    if (onRun) {
      onRun(template.adjustments || [], template.name);
    }
  };

  addAdjustment = () => {
    const { adjustments, onAdjustmentsChange } = this.props;
    const {
      addMode,
      selectedRequestId,
      selectedBenchId,
      selectedAllocationId,
      benchProjectName,
      benchAllocationPct,
      shiftDelta,
    } = this.state;
    let next = null;

    if (addMode === "FULFILL" && selectedRequestId) {
      next = { type: SIMULATION_ADJUSTMENT_TYPES.FULFILL_REQUEST, requestId: selectedRequestId };
    } else if (addMode === "BENCH" && selectedBenchId) {
      next = {
        type: SIMULATION_ADJUSTMENT_TYPES.PLACE_BENCH,
        benchId: selectedBenchId,
        projectName: benchProjectName,
        allocationPct: benchAllocationPct,
      };
    } else if (addMode === "SHIFT" && selectedAllocationId) {
      next = {
        type: SIMULATION_ADJUSTMENT_TYPES.SHIFT_ALLOCATION,
        allocationId: selectedAllocationId,
        deltaPct: shiftDelta,
      };
    }

    if (!next || !onAdjustmentsChange) {
      return;
    }
    onAdjustmentsChange([...(adjustments || []), next]);
  };

  renderAddForm() {
    const { staffingRequests, benchRecords, allocations } = this.props;
    const {
      addMode,
      selectedRequestId,
      selectedBenchId,
      selectedAllocationId,
      benchProjectName,
      benchAllocationPct,
      shiftDelta,
    } = this.state;
    const openRequests = (staffingRequests || []).filter(
      (row) => row.status === "Pending" || row.status === "Approved"
    );
    const benchPool = (benchRecords || []).filter(
      (row) => row.status === "ON_BENCH" || row.status === "PARTIAL" || row.status === "ROLLING_OFF"
    );

    return (
      <div className="lux-simulation-panel__add">
        <div className="lux-simulation-panel__mode-tabs">
          {[
            { id: "FULFILL", label: "Fulfill request", icon: "fe fe-check-circle" },
            { id: "BENCH", label: "Place bench", icon: "fe fe-user-plus" },
            { id: "SHIFT", label: "Shift allocation", icon: "fe fe-shuffle" },
          ].map((tab) => (
            <button
              key={tab.id}
              type="button"
              className={classNames("lux-simulation-panel__mode-tab", { "is-active": addMode === tab.id })}
              onClick={() => this.setState({ addMode: tab.id })}
            >
              <i className={tab.icon} aria-hidden="true" />
              {tab.label}
            </button>
          ))}
        </div>

        {addMode === "FULFILL" && (
          <label className="lux-simulation-panel__field">
            <span>Staffing request</span>
            <select
              className="lux-simulation-panel__select"
              value={selectedRequestId}
              onChange={(event) => this.setState({ selectedRequestId: event.target.value })}
            >
              {openRequests.map((row) => (
                <option key={row.id} value={row.id}>
                  {row.title} ({row.headcount} role{row.headcount === 1 ? "" : "s"})
                </option>
              ))}
            </select>
          </label>
        )}

        {addMode === "BENCH" && (
          <div className="lux-simulation-panel__grid">
            <label className="lux-simulation-panel__field">
              <span>Bench consultant</span>
              <select
                className="lux-simulation-panel__select"
                value={selectedBenchId}
                onChange={(event) => this.setState({ selectedBenchId: event.target.value })}
              >
                {benchPool.map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.employeeName} ({row.availabilityPct}% free)
                  </option>
                ))}
              </select>
            </label>
            <label className="lux-simulation-panel__field">
              <span>Target project</span>
              <input
                type="text"
                className="lux-simulation-panel__input"
                value={benchProjectName}
                onChange={(event) => this.setState({ benchProjectName: event.target.value })}
              />
            </label>
            <label className="lux-simulation-panel__field">
              <span>Allocation %</span>
              <input
                type="number"
                min={10}
                max={100}
                step={10}
                className="lux-simulation-panel__input"
                value={benchAllocationPct}
                onChange={(event) =>
                  this.setState({ benchAllocationPct: Number(event.target.value) || 80 })
                }
              />
            </label>
          </div>
        )}

        {addMode === "SHIFT" && (
          <div className="lux-simulation-panel__grid">
            <label className="lux-simulation-panel__field is-wide">
              <span>Allocation</span>
              <select
                className="lux-simulation-panel__select"
                value={selectedAllocationId}
                onChange={(event) => this.setState({ selectedAllocationId: event.target.value })}
              >
                {(allocations || []).map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.employeeName} · {row.projectName} ({row.allocationPct}%)
                  </option>
                ))}
              </select>
            </label>
            <div className="lux-simulation-panel__field is-wide">
              <span>Shift amount</span>
              <div className="lux-simulation-panel__presets">
                {SHIFT_PRESETS.map((preset) => (
                  <button
                    key={preset}
                    type="button"
                    className={classNames("lux-simulation-panel__preset", {
                      "is-active": shiftDelta === preset,
                    })}
                    onClick={() => this.setState({ shiftDelta: preset })}
                  >
                    {preset > 0 ? "+" : ""}
                    {preset}%
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        <ResourcesActionButton icon="fe fe-plus" variant="ghost" onClick={this.addAdjustment}>
          Add to scenario
        </ResourcesActionButton>
      </div>
    );
  }

  render() {
    const { templates, adjustments, context, scenarioName, onAdjustmentsChange, onRun, onRemoveAdjustment, running } =
      this.props;

    return (
      <section className="lux-simulation-panel">
        <div className="lux-simulation-panel__templates">
          <span className="lux-simulation-panel__section-label">Quick templates</span>
          <div className="lux-simulation-panel__template-grid">
            {(templates || []).map((template) => (
              <button
                key={template.id}
                type="button"
                className="lux-simulation-panel__template-card"
                onClick={() => this.loadTemplate(template)}
              >
                <strong>{template.name}</strong>
                <span>{template.description}</span>
              </button>
            ))}
          </div>
        </div>

        {this.renderAddForm()}

        <div className="lux-simulation-panel__queue">
          <div className="lux-simulation-panel__queue-head">
            <span className="lux-simulation-panel__section-label">Scenario queue</span>
            {scenarioName && <span className="lux-simulation-panel__scenario-name">{scenarioName}</span>}
          </div>
          <SimulationAdjustmentList
            adjustments={adjustments}
            context={context}
            onRemove={onRemoveAdjustment}
          />
        </div>

        <div className="lux-simulation-panel__actions">
          <ResourcesActionButton
            variant="ghost"
            onClick={() => onAdjustmentsChange && onAdjustmentsChange([])}
            disabled={!adjustments || adjustments.length === 0}
          >
            Clear
          </ResourcesActionButton>
          <ResourcesActionButton
            icon="fe fe-play"
            variant="primary"
            onClick={() => onRun && onRun(adjustments, scenarioName)}
            disabled={running || !adjustments || adjustments.length === 0}
          >
            {running ? "Running…" : "Run scenario"}
          </ResourcesActionButton>
        </div>
      </section>
    );
  }
}

export default SimulationScenarioPanel;
