import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAnalyticsPlatformEnabled } from "config/analytics-platform.config";
import { analyticsPlatformService } from "_services/analyticsPlatform.service";
import AnalyticsLuxPage, {
  AnalyticsActionButton,
  AnalyticsDomainGrid,
  AnalyticsInsightPanel,
  AnalyticsLuxPanel,
} from "views/analytics/components/AnalyticsLuxShared";

class AnalyticsHubPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    hub: null,
  };

  componentDidMount() {
    this.loadHub();
  }

  loadHub = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await analyticsPlatformService.getAnalyticsHub();
      this.setState({
        loading: false,
        hub: result.payload,
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load analytics hub.",
      });
    }
  };

  render() {
    if (!isAnalyticsPlatformEnabled()) {
      return <PersonaAccessDenied featureLabel="Analytics hub" />;
    }

    const { loading, loadError, hub, dataSource } = this.state;

    return (
      <AnalyticsLuxPage
        hub
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        dataSource={dataSource}
        demoLabel="Demo analytics hub"
        loading={loading}
        kpiCards={(hub && hub.kpiCards) || []}
        onRefresh={this.loadHub}
        refreshLoading={loading}
        heroActions={
          <>
            <AnalyticsActionButton to="/analytics/report-builder" icon="fe fe-edit-3" variant="ghost">
              Report builder
            </AnalyticsActionButton>
            <AnalyticsActionButton to="/analytics/scheduled-reports" icon="fe fe-clock" variant="ghost">
              Scheduled reports
            </AnalyticsActionButton>
            <AnalyticsActionButton to="/analytics/executive" icon="fe fe-bar-chart-2" variant="primary">
              Executive analytics
            </AnalyticsActionButton>
          </>
        }
      >
        <AnalyticsInsightPanel insights={(hub && hub.insights) || []} />
        {loadError ? (
          <AnalyticsLuxPanel title="Hub load issue" meta={loadError} accent="rose">
            <AnalyticsActionButton icon="fe fe-refresh-cw" variant="primary" onClick={this.loadHub}>
              Retry
            </AnalyticsActionButton>
          </AnalyticsLuxPanel>
        ) : null}

        <AnalyticsLuxPanel
          title="Domain dashboards"
          meta={hub ? `${hub.metricCount} metrics · ${hub.dashboardCount} dashboard configs` : "Analytics platform"}
          icon="fe fe-grid"
          accent="indigo"
        >
          <AnalyticsDomainGrid domains={(hub && hub.domains) || []} loading={loading} />
        </AnalyticsLuxPanel>
      </AnalyticsLuxPage>
    );
  }
}

export default AnalyticsHubPage;
