import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseDeveloperPortalApi } from "config/developer-portal.config";
import { normalizeDeveloperPortalOverview } from "config/developer-portal.utils";

import { apiErrorResult } from "config/mock-fallback.utils";

export const developerPortalService = {
  getOverview,
  listApiKeys,
  createApiKey,
  revokeApiKey,
  deleteApiKey,
  listWebhooks,
  createWebhook,
  createApp,
  listWebhookDeliveries,
  listMarketplaceListings,
  installMarketplaceListing,
  exportApiKeysCsv,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getOverview(filters) {
  if (!shouldUseDeveloperPortalApi()) {
    const result = apiErrorResult(null);
    return {
      ...result,
      payload: normalizeDeveloperPortalOverview(result && result.payload),
    };
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.DEVELOPER_PORTAL_API_PATH}/overview`,
    teamQuery(filters)
  );
  const raw = (response && response.payload) || response;
  return { payload: normalizeDeveloperPortalOverview(raw), source: "api" };
}

async function listApiKeys(filters) {
  if (!shouldUseDeveloperPortalApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.DEVELOPER_PORTAL_API_PATH}/api-keys`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

function apiKeyPath(keyId) {
  return `${urlConfig.DEVELOPER_PORTAL_API_PATH}/api-keys/${encodeURIComponent(keyId)}`;
}

async function revokeApiKey(keyId) {
  if (!shouldUseDeveloperPortalApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.post(
    `${apiKeyPath(keyId)}/revoke?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    {}
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

