import React, { useEffect, useState } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  ATTENDANCE_EXCEPTION_TYPES,
} from "config/attendance-regularization.config";

const POLICY_METRICS = [
  { key: "maxRequestsPerMonth", label: "Max requests / month", icon: "fe-repeat", format: (v) => (v != null ? v : "—") },
  { key: "allowBackdatedDays", label: "Backdate window", icon: "fe-calendar", format: (v) => (v != null ? `${v} days` : "—") },
  { key: "payrollLockDayOfMonth", label: "Payroll lock day", icon: "fe-lock", format: (v) => (v != null ? `Day ${v}` : "—") },
  {
    key: "requireManagerApproval",
    label: "Manager approval",
    icon: "fe-check-circle",
    format: (v) => (v === false ? "Optional" : "Required"),
  },
];

const EXCEPTION_ICONS = {
  MISSING_PUNCH: "fe-clock",
  LATE_ARRIVAL: "fe-watch",
  EARLY_DEPARTURE: "fe-log-out",
  WRONG_SHIFT: "fe-shuffle",
  WORK_FROM_HOME: "fe-home",
  ON_DUTY_TRAVEL: "fe-map-pin",
};

function toDraft(policy) {
  const p = policy || {};
  return {
    maxRequestsPerMonth: p.maxRequestsPerMonth != null ? Number(p.maxRequestsPerMonth) : 4,
    allowBackdatedDays: p.allowBackdatedDays != null ? Number(p.allowBackdatedDays) : 7,
    payrollLockDayOfMonth: p.payrollLockDayOfMonth != null ? Number(p.payrollLockDayOfMonth) : 25,
    requireManagerApproval: p.requireManagerApproval !== false,
    blockedExceptionCodes: Array.isArray(p.blockedExceptionCodes) ? [...p.blockedExceptionCodes] : [],
  };
}

export default function AttendanceExceptionPolicyPanel({
  policy,
  loading,
  canEdit = false,
  saving = false,
  saveError = null,
  onSave,
}) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(() => toDraft(policy));
  const [localError, setLocalError] = useState(null);

  useEffect(() => {
    if (!editing) {
      setDraft(toDraft(policy));
    }
  }, [policy, editing]);

  if (loading) {
    return (
      <section className="lux-att-policy is-loading" aria-busy="true" aria-label="Loading exception policy">
        <div className="lux-att-policy__skeleton" />
      </section>
    );
  }

  const p = policy || {};
  const display = editing ? draft : p;

  const toggleBlocked = (code) => {
    setDraft((prev) => {
      const blocked = new Set(prev.blockedExceptionCodes || []);
      if (blocked.has(code)) blocked.delete(code);
      else blocked.add(code);
      return { ...prev, blockedExceptionCodes: Array.from(blocked) };
    });
  };

  const handleSave = async () => {
    setLocalError(null);
    if (!onSave) return;
    if (!(draft.maxRequestsPerMonth > 0)) {
      setLocalError("Max requests per month must be greater than 0.");
      return;
    }
    if (draft.allowBackdatedDays < 0) {
      setLocalError("Backdate window cannot be negative.");
      return;
    }
    if (draft.payrollLockDayOfMonth < 1 || draft.payrollLockDayOfMonth > 28) {
      setLocalError("Payroll lock day must be between 1 and 28.");
      return;
    }
    try {
      await onSave(draft);
      setEditing(false);
    } catch (e) {
      setLocalError((e && e.message) || "Unable to save attendance policy.");
    }
  };

  return (
    <section className="lux-att-policy" aria-label="Attendance exception policy">
      <div className="lux-att-policy__glow" aria-hidden="true" />

      <header className="lux-att-policy__hero">
        <div className="lux-att-policy__hero-copy">
          <LuxSummaryEyebrow variant="attendance" className="lux-att-policy__eyebrow">
            Exception policy
          </LuxSummaryEyebrow>
          <h3 className="lux-att-policy__title">Regularization rules</h3>
          <p className="lux-att-policy__subtitle">
            Limits, payroll lock windows, and allowed exception types for your organization
          </p>
        </div>
        <div className="lux-att-policy__hero-actions">
          <div className="lux-att-policy__hero-badge">
            <i className="fe fe-shield" aria-hidden="true" />
            <span>{ATTENDANCE_EXCEPTION_TYPES.length} types</span>
          </div>
          {canEdit && !editing && (
            <button type="button" className="btn btn-sm btn-primary" onClick={() => setEditing(true)}>
              Configure policy
            </button>
          )}
        </div>
      </header>

      {(localError || saveError) && (
        <div className="alert alert-danger" role="alert">
          {localError || saveError}
        </div>
      )}

      <div className="lux-att-policy__metrics">
        {POLICY_METRICS.map((metric) => (
          <article key={metric.key} className="lux-att-policy__metric">
            <i className={classNames("fe", metric.icon)} aria-hidden="true" />
            <div>
              <span>{metric.label}</span>
              {editing ? (
                metric.key === "requireManagerApproval" ? (
                  <label className="lux-att-policy__edit-check">
                    <input
                      type="checkbox"
                      checked={draft.requireManagerApproval !== false}
                      onChange={(e) =>
                        setDraft((prev) => ({ ...prev, requireManagerApproval: e.target.checked }))
                      }
                    />
                    Required
                  </label>
                ) : (
                  <input
                    type="number"
                    className="form-control form-control-sm"
                    value={draft[metric.key]}
                    onChange={(e) =>
                      setDraft((prev) => ({
                        ...prev,
                        [metric.key]: e.target.value === "" ? "" : Number(e.target.value),
                      }))
                    }
                    aria-label={metric.label}
                  />
                )
              ) : (
                <strong>{metric.format(display[metric.key])}</strong>
              )}
            </div>
          </article>
        ))}
      </div>

      <section className="lux-att-policy__section">
        <header className="lux-att-policy__section-head">
          <h4>Allowed exception types</h4>
          <p>
            {editing
              ? "Toggle types to block or allow before manager approval"
              : "Each request is validated against these categories before manager approval"}
          </p>
        </header>

        <ul className="lux-att-policy__types">
          {ATTENDANCE_EXCEPTION_TYPES.map((type) => {
            const blocked = (display.blockedExceptionCodes || []).includes(type.code);
            return (
              <li
                key={type.code}
                className={classNames("lux-att-policy__type-card", {
                  "is-blocked": blocked,
                  "is-evidence": type.requiresEvidence && !blocked,
                })}
              >
                <div className="lux-att-policy__type-icon">
                  <i className={classNames("fe", EXCEPTION_ICONS[type.code] || "fe-alert-circle")} aria-hidden="true" />
                </div>
                <div className="lux-att-policy__type-copy">
                  <strong>{type.label}</strong>
                  <span>{type.code.replace(/_/g, " ")}</span>
                </div>
                <div className="lux-att-policy__type-tags">
                  {editing ? (
                    <button
                      type="button"
                      className={classNames("lux-att-policy__tag", blocked ? "is-blocked" : "is-allowed")}
                      onClick={() => toggleBlocked(type.code)}
                    >
                      {blocked ? "Blocked" : "Allowed"}
                    </button>
                  ) : (
                    <>
                      {type.requiresEvidence && !blocked && (
                        <span className="lux-att-policy__tag is-evidence">Evidence</span>
                      )}
                      {blocked ? (
                        <span className="lux-att-policy__tag is-blocked">Blocked</span>
                      ) : (
                        <span className="lux-att-policy__tag is-allowed">Allowed</span>
                      )}
                    </>
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      </section>

      {editing && (
        <footer className="lux-att-policy__footer">
          <button
            type="button"
            className="lux-onb-action lux-onb-action--ghost"
            disabled={saving}
            onClick={() => {
              setEditing(false);
              setLocalError(null);
              setDraft(toDraft(policy));
            }}
          >
            Cancel
          </button>
          <button
            type="button"
            className="lux-onb-action lux-onb-action--primary"
            disabled={saving}
            onClick={handleSave}
          >
            {saving ? "Saving…" : "Save policy"}
          </button>
        </footer>
      )}
    </section>
  );
}
