import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isFinanceIntelligenceEnabled } from "config/finance-intelligence.config";
import { PROJECT_FINANCIALS_PAGE_META } from "config/finance-intelligence-nav.config";
import { financeIntelligenceService } from "_services/financeIntelligence.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import ProjectFinancialsPanel from "views/finance/components/ProjectFinancialsPanel";
import { shouldHideRegisterOnLoadError } from "_helpers/registerListError.utils";

class ProjectFinancialsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    exporting: false,
    dataSource: null,
    snapshots: [],
    kpiCards: [],
    insights: [],
    programOptions: [],
    filters: {
      search: "",
      marginBand: "ALL",
      billingStatus: "ALL",
      programId: "ALL",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Project financials");
    }
    this.loadData();
  }

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await financeIntelligenceService.getProjectFinancialsOverview(filters);
      const overview = result.payload || {};
      financeIntelligenceService.recordProjectFinancialsViewed(filters);
      this.setState({
        loading: false,
        snapshots: overview.snapshots || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        programOptions: overview.programOptions || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  handleExport = async () => {
    this.setState({ exporting: true });
    try {
      const result = await financeIntelligenceService.exportProjectFinancials(this.state.filters);
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = result.filename || "project-financials.csv";
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({
        loadError: error,
      });
    } finally {
      this.setState({ exporting: false });
    }
  };

  render() {
    if (!isFinanceIntelligenceEnabled()) {
      return <PersonaAccessDenied featureLabel="Project financials" />;
    }

    const {
      loading,
      loadError,
      exporting,
      dataSource,
      snapshots,
      kpiCards,
      insights,
      programOptions,
      filters,
    } = this.state;
    const meta = PROJECT_FINANCIALS_PAGE_META;
    const hideRegister = shouldHideRegisterOnLoadError(loadError, snapshots);

    return (
      <FinanceLuxPage
        testId="page-finance-project-financials"
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo project financials"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton to="/finance/dashboard" icon="fe fe-grid" variant="ghost">
              Finance hub
            </FinanceActionButton>
            <FinanceActionButton to="/analytics/finance" icon="fe fe-trending-up" variant="primary">
              Financial analytics
            </FinanceActionButton>
          </>
        }
      >
        <FinanceInsightPanel insights={insights} />

        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load project financial snapshots."
          onDismiss={() => this.setState({ loadError: null })}
        />

        {hideRegister ? null : (
        <FinanceLuxPanel
          title={meta.panelTitle}
          meta={meta.panelMeta}
          icon="fe fe-pie-chart"
          accent="amber"
        >
          <ProjectFinancialsPanel
            rows={snapshots}
            loading={loading}
            filters={filters}
            programOptions={programOptions}
            onFilterChange={this.handleFilterChange}
            onExport={this.handleExport}
            exporting={exporting}
          />
        </FinanceLuxPanel>
        )}
      </FinanceLuxPage>
    );
  }
}

export default ProjectFinancialsPage;
