import { commonUtils } from "_helpers";

function collectSearchableStrings(value, out = []) {
  if (value == null) return out;
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    out.push(String(value));
    return out;
  }
  if (Array.isArray(value)) {
    value.forEach((entry) => collectSearchableStrings(entry, out));
    return out;
  }
  if (typeof value === "object") {
    Object.values(value).forEach((entry) => collectSearchableStrings(entry, out));
  }
  return out;
}

/** Client-side filter for loaded report rows (does not change cell rendering). */
export function filterReportItems(items, filterText) {
  if (!items || !items.length) return items || [];
  const needle = (filterText || "").trim();
  if (!needle) return items;

  return items.filter((item) =>
    collectSearchableStrings(item).some((text) => commonUtils.stringContainsString(text, needle))
  );
}
