import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { getBenefitPlanTone } from "config/employee-finance.config";
import { EmployeeFinanceActionButton } from "views/payroll/components/EmployeeFinanceLuxShared";

export default function BenefitPlansPanel({ plans = [], loading, filters = {}, onFilterChange, onCreatePlan, saving }) {
  return (
    <div className="lux-empfin-snapshots">
      <div className="lux-empfin-snapshots__toolbar">
        <div className="lux-empfin-snapshots__filters">
          <label className="lux-empfin-snapshots__field">
            <span>Search</span>
            <input
              type="search"
              placeholder="Plan, code, provider…"
              value={filters.query || ""}
              onChange={(event) => onFilterChange({ query: event.target.value })}
            />
          </label>
          <label className="lux-empfin-snapshots__field">
            <span>Status</span>
            <select value={filters.status || "ALL"} onChange={(event) => onFilterChange({ status: event.target.value })}>
              <option value="ALL">All statuses</option>
              <option value="ACTIVE">Active</option>
              <option value="DRAFT">Draft</option>
              <option value="SUNSET">Sunset</option>
            </select>
          </label>
        </div>
        <div className="lux-empfin-snapshots__actions">
          <EmployeeFinanceActionButton icon="fe fe-plus" variant="primary" onClick={onCreatePlan} disabled={saving}>
            {saving ? "Saving…" : "New plan"}
          </EmployeeFinanceActionButton>
        </div>
      </div>

      {loading ? (
        <div className="lux-empfin-register__skeleton" aria-busy="true" />
      ) : !plans.length ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No benefit plans"
          description="Create a benefit plan or adjust filters to see enrollment coverage."
        />
      ) : (
        <div className="lux-empfin-plans">
          {plans.map((plan) => (
            <article key={plan.id} className="lux-empfin-plan-card">
              <header>
                <div>
                  <strong>{plan.name}</strong>
                  <small>
                    {plan.code} · {plan.provider} · {plan.category}
                  </small>
                </div>
                <span className={classNames("lux-portfolio-badge", `is-${getBenefitPlanTone(plan.status)}`)}>{plan.status}</span>
              </header>
              <div className="lux-empfin-plan-card__metrics">
                <div>
                  <span>Employer</span>
                  <strong>${Number(plan.employerContributionUsd || 0).toLocaleString()}/mo</strong>
                </div>
                <div>
                  <span>Employee</span>
                  <strong>${Number(plan.employeeContributionUsd || 0).toLocaleString()}/mo</strong>
                </div>
                <div>
                  <span>Enrolled</span>
                  <strong>{plan.enrolledCount || 0}</strong>
                </div>
                <div>
                  <span>Effective</span>
                  <strong>{plan.effectiveFrom || "—"}</strong>
                </div>
              </div>
            </article>
          ))}
        </div>
      )}
    </div>
  );
}
