import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPayrollManagementEnabled } from "config/payroll.config";
import {
  filterPayrollRuns,
  buildPayrollDashboardMetrics,
} from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import PayrollRunWizardDrawer from "views/payroll/components/PayrollRunWizardDrawer";
import { PayrollRunsRegister } from "views/payroll/components/PayrollRegister";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class PayrollRunsPage extends Component {
  state = {
    runs: [],
    groups: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "ALL",
    query: "",
    wizardOpen: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Payroll runs");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [runsResult, groupsResult] = await Promise.all([
        payrollService.listPayrollRuns(),
        payrollService.listPayrollGroups(),
      ]);
      this.setState({
        runs: runsResult.payload || [],
        groups: groupsResult.payload || [],
        loading: false,
        dataSource: runsResult.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load payroll runs.", runs: [], groups: [] });
    }
  };

  handleCreateRun = async (payload) => {
    await payrollService.createRun(payload);
    await this.loadData();
  };

  getFilteredRuns = () => {
    const { runs, statusFilter, query } = this.state;
    return filterPayrollRuns(runs, {
      status: statusFilter === "ALL" ? null : statusFilter,
      query,
    });
  };

  render() {
    if (!isPayrollManagementEnabled()) {
      return <PersonaAccessDenied moduleName="Payroll runs" reason="Payroll management is not enabled." />;
    }

    const { loading, loadError, dataSource, statusFilter, query, groups, wizardOpen } = this.state;
    const rows = this.getFilteredRuns();
    const metrics = buildPayrollDashboardMetrics(this.state.runs, [], groups);
    const kpiCards = [
      { id: "total", label: "Total runs", value: metrics.totalRuns, hint: `${metrics.openRuns} open`, tone: "primary", icon: "fe fe-layers" },
      { id: "approval", label: "Pending approval", value: metrics.pendingApproval, hint: "Awaiting sign-off", tone: "amber", icon: "fe fe-clock" },
      { id: "readiness", label: "Avg readiness", value: `${metrics.avgReadiness}%`, hint: "Across all runs", tone: metrics.avgReadiness >= 90 ? "green" : "amber", icon: "fe fe-activity" },
      { id: "groups", label: "Payroll groups", value: metrics.groups, hint: "Linked cohorts", tone: "blue", icon: "fe fe-users" },
    ];

    return (
      <PayrollLuxPage
        dataSource={dataSource}
        pageMeta={DENSE_PAGE_META.payrollRuns}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <PayrollActionButton
              icon="fe fe-plus"
              variant="primary"
              onClick={() => this.setState({ wizardOpen: true })}
            >
              New run
            </PayrollActionButton>
            <PayrollActionButton to="/payroll/dashboard" icon="fe fe-pie-chart" variant="ghost">
              Dashboard
            </PayrollActionButton>
          </>
        }
      >
        {loadError && <div className="lux-employee-360__error" role="alert">{loadError}</div>}

        <section className="lux-hrms-dash__panel lux-payroll-panel">
          <PayrollPanelHead title="Run register" subtitle="Filter by lifecycle status or search by run name and period" />

          <div className="lux-payroll-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search runs, groups, or periods"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count"><strong>{rows.length}</strong> run(s)</span>
            </div>
            <div className="lux-appr-toolbar__group">
              <span className="lux-appr-toolbar__label">Status</span>
              <div className="lux-hrms-dash__filter-group">
                {["ALL", "Draft", "Calculated", "Pending approval", "Approved", "Locked"].map((value) => (
                  <button
                    key={value}
                    type="button"
                    className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === value })}
                    onClick={() => this.setState({ statusFilter: value })}
                  >
                    {value === "ALL" ? "All" : value}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading runs" description="Fetching payroll run register." />
            ) : rows.length === 0 ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-layers" title="No payroll runs" description="Create a draft run to begin the payroll cycle." />
            ) : (
              <PayrollRunsRegister rows={rows} />
            )}
          </div>
        </section>

        <PayrollRunWizardDrawer open={wizardOpen} groups={groups} onClose={() => this.setState({ wizardOpen: false })} onSubmit={this.handleCreateRun} />
      </PayrollLuxPage>
    );
  }
}

export default PayrollRunsPage;
