import classNames from "classnames/bind";
import React, { Component } from "react";
import {
  getAttendanceRecordDetails,
  getDayMeta,
  getAttendanceStatusMeta,
  isAttendancePending,
  isAttendancePendingRemoval,
  isAttendanceRejected,
  isAttendanceApproved,
  isAttendanceAwaitingManagerAction,
} from "./attendance.utils";
import AttendanceApprovalCommentField from "./AttendanceApprovalCommentField";
import ApprovalRemindApproverButton from "../delegation/ApprovalRemindApproverButton";
import ApprovalAuthorityHistory from "../delegation/ApprovalAuthorityHistory";
import { buildApprovalInboxContext } from "_helpers/approvalAuthority.utils";

class AttendanceDetailsPopover extends Component {
  constructor(props) {
    super(props);
    this.state = { approvalComment: "", rejectError: null };
  }

  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
    this.syncComment(this.props);
  }

  componentDidUpdate(prevProps) {
    if (
      this.props.show !== prevProps.show ||
      (this.props.attendanceItem && this.props.attendanceItem.id) !==
        (prevProps.attendanceItem && prevProps.attendanceItem.id)
    ) {
      this.syncComment(this.props);
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
  }

  syncComment = (props) => {
    const existingComment =
      props.attendanceItem && props.attendanceItem.approvalComment
        ? props.attendanceItem.approvalComment
        : "";
    this.setState({ approvalComment: existingComment, rejectError: null });
  };

  handleCommentChange = (value) => {
    this.setState((prevState) => ({
      approvalComment: value,
      rejectError: prevState.rejectError && value.trim() ? null : prevState.rejectError,
    }));
  };

  handleReject = () => {
    const { attendanceItem, onReject } = this.props;
    if (!attendanceItem || !onReject) return;

    const comment = (this.state.approvalComment || "").trim();
    if (!comment) {
      this.setState({
        rejectError: isAttendancePendingRemoval(attendanceItem)
          ? "Please explain why the attendance should be kept."
          : "Please enter a rejection reason before rejecting this attendance.",
      });
      return;
    }

    this.setState({ rejectError: null });
    onReject(attendanceItem.id, comment, attendanceItem);
  };

  handleApprove = () => {
    const { attendanceItem, onApprove } = this.props;
    if (!attendanceItem || !onApprove) return;
    const comment = (this.state.approvalComment || "").trim();
    onApprove(attendanceItem.id, comment || null, attendanceItem);
  };

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      this.props.onClose();
    }
  };

  handleResubmit = () => {
    const { attendanceItem, employeeId, employeeName, markDate, onResubmit } = this.props;
    if (!onResubmit || !attendanceItem) return;
    onResubmit(employeeId, employeeName, markDate, attendanceItem);
  };

  handleRequestRemoval = () => {
    const { attendanceItem, onRequestRemoval } = this.props;
    if (!attendanceItem || !onRequestRemoval) return;
    onRequestRemoval(attendanceItem.id);
  };

  renderStatusIntro = (statusMeta) => {
    if (statusMeta.tone === "pending") {
      return " — waiting for manager approval.";
    }
    if (statusMeta.tone === "pending-removal") {
      return " — waiting for manager approval to remove this day.";
    }
    if (statusMeta.tone === "rejected") {
      return " — edit times and resubmit for manager approval.";
    }
    return " — review check-in and checkout below.";
  };

  render() {
    const {
      show,
      employeeName,
      markDate,
      attendanceItem,
      onClose,
      onApprove,
      onReject,
      isLoading,
      canApprove,
      canRequestRemoval,
      canResubmit,
      permission,
      employeeId,
      showRemindApprover,
      employees,
    } = this.props;

    if (!show || !markDate || !attendanceItem) return null;

    const meta = getDayMeta(markDate);
    const details = getAttendanceRecordDetails(attendanceItem);
    const statusMeta = getAttendanceStatusMeta(attendanceItem);
    const isRemovalReview = isAttendancePendingRemoval(attendanceItem);
    const showApprovalActions = canApprove && isAttendanceAwaitingManagerAction(attendanceItem);
    const showResubmit = canResubmit && isAttendanceRejected(attendanceItem);
    const showRequestRemoval =
      canRequestRemoval && isAttendanceApproved(attendanceItem) && !isAttendanceAwaitingManagerAction(attendanceItem);
    const showStoredComment =
      attendanceItem.approvalComment &&
      (isAttendanceApproved(attendanceItem) || isAttendanceRejected(attendanceItem));
    const approvalHistoryContext = buildApprovalInboxContext(null, employees);
    return (
      <>
        <button
          type="button"
          className="lux-att-mark-popover__backdrop"
          aria-label="Close attendance details"
          onClick={onClose}
        />
        <div
          className="lux-att-mark-popover"
          role="dialog"
          aria-modal="true"
          aria-labelledby="lux-att-details-popover-title"
        >
          <header className="lux-att-mark-popover__head">
            <div>
              <span className="lux-att-mark-popover__eyebrow">Attendance details</span>
              <h2 id="lux-att-details-popover-title">{employeeName || "Employee"}</h2>
              <p>
                {markDate.format("dddd, MMMM D, YYYY")}
                {meta.isToday && <span className="lux-att-mark-popover__today">Today</span>}
                {meta.isWeekend && (
                  <span className="lux-att-mark-popover__optional">Optional day</span>
                )}
              </p>
            </div>
            <button type="button" className="lux-att-mark-popover__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-att-mark-popover__body">
            <div className={classNames("lux-att-mark-popover__intro", `is-${statusMeta.tone}`)}>
              <i className={statusMeta.icon} aria-hidden="true" />
              <span>
                {statusMeta.label}
                {this.renderStatusIntro(statusMeta)}
              </span>
            </div>

            <div className="lux-att-mark-popover__grid">
              <div className="lux-att-mark-popover__field is-highlight is-wide">
                <span>Status</span>
                <div className="lux-att-mark-popover__value">{statusMeta.label}</div>
              </div>
              <div className="lux-att-mark-popover__field is-highlight">
                <span>Start time</span>
                <div className="lux-att-mark-popover__value">{details.startTimeLabel}</div>
                <em>Check-in / mark time</em>
              </div>

              <div className="lux-att-mark-popover__field is-highlight">
                <span>Hours</span>
                <div className="lux-att-mark-popover__value">{details.hoursLabel}</div>
                <em>Total hours worked</em>
              </div>

              <div className="lux-att-mark-popover__field is-highlight is-wide">
                <span>Checkout time</span>
                <div className="lux-att-mark-popover__value">{details.checkoutTimeLabel}</div>
                <em>End of day</em>
              </div>

              {showStoredComment && (
                <div className="lux-att-mark-popover__field is-highlight is-wide">
                  <span>Manager comment</span>
                  <div className="lux-att-mark-popover__value">{attendanceItem.approvalComment}</div>
                </div>
              )}
              {isAttendanceApproved(attendanceItem) && (
                <div className="lux-att-mark-popover__field is-highlight is-wide">
                  <span>Approval history</span>
                  <ApprovalAuthorityHistory
                    record={attendanceItem}
                    context={approvalHistoryContext}
                  />
                </div>
              )}
            </div>

            {showRemindApprover && (
              <div className="lux-att-mark-popover__remind">
                <ApprovalRemindApproverButton
                  visible={showRemindApprover}
                  requestType="ATTENDANCE"
                  referenceId={attendanceItem.id}
                  employeeId={employeeId}
                  permission={permission}
                />
              </div>
            )}

            {showApprovalActions && (
              <AttendanceApprovalCommentField
                value={this.state.approvalComment}
                onChange={this.handleCommentChange}
                disabled={isLoading}
                required
                error={this.state.rejectError}
                id="lux-att-details-approval-comment"
              />
            )}

            <footer className="lux-att-mark-popover__foot">
              <button type="button" className="lux-att-mark-popover__btn" onClick={onClose} disabled={isLoading}>
                Close
              </button>
              {showResubmit && (
                <button
                  type="button"
                  className={classNames("lux-att-mark-popover__btn is-primary", { "is-loading": isLoading })}
                  onClick={this.handleResubmit}
                  disabled={isLoading}
                >
                  <i className="fe fe-edit" aria-hidden="true" />
                  Edit &amp; resubmit
                </button>
              )}
              {showRequestRemoval && (
                <button
                  type="button"
                  className={classNames("lux-att-mark-popover__btn is-danger", { "is-loading": isLoading })}
                  onClick={this.handleRequestRemoval}
                  disabled={isLoading}
                >
                  <i className="fe fe-trash-2" aria-hidden="true" />
                  Request removal
                </button>
              )}
              {showApprovalActions && onReject && (
                <button
                  type="button"
                  className={classNames("lux-att-mark-popover__btn is-danger", { "is-loading": isLoading })}
                  onClick={this.handleReject}
                  disabled={isLoading}
                >
                  <i className="fe fe-x-circle" aria-hidden="true" />
                  {isRemovalReview ? "Keep attendance" : "Reject"}
                </button>
              )}
              {showApprovalActions && onApprove && (
                <button
                  type="button"
                  className={classNames("lux-att-mark-popover__btn is-primary", { "is-loading": isLoading })}
                  onClick={this.handleApprove}
                  disabled={isLoading}
                >
                  <i className="fe fe-check" aria-hidden="true" />
                  {isRemovalReview ? "Approve removal" : "Approve"}
                </button>
              )}
            </footer>
          </div>
        </div>
      </>
    );
  }
}

export default AttendanceDetailsPopover;
