import React from "react";
import classNames from "classnames/bind";
import {
  formatAuditRelativeTime,
  formatAuditTimestamp,
  getActionMeta,
  getActorName,
  getEntityMeta,
} from "_helpers/audit.utils";

function getActorInitials(name) {
  const parts = String(name || "?")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

export default function AuditEventRegister({ events }) {
  return (
    <div className="lux-audit-admin-register-wrap">
      <table className="lux-audit-admin-register">
        <thead>
          <tr>
            <th>Event</th>
            <th>Actor</th>
            <th>Area</th>
            <th>Action</th>
            <th>When</th>
          </tr>
        </thead>
        <tbody>
          {events.map((event) => {
            const actionMeta = getActionMeta(event.actionType);
            const entityType = (event.entity && event.entity.type) || event.entityType;
            const entityMeta = getEntityMeta(entityType);
            const actorName = getActorName(event);
            const isDelegate = actionMeta.key === "DELEGATE_ACTED";
            const isApproval = actionMeta.key === "APPROVED" || actionMeta.key === "REJECTED";

            return (
              <tr
                key={event.id || `${event.createdDate}-${event.actionType}`}
                className={classNames("lux-audit-admin-register__row", {
                  "is-delegate": isDelegate,
                  "is-approval": isApproval,
                })}
              >
                <td>
                  <div className="lux-audit-admin-register__primary">
                    <span
                      className={classNames("lux-audit-admin-register__icon", actionMeta.tone && `is-${actionMeta.tone}`)}
                      aria-hidden="true"
                    >
                      <i className={`fe ${actionMeta.icon}`} />
                    </span>
                    <span className="lux-audit-admin-register__primary-copy">
                      <strong className="lux-audit-admin-register__primary-title">
                        {event.headline || actionMeta.label}
                      </strong>
                      {(event.entity && event.entity.ref) && (
                        <span className="lux-audit-admin-register__primary-meta">{event.entity.ref}</span>
                      )}
                    </span>
                  </div>
                </td>
                <td>
                  <div className="lux-audit-admin-register__actor">
                    <span className="lux-audit-admin-register__actor-avatar" aria-hidden="true">
                      {getActorInitials(actorName)}
                    </span>
                    <span>{actorName}</span>
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-audit-admin-register__chip", entityMeta.tone && `is-${entityMeta.tone}`)}>
                    <i className={`fe ${entityMeta.icon}`} aria-hidden="true" />
                    {entityMeta.label}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${actionMeta.tone === "success" ? "primary" : actionMeta.tone === "danger" ? "danger" : "slate"}`)}>
                    {actionMeta.label}
                  </span>
                </td>
                <td>
                  <span className="lux-audit-admin-register__date" title={formatAuditTimestamp(event.createdDate)}>
                    {formatAuditRelativeTime(event.createdDate) || formatAuditTimestamp(event.createdDate)}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
