import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

function KpiCard({ label, value, suffix, hint, tone, icon, isPercent }) {
  const displayValue = isPercent
    ? parseInt(String(value).replace("%", ""), 10)
    : Number(value) || 0;

  return (
    <article className={classNames("lux-hrms-dash__kpi", tone && `is-${tone}`)}>
      <div className="lux-hrms-dash__kpi-top">
        <span className="lux-hrms-dash__kpi-label">{label}</span>
        {icon && (
          <span className="lux-hrms-dash__kpi-icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </span>
        )}
      </div>
      <strong className="lux-hrms-dash__kpi-value">
        <CountUp end={displayValue} duration={0.8} separator="," />
        {suffix && <small>{suffix}</small>}
        {isPercent && <small>%</small>}
      </strong>
      {hint && <span className="lux-hrms-dash__kpi-hint">{hint}</span>}
    </article>
  );
}

function LifecycleCaseKpiStrip({ metrics, lifecycle = "onboarding", loading = false }) {
  if (loading || !metrics) {
    return (
      <div
        className="lux-hrms-dash__kpi-strip lux-onb-kpi-strip lux-onb-detail__kpi"
        role="list"
        aria-busy="true"
      >
        {[1, 2, 3, 4].map((id) => (
          <article key={id} className="lux-hrms-dash__kpi is-slate">
            <div className="lux-hrms-dash__kpi-top">
              <span className="lux-hrms-dash__kpi-label">Loading</span>
            </div>
            <strong className="lux-hrms-dash__kpi-value">—</strong>
          </article>
        ))}
      </div>
    );
  }

  const items =
    lifecycle === "offboarding"
      ? [
          {
            id: "readiness",
            label: "Exit readiness",
            value: metrics.readiness,
            hint: "Checklist completion",
            tone: "amber",
            icon: "fe-activity",
            isPercent: true,
          },
          {
            id: "tasks",
            label: "Tasks complete",
            value: metrics.tasksComplete,
            suffix: ` / ${metrics.taskTotal}`,
            hint: "Required exit steps",
            tone: "primary",
            icon: "fe-check-square",
          },
          {
            id: "overdue",
            label: "Overdue tasks",
            value: metrics.overdueTasks,
            hint: "Past due date",
            tone: metrics.overdueTasks > 0 ? "rose" : "green",
            icon: "fe-clock",
          },
          {
            id: "blocked",
            label: "Blocked",
            value: metrics.blocked,
            hint: metrics.blocked ? "Needs HR attention" : "No blockers",
            tone: metrics.blocked ? "rose" : "slate",
            icon: "fe-alert-circle",
          },
        ]
      : [
          {
            id: "readiness",
            label: "Readiness",
            value: metrics.readiness,
            hint: "Day-one preparedness",
            tone: "violet",
            icon: "fe-activity",
            isPercent: true,
          },
          {
            id: "tasks",
            label: "Tasks complete",
            value: metrics.tasksComplete,
            suffix: ` / ${metrics.taskTotal}`,
            hint: "Checklist progress",
            tone: "primary",
            icon: "fe-check-square",
          },
          {
            id: "overdue",
            label: "Overdue tasks",
            value: metrics.overdueTasks,
            hint: "Past due date",
            tone: metrics.overdueTasks > 0 ? "rose" : "green",
            icon: "fe-clock",
          },
          {
            id: "pending",
            label: "Pending tasks",
            value: metrics.pendingTasks,
            hint: metrics.ready ? "Ready for day one" : "Still in progress",
            tone: metrics.ready ? "green" : "sky",
            icon: "fe-list",
          },
        ];

  return (
    <div
      className="lux-hrms-dash__kpi-strip lux-onb-kpi-strip lux-onb-detail__kpi"
      role="list"
      data-testid="lifecycle-case-kpi-strip"
    >
      {items.map((item) => (
        <KpiCard key={item.id} {...item} />
      ))}
    </div>
  );
}

export default LifecycleCaseKpiStrip;
