/**
 * F01-T5: Merge server navigation flags over client RBAC (env pilot flags preserved).
 */

function isPlainObject(value) {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

function preserveClientFlag(merged, apiModule, clientModule, flagKey) {
  if (clientModule[flagKey] === true && apiModule) {
    merged[flagKey] = apiModule[flagKey] === true || clientModule[flagKey] === true;
  }
}

function preserveClientFlags(merged, apiModule, clientModule, flagKeys) {
  flagKeys.forEach((flagKey) => preserveClientFlag(merged, apiModule, clientModule, flagKey));
}

export function mergeModuleFlags(clientModule, apiModule) {
  if (!isPlainObject(clientModule) && !isPlainObject(apiModule)) {
    return clientModule || apiModule || {};
  }
  return {
    ...(clientModule || {}),
    ...(apiModule || {}),
  };
}

export function mergeMenuAccessControl(clientMenu, apiMenu) {
  if (!isPlainObject(apiMenu)) {
    return clientMenu || {};
  }
  if (!isPlainObject(clientMenu)) {
    return apiMenu;
  }

  const merged = { ...clientMenu };
  Object.keys(apiMenu).forEach((moduleKey) => {
    merged[moduleKey] = mergeModuleFlags(clientMenu[moduleKey], apiMenu[moduleKey]);
  });

  if (merged.peopleModules && merged.peopleModules.active === true && apiMenu.peopleModules) {
    const clientPeople = clientMenu.peopleModules || {};
    merged.peopleModules = { ...merged.peopleModules };
    preserveClientFlags(merged.peopleModules, apiMenu.peopleModules, clientPeople, [
      "employee360Enabled",
      "onboardingEnabled",
      "offboardingEnabled",
      "onboardingSelfServiceEnabled",
      "recruitingEnabled",
      "learningEnabled",
      "leavesEnabled",
      "documentsEnabled",
      "policiesEnabled",
      "assetsEnabled",
      "orgChartEnabled",
    ]);
  }

  if (merged.projectModules && apiMenu.projectModules) {
    const clientProject = clientMenu.projectModules || {};
    merged.projectModules = { ...merged.projectModules };
    preserveClientFlags(merged.projectModules, apiMenu.projectModules, clientProject, [
      "npdEnabled",
      "dossiersEnabled",
      "portfolioEnabled",
      "ganttEnabled",
      "milestonesEnabled",
      "risksEnabled",
      "issuesEnabled",
      "governanceEnabled",
      "ticketsEnabled",
      "lessonsLearnedEnabled",
      "rcaEnabled",
    ]);
  }

  if (merged.hrmsModules && apiMenu.hrmsModules) {
    const clientHrms = clientMenu.hrmsModules || {};
    merged.hrmsModules = { ...merged.hrmsModules };
    preserveClientFlag(merged.hrmsModules, apiMenu.hrmsModules, clientHrms, "leavesEnabled");
  }

  if (merged.workspaceModules && apiMenu.workspaceModules) {
    const clientWorkspace = clientMenu.workspaceModules || {};
    merged.workspaceModules = { ...merged.workspaceModules };
    preserveClientFlags(merged.workspaceModules, apiMenu.workspaceModules, clientWorkspace, [
      "approvalsEnabled",
      "myWorkEnabled",
      "notificationsEnabled",
      "myPaychecksEnabled",
      "myTicketsEnabled",
      "workGraphEnabled",
    ]);
  }

  if (merged.payrollModules && apiMenu.payrollModules) {
    const clientPayroll = clientMenu.payrollModules || {};
    merged.payrollModules = { ...merged.payrollModules };
    preserveClientFlags(merged.payrollModules, apiMenu.payrollModules, clientPayroll, [
      "active",
      "dashboardEnabled",
      "salaryStructuresEnabled",
      "groupsEnabled",
      "runsEnabled",
      "reportsEnabled",
      "paychecksEnabled",
      "deductionsEnabled",
      "benefitsEnabled",
    ]);
  }

  if (merged.financeModules && apiMenu.financeModules) {
    const clientFinanceMods = clientMenu.financeModules || {};
    merged.financeModules = { ...merged.financeModules };
    preserveClientFlags(merged.financeModules, apiMenu.financeModules, clientFinanceMods, [
      "creditNotesEnabled",
      "writeOffsEnabled",
      "vendorInvoicesEnabled",
      "vendorCostsEnabled",
      "revenueRecognitionEnabled",
    ]);
  }

  if (merged.adminModules && apiMenu.adminModules) {
    const clientAdmin = clientMenu.adminModules || {};
    merged.adminModules = { ...merged.adminModules };
    preserveClientFlags(merged.adminModules, apiMenu.adminModules, clientAdmin, [
      "leavePoliciesEnabled",
      "delegationEnabled",
      "approvalPoliciesEnabled",
      "auditEnabled",
      "systemErrorsEnabled",
      "rolesEnabled",
      "featureFlagsEnabled",
      "securityEnabled",
      "dataRetentionEnabled",
      "complianceExportEnabled",
      "adminInsightsEnabled",
      "accessRequestsEnabled",
      "orgStructureEnabled",
    ]);
  }

  if (merged.integrationsModules && apiMenu.integrationsModules) {
    const clientIntegrations = clientMenu.integrationsModules || {};
    merged.integrationsModules = { ...merged.integrationsModules };
    preserveClientFlags(merged.integrationsModules, apiMenu.integrationsModules, clientIntegrations, [
      "active",
      "hubEnabled",
      "syncHealthEnabled",
      "mappingEnabled",
      "jobsEnabled",
      "logsEnabled",
      "adaptersEnabled",
    ]);
    if (
      merged.integrationsModules.hubEnabled === true ||
      merged.integrationsModules.syncHealthEnabled === true ||
      merged.integrationsModules.mappingEnabled === true ||
      merged.integrationsModules.jobsEnabled === true ||
      merged.integrationsModules.logsEnabled === true ||
      merged.integrationsModules.adaptersEnabled === true
    ) {
      merged.integrationsModules.active = true;
    }
  }

  if (merged.aiModules && apiMenu.aiModules) {
    const clientAi = clientMenu.aiModules || {};
    merged.aiModules = { ...merged.aiModules };
    preserveClientFlags(merged.aiModules, apiMenu.aiModules, clientAi, [
      "active",
      "agentsEnabled",
      "recommendationsEnabled",
      "wbsEnabled",
      "staffingEnabled",
      "timesheetEnabled",
      "payrollReadinessEnabled",
      "riskEnabled",
      "executiveBriefingEnabled",
      "knowledgeEnabled",
      "auditEnabled",
    ]);
  }

  if (merged.performanceModules && apiMenu.performanceModules) {
    const clientPerformance = clientMenu.performanceModules || {};
    merged.performanceModules = { ...merged.performanceModules };
    preserveClientFlags(merged.performanceModules, apiMenu.performanceModules, clientPerformance, [
      "active",
      "dashboardEnabled",
      "goalsEnabled",
      "reviewCyclesEnabled",
      "reviewsEnabled",
      "continuousFeedbackEnabled",
      "oneOnOnesEnabled",
      "growthPlansEnabled",
      "calibrationEnabled",
    ]);
  }

  if (merged.analyticsModules && apiMenu.analyticsModules) {
    const clientAnalytics = clientMenu.analyticsModules || {};
    merged.analyticsModules = { ...merged.analyticsModules };
    preserveClientFlags(merged.analyticsModules, apiMenu.analyticsModules, clientAnalytics, [
      "active",
      "controlTowerEnabled",
      "analyticsPlatformEnabled",
      "executiveEnabled",
      "workforceEnabled",
      "deliveryEnabled",
      "resourcesEnabled",
      "payrollEnabled",
      "financeEnabled",
      "approvalsEnabled",
      "riskEnabled",
      "workGraphEnabled",
      "aiInsightsEnabled",
      "reportBuilderEnabled",
      "scheduledReportsEnabled",
    ]);
  }

  if (merged.financeModules && apiMenu.financeModules) {
    const clientFinance = clientMenu.financeModules || {};
    merged.financeModules = { ...merged.financeModules };
    preserveClientFlags(merged.financeModules, apiMenu.financeModules, clientFinance, [
      "active",
      "dashboardEnabled",
      "projectFinancialsEnabled",
      "billingPlansEnabled",
      "revenueForecastEnabled",
      "revenueLeakageEnabled",
      "creditNotesEnabled",
      "writeOffsEnabled",
      "revenueRecognitionEnabled",
      "vendorInvoicesEnabled",
      "vendorCostsEnabled",
      "expensesEnabled",
      "analyticsFinanceEnabled",
    ]);
  }

  return merged;
}
