import React, { useEffect, useState } from "react";
import { stringifyConfigNestedValue } from "./appConfigTree.utils";

/**
 * Compact JSON editor for nested Application Config values (object maps and
 * object arrays such as timesheet lateBands). react-select cannot render those.
 */
export default function AppConfigNestedJsonField({
  propertyName,
  value,
  canEdit = false,
  onApply,
}) {
  const [draftText, setDraftText] = useState(() => stringifyConfigNestedValue(value));
  const [parseError, setParseError] = useState(null);

  useEffect(() => {
    setDraftText(stringifyConfigNestedValue(value));
    setParseError(null);
  }, [value]);

  const applyJson = () => {
    if (!canEdit || typeof onApply !== "function") {
      return;
    }
    try {
      const parsed = JSON.parse(draftText);
      onApply(propertyName, parsed);
      setDraftText(stringifyConfigNestedValue(parsed));
      setParseError(null);
    } catch (e) {
      setParseError(e && e.message ? e.message : "Invalid JSON");
    }
  };

  const formatJson = () => {
    try {
      const parsed = JSON.parse(draftText);
      setDraftText(stringifyConfigNestedValue(parsed));
      setParseError(null);
    } catch (e) {
      setParseError(e && e.message ? e.message : "Invalid JSON");
    }
  };

  return (
    <span className="lux-ac-config-block__field-value lux-ac-config-block__field-value--nested">
      <textarea
        className="lux-ac-config-block__textarea lux-ac-config-block__nested-json"
        rows={8}
        spellCheck={false}
        readOnly={!canEdit}
        disabled={!canEdit}
        value={draftText}
        onChange={(event) => {
          setDraftText(event.target.value);
          setParseError(null);
        }}
        aria-label={`${propertyName} JSON`}
        data-testid={`appconfig-nested-json-${propertyName}`}
      />
      {parseError ? (
        <span className="text-danger small" role="alert">
          {parseError}
        </span>
      ) : null}
      {canEdit ? (
        <span className="lux-appconfig-invoice-json__actions">
          <button
            type="button"
            className="btn btn-sm btn-outline-secondary"
            onClick={formatJson}
          >
            Format
          </button>
          <button
            type="button"
            className="btn btn-sm btn-primary"
            onClick={applyJson}
            data-testid={`appconfig-nested-json-apply-${propertyName}`}
          >
            Apply JSON
          </button>
        </span>
      ) : null}
    </span>
  );
}
