const EMPTY = "";

function norm(value) {
  if (value === null || value === undefined) return EMPTY;
  return String(value).trim();
}

export function computeBillableRowLayout(tasks, index) {
  const task = (tasks && tasks[index]) || {};
  const prev = index > 0 ? tasks[index - 1] : null;
  const deliverable = norm(task.taskName);
  const category = norm(task.taskActCategory);
  const workItem = norm(task.workItemName);

  const prevDeliverable = prev ? norm(prev.taskName) : null;
  const prevCategory = prev ? norm(prev.taskActCategory) : null;

  const showDeliverable = !prev || deliverable !== prevDeliverable;
  const showCategory = !prev || showDeliverable || category !== prevCategory;

  return {
    deliverable,
    category,
    workItem,
    showDeliverable,
    showCategory,
    showWorkItem: true,
  };
}

export function computeNonBillableRowLayout(tasks, index) {
  const task = (tasks && tasks[index]) || {};
  const prev = index > 0 ? tasks[index - 1] : null;

  const division = norm(task.division);
  const account = norm(task.account);
  const clientPartner = norm(task.clientPartner);
  const requestingTeam = norm(task.requestingTeamName);
  const workItem = norm(task.workItemName);

  const showDivision = !prev || division !== norm(prev.division);
  const showAccount = !prev || showDivision || account !== norm(prev.account);
  const showClientPartner =
    !prev || showAccount || clientPartner !== norm(prev.clientPartner);
  const showRequestingTeam =
    !prev || showClientPartner || requestingTeam !== norm(prev.requestingTeamName);

  return {
    division,
    account,
    clientPartner,
    requestingTeam,
    workItem,
    showDivision,
    showAccount,
    showClientPartner,
    showRequestingTeam,
    showWorkItem: true,
  };
}

export const BILLABLE_TABLE_COLUMNS = [
  { key: "deliverable", label: "Deliverable", showKey: "Deliverable" },
  { key: "category", label: "Category", showKey: "Category" },
  { key: "workItem", label: "Work Item", showKey: "WorkItem" },
];

export const NON_BILLABLE_TABLE_COLUMNS = [
  { key: "division", label: "Division", showKey: "Division" },
  { key: "account", label: "Account", showKey: "Account" },
  { key: "clientPartner", label: "Client Partner", showKey: "ClientPartner" },
  { key: "requestingTeam", label: "Requesting Team", showKey: "RequestingTeam" },
  { key: "workItem", label: "Work Item", showKey: "WorkItem" },
];

export const LEAVE_HOLIDAY_TABLE_COLUMNS = [
  { key: "workItem", label: "Work Item", showKey: "WorkItem" },
];

export function getNonBillableTableColumns(taskGroupId) {
  const key = (taskGroupId || "").toLowerCase();
  if (key === "leave" || key === "holiday") {
    return LEAVE_HOLIDAY_TABLE_COLUMNS;
  }
  return NON_BILLABLE_TABLE_COLUMNS;
}

export function computeLeaveHolidayRowLayout(tasks, index) {
  const task = (tasks && tasks[index]) || {};
  return {
    workItem: norm(task.workItemName),
    showWorkItem: true,
  };
}

export function hasTaskGroupItems(taskGroupItems) {
  return (
    taskGroupItems &&
    typeof taskGroupItems === "object" &&
    Object.keys(taskGroupItems).some((groupId) => {
      const section = taskGroupItems[groupId];
      return section && Array.isArray(section.tasks) && section.tasks.length > 0;
    })
  );
}
