import React, { Component } from "react";
import classNames from "classnames/bind";
import Calendar from "views/common/plugins/calendar/Calendar";
import dateUtils from "_helpers/date.utils";
import LuxPageHeaderPopoverPortal from "./LuxPageHeaderPopoverPortal";

class PageInnerHeaderActivityCalendarMenu extends Component {
  constructor(props) {
    super(props);
    this.state = { isOpen: false };
    this.wrapRef = React.createRef();
    this.popoverRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick, true);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick, true);
  }

  handleOutsideClick = (event) => {
    if (!this.state.isOpen) return;
    const wrap = this.wrapRef.current;
    const popover = this.popoverRef.current;
    if (wrap && wrap.contains(event.target)) return;
    if (popover && popover.contains(event.target)) return;
    this.setState({ isOpen: false });
  };

  togglePanel = () => {
    if (this.props.isLoading) return;
    this.setState((prev) => ({ isOpen: !prev.isOpen }));
  };

  closePanel = () => {
    this.setState({ isOpen: false });
  };

  getLabel = () => {
    const { dateRange } = this.props;
    if (!dateRange || !dateRange.startDateMoment) return "Select period";
    if (dateRange.startDateMoment.isSame(dateRange.endDateMoment, "day")) {
      return dateRange.startDateMoment.format("ddd, MMM D YYYY");
    }
    return `${dateRange.startDateMoment.format("MMM D")} – ${dateRange.endDateMoment.format("MMM D, YYYY")}`;
  };

  handleDateChange = (selectedDates) => {
    this.props.onSelectedDateChange(selectedDates);
    if (selectedDates.length === 1) {
      this.closePanel();
    }
  };

  goToToday = () => {
    const today = dateUtils.getCurrentTime();
    this.props.onSelectedDateChange([today]);
    if (this.props.onCalendarViewDate) {
      this.props.onCalendarViewDate(today);
    }
  };

  render() {
    const { isOpen } = this.state;
    const { selectedDates, viewMonthDate, holidayItems, isLoading } = this.props;

    return (
      <div
        className={classNames("lux-page-header__activity-calendar", { "is-open": isOpen })}
        ref={this.wrapRef}
      >
        <button
          type="button"
          className="lux-page-header__activity-calendar-btn"
          onClick={this.togglePanel}
          disabled={isLoading}
          aria-expanded={isOpen}
          aria-haspopup="dialog"
          title="Select day, week, or month"
        >
          <i className="fe fe-calendar" aria-hidden="true" />
          <span className="lux-page-header__activity-calendar-label">{this.getLabel()}</span>
          <i className="fe fe-chevron-down" aria-hidden="true" />
        </button>

        <LuxPageHeaderPopoverPortal
          isOpen={isOpen}
          anchorRef={this.wrapRef}
          align="right"
          popoverRef={this.popoverRef}
          className="lux-page-header__query-popover lux-page-header__activity-calendar-popover"
          role="dialog"
          aria-label="Activity calendar"
        >
          <header className="lux-page-header__query-popover-head">
            <span className="lux-page-header__query-popover-icon" aria-hidden="true">
              <i className="fe fe-calendar" />
            </span>
            <div>
              <span className="lux-page-header__query-popover-eyebrow">Period selector</span>
              <strong>Calendar view</strong>
            </div>
            <button type="button" className="lux-page-header__query-popover-close" onClick={this.closePanel} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-page-header__activity-calendar-hints">
            <span><i className="fe fe-square" aria-hidden="true" /> Day — click a date</span>
            <span><i className="fe fe-columns" aria-hidden="true" /> Week — click week #</span>
            <span><i className="fe fe-grid" aria-hidden="true" /> Month — click month title</span>
          </div>

          <div className="lux-page-header__activity-calendar-body">
            <Calendar
              embedded
              selectedDates={selectedDates}
              viewMonthDate={viewMonthDate}
              onSelectedDateChange={this.handleDateChange}
              onCalendarViewDate={this.props.onCalendarViewDate}
              holidayItems={holidayItems}
            />
          </div>

          <footer className="lux-page-header__activity-calendar-foot">
            <button type="button" className="lux-page-header__query-cancel" onClick={this.goToToday}>
              <i className="fe fe-home" aria-hidden="true" /> Today
            </button>
            <button type="button" className="lux-page-header__query-submit" onClick={this.closePanel}>
              Done
            </button>
          </footer>
        </LuxPageHeaderPopoverPortal>
      </div>
    );
  }
}

export default PageInnerHeaderActivityCalendarMenu;
