import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isKnowledgeRcaEnabled } from "config/knowledge-rca.config";
import { RCA_PAGE_META } from "config/knowledge-rca-nav.config";
import { knowledgeRcaService } from "_services/knowledgeRca.service";
import KnowledgeLuxPage, {
  KnowledgeActionButton,
  KnowledgeInsightPanel,
  KnowledgeLuxPanel,
} from "views/knowledge/components/KnowledgeLuxShared";
import PatternInsightsPanel from "views/knowledge/components/PatternInsightsPanel";
import RcaDetailDrawer from "views/knowledge/components/RcaDetailDrawer";
import RcaRegister from "views/knowledge/components/RcaRegister";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class ProjectRcaPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    records: [],
    kpiCards: [],
    insights: [],
    analytics: null,
    statusFilter: "ALL",
    drawerRecord: null,
    aiDraft: null,
    aiLoading: false,
    busy: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const result = await knowledgeRcaService.getRcaOverview(filters);
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        records: payload.records || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        analytics: payload.analytics || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load RCA records.",
      });
    }
  };

  openDrawer = async (record) => {
    this.setState({ drawerRecord: record, aiDraft: null, aiLoading: true });
    try {
      const result = await knowledgeRcaService.getRcaAiDraft(record.id);
      this.setState({ aiDraft: result.payload || null, aiLoading: false });
    } catch (error) {
      this.setState({ aiLoading: false });
    }
  };

  handleSubmit = async (record) => {
    this.setState({ busy: true });
    try {
      await knowledgeRcaService.submitRcaForApproval(record.id);
      await this.loadData();
      this.setState({ drawerRecord: null });
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to submit RCA." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleApprove = async (record) => {
    this.setState({ busy: true });
    try {
      await knowledgeRcaService.approveRca(record.id);
      await this.loadData();
      this.setState({ drawerRecord: null });
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to approve RCA." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleReject = async (record) => {
    this.setState({ busy: true });
    try {
      await knowledgeRcaService.rejectRca(record.id);
      await this.loadData();
      this.setState({ drawerRecord: null });
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to return RCA to draft." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleCreateRca = async () => {
    const title = window.prompt("RCA title");
    if (!title || !String(title).trim()) {
      return;
    }
    this.setState({ busy: true, loadError: null });
    try {
      await knowledgeRcaService.createRca({
        title: String(title).trim(),
        category: "process",
        status: "draft",
      });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to create RCA." });
    } finally {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isKnowledgeRcaEnabled()) {
      return <PersonaAccessDenied featureLabel="Root cause analysis" />;
    }

    const {
      loading,
      loadError,
      dataSource,
      records,
      kpiCards,
      insights,
      analytics,
      statusFilter,
      drawerRecord,
      aiDraft,
      aiLoading,
      busy,
    } = this.state;

    return (
      <KnowledgeLuxPage
        pageMeta={RCA_PAGE_META}
        shellTitle="Root cause analysis"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
      >
        {loadError ? <LuxInlineAlert message={loadError} onDismiss={() => this.setState({ loadError: null })} /> : null}
        <KnowledgeInsightPanel insights={insights} loading={loading} />
        <PatternInsightsPanel analytics={analytics} loading={loading} />

        <KnowledgeLuxPanel
          title="RCA register"
          meta="Workflow-linked root cause records"
          icon="fe fe-target"
          accent="rose"
          featured
          actions={
            <select
              className="lux-krca-filter"
              value={statusFilter}
              onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
            >
              <option value="ALL">All statuses</option>
              <option value="draft">Draft</option>
              <option value="in_review">In review</option>
              <option value="approved">Approved</option>
            </select>
          }
        >
          <RcaRegister
            records={records}
            loading={loading}
            selectedId={drawerRecord && drawerRecord.id}
            onSelect={this.openDrawer}
          />
        </KnowledgeLuxPanel>

        <RcaDetailDrawer
          record={drawerRecord}
          aiDraft={aiDraft}
          aiLoading={aiLoading}
          busy={busy}
          onClose={() => this.setState({ drawerRecord: null, aiDraft: null })}
          onSubmit={this.handleSubmit}
          onApprove={this.handleApprove}
          onReject={this.handleReject}
        />
      </KnowledgeLuxPage>
    );
  }
}

export default ProjectRcaPage;
