import moment from "moment";
import { parseDelegationDate, getDelegationStatus } from "_helpers/approvalDelegation.utils";

/**
 * Build month grid cells with delegation count per day (F07-T4 calendar).
 */
export function buildDelegationMonthCalendar(delegations, monthDate) {
  const month = moment(monthDate || new Date()).startOf("month");
  const daysInMonth = month.daysInMonth();
  const counts = new Array(daysInMonth).fill(0);
  const labels = [];

  (delegations || []).forEach((delegation) => {
    const status = getDelegationStatus(delegation);
    if (status === "revoked" || status === "expired") return;

    const start = parseDelegationDate(delegation.startDate);
    const end = parseDelegationDate(delegation.endDate);
    if (!start || !start.isValid()) return;

    const cursor = start.clone().startOf("day");
    const endDay = end && end.isValid() ? end.clone().startOf("day") : cursor.clone();

    while (cursor.isSameOrBefore(endDay, "day")) {
      if (cursor.isSame(month, "month")) {
        counts[cursor.date() - 1] += 1;
      }
      cursor.add(1, "day");
    }
  });

  for (let index = 0; index < daysInMonth; index += 1) {
    const date = month.clone().date(index + 1);
    const dow = date.day();
    labels.push({
      day: index + 1,
      count: counts[index],
      isWeekend: dow === 0 || dow === 6,
      isToday: date.isSame(moment(), "day"),
    });
  }

  return labels;
}

export function getDelegationHeatLevel(count) {
  if (count >= 3) return "high";
  if (count >= 2) return "medium";
  if (count >= 1) return "low";
  return "none";
}

/** Flatten mine + acting lists for calendar with role metadata. */
export function mergeDelegationsForCalendar(mine, acting) {
  const outgoing = (mine || []).map((row) => ({
    ...row,
    calendarRole: "outgoing",
    calendarLabel: row.delegateName || "Delegate",
  }));
  const incoming = (acting || []).map((row) => ({
    ...row,
    calendarRole: "incoming",
    calendarLabel: row.delegatorName || row.managerName || "Manager",
  }));
  return [...outgoing, ...incoming];
}

export function summarizeDelegationCalendar(delegations) {
  const list = delegations || [];
  let outgoing = 0;
  let incoming = 0;
  list.forEach((row) => {
    if (row.calendarRole === "incoming") incoming += 1;
    else outgoing += 1;
  });
  return { total: list.length, outgoing, incoming };
}
