export function getOrgGuideById(id) {
  return APP_CONFIG_ORG_GUIDE.find((row) => row.id === id) || null;
}

export function orgGuideKeyPath(entry) {
  if (!entry) return "";
  if (entry.group && entry.group !== entry.key) {
    return `${entry.module}.${entry.group}.${entry.key}`;
  }
  return `${entry.module}.${entry.key}`;
}

