import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isUniversalApprovalInboxEnabled } from "config/universal-approval.config";
import {
  buildApprovalInboxMetrics,
  filterApprovalInboxItems,
  isBulkSelectableApprovalItem,
  sortApprovalInboxItems,
  summarizeApprovalSelection,
} from "config/universal-approval.utils";
import {
  UNIVERSAL_APPROVAL_BULK_MAX,
  universalApprovalService,
} from "_services/universalApproval.service";
import { workTimeGovernanceService } from "_services/workTimeGovernance.service";
import { WORK_TIME_GOVERNANCE_FEATURE_KEYS } from "config/work-time-governance.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import UniversalApprovalSummary from "views/workspace/components/approvals/UniversalApprovalSummary";
import UniversalApprovalFilterBar from "views/workspace/components/approvals/UniversalApprovalFilterBar";
import UniversalApprovalRegister from "views/workspace/components/approvals/UniversalApprovalRegister";
import UniversalApprovalDetailDrawer from "views/workspace/components/approvals/UniversalApprovalDetailDrawer";
import UniversalApprovalBulkActionDialog from "views/workspace/components/approvals/UniversalApprovalBulkActionDialog";
import UniversalApprovalAnalyticsPanel from "views/workspace/components/approvals/UniversalApprovalAnalyticsPanel";
import UniversalApprovalSlaBanner from "views/workspace/components/approvals/UniversalApprovalSlaBanner";
import WorkspaceSavedViewBar from "views/workspace/components/WorkspaceSavedViewBar";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import LuxRegisterListSection from "views/common/lux/LuxRegisterListSection";
import { buildShownPulse } from "views/common/lux/registerAtelier.utils";

const DEFAULT_FILTERS = {
  status: "PENDING",
  domain: "ALL",
  priority: "ALL",
  query: "",
};

class ApprovalsPage extends Component {
  state = {
    items: [],
    loading: true,
    loadError: null,
    dataSource: null,
    filters: { ...DEFAULT_FILTERS },
    selectedItem: null,
    drawerOpen: false,
    acting: false,
    activeView: "inbox",
    bulkActionsEnabled: false,
    selectedItemIds: [],
    bulkSelectionError: null,
    bulkDialogOpen: false,
    bulkDialogAction: null,
    bulkDialogItems: [],
    bulkActing: false,
    bulkError: null,
    bulkResult: null,
  };

  componentDidMount() {
    const { pageHeaderNameChangeHandler } = this.props;
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler("My approvals");
    }
    this.loadInbox();
    this.loadBulkActionsGate();
  }

  loadBulkActionsGate = async () => {
    try {
      const result = await workTimeGovernanceService.getFeatureGate(
        WORK_TIME_GOVERNANCE_FEATURE_KEYS.APPROVAL_BULK_ACTIONS
      );
      this.setState({
        bulkActionsEnabled: result.enabled === true,
      });
    } catch (_error) {
      this.setState({ bulkActionsEnabled: false });
    }
  };

  loadInbox = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await universalApprovalService.listInbox({ status: "ALL" });
      const isApiError = result.source === "api-error";
      const items = isApiError ? [] : sortApprovalInboxItems(result.payload || []);
      const availableIds = new Set(items.map((item) => item.id));
      this.setState((prev) => ({
        items,
        selectedItemIds: prev.selectedItemIds.filter((id) => availableIds.has(id)),
        loading: false,
        dataSource: result.source || null,
        loadError: isApiError
          ? result.error || "Unable to load your approval inbox."
          : null,
      }));
    } catch (_error) {
      this.setState({
        loading: false,
        loadError: "Unable to load your approval inbox.",
        items: [],
        selectedItemIds: [],
      });
    }
  };

  handleFiltersChange = (filters) => {
    this.setState({
      filters,
      selectedItemIds: [],
      bulkSelectionError: null,
    });
  };

  handleSummaryFilter = (patch) => {
    this.setState((prev) => ({
      filters: { ...prev.filters, ...patch },
      activeView: "inbox",
      selectedItemIds: [],
      bulkSelectionError: null,
    }));
  };

  handleSlaFocus = () => {
    this.setState((prev) => {
      const alreadyFocused =
        prev.filters.status === "PENDING" && prev.filters.priority === "HIGH";
      return {
        activeView: "inbox",
        selectedItemIds: [],
        bulkSelectionError: null,
        filters: alreadyFocused
          ? { ...DEFAULT_FILTERS }
          : {
              ...DEFAULT_FILTERS,
              status: "PENDING",
              priority: "HIGH",
            },
      };
    });
  };

  handleSelectItem = (item) => {
    this.setState({ selectedItem: item, drawerOpen: true });
  };

  handleCloseDrawer = () => {
    this.setState({ drawerOpen: false, selectedItem: null, acting: false });
  };

  handleApprove = async (item, comment) => {
    this.setState({ acting: true });
    try {
      await universalApprovalService.approveItem(item, comment);
      await this.loadInbox();
      this.setState({ acting: false });
    } catch (error) {
      this.setState({ acting: false });
      throw error;
    }
  };

  handleReject = async (item, comment) => {
    this.setState({ acting: true });
    try {
      await universalApprovalService.rejectItem(item, comment);
      await this.loadInbox();
      this.setState({ acting: false });
    } catch (error) {
      this.setState({ acting: false });
      throw error;
    }
  };

  getSelectedItems = () => {
    const selected = new Set(this.state.selectedItemIds);
    return this.state.items.filter(
      (item) => selected.has(item.id) && isBulkSelectableApprovalItem(item)
    );
  };

  handleToggleBulkItem = (item, checked) => {
    this.setState((prev) => {
      const selected = new Set(prev.selectedItemIds);
      if (checked) {
        if (selected.size >= UNIVERSAL_APPROVAL_BULK_MAX) {
          return {
            bulkSelectionError: `Select up to ${UNIVERSAL_APPROVAL_BULK_MAX} approvals at a time.`,
          };
        }
        selected.add(item.id);
      } else {
        selected.delete(item.id);
      }
      return {
        selectedItemIds: Array.from(selected),
        bulkSelectionError: null,
      };
    });
  };

  handleToggleAllBulkItems = (items, checked) => {
    if (!checked) {
      this.setState({ selectedItemIds: [], bulkSelectionError: null });
      return;
    }
    const selectable = (items || []).filter(isBulkSelectableApprovalItem);
    this.setState({
      selectedItemIds: selectable
        .slice(0, UNIVERSAL_APPROVAL_BULK_MAX)
        .map((item) => item.id),
      bulkSelectionError:
        selectable.length > UNIVERSAL_APPROVAL_BULK_MAX
          ? `The first ${UNIVERSAL_APPROVAL_BULK_MAX} approvals were selected.`
          : null,
    });
  };

  openBulkDialog = (action) => {
    const items = this.getSelectedItems();
    if (!items.length) {
      this.setState({ bulkSelectionError: "Select at least one pending approval." });
      return;
    }
    this.setState({
      bulkDialogOpen: true,
      bulkDialogAction: action,
      bulkDialogItems: items,
      bulkActing: false,
      bulkError: null,
      bulkResult: null,
    });
  };

  closeBulkDialog = () => {
    if (this.state.bulkActing) return;
    this.setState({
      bulkDialogOpen: false,
      bulkDialogAction: null,
      bulkDialogItems: [],
      bulkError: null,
      bulkResult: null,
    });
  };

  handleBulkConfirm = async (comment) => {
    const { bulkDialogItems, bulkDialogAction } = this.state;
    this.setState({ bulkActing: true, bulkError: null });
    try {
      const response = await universalApprovalService.bulkActOnItems(
        bulkDialogItems,
        bulkDialogAction,
        comment,
        { failFast: false }
      );
      const result = response.payload;
      const successfulIndexes = new Set(
        (result.results || [])
          .filter((row) => row.success)
          .map((row) => row.index)
      );
      const failedIds = bulkDialogItems
        .filter((_item, index) => !successfulIndexes.has(index))
        .map((item) => item.id);
      this.setState({
        bulkActing: false,
        bulkResult: result,
        selectedItemIds: failedIds,
      });
      if (result.successCount > 0) {
        await this.loadInbox();
      }
    } catch (error) {
      this.setState({
        bulkActing: false,
        bulkError:
          (error && error.message) ||
          "The governed bulk approval request could not be completed.",
      });
    }
  };

  getFilteredItems = () => {
    const { items, filters } = this.state;
    return filterApprovalInboxItems(items, filters);
  };

  getStatusCounts = () => {
    const { items } = this.state;
    const counts = { ALL: items.length, PENDING: 0, APPROVED: 0, REJECTED: 0 };
    items.forEach((item) => {
      if (counts[item.status] != null) {
        counts[item.status] += 1;
      }
    });
    return counts;
  };

  render() {
    if (!isUniversalApprovalInboxEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Approval inbox"
          reason="Universal approval inbox is not enabled for your organization."
        />
      );
    }

    const {
      loading,
      loadError,
      filters,
      selectedItem,
      drawerOpen,
      acting,
      dataSource,
      activeView,
      bulkActionsEnabled,
      selectedItemIds,
      bulkSelectionError,
      bulkDialogOpen,
      bulkDialogAction,
      bulkDialogItems,
      bulkActing,
      bulkError,
      bulkResult,
    } = this.state;
    const filteredItems = this.getFilteredItems();
    const selectedItems = this.getSelectedItems();
    const selectionSummary = summarizeApprovalSelection(selectedItems);
    const metrics = buildApprovalInboxMetrics(this.state.items);
    const statusCounts = this.getStatusCounts();
    const isInbox = activeView === "inbox";
    const inboxPulse = buildShownPulse(filteredItems.length, "Pending");
    const analyticsPulse = buildShownPulse(this.state.items.length, "Total");

    return (
      <div className="lux-appr-page lux-register-page" data-testid="page-approvals">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.approvals}
          nav={
            <LuxSegmentNav
              className="lux-appr-view-tabs"
              items={[
                {
                  id: "inbox",
                  label: "Inbox",
                  icon: "fe fe-inbox",
                  badge: metrics.pending,
                  showZeroBadge: false,
                },
                { id: "analytics", label: "Analytics", icon: "fe fe-bar-chart-2" },
              ]}
              activeId={activeView}
              onChange={(next) =>
                this.setState({
                  activeView: next,
                  selectedItemIds: [],
                  bulkSelectionError: null,
                })
              }
              ariaLabel="Approval views"
              tabList
              testId="approval-view-nav"
            />
          }
          onRefresh={this.loadInbox}
          refreshLoading={loading}
        />

        {isInbox && (
          <UniversalApprovalFilterBar
            filters={filters}
            onChange={this.handleFiltersChange}
            resultCount={filteredItems.length}
            statusCounts={statusCounts}
          />
        )}

        {isInbox && (
          <UniversalApprovalSummary
            metrics={metrics}
            loading={loading}
            filters={filters}
            onFilter={this.handleSummaryFilter}
          />
        )}

        {isInbox && (
          <UniversalApprovalSlaBanner
            items={this.state.items}
            onReview={this.handleSlaFocus}
            active={filters.status === "PENDING" && filters.priority === "HIGH"}
          />
        )}

        {activeView === "analytics" && (
          <LuxRegisterListSection
            tone="violet"
            kickerIcon="fe fe-bar-chart-2"
            kicker="Approval analytics"
            title="Analytics"
            subtitle="Throughput and SLA trends across approval domains"
            pulseCards={analyticsPulse}
            className="lux-appr-list-section lux-appr-analytics-section"
          >
            <UniversalApprovalAnalyticsPanel items={this.state.items} loading={loading} />
          </LuxRegisterListSection>
        )}

        {loadError && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-appr-empty"
            icon="fe fe-alert-circle"
            title="Inbox unavailable"
            description={loadError}
          />
        )}

        {isInbox && !loadError && (
          <LuxRegisterListSection
            tone="violet"
            kickerIcon="fe fe-inbox"
            kicker="Approval inbox"
            title={DENSE_PAGE_META.approvals.title || "Approvals"}
            subtitle="Items awaiting your review in the current filter scope"
            pulseCards={inboxPulse}
            className="lux-appr-list-section"
          >
            <WorkspaceSavedViewBar
              surface="APPROVALS"
              currentFilters={filters}
              onApply={this.handleFiltersChange}
            />
            {bulkActionsEnabled && (
              <div className="lux-appr-bulk-toolbar" data-testid="approval-bulk-toolbar">
                <div className="lux-appr-bulk-toolbar__summary" aria-live="polite">
                  <i className="fe fe-check-square" aria-hidden="true" />
                  <strong>{selectionSummary.count} selected</strong>
                  {selectionSummary.hours != null ? (
                    <span>{selectionSummary.hours}h available</span>
                  ) : null}
                  <em>Maximum {UNIVERSAL_APPROVAL_BULK_MAX}</em>
                </div>
                {bulkSelectionError ? (
                  <p className="lux-appr-bulk-toolbar__error" role="alert">
                    {bulkSelectionError}
                  </p>
                ) : null}
                <div className="lux-appr-bulk-toolbar__actions">
                  <button
                    type="button"
                    className="is-danger"
                    disabled={!selectedItems.length}
                    onClick={() => this.openBulkDialog("REJECT")}
                  >
                    <i className="fe fe-x" aria-hidden="true" />
                    Bulk reject
                  </button>
                  <button
                    type="button"
                    className="is-success"
                    disabled={!selectedItems.length}
                    onClick={() => this.openBulkDialog("APPROVE")}
                  >
                    <i className="fe fe-check" aria-hidden="true" />
                    Bulk approve
                  </button>
                </div>
              </div>
            )}
            <UniversalApprovalRegister
              items={filteredItems}
              loading={loading}
              onSelect={this.handleSelectItem}
              bulkActionsEnabled={bulkActionsEnabled}
              selectedItemIds={selectedItemIds}
              onToggleItem={this.handleToggleBulkItem}
              onToggleAll={this.handleToggleAllBulkItems}
              maxSelection={UNIVERSAL_APPROVAL_BULK_MAX}
              onClearFilters={
                filteredItems.length === 0 &&
                (filters.status !== DEFAULT_FILTERS.status ||
                  filters.domain !== DEFAULT_FILTERS.domain ||
                  filters.priority !== DEFAULT_FILTERS.priority ||
                  Boolean((filters.query || "").trim()))
                  ? () => this.handleFiltersChange({ ...DEFAULT_FILTERS })
                  : undefined
              }
            />
          </LuxRegisterListSection>
        )}

        <UniversalApprovalDetailDrawer
          item={selectedItem}
          open={drawerOpen}
          onClose={this.handleCloseDrawer}
          onApprove={this.handleApprove}
          onReject={this.handleReject}
          acting={acting}
        />
        <UniversalApprovalBulkActionDialog
          open={bulkDialogOpen}
          action={bulkDialogAction}
          items={bulkDialogItems}
          summary={summarizeApprovalSelection(bulkDialogItems)}
          acting={bulkActing}
          error={bulkError}
          result={bulkResult}
          onConfirm={this.handleBulkConfirm}
          onClose={this.closeBulkDialog}
        />
      </div>
    );
  }
}

export default ApprovalsPage;
