import React, { useMemo } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import DashboardApexChart from "../dashboard/DashboardApexChart";
import TimesheetLuxuryDialog from "./TimesheetLuxuryDialog";
import { DAILY_TARGET_MINS } from "./timesheetBoard.utils";
import {
  buildDayDetailModel,
  buildDayMixDonutChart,
  buildDayTargetGaugeChart,
} from "./timesheetDetail.utils";
import { convertMinsToDisplay } from "./timesheetSummary.utils";

function TimesheetDayDetailModal({ show, dateString, timeSheetRequest, weekDates, onClose }) {
  const model = useMemo(
    () => (show && dateString ? buildDayDetailModel(timeSheetRequest, dateString, weekDates) : null),
    [show, dateString, timeSheetRequest, weekDates]
  );

  const mixChart = useMemo(() => (model ? buildDayMixDonutChart(model) : null), [model]);
  const gaugeChart = useMemo(() => (model ? buildDayTargetGaugeChart(model) : null), [model]);

  if (!model) return null;

  const badgeTone =
    model.targetLevel === "target"
      ? "green"
      : model.targetLevel === "over"
        ? "rose"
        : model.targetLevel === "under"
          ? "amber"
          : "slate";

  const targetPct = Math.min(
    120,
    Math.round((model.totalMins / Math.max(DAILY_TARGET_MINS, 1)) * 100)
  );
  const billablePct =
    model.totalMins > 0 ? Math.round((model.billableMins / model.totalMins) * 100) : 0;
  const maxEntryMins = Math.max(
    ...(model.entries || []).map((entry) => entry.mins || 0),
    1
  );

  const pulseHint =
    model.targetLevel === "target"
      ? "Right on the 8h mark — nice pace."
      : model.targetLevel === "over"
        ? "Above the daily target — check for overtime or corrections."
        : model.targetLevel === "under"
          ? "Still short of 8h — add missing work before submit."
          : model.isWeekend
            ? "Weekend day — log only if you worked."
            : "No hours yet for this day.";

  return (
    <TimesheetLuxuryDialog
      show={show}
      onClose={onClose}
      wide
      ariaLabel="Daily timesheet summary"
      kicker={model.isToday ? "Today · Day summary" : "Day summary"}
      kickerIcon={model.isToday ? "fe-sun" : "fe-calendar"}
      title={model.title}
      subtitle={`${model.entryCount} ${model.entryCount === 1 ? "entry" : "entries"} · ${model.gapDisplay}`}
      badge={{ label: model.totalDisplay, tone: badgeTone }}
      panelClassName="lux-ts-detail__panel--day-summary"
      footer={
        <div className="lux-ts-day-summary__foot">
          <span>
            <i className="fe fe-info" aria-hidden="true" />
            {model.isWeekend
              ? "Weekend day — targets may differ by your team policy."
              : "Aim for about 8 hours on standard workdays before you submit."}
          </span>
          <button type="button" className="lux-ts-day-summary__done" onClick={onClose}>
            Done
          </button>
        </div>
      }
    >
      <div className="lux-ts-day-summary">
        <div
          className={classNames("lux-ts-progress", `is-${badgeTone}`)}
          aria-label="Day progress"
          style={{ "--ts-progress": `${Math.min(targetPct, 100)}%` }}
        >
          <span className="lux-ts-progress__accent" aria-hidden="true" />
          <div className="lux-ts-progress__ring" aria-hidden="true">
            <strong>
              <CountUp end={Math.min(targetPct, 100)} duration={0.7} preserveValue />
              <small>%</small>
            </strong>
          </div>
          <div className="lux-ts-progress__body">
            <div className="lux-ts-progress__top">
              <span className="lux-ts-progress__icon" aria-hidden="true">
                <i className={model.isToday ? "fe fe-sun" : "fe fe-bar-chart-2"} />
              </span>
              <div className="lux-ts-progress__titles">
                <em>{model.isToday ? "Today’s progress" : "Day progress"}</em>
                <strong>
                  {model.totalDisplay}
                  <span> of 8h target</span>
                </strong>
              </div>
              <span className={classNames("lux-ts-progress__pill", `is-${badgeTone}`)}>
                {model.gapDisplay}
              </span>
            </div>
            <p className="lux-ts-progress__hint">{pulseHint}</p>
            <div className="lux-ts-progress__meta">
              <span>
                <b>{model.entryCount}</b> {model.entryCount === 1 ? "entry" : "entries"}
              </span>
              <span>
                <b>{billablePct}%</b> billable
              </span>
              <span>
                <b>{Math.min(targetPct, 100)}%</b> of 8h
              </span>
            </div>
            <div className="lux-ts-progress__track" aria-hidden="true">
              <i
                style={{
                  width: `${Math.max(Math.min(targetPct, 100), model.totalMins ? 6 : 0)}%`,
                }}
              />
              <em title="8h target" />
            </div>
          </div>
        </div>

        <div className="lux-ts-day-summary__kpis" aria-label="Day metrics">
          <article className={classNames("lux-ts-day-summary__kpi", `is-${badgeTone}`)}>
            <span className="lux-ts-day-summary__kpi-icon" aria-hidden="true">
              <i className="fe fe-clock" />
            </span>
            <div>
              <em>Total logged</em>
              <strong>{model.totalDisplay}</strong>
              <span>{model.entryCount} line{model.entryCount === 1 ? "" : "s"}</span>
            </div>
          </article>
          <article className="lux-ts-day-summary__kpi is-green">
            <span className="lux-ts-day-summary__kpi-icon" aria-hidden="true">
              <i className="fe fe-briefcase" />
            </span>
            <div>
              <em>Billable</em>
              <strong>{convertMinsToDisplay(model.billableMins)}</strong>
              <span>Project time</span>
            </div>
          </article>
          <article className="lux-ts-day-summary__kpi is-sky">
            <span className="lux-ts-day-summary__kpi-icon" aria-hidden="true">
              <i className="fe fe-layers" />
            </span>
            <div>
              <em>Non-billable</em>
              <strong>{convertMinsToDisplay(model.nonProjectMins)}</strong>
              <span>Internal / other</span>
            </div>
          </article>
          <article className="lux-ts-day-summary__kpi is-amber">
            <span className="lux-ts-day-summary__kpi-icon" aria-hidden="true">
              <i className="fe fe-sun" />
            </span>
            <div>
              <em>Leave / holiday</em>
              <strong>{convertMinsToDisplay(model.leaveMins)}</strong>
              <span>Away time</span>
            </div>
          </article>
        </div>

        <div className="lux-ts-day-summary__charts">
          <section className="lux-ts-day-summary__card">
            <header className="lux-ts-day-summary__card-head">
              <div>
                <h4>8-hour target</h4>
                <p>Progress toward the daily goal</p>
              </div>
            </header>
            {gaugeChart ? (
              <DashboardApexChart
                type="radialBar"
                series={gaugeChart.series}
                options={gaugeChart.options}
                height={220}
              />
            ) : (
              <p className="lux-ts-detail__empty">No target chart for this day.</p>
            )}
          </section>

          <section className="lux-ts-day-summary__card">
            <header className="lux-ts-day-summary__card-head">
              <div>
                <h4>Time mix</h4>
                <p>How hours split across categories</p>
              </div>
            </header>
            {mixChart ? (
              <DashboardApexChart
                type="donut"
                series={mixChart.series}
                options={mixChart.options}
                height={220}
              />
            ) : (
              <div className="lux-ts-day-summary__empty">
                <i className="fe fe-inbox" aria-hidden="true" />
                <strong>No hours logged</strong>
                <span>Add time on the board to see the mix here.</span>
              </div>
            )}
          </section>
        </div>

        <section className="lux-ts-day-summary__card lux-ts-day-summary__card--entries">
          <header className="lux-ts-day-summary__card-head">
            <div>
              <h4>Entries on this day</h4>
              <p>All tasks and projects with time logged — longer bars took more of the day</p>
            </div>
            {model.entryCount > 0 ? (
              <span className="lux-ts-day-summary__count-pill">{model.entryCount}</span>
            ) : null}
          </header>

          {model.entries.length === 0 ? (
            <div className="lux-ts-day-summary__empty">
              <i className="fe fe-calendar" aria-hidden="true" />
              <strong>This day is empty</strong>
              <span>Open the timesheet board and enter hours for {model.dayShort || "this day"}.</span>
            </div>
          ) : (
            <ul className="lux-ts-day-summary__entries" aria-label="Day entries">
              {model.entries.map((entry, index) => {
                const sharePct = Math.min(
                  100,
                  Math.round(((entry.mins || 0) / maxEntryMins) * 100)
                );
                return (
                  <li
                    key={`${entry.timesheetType}-${entry.taskGroupId}-${index}`}
                    className={classNames("lux-ts-day-summary__entry", {
                      "is-billable": entry.timesheetType === "project",
                      "is-leave": entry.leaveKind === "leave",
                      "is-holiday": entry.leaveKind === "holiday",
                    })}
                  >
                    <div className="lux-ts-day-summary__entry-top">
                      <div className="lux-ts-day-summary__entry-copy">
                        <strong title={entry.labelTitle || entry.label}>{entry.label}</strong>
                        {entry.groupLabel ? (
                          <em className="lux-ts-day-summary__entry-group">{entry.groupLabel}</em>
                        ) : null}
                        {Array.isArray(entry.metaChips) && entry.metaChips.length > 0 ? (
                          <span className="lux-ts-detail__chips is-compact">
                            {entry.metaChips.map((chip) => (
                              <span
                                key={chip.key || chip.label}
                                className={classNames(
                                  "lux-ts-detail__chip",
                                  chip.tone && `is-${chip.tone}`
                                )}
                              >
                                {chip.label}
                              </span>
                            ))}
                          </span>
                        ) : null}
                      </div>
                      <div className="lux-ts-day-summary__entry-right">
                        <strong>{entry.hoursDisplay}</strong>
                        <span
                          className={classNames(
                            "lux-ts-detail__status-pill is-compact",
                            `is-${entry.statusMeta.tone}`
                          )}
                        >
                          {entry.statusMeta.label}
                        </span>
                      </div>
                    </div>
                    <div className="lux-ts-day-summary__entry-bar" aria-hidden="true">
                      <i style={{ width: `${Math.max(sharePct, 8)}%` }} />
                    </div>
                    {entry.comments ? (
                      <p className="lux-ts-day-summary__comment">
                        <i className="fe fe-message-square" aria-hidden="true" />
                        {entry.comments}
                      </p>
                    ) : null}
                  </li>
                );
              })}
            </ul>
          )}
        </section>
      </div>
    </TimesheetLuxuryDialog>
  );
}

export default TimesheetDayDetailModal;
