/**
 * F04-T3: Payroll-ready leave extract and LWP indicators (client derivation).
 */
import moment from "moment";
import {
  formatLeaveDateRange,
  getLeaveTypeLabel,
  getWorkflowStatusMeta,
  parseLeaveDate,
} from "views/hrms/components/leave/leave.utils";
import { isLwpLeaveType } from "config/leave-impact.utils";

function toNumber(value) {
  const n = parseFloat(value);
  return Number.isNaN(n) ? 0 : n;
}

export function buildPayrollLeaveExtract(leaves, employeesById, periodStart, periodEnd) {
  const start = moment(periodStart).startOf("day");
  const end = moment(periodEnd).endOf("day");
  const rows = [];

  (leaves || []).forEach((leave) => {
    const meta = getWorkflowStatusMeta(leave);
    if (meta.code !== "APPROVED" && meta.code !== "SYNCED") {
      return;
    }
    const from = parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
    const to = parseLeaveDate(leave.applicationToDate || leave.application_to_date);
    if (!from || !to || !from.isValid() || !to.isValid()) return;
    if (to.isBefore(start) || from.isAfter(end)) return;

    const employeeId = leave.employeeId || leave.employee_id;
    const employee = employeesById && employeesById[employeeId];
    const code = leave.leaveTypeCode || leave.leave_type_code;
    const days = toNumber(leave.numberOfDays || leave.number_of_days);

    rows.push({
      leaveId: leave.id,
      employeeId,
      employeeName: (employee && employee.name) || leave.employeeName || `Employee ${employeeId}`,
      empCode: (employee && employee.empCode) || "—",
      leaveTypeCode: code,
      leaveTypeLabel: getLeaveTypeLabel(code, leave.leaveTypeDescription),
      dateRange: formatLeaveDateRange(leave),
      days,
      lwp: isLwpLeaveType(code),
      payrollStatus: isLwpLeaveType(code) ? "LWP" : "PAID",
      source: leave.source || "NATIVE",
    });
  });

  const lwpDays = rows.filter((row) => row.lwp).reduce((sum, row) => sum + row.days, 0);
  const paidDays = rows.filter((row) => !row.lwp).reduce((sum, row) => sum + row.days, 0);

  return {
    periodLabel: `${start.format("D MMM YYYY")} – ${end.format("D MMM YYYY")}`,
    rows: rows.sort((a, b) => String(a.employeeName).localeCompare(String(b.employeeName))),
    totals: {
      records: rows.length,
      lwpDays: Math.round(lwpDays * 10) / 10,
      paidDays: Math.round(paidDays * 10) / 10,
    },
  };
}

export function payrollExtractToCsv(extract) {
  if (!extract || !Array.isArray(extract.rows)) {
    return "";
  }
  const header = [
    "Employee",
    "Emp Code",
    "Leave Type",
    "Dates",
    "Days",
    "Payroll Status",
    "LWP",
    "Source",
  ];
  const lines = extract.rows.map((row) =>
    [
      row.employeeName,
      row.empCode,
      row.leaveTypeLabel,
      row.dateRange,
      row.days,
      row.payrollStatus,
      row.lwp ? "Yes" : "No",
      row.source,
    ]
      .map((cell) => `"${String(cell).replace(/"/g, '""')}"`)
      .join(",")
  );
  return [header.join(","), ...lines].join("\n");
}
