import React, { Component } from "react";
import { AdminActionButton } from "views/admin/components/AdminLuxShared";
import { filterManagerCandidates } from "config/org-structure.utils";

class OrgManagerReassignForm extends Component {
  state = { query: "" };

  getCandidates = () => {
    const { employees, employeeId, tree } = this.props;
    const query = String(this.state.query || "").trim().toLowerCase();
    const rows = filterManagerCandidates(employees, employeeId, tree);
    if (!query) {
      return rows;
    }
    return rows.filter((row) => {
      const haystack = [row.name, row.designation, row.department]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(query);
    });
  };

  render() {
    const {
      employeeId,
      value,
      onChange,
      onSave,
      saving,
      error,
      success,
      disabled,
    } = this.props;
    const candidates = this.getCandidates();
    const canSave = Boolean(employeeId) && Boolean(value) && !saving && !disabled;

    return (
      <div className="lux-org-reassign" data-testid="org-manager-reassign">
        <header className="lux-org-reassign__head">
          <span className="lux-org-reassign__mark" aria-hidden="true">
            <i className="fe fe-git-merge" />
          </span>
          <div>
            <strong>Reassign manager</strong>
            <p>Writes the employee reporting line. Descendants are excluded to prevent cycles.</p>
          </div>
        </header>
        <label className="lux-org-reassign__field" htmlFor="org-reassign-query">
          <span>Filter people</span>
          <input
            id="org-reassign-query"
            type="search"
            className="lux-org-reassign__control"
            placeholder="Name, title, or department"
            value={this.state.query}
            onChange={(event) => this.setState({ query: event.target.value })}
            disabled={disabled}
          />
        </label>
        <label className="lux-org-reassign__field" htmlFor="org-reassign-manager">
          <span>New manager</span>
          <select
            id="org-reassign-manager"
            className="lux-org-reassign__control"
            value={value || ""}
            onChange={(event) => onChange && onChange(event.target.value)}
            disabled={disabled}
          >
            <option value="">Select manager…</option>
            {candidates.map((row) => (
              <option key={row.id} value={row.id}>
                {row.name}
                {row.designation ? ` — ${row.designation}` : ""}
                {row.department ? ` · ${row.department}` : ""}
              </option>
            ))}
          </select>
        </label>
        <AdminActionButton variant="primary" onClick={onSave} disabled={!canSave}>
          {saving ? "Saving…" : "Save reporting line"}
        </AdminActionButton>
        {error ? (
          <p className="lux-org-structure-detail__error" role="alert">
            {error}
          </p>
        ) : null}
        {success ? (
          <p className="lux-org-structure-detail__success" role="status">
            {success}
          </p>
        ) : null}
      </div>
    );
  }
}

export default OrgManagerReassignForm;
