import React, { Component } from "react";
import { createPortal } from "react-dom";
import { LEGACY_CONNECTION_LABELS } from "config/integrations-connections.config";
import { IntegrationActionButton } from "views/integrations/components/IntegrationsLuxShared";

const SECRET_FIELDS = new Set(["password", "clientSecret", "token"]);

function ConfigField({ field, value, onChange, placeholder }) {
  const type = field.type || "text";
  if (type === "boolean") {
    return (
      <label className="lux-int-config-field lux-int-config-field--checkbox">
        <input
          type="checkbox"
          checked={value === true}
          onChange={(e) => onChange(field.key, e.target.checked)}
        />
        <span>{field.label}</span>
      </label>
    );
  }
  const inputType = type === "password" ? "password" : type === "number" ? "number" : "text";
  return (
    <label className="lux-int-config-field">
      <span>{field.label}{field.required ? " *" : ""}</span>
      <input
        type={inputType}
        autoComplete={type === "password" ? "new-password" : "off"}
        placeholder={placeholder}
        value={value == null ? "" : value}
        onChange={(e) => onChange(field.key, type === "number" ? Number(e.target.value) : e.target.value)}
      />
    </label>
  );
}

export default class IntegrationConnectionConfigDrawer extends Component {
  state = {
    config: {},
    secrets: {},
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open && this.props.connection) {
      const config = { ...(this.props.connection.config || {}) };
      // Never hydrate secret values into the form — leave blank to keep existing
      SECRET_FIELDS.forEach((key) => {
        delete config[key];
      });
      this.setState({
        config,
        secrets: {},
        saving: false,
        error: null,
      });
    }
  }

  handleChange = (key, value) => {
    if (SECRET_FIELDS.has(key)) {
      this.setState((prev) => ({
        secrets: { ...prev.secrets, [key]: value },
      }));
      return;
    }
    this.setState((prev) => ({
      config: { ...prev.config, [key]: value },
    }));
  };

  handleSave = async () => {
    const { connection, onSave, onSaveCredentials } = this.props;
    const { config, secrets } = this.state;
    if (!connection || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      const nonSecretConfig = { ...config };
      SECRET_FIELDS.forEach((key) => {
        delete nonSecretConfig[key];
      });

      const credentialPayload = {
        ...nonSecretConfig,
      };
      Object.keys(secrets).forEach((key) => {
        if (secrets[key] != null && String(secrets[key]).trim() !== "") {
          credentialPayload[key] = secrets[key];
        }
      });
      const supportsSecrets = connection.legacyKey === "salesforce" || connection.legacyKey === "zinghr";
      if (onSaveCredentials && supportsSecrets) {
        const credentialResult = await onSaveCredentials(connection.legacyKey, credentialPayload);
        const persisted = credentialResult && credentialResult.payload && credentialResult.payload.persisted;
        const typedSecret = Object.keys(secrets).some(
          (key) => secrets[key] != null && String(secrets[key]).trim() !== ""
        );
        if (typedSecret && persisted === false) {
          throw new Error("Password was not persisted. Check the secrets file path and try again.");
        }
      }

      await onSave(connection.legacyKey, {
        enabled: connection.integrationCenterEnabled !== false,
        config: nonSecretConfig,
      });

      if (this.props.onSaved) {
        this.props.onSaved();
      }
      if (this.props.onClose) {
        this.props.onClose();
      }
    } catch (error) {
      this.setState({
        saving: false,
        error: (error && error.message) || "Unable to save configuration.",
      });
    }
  };

  render() {
    const { open, onClose, connection } = this.props;
    const { config, secrets, saving, error } = this.state;
    if (!open || !connection) {
      return null;
    }
    const title = LEGACY_CONNECTION_LABELS[connection.legacyKey] || connection.name;
    const runtime = connection.runtimeConfig || {};
    const fields = connection.configFields || [];
    const supportsSecrets = connection.legacyKey === "salesforce" || connection.legacyKey === "zinghr";

    return createPortal(
      <div className="lux-dev-drawer-backdrop" role="presentation" onClick={onClose}>
        <aside
          className="lux-dev-drawer lux-dev-drawer--blue"
          role="dialog"
          aria-modal="true"
          onClick={(e) => e.stopPropagation()}
        >
          <header className="lux-dev-drawer__head">
            <div className="lux-dev-drawer__head-copy">
              <span className="lux-dev-drawer__eyebrow">Configure connection</span>
              <h2>{title}</h2>
            </div>
            <button type="button" className="lux-dev-drawer__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" />
            </button>
          </header>
          <div className="lux-dev-drawer__body">
            {error ? <p className="lux-integ-error">{error}</p> : null}
            <p className="lux-int-connection-intro">
              {supportsSecrets
                ? "Save writes Salesforce / ZingHR passwords and tokens to the secrets file (with a .bak backup) and reloads the connection without a restart. Leave password/token blank to keep the current secret."
                : "Settings saved here apply to the Integrations section."}
            </p>
            {runtime.serverConfigured ? (
              <p className="lux-int-connection-card__note">
                Server runtime: configured
                {runtime.source ? ` · source: ${runtime.source}` : ""}
                {runtime.passwordConfigured || runtime.tokenConfigured || runtime.clientSecretConfigured
                  ? " (credentials present)"
                  : ""}
              </p>
            ) : (
              <p className="lux-int-connection-card__note">
                Server runtime: not fully configured — enter host and credentials below, then Save.
              </p>
            )}
            <div className="lux-int-config-grid">
              {fields.map((field) => (
                <ConfigField
                  key={field.key}
                  field={field}
                  value={SECRET_FIELDS.has(field.key) ? secrets[field.key] : config[field.key]}
                  placeholder={
                    SECRET_FIELDS.has(field.key)
                      ? "Leave blank to keep current"
                      : undefined
                  }
                  onChange={this.handleChange}
                />
              ))}
            </div>
          </div>
          <footer className="lux-dev-drawer__footer">
            <IntegrationActionButton onClick={onClose}>Cancel</IntegrationActionButton>
            <IntegrationActionButton variant="primary" onClick={this.handleSave} disabled={saving}>
              {saving ? "Saving…" : "Save & apply"}
            </IntegrationActionButton>
          </footer>
        </aside>
      </div>,
      document.body
    );
  }
}
