import React from "react";
import { isWorkGraphEnabled } from "config/work-graph.config";
import SearchPage from "views/project/SearchPage";
import EnterpriseSearchPage from "views/workspace/EnterpriseSearchPage";

/** Routes /search to enterprise search when F26 is enabled; otherwise legacy project search. */
export default function SearchRouteSwitch(props) {
  if (isWorkGraphEnabled()) {
    return <EnterpriseSearchPage {...props} />;
  }
  return <SearchPage {...props} />;
}
